INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('alexanderop/second-brain-nuxt/mermaid-diagrams', 'mermaid-diagrams', 'alexanderop', 'second-brain-nuxt', 'community', 'mermaid-diagrams alexanderop second-brain-nuxt community mermaid-diagrams generates diagrams using Mermaid syntax, supporting various diagram types like flowcharts and sequence diagrams, benefiting developers and technical writers. Mermaid Diagrams 是一种使用 Mermaid 语法创建图表的工具，支持流程图、序列图、类图等 Mermaid Diagrams は、Mermaid 構文を使用してグラフを作成するツールです Mermaid Diagrams 는 Mermaid 구문으로 다이어그램을 생성하는 도구로, 流程图、시퀀스图、클래스图 등을 지원합니다 Mermaid-diagrams es una herramienta para generar diagramas usando la sintaxis Mermaid, ideal para desarrolladores que necesitan visualizar flujos de proceso y estructuras de datos Mermaid-diagrams est un outil pour générer des diagrammes à l''aide de la syntaxe Mermaid, idéal pour les développeurs qui ont besoin de visualiser les flux de processus et les structures de données Mermaid-diagrams ist ein Tool zum Erstellen von Diagrammen mit der Mermaid-Syntax, ideal für Entwickler, die Prozessflüsse und Datenstrukturen visualisieren müssen Mermaid Diagrams é uma ferramenta para criar diagramas complexos usando sintaxe Mermaid. Permite gerar fluxogramas, sequências e mais Mermaid Diagrams - это инструмент для создания сложных диаграмм с помощью синтаксиса Mermaid. Позволяет генерировать флоучарты, последовательности и многое другое для ИИ Агентов Mermaid Diagrams هو أداة لإنشاء مخططات معقدة باستخدام بناء الجملة Mermaid. يسمح بإنشاء مخططات انسيابية وترتيب واكثر لادوات الذكية how to use mermaid-diagrams mermaid-diagrams alternative mermaid-diagrams setup guide what is mermaid-diagrams mermaid-diagrams vs graphviz mermaid-diagrams install mermaid syntax tutorial generating diagrams with mermaid mermaid diagrams for developers Mermaid Diagrams Mermaid 语法 图表创建工具 流程图 序列图 类图 Zettelkasten wiki 链接 AI 工具 开发工具 Generates flowcharts for process flow and decision trees Supports sequence diagrams for API calls and system interactions Creates class diagrams for OOP structure and domain models Renders state diagrams for state machines and workflows Generates ER diagrams for database schemas and data relationships Supports C4 model diagrams for software architecture mermaid-diagrams is a skill for generating diagrams using Mermaid syntax, rendering in markdown code blocks with the mermaid language identifier.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kbaseincubator/BERIL-research-observatory/berdl_start', 'community', 'kbaseincubator', 'BERIL-research-observatory', 'kbaseincubator/BERIL-research-observatory', 'berdl_start', 0, 0, 45, '2026-03-08T01:57:15.312Z', '2026-03-08T02:02:36.281Z', '62a467621d9b12bec8402fb7b243cde86a7cf3c58d8e9a3a461b3e5492683137', '{"id":"kbaseincubator/BERIL-research-observatory/berdl_start","name":"berdl_start","description":{"en":"The berdl_start skill enables onboarding to the KBase Data Lakehouse, providing an overview of the system and routing users to the right context based on their goals, benefiting researchers and developers in microbial ecology.","zh":"BERIL Research Observatory 是一个使用 KBase Data Lakehouse 探索微生物生态学的平台，拥有 35 个数据库和 9 个租户","ja":"BERIL Research Observatory は、KBase Data Lakehouse を使用して微生物生態学を探索するプラットフォームで、35 のデータベースと 9 のテナントを備えています","ko":"BERIL Research Observatory는 미생물 생태학을 탐색하기 위한 KBase Data Lakehouse 플랫폼으로, 35개의 데이터베이스와 9개의 테넌트를 제공합니다","es":"BERDL es un Data Lakehouse de KBase que alberga 35 bases de datos en 9 inquilinos, permitiendo la exploración de la ecología microbiana","fr":"BERDL est un Data Lakehouse KBase qui héberge 35 bases de données dans 9 locataires, permettant l''exploration de l''écologie microbienne","de":"BERDL ist ein KBase-Data-Lakehouse, das 35 Datenbanken in 9 Mandanten hostet und die Erforschung der mikrobiellen Ökologie ermöglicht","pt":"O BERDL Start é uma ferramenta de IA para ecologia microbiana que utiliza o KBase Data Lakehouse, com 35 bancos de dados em 9 locatários","ru":"BERDL Start - это инструмент ИИ для микробной экологии, использующий KBase Data Lakehouse, с 35 базами данных в 9 арендаторах","ar":"BERDL Start هو أداة ذكاء اصطناعي للبيئة الميكروبية التي تستخدم KBase Data Lakehouse، مع 35 قاعدة بيانات في 9 منازل"},"seo":{"title":{"en":"berdl_start: KBase Data Lakehouse Onboarding Guide | AI A...","zh":"BERIL Research Observatory 入门指南 - 了解 KBase Data Lakehouse","ja":"BERIL Research Observatory 導入ガイド - KBase Data Lakehouse の探索","ko":"BERIL Research Observatory 시작하기 - KBase Data Lakehouse 소개","es":"Guía de configuración de BERDL - Exploración de la ecolog...","fr":"Guide de démarrage de BERDL - Exploration de l''écologie m...","de":"Einrichtungsleitfaden für BERDL - Erforschung der mikrobi...","pt":"Guia de Configuração do BERDL Start - Ferramentas de IAs ...","ru":"Настройка BERDL Start - ИИ Агенты для Микробной Экологии","ar":"دليل إعداد BERDL Start - أدوات ذكاء اصطناعي للبيئة الميكر..."},"description":{"en":"Unlock the power of microbial ecology with berdl_start. Explore 35 databases across 9 tenants and get started with the KBase BER Data Lakehouse today!","zh":"使用 BERIL Research Observatory 探索微生物生态学，并了解 KBase Data Lakehouse 的功能","ja":"BERIL Research Observatory を使用して微生物生態学を探索し、KBase Data Lakehouse の機能を理解する","ko":"BERIL Research Observatory를 사용하여 미생물 생태학을 탐색하고 KBase Data Lakehouse의 기능을 알아보세요","es":"Descubre cómo usar BERDL para explorar la ecología microbiana con KBase Data Lakehouse y aprovecha al máximo tus investigaciones","fr":"Découvrez comment utiliser BERDL pour explorer l''écologie microbienne avec KBase Data Lakehouse et tirez le meilleur parti de vos recherches","de":"Erfahren Sie, wie Sie BERDL verwenden können, um die mikrobielle Ökologie mit KBase Data Lakehouse zu erforschen und Ihre Forschung zu optimieren","pt":"Aprenda a configurar o BERDL Start, uma ferramenta de IA para ecologia microbiana, e explore os recursos do KBase Data Lakehouse","ru":"Узнайте, как настроить BERDL Start, инструмент ИИ для микробной экологии, и изучите возможности KBase Data Lakehouse","ar":"تعرف على كيفية إعداد BERDL Start، أداة ذكاء اصطناعي للبيئة الميكروبية، واستكشف موارد KBase Data Lakehouse"},"definition":{"en":"berdl_start is an AI agent skill that facilitates exploration of microbial ecology using the KBase Data Lakehouse, a Spark SQL-based Delta Lakehouse hosting multiple databases and collections.","zh":"BERIL Research Observatory 是一个使用 KBase Data Lakehouse 的微生物生态学研究平台","ja":"BERIL Research Observatory は、KBase Data Lakehouse を使用する微生物生態学研究プラットフォームです","ko":"BERIL Research Observatory는 KBase Data Lakehouse를 사용하는 미생물 생태학 연구 플랫폼입니다","es":"BERDL es un sistema de Data Lakehouse que utiliza Spark SQL para alojar múltiples bases de datos y facilitar la investigación","fr":"BERDL est un système de Data Lakehouse qui utilise Spark SQL pour héberger de multiples bases de données et faciliter la recherche","de":"BERDL ist ein Data-Lakehouse-System, das Spark SQL verwendet, um mehrere Datenbanken zu hosten und die Forschung zu erleichtern","pt":"O que é BERDL Start? É uma ferramenta de IA para ecologia microbiana que utiliza o KBase Data Lakehouse","ru":"Что такое BERDL Start? Это инструмент ИИ для микробной экологии, использующий KBase Data Lakehouse","ar":"ما هو BERDL Start؟ هو أداة ذكاء اصطناعي للبيئة الميكروبية التي تستخدم KBase Data Lakehouse"},"features":{"en":["Presents an overview of the KBase BER Data Lakehouse, including 35 databases across 9 tenants","Routes users to the right context based on their goals","Provides information on key collections, such as kbase_ke_pa","Supports exploration of microbial ecology using Spark SQL","Hosts data in an on-prem Delta Lakehouse","Offers a system overview without requiring file reads"],"zh":["使用 KBase Data Lakehouse 探索微生物生态学","35 个数据库和 9 个租户","支持 Spark SQL","Delta Lakehouse 架构","微生物生态学数据分析"],"ja":["KBase Data Lakehouse を使用して微生物生態学を探索","35 のデータベースと 9 のテナント","Spark SQL をサポート","Delta Lakehouse アーキテクチャ","微生物生態学データ分析"],"ko":["KBase Data Lakehouse를 사용하여 미생물 생태학을 탐색","35개의 데이터베이스와 9개의 테넌트","Spark SQL 지원","Delta Lakehouse 아키텍처","미생물 생태학 데이터 분석"],"es":["Almacenamiento de 35 bases de datos en 9 inquilinos","Uso de Spark SQL para consultas y análisis","Exploración de la ecología microbiana con KBase Data Lakehouse","Integración con herramientas de investigación para análisis avanzados","Soporte para múltiples formatos de datos y colecciones"],"fr":["Stockage de 35 bases de données dans 9 locataires","Utilisation de Spark SQL pour les requêtes et les analyses","Exploration de l''écologie microbienne avec KBase Data Lakehouse","Intégration avec des outils de recherche pour des analyses avancées","Prise en charge de plusieurs formats de données et collections"],"de":["Speicherung von 35 Datenbanken in 9 Mandanten","Verwendung von Spark SQL für Abfragen und Analysen","Erforschung der mikrobiellen Ökologie mit KBase Data Lakehouse","Integration mit Forschungstools für erweiterte Analysen","Unterstützung für mehrere Datenformate und Sammlungen"],"pt":["Utiliza o KBase Data Lakehouse com 35 bancos de dados","Suporta 9 locatários","Inclui coleções de dados como kbase_ke_pa","Permite a exploração da ecologia microbiana","Utiliza Spark SQL para consultas de dados","Oferece uma visão geral do sistema"],"ru":["Использует KBase Data Lakehouse с 35 базами данных","Поддерживает 9 арендаторов","Включает коллекции данных, такие как kbase_ke_pa","Позволяет исследовать микробную экологию","Использует Spark SQL для запросов к данным","Предоставляет обзор системы"],"ar":["يستخدم KBase Data Lakehouse مع 35 قاعدة بيانات","يدعم 9 منازل","يتضمن مجموعات بيانات مثل kbase_ke_pa","يسمح بالاستكشاف البيئي الميكروبي","يستخدم Spark SQL لاستفسارات البيانات","يوفر نظرة عامة على النظام"]},"keywords":{"en":["how to use berdl_start","what is berdl_start","berdl_start alternative","berdl_start vs KBase","berdl_start install","berdl_start setup guide","KBase Data Lakehouse tutorial","microbial ecology research tools","Spark SQL for data analysis"],"zh":["BERIL Research Observatory","KBase Data Lakehouse","微生物生态学","Spark SQL","Delta Lakehouse","数据分析","AI工具","机器学习"],"ja":["BERIL Research Observatory","KBase Data Lakehouse","微生物生態学","Spark SQL","Delta Lakehouse","データ分析","AIエージェント","機械学習"],"ko":["BERIL Research Observatory","KBase Data Lakehouse","미생물 생태학","Spark SQL","Delta Lakehouse","데이터 분석","AI 에이전트","기계 학습"],"es":["BERDL","KBase Data Lakehouse","ecología microbiana","Spark SQL","Data Lakehouse","investigación científica","análisis de datos","herramientas de investigación","formatos de datos"],"fr":["BERDL","KBase Data Lakehouse","écologie microbienne","Spark SQL","Data Lakehouse","recherche scientifique","analyse de données","outils de recherche","formats de données"],"de":["BERDL","KBase Data Lakehouse","mikrobielle Ökologie","Spark SQL","Data-Lakehouse","wissenschaftliche Forschung","Datenanalyse","Forschungstools","Datenformate"],"pt":["BERDL Start","Ferramentas de IA para ecologia microbiana","KBase Data Lakehouse","Ecologia microbiana","Spark SQL","Bancos de dados","Locatários","Coleções de dados","Consultas de dados"],"ru":["BERDL Start","ИИ Агенты для микробной экологии","KBase Data Lakehouse","Микробная экология","Spark SQL","Базы данных","Арендаторы","Коллекции данных","Запросы к данным"],"ar":["BERDL Start","أدوات ذكاء اصطناعي للبيئة الميكروبية","KBase Data Lakehouse","البيئة الميكروبية","Spark SQL","قواعد البيانات","المنازل","مجموعات البيانات","استفسارات البيانات"]}},"owner":"kbaseincubator","repo":"BERIL-research-observatory","repoPath":"kbaseincubator/BERIL-research-observatory","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.312Z","topics":[],"category":"community","skillMd":{"name":"berdl_start","description":"Get started with the BERIL Research Observatory. Use when a user is new, wants orientation, or asks what they can do.","bodyPreview":"# BERIL Research Observatory - Onboarding\n\nWelcome the user and orient them to the system, then route them to the right context based on their goal.\n\n## Phase 1: System Overview\n\nPresent this information directly (no file reads needed):\n\n### What is BERDL?\n\nThe **KBase BER Data Lakehouse (BERDL)** is an on-prem Delta Lakehouse (Spark SQL) hosting **35 databases across 9 tenants**. Key collections:\n\n| Collection | Scale | What it contains |\n|------------|-------|------------------|\n| `kbase_ke_pa","body":"# BERIL Research Observatory - Onboarding\n\nWelcome the user and orient them to the system, then route them to the right context based on their goal.\n\n## Phase 1: System Overview\n\nPresent this information directly (no file reads needed):\n\n### What is BERDL?\n\nThe **KBase BER Data Lakehouse (BERDL)** is an on-prem Delta Lakehouse (Spark SQL) hosting **35 databases across 9 tenants**. Key collections:\n\n| Collection | Scale | What it contains |\n|------------|-------|------------------|\n| `kbase_ke_pangenome` | 293K genomes, 1B genes, 27K species | Species-level pangenomes from GTDB r214: gene clusters, ANI, functional annotations (eggNOG), pathway predictions (GapMind), environmental embeddings (AlphaEarth) |\n| `kbase_genomes` | 293K genomes, 253M proteins | Structural genomics (contigs, features, protein sequences) in CDM format |\n| `kbase_msd_biochemistry` | 56K reactions, 46K molecules | ModelSEED biochemical reactions and compounds for metabolic modeling |\n| `kescience_fitnessbrowser` | 48 organisms, 27M fitness scores | Genome-wide mutant fitness from RB-TnSeq experiments |\n| `enigma_coral` | 3K taxa, 7K genomes | ENIGMA SFA environmental microbiology |\n| `nmdc_arkin` | 48 studies, 3M+ metabolomics | NMDC multi-omics (annotations, embeddings, metabolomics, proteomics) |\n| PhageFoundry (5 DBs) | Various | Species-specific genome browsers for phage-host research |\n| `planetmicrobe_planetmicrobe` | 2K samples, 6K experiments | Marine microbial ecology |\n\n### Repo Structure\n\n```\nprojects/           # Science projects (each has README.md + notebooks/ + data/)\ndocs/               # Shared knowledge base\n  collections.md    # Full database inventory\n  schemas/          # Per-collection schema docs\n  pitfalls.md       # SQL gotchas, data sparsity, common errors\n  performance.md    # Query strategies for large tables\n  research_ideas.md # Future research directions\n  overview.md       # Scientific context and data generation workflow\n  discoveries.md    # Running log of insights\n.claude/skills/     # Agent skills\ndata/               # Shared data extracts reusable across projects\n```\n\n### Available Skills\n\n| Skill | What it does |\n|-------|-------------|\n| `/berdl` | Query BERDL databases via REST API or Spark SQL |\n| `/berdl-query` | Run SQL queries locally with remote Spark compute (CLI tools + notebook support) |\n| `/berdl-minio` | Transfer files between BERDL MinIO and local machine |\n| `/berdl-discover` | Explore and document a new BERDL database |\n| `/literature-review` | Search PubMed, bioRxiv, arXiv, Semantic Scholar, and Google Scholar for relevant biological literature |\n| `/synthesize` | Read analysis outputs, compare against literature, and draft findings |\n| `/submit` | Submit a project for automated review |\n| `/cts` | Run batch compute jobs on the CTS cluster |\n\n> **Note**: Hypothesis generation, research planning, and notebook creation are handled automatically as part of the research workflow (Path 1 below). You don''t need to invoke them separately.\n\n### Existing Projects\n\nDiscover projects dynamically — run `ls projects/` to list them. Read the first line of each `projects/*/README.md` to get titles. Present the list to the user so they can see what''s been done.\n\n### How Projects Work\n\nEach project lives in `projects/<name>/` with a three-file structure plus supporting directories:\n\n```\nprojects/<name>/\n├── README.md            — Project overview, reproduction, authors\n├── RESEARCH_PLAN.md     — Hypothesis, approach, query strategy, revision history\n├── REPORT.md            — Findings, interpretation, supporting evidence\n├── REVIEW.md            — Automated review (generated by /submit)\n├── notebooks/           — Analysis notebooks with saved outputs\n├── data/                — Agent-derived data from queries and analysis\n├── user_data/           — User-provided input data (gene lists, phenotypes, etc.)\n├── figures/             — Key visualizations\n└── requirements.txt     — Python dependencies\n```\n\n**Reproducibility is required**: notebooks must be committed with outputs, figures must be saved to `figures/`, and README must include a `## Reproduction` section. See PROJECT.md for full standards.\n\n---\n\n## Phase 1.5: Environment Detection\n\nBefore routing the user, run environment detection to ensure prerequisites are met:\n\n**Run the detection script:**\n```bash\npython scripts/detect_berdl_environment.py\n```\n\nThis script automatically:\n1. **Detects location**: Tests connectivity to `spark.berdl.kbase.us:443` to determine if you''re on-cluster (BERDL JupyterHub) or off-cluster (local machine)\n2. **On-cluster path**:\n   - Automatically retrieves `KBASE_AUTH_TOKEN` from the environment and saves it to `.env`\n   - Confirms direct access works (no proxy needed)\n   - Reports ready status\n3. **Off-cluster path**:\n   - Checks `.env` for `KBASE_AUTH_TOKEN`\n   - Checks `.venv-berdl` exists\n   - Checks SSH tunnels on ports 1337 and 1338\n   - Checks pproxy on port 8123\n   - Provides specific next steps for anything missing\n\n**Present the output to the user** and help them resolve any issues before proceeding to Phase 2.\n\n**Common resolutions:**\n- **Missing .venv-berdl**: `bash scripts/bootstrap_client.sh`\n- **Missing KBASE_AUTH_TOKEN**: Get token from https://narrative.kbase.us/#auth2/account and add to `.env`\n- **Off-cluster without proxy**: User must start SSH tunnels (requires credentials). See `.claude/skills/berdl-query/references/proxy-setup.md` for full guide. Claude can start pproxy once tunnels are up.\n\n---\n\n## Phase 1.7: Session Naming Reminder\n\nIf the session does not already have a name, remind the user:\n\n> **Tip**: Name this session for easy identification — especially useful for long-running or remote sessions where the connection may drop. A good convention is to match the project name and git branch (e.g., `essential_metabolome`).\n\nThis is a non-blocking reminder. Move on to Phase 2 regardless.\n\n---\n\n## Phase 2: Interactive Routing\n\nAsk the user which of these they want to do:\n\n1. **Start a new research project**\n2. **Explore BERDL data**\n3. **Review published literature**\n4. **Continue an existing project**\n5. **Understand the system**\n\nThen follow the appropriate path below.\n\n---\n\n### Path 1: Start a New Research Project (Orchestrated Workflow)\n\nWhen the user wants to start a new research project, the agent drives the entire process — from ideation through review — checking in with the user at natural decision points rather than requiring manual skill invocations.\n\n#### Phase A: Orientation & Ideation\n\n**Required reading before anything else:**\n1. Read `PROJECT.md` — understand dual goals (science + knowledge capture), project structure requirements, reproducibility standards, JupyterHub workflow, Spark notebook patterns\n2. Read `docs/overview.md` — understand the data architecture, key tables, data generation workflow, known limitations\n3. Read `docs/collections.md` — full database inventory (35 databases, 9 tenants), what data is actually available\n4. Read `docs/pitfalls.md` and `docs/performance.md` — **critical: read these before designing any queries or analysis**\n5. Read `docs/research_ideas.md` — check for existing ideas, avoid duplicating work\n\n**Additional setup (Phase 1.5 should have already checked KBASE_AUTH_TOKEN and proxy):**\n6. Check `gh auth status` — needed for creating branches, PRs, and pushing code. If not authenticated, prompt the user to run `gh auth login`\n7. Note the user''s ORCID and affiliation for the Authors section — ask once, remember for future projects\n\n**Then engage with the user:**\n9. Chat with the user about their research interest\n10. Explore BERDL data (use `/berdl` queries) to check data availability, row counts, column types\n11. Check existing projects (`ls projects/`) — read READMEs of related projects to understand what''s been done\n12. Develop 2-3 testable hypotheses with H0/H1\n13. Search literature (use `/literature-review` internally) for context\n\n#### Phase B: Research Plan\n\n14. Write `RESEARCH_PLAN.md` with: Research Question, Hypothesis, Literature Context, Approach, Data Sources, Query Strategy, Analysis Plan, Expected Outcomes, Revision History (v1)\n15. Write slim `README.md` with: Title, Research Question, Status (In Progress), Overview, Quick Links, Reproduction placeholder, Authors\n16. Create project directory structure: `notebooks/`, `data/`, `user_data/`, `figures/`\n17. Suggest naming this session to match the project: \"Consider naming this session `{project_id}` to match the branch.\"\n18. Create branch `projects/{project_id}`, switch to it, and commit README + RESEARCH_PLAN. Working on a dedicated branch from the start avoids accumulating changes on main during long-running projects. Tell the user what you''re doing — if they prefer to stay on main, skip branch creation.\n19. **Optional: Research plan review** — Offer to run a quick review of the research plan before starting analysis. If the user accepts, invoke the plan reviewer subagent:\n\n    ```bash\n    CLAUDECODE= claude -p \\\n      --system-prompt \"$(cat .claude/reviewer/PLAN_REVIEW_PROMPT.md)\" \\\n      --allowedTools \"Read\" \\\n      --dangerously-skip-permissions \\\n      \"Review the research plan at projects/{project_id}/. Read RESEARCH_PLAN.md and README.md. Also read docs/pitfalls.md, docs/performance.md, docs/collections.md, and PROJECT.md. Check docs/schemas/ for any tables referenced in the plan. List existing projects with ls projects/ and read their README.md files to check for overlap. Return a concise list of suggestions.\"\n    ```\n\n    Present the suggestions to the user. They can address them, note them for later, or skip — this is advisory, not blocking.\n\n#### Phase C: Analysis (Notebooks)\n\n20. Write numbered notebooks (`01_data_exploration.ipynb`, `02_analysis.ipynb`, etc.) following the analysis plan\n21. Notebooks are the primary audit trail — do as much work as possible in notebooks so humans can inspect intermediate results\n22. When parallel execution or complex pipelines are needed, write scripts in `src/` but call them from notebooks\n23. **Run notebooks** — execute cells, inspect outputs, iterate\n24. As new information emerges, update `RESEARCH_PLAN.md` with a revision tag: `- **v2** ({date}): {what changed and why}`\n25. **Check in code frequently** — commit after each major milestone (plan written, notebooks created, data extracted, analysis complete)\n26. Re-read `docs/pitfalls.md` when something doesn''t work as expected\n\n#### Checkpoint: Results Review\n\nAfter notebooks are executed and committed, **pause and present the key results to the user** before moving to synthesis. This is a natural decision point — the user may want to inspect figures, question a result, or request additional analysis before the interpretation gets written.\n\n27. Summarize the key results: main statistics, notable patterns, anything unexpected\n28. Ask: \"Would you like to look at the notebooks/figures before I proceed with the writeup, or should I go ahead with `/synthesize`?\"\n29. If the user wants to explore first, wait. If they want changes, iterate on the notebooks before proceeding.\n\n#### Phase D: Synthesis & Writeup\n\n30. Run `/synthesize` to create `REPORT.md` with findings, interpretation, supporting evidence\n31. Commit the report\n32. Chat with user about the report — revise if needed\n\n#### Phase E: Review & Submission\n\n33. Run `/submit` to validate documentation and generate `REVIEW.md`\n34. Fix any issues flagged by the review\n35. Commit fixes\n36. Upload project to the lakehouse: `python tools/lakehouse_upload.py {project_id}` (prompted by `/submit` after clean review)\n37. Chat with user about next steps\n\n#### Throughout the Entire Workflow:\n- **Check in code often** — don''t let work accumulate uncommitted\n- **Update `docs/discoveries.md`** when you find something interesting (tag with `[project_id]`)\n- **Update `docs/pitfalls.md`** when you hit a gotcha (follow pitfall-capture protocol from `.claude/skills/pitfall-capture/SKILL.md`)\n- **Update `docs/performance.md`** when you learn a query optimization\n- **Re-read `docs/pitfalls.md`** when debugging failures — the answer may already be documented\n- **Re-read `docs/performance.md`** when queries are slow — check for existing optimization patterns\n- **Follow `PROJECT.md` standards** — notebooks with saved outputs, figures as standalone PNGs, requirements.txt, Reproduction section in README\n\n### Path 2: Explore BERDL Data\n\nRead these files:\n- `docs/collections.md` — full database inventory\n- `docs/pitfalls.md` — critical gotchas before querying\n\nThen:\n- Summarize what databases are available and their scale\n- Highlight cross-collection relationships (pangenome <-> genomes <-> biochemistry <-> fitness)\n- Suggest using `/berdl` to start querying\n- Suggest using `/berdl-discover` if they want to explore a database not yet documented in `docs/schemas/`\n- Warn about the key pitfalls (see Critical Pitfalls below)\n\n### Path 3: Review Published Literature\n\nSuggest using `/literature-review` to search biological databases. This is useful for:\n- Checking what''s already known about an organism or pathway before querying BERDL\n- Finding published pangenome analyses to compare against BERDL data\n- Supporting a hypothesis with existing citations\n- Discovering methods and approaches used in similar studies\n\n**MCP setup check**: The `paper-search-mcp` ([openags/paper-search-mcp](https://github.com/openags/paper-search-mcp)) is configured in `.mcp.json`. It runs via `uvx paper-search-mcp`. If it''s not working:\n1. Ensure Python 3.10+ and [uv](https://docs.astral.sh/uv/) are installed\n2. Test: `uvx --from paper-search-mcp python -m paper_search_mcp.server`\n3. Optionally set `SEMANTIC_SCHOLAR_API_KEY` in your environment for enhanced Semantic Scholar features\n4. The skill falls back to WebSearch if the MCP server is unavailable\n\n### Path 4: Continue an Existing Project\n\nSteps:\n1. Run `ls projects/` and list all projects for the user to choose from\n2. Read the chosen project''s `README.md`\n3. Check if a `REVIEW.md` exists in that project directory (read it if so)\n4. Summarize where the project stands: what''s done, what''s next\n5. Suggest using `/submit` when the project is ready for review\n\n### Path 5: Understand the System\n\nRead these files:\n- `PROJECT.md` — high-level goals and structure\n- `docs/collections.md` — database inventory\n- `docs/overview.md` — scientific context and data workflow\n\nThen:\n- Walk through the dual goals (science + knowledge capture)\n- Explain the documentation workflow (tag discoveries, update pitfalls)\n- Mention the UI can be browsed at the BERDL JupyterHub\n- List the available skills and what each does\n- Point to `docs/research_ideas.md` for future directions\n\n---\n\n## Key Principles (for the agent)\n\n1. **Read the docs first** — `PROJECT.md`, `docs/overview.md`, `docs/collections.md`, `docs/pitfalls.md`, and `docs/performance.md` before designing anything. Check existing `projects/` to avoid duplicating work.\n2. **Notebooks are the audit trail** — numbered sequentially (01, 02, 03...), each self-contained with a clear purpose. Commit with saved outputs per `PROJECT.md` reproducibility standards.\n3. **Commit early and often** — after plan, after notebooks, after data extraction, after analysis, after synthesis.\n4. **Branch by default** — create a `projects/{project_id}` branch when starting a new project. Extended work on main causes merge difficulties and risks conflicting with other contributors. Tell the user what branch you''re creating; if they explicitly prefer main, respect that.\n5. **Update the plan** — when the analysis reveals something that changes the approach, update RESEARCH_PLAN.md with a dated revision tag explaining what changed and why.\n6. **Don''t stop and wait** — drive the process forward, checking in with the user at decision points rather than stopping after each step.\n7. **Document as you go** — discoveries go in `docs/discoveries.md`, pitfalls in `docs/pitfalls.md`, performance tips in `docs/performance.md` — captured in real-time, tagged with `[project_id]`.\n8. **Use Spark patterns from PROJECT.md** — `get_spark_session()`, PySpark-first, `.toPandas()` only for final small results.\n\n---\n\n## Critical Pitfalls (always mention)\n\nRegardless of path chosen, surface these early:\n\n1. **Species IDs contain `--`** — This is fine inside quoted strings in SQL. Use exact equality (`WHERE id = ''s__Escherichia_coli--RS_GCF_000005845.2''`), not LIKE patterns.\n2. **Large tables need filters** — Never full-scan `gene` (1B rows) or `genome_ani` (420M rows). Always filter by species or genome ID.\n3. **AlphaEarth embeddings cover only 28%** of genomes (83K/293K) — check coverage before relying on them.\n4. **Match Spark import to environment** — On JupyterHub notebooks: `spark = get_spark_session()` (no import). On JupyterHub CLI/scripts: `from berdl_notebook_utils.setup_spark_session import get_spark_session`. Locally: `from get_spark_session import get_spark_session` (requires `.venv-berdl` + proxy chain). See `docs/pitfalls.md` for details.\n5. **Auth token** — stored in `.env` as `KBASE_AUTH_TOKEN` (not `KB_AUTH_TOKEN`).\n6. **String-typed numeric columns** — Many databases store numbers as strings. Always CAST before comparisons.\n7. **Gene clusters are species-specific** — Cannot compare cluster IDs across species. Use COG/KEGG/PFAM for cross-species comparisons.\n8. **Avoid unnecessary `.toPandas()`** — `.toPandas()` pulls all data to the driver node and can be very slow or cause OOM errors. Use PySpark DataFrame operations for filtering, joins, and aggregations. Only convert to pandas for final small results (plotting, CSV export).\n\n---\n\n## Templates\n\n### RESEARCH_PLAN.md\n\n```markdown\n# Research Plan: {Title}\n\n## Research Question\n{Refined question after literature review}\n\n## Hypothesis\n- **H0**: {Null hypothesis}\n- **H1**: {Alternative hypothesis}\n\n## Literature Context\n{Summary of what''s known, key references, identified gaps}\n\n## Query Strategy\n\n### Tables Required\n| Table | Purpose | Estimated Rows | Filter Strategy |\n|---|---|---|---|\n| {table} | {why needed} | {count} | {how to filter} |\n\n### Key Queries\n1. **{Description}**:\n\\```sql\n{query}\n\\```\n\n### Performance Plan\n- **Tier**: {REST API / JupyterHub}\n- **Estimated complexity**: {simple / moderate / complex}\n- **Known pitfalls**: {list from pitfalls.md}\n\n## Analysis Plan\n\n### Notebook 1: Data Exploration\n- **Goal**: {what to verify/explore}\n- **Expected output**: {CSV/figures}\n\n### Notebook 2: Main Analysis\n- **Goal**: {core analysis}\n- **Expected output**: {CSV/figures}\n\n### Notebook 3: Visualization (if needed)\n- **Goal**: {figures for findings}\n\n## Expected Outcomes\n- **If H1 supported**: {interpretation}\n- **If H0 not rejected**: {interpretation}\n- **Potential confounders**: {list}\n\n## Revision History\n- **v1** ({date}): Initial plan\n\n## Authors\n{ORCID, affiliation}\n```\n\n### README.md\n\n```markdown\n# {Title}\n\n## Research Question\n{Refined question}\n\n## Status\nIn Progress — research plan created, awaiting analysis.\n\n## Overview\n{One-paragraph summary of the hypothesis and approach}\n\n## Quick Links\n- [Research Plan](RESEARCH_PLAN.md) — hypothesis, approach, query strategy\n- [Report](REPORT.md) — findings, interpretation, supporting evidence\n\n## Reproduction\n*TBD — add prerequisites and step-by-step instructions after analysis is complete.*\n\n## Authors\n{Authors}\n```\n"},"lastSynced":"2026-03-08T02:02:36.281Z","agentAnalysis":{"suitability":{"en":"Perfect for Research Agents in microbial ecology needing comprehensive onboarding to the KBase Data Lakehouse","zh":"适合需要全面入门KBase Data Lakehouse的微生物生态学研究代理","ja":"KBase Data Lakehouseの包括的なオンボーディングが必要な微生物生態学の研究エージェントに最適","ko":"미생물 생태학 연구 에이전트가 KBase Data Lakehouse에 대한 포괄적인 온보딩이 필요한 경우 적합","es":"Perfecto para Agentes de Investigación en ecología microbiana que necesitan una incorporación integral al lago de datos KBase","fr":"Parfait pour les agents de recherche en écologie microbienne ayant besoin d''une intégration complète au lac de données KBase","de":"Perfekt für Forschungsagenten in der Mikroökologie, die eine umfassende Einarbeitung in das KBase Data Lakehouse benötigen","pt":"Perfeito para Agentes de Pesquisa em ecologia microbiana que necessitam de uma integração abrangente ao KBase Data Lakehouse","ru":"Идеально подходит для исследовательских агентов в области микробной экологии, которым необходима комплексная интеграция с KBase Data Lakehouse","ar":"مثالي لوكلاء البحث في علم البيئة الميكروبي الذي يحتاج إلى دمج شامل مع KBase Data Lakehouse"},"recommendation":{"en":"Empowers agents to route users to the right context based on their goals, leveraging Spark SQL and Delta Lakehouse capabilities, and providing an overview of the 35 databases across 9 tenants","zh":"赋予代理根据用户的目标将他们路由到正确的上下文，利用Spark SQL和Delta Lakehouse的能力，并提供对35个数据库跨9个租户的概述","ja":"エージェントに、ユーザーの目標に基づいて正しいコンテキストにルーティングする能力を与え、Spark SQLとDelta Lakehouseの機能を利用し、9つのテナントにわたる35のデータベースの概要を提供する","ko":"에이전트가 사용자의 목표에 따라 올바른 컨텍스트로 사용자를 라우팅할 수 있도록 하며, Spark SQL 및 Delta Lakehouse 기능을 활용하고, 9개의 테넌트에 걸친 35개의 데이터베이스에 대한 개요를 제공함","es":"Habilita a los agentes para enrutrar a los usuarios al contexto correcto en función de sus objetivos, aprovechando las capacidades de Spark SQL y Delta Lakehouse, y proporcionando una visión general de las 35 bases de datos en 9 inquilinos","fr":"Permet aux agents de router les utilisateurs vers le contexte approprié en fonction de leurs objectifs, en exploitant les capacités de Spark SQL et de Delta Lakehouse, et en fournissant une vue d''ensemble des 35 bases de données sur 9 locataires","de":"Ermächtigt die Agenten, Benutzer basierend auf ihren Zielen an den richtigen Kontext zu verweisen, indem sie die Funktionen von Spark SQL und Delta Lakehouse nutzen und einen Überblick über die 35 Datenbanken in 9 Mandanten bieten","pt":"Habilita os agentes a encaminhar os usuários para o contexto correto com base em seus objetivos, aproveitando as capacidades do Spark SQL e do Delta Lakehouse e fornecendo uma visão geral dos 35 bancos de dados em 9 locatários","ru":"Наделяет агентов возможностью направлять пользователей в правильный контекст на основе их целей, используя возможности Spark SQL и Delta Lakehouse, и предоставляя обзор 35 баз данных в 9 арендаторах","ar":"يمنح الوكلاء القدرة على توجيه المستخدمين إلى السياق الصحيح بناءً على أهدافهم، واستخدام khảيات Spark SQL و Delta Lakehouse، وتقديم نظرة عامة على 35 قاعدة بيانات عبر 9 مستأجرين"},"useCases":{"en":["Onboarding new researchers to the BERDL system","Routing users to specific databases based on their goals","Providing an overview of the KBase BER Data Lakehouse"],"zh":["将新的研究人员引入BERDL系统","根据用户的目标将他们路由到特定的数据库","提供KBase BER Data Lakehouse的概述"],"ja":["BERDLシステムへの新しい研究者のオンボーディング","ユーザーの目標に基づいて特定のデータベースへのルーティング","KBase BER Data Lakehouseの概要の提供"],"ko":["新的 연구자를 BERDL 시스템에 온보딩하는 것","사용자의 목표에 따라 특정 데이터베이스로 사용자를 라우팅하는 것","KBase BER Data Lakehouse의 개요를 제공하는 것"],"es":["Incorporación de nuevos investigadores al sistema BERDL","Enrutamiento de usuarios a bases de datos específicas según sus objetivos","Proporcionar una visión general del lago de datos KBase BER"],"fr":["Intégration de nouveaux chercheurs au système BERDL","Acheminement des utilisateurs vers des bases de données spécifiques en fonction de leurs objectifs","Fournir une vue d''ensemble du lac de données KBase BER"],"de":["Einarbeitung neuer Forscher in das BERDL-System","Weiterleitung von Benutzern an bestimmte Datenbanken basierend auf ihren Zielen","Bereitstellung einer Übersicht über das KBase-BER-Data-Lakehouse"],"pt":["