INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('kbaseincubator/BERIL-research-observatory/berdl_start', 'berdl_start', 'kbaseincubator', 'BERIL-research-observatory', 'community', 'berdl_start kbaseincubator BERIL-research-observatory community The berdl_start skill enables onboarding to the KBase Data Lakehouse, providing an overview of the system and routing users to the right context based on their goals, benefiting researchers and developers in microbial ecology. BERIL Research Observatory 是一个使用 KBase Data Lakehouse 探索微生物生态学的平台，拥有 35 个数据库和 9 个租户 BERIL Research Observatory は、KBase Data Lakehouse を使用して微生物生態学を探索するプラットフォームで、35 のデータベースと 9 のテナントを備えています BERIL Research Observatory는 미생물 생태학을 탐색하기 위한 KBase Data Lakehouse 플랫폼으로, 35개의 데이터베이스와 9개의 테넌트를 제공합니다 BERDL es un Data Lakehouse de KBase que alberga 35 bases de datos en 9 inquilinos, permitiendo la exploración de la ecología microbiana BERDL est un Data Lakehouse KBase qui héberge 35 bases de données dans 9 locataires, permettant l''exploration de l''écologie microbienne BERDL ist ein KBase-Data-Lakehouse, das 35 Datenbanken in 9 Mandanten hostet und die Erforschung der mikrobiellen Ökologie ermöglicht O BERDL Start é uma ferramenta de IA para ecologia microbiana que utiliza o KBase Data Lakehouse, com 35 bancos de dados em 9 locatários BERDL Start - это инструмент ИИ для микробной экологии, использующий KBase Data Lakehouse, с 35 базами данных в 9 арендаторах BERDL Start هو أداة ذكاء اصطناعي للبيئة الميكروبية التي تستخدم KBase Data Lakehouse، مع 35 قاعدة بيانات في 9 منازل how to use berdl_start what is berdl_start berdl_start alternative berdl_start vs KBase berdl_start install berdl_start setup guide KBase Data Lakehouse tutorial microbial ecology research tools Spark SQL for data analysis BERIL Research Observatory KBase Data Lakehouse 微生物生态学 Spark SQL Delta Lakehouse 数据分析 AI工具 机器学习 Presents an overview of the KBase BER Data Lakehouse, including 35 databases across 9 tenants Routes users to the right context based on their goals Provides information on key collections, such as kbase_ke_pa Supports exploration of microbial ecology using Spark SQL Hosts data in an on-prem Delta Lakehouse Offers a system overview without requiring file reads berdl_start is an AI agent skill that facilitates exploration of microbial ecology using the KBase Data Lakehouse, a Spark SQL-based Delta Lakehouse hosting multiple databases and collections.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('emirrtopaloglu/claude-code-virtuoso/step-by-step', 'community', 'emirrtopaloglu', 'claude-code-virtuoso', 'emirrtopaloglu/claude-code-virtuoso', 'step-by-step', 0, 0, 45, '2026-03-08T01:57:15.312Z', '2026-03-08T02:02:38.194Z', '2a19f25063b54ff2244ed6f87484d660cde958712d88d36f30cf8a9f4cc4bc57', '{"id":"emirrtopaloglu/claude-code-virtuoso/step-by-step","name":"step-by-step","description":{"en":"The step-by-step skill executes tasks one step at a time, utilizing the AskUserQuestion tool for user interactions and approval. This skill benefits developers and power users seeking controlled and transparent task execution.","zh":"Claude Code Virtuoso AI 编排工具提供一步一步的任务执行指南，使用 AskUserQuestion 工具进行用户交互","ja":"Claude Code Virtuoso AI オーケストレーターは、AskUserQuestion ツールを使用してステップバイステップでタスクを実行するためのガイドを提供します","ko":"Claude Code Virtuoso AI 오케스트레이터는 AskUserQuestion 툴을 사용하여 단계별로 태스크를 실행하는 가이드를 제공합니다","es":"Claude Code Virtuoso es un orquestador de AI que ejecuta tareas paso a paso, utilizando herramientas como AskUserQuestion para interactuar con los usuarios","fr":"Claude Code Virtuoso est un orchestrateur d''IA qui exécute des tâches étape par étape, en utilisant des outils comme AskUserQuestion pour interagir avec les utilisateurs","de":"Claude Code Virtuoso ist ein AI-Orchestrierer, der Aufgaben schrittweise ausführt, indem er Tools wie AskUserQuestion für die Benutzerinteraktion verwendet","pt":"O Claude Code Virtuoso é um orquestrador de IA que executa tarefas de forma step-by-step, utilizando o tool AskUserQuestion para interações com o usuário.","ru":"Claude Code Virtuoso - это оркестратор ИИ, который выполняет задачи пошагово, используя инструмент AskUserQuestion для взаимодействия с пользователем.","ar":"Claude Code Virtuoso هو مشرف على واجهات برمجة التطبيقات الاصطناعية الذي ينفذ المهام خطوة بخطوة، مستخدما أداة AskUserQuestion للتفاعل مع المستخدم."},"seo":{"title":{"en":"step-by-step: AI Orchestrator Setup Guide | AI Agent Skill","zh":"一步一步指南：Claude Code Virtuoso AI 编排工具","ja":"ステップバイステップガイド：Claude Code Virtuoso AI オーケストレーター","ko":"단계별 가이드: Claude Code Virtuoso AI 오케스트레이터","es":"Guía de configuración paso a paso para Claude Code Virtuoso","fr":"Guide d''installation étape par étape pour Claude Code Vir...","de":"Schritt-für-Schritt-Anleitung für Claude Code Virtuoso","pt":"Guia de Configuração de Agentes de IA: Step-by-Step com C...","ru":"Настройка ИИ Агентов: пошаговое руководство с Claude Code...","ar":"دليل إعداد واجهات برمجة التطبيقات الاصطناعية: خطوة بخطوة ..."},"description":{"en":"Unlock efficient task execution with step-by-step AI Orchestrator. Learn how to use AskUserQuestion for seamless user interactions and approval processes.","zh":"了解 Claude Code Virtuoso AI 编排工具的步骤指南，包括使用 AskUserQuestion 工具和错误恢复机制","ja":"Claude Code Virtuoso AI オーケストレーターのステップバイステップガイド。AskUserQuestion ツールとエラーリカバリメカニズムを使用する方法を学びます","ko":"Claude Code Virtuoso AI 오케스트레이터의 단계별 가이드. AskUserQuestion 툴과 오류 복구 메커니즘 사용 방법을 알아보세요","es":"Aprende a ejecutar tareas paso a paso con Claude Code Virtuoso, utilizando herramientas como AskUserQuestion para interactuar con los usuarios","fr":"Découvrez comment exécuter des tâches étape par étape avec Claude Code Virtuoso, en utilisant des outils comme AskUserQuestion pour interagir avec les utilis...","de":"Erfahren Sie, wie Sie Aufgaben schrittweise mit Claude Code Virtuoso ausführen, indem Sie Tools wie AskUserQuestion für die Benutzerinteraktion verwenden","pt":"Aprenda a configurar agentes de IA de forma eficaz com o guia step-by-step do Claude Code Virtuoso. Desenvolva soluções personalizadas com React, Vue e Angular.","ru":"Узнайте, как настроить ИИ Агенты эффективно с помощью пошагового руководства от Claude Code Virtuoso. Разрабатывайте индивидуальные решения с использованием ...","ar":"تعلم كيفية إعداد واجهات برمجة التطبيقات الاصطناعية بفعالية مع دليل خطوة بخطوة من Claude Code Virtuoso. قم بإنشاء حلول مخصصة مع React و Vue و Angular."},"definition":{"en":"step-by-step is a task execution skill that performs tasks in a sequential manner, relying on AskUserQuestion for user input and approval at each step.","zh":"一步一步指南是 Claude Code Virtuoso AI 编排工具的一项功能，用于执行任务并与用户进行交互","ja":"ステップバイステップガイドは、Claude Code Virtuoso AI オーケストレーターの機能の 1 つで、タスクを実行し、ユーザーとやり取りするために使用されます","ko":"단계별 가이드는 Claude Code Virtuoso AI 오케스트레이터의 기능 중 하나로 태스크를 실행하고 사용자와 상호 작용하는 데 사용됩니다","es":"Un orquestador de AI que ejecuta tareas paso a paso, utilizando herramientas como AskUserQuestion","fr":"Un orchestrateur d''IA qui exécute des tâches étape par étape, en utilisant des outils comme AskUserQuestion","de":"Ein AI-Orchestrierer, der Aufgaben schrittweise ausführt, indem er Tools wie AskUserQuestion verwendet","pt":"O que é um agente de IA step-by-step? É um tipo de orquestrador que executa tarefas de forma sequencial, solicitando aprovação do usuário em cada etapa.","ru":"Что такое ИИ Агент пошаговый? Это тип оркестратора, который выполняет задачи последовательно, запрашивая одобрение пользователя на каждом этапе.","ar":"ما هو واجهة برمجة التطبيقات الاصطناعية خطوة بخطوة؟ هو نوع من المشرف الذي ينفذ المهام بشكل متسلسل، ويطلب موافقة المستخدم في كل خطوة."},"features":{"en":["Executes tasks one step at a time for controlled execution","Utilizes AskUserQuestion tool for all user interactions","Mandatory plan approval via AskUserQuestion","Step continuation and error recovery via AskUserQuestion","Supports clarifying questions for technology selection (e.g., React, Vue, Angular)"],"zh":["使用 AskUserQuestion 工具进行用户交互","一步一步地执行任务","支持计划批准和步骤继续","支持错误恢复机制","支持技术选择（React、Vue、Angular）"],"ja":["AskUserQuestion ツールを使用してユーザーとやり取りする","ステップバイステップでタスクを実行する","プランの承認とステップの続行をサポートする","エラーリカバリメカニズムをサポートする","技術の選択（React、Vue、Angular）をサポートする"],"ko":["AskUserQuestion 툴을 사용하여 사용자와 상호 작용","단계별로 태스크를 실행","계획 승인 및 단계 계속을 지원","오류 복구 메커니즘을 지원","기술 선택（React、Vue、Angular）을 지원"],"es":["Ejecución de tareas paso a paso","Uso de AskUserQuestion para la aprobación del plan","Uso de AskUserQuestion para la continuación de los pasos","Uso de AskUserQuestion para la recuperación de errores","Compatibilidad con tecnologías como React, Vue y Angular"],"fr":["Exécution de tâches étape par étape","Utilisation d''AskUserQuestion pour l''approbation du plan","Utilisation d''AskUserQuestion pour la poursuite des étapes","Utilisation d''AskUserQuestion pour la récupération des erreurs","Compatibilité avec des technologies comme React, Vue et Angular"],"de":["Ausführung von Aufgaben schrittweise","Verwendung von AskUserQuestion für die Planbestätigung","Verwendung von AskUserQuestion für die Fortsetzung der Schritte","Verwendung von AskUserQuestion für die Fehlerbehebung","Kompatibilität mit Technologien wie React, Vue und Angular"],"pt":["Execução de tarefas de forma step-by-step","Utilização do tool AskUserQuestion para interações com o usuário","Aprovação de plano e continuação de etapas com AskUserQuestion","Suporte a tecnologias como React, Vue e Angular","Recuperação de erros com AskUserQuestion"],"ru":["Выполнение задач пошагово","Использование инструмента AskUserQuestion для взаимодействия с пользователем","Одобрение плана и продолжение этапов с AskUserQuestion","Поддержка технологий seperti React, Vue и Angular","Восстановление после ошибок с AskUserQuestion"],"ar":["تنفيذ المهام خطوة بخطوة","استخدام أداة AskUserQuestion للتفاعل مع المستخدم","موافقة الخطة ومواصلة الخطوات مع AskUserQuestion","دعم تكنولوجيا مثل React و Vue و Angular","استعادة الخطأ مع AskUserQuestion"]},"keywords":{"en":["how to use step-by-step","step-by-step AI Orchestrator","step-by-step alternative","step-by-step vs AI Assistant","step-by-step install guide","step-by-step setup for developers","what is step-by-step","step-by-step tutorial","step-by-step best practices"],"zh":["AI 编排工具","一步一步指南","AskUserQuestion 工具","错误恢复机制","计划批准","React","Vue","Angular"],"ja":["AI オーケストレーター","ステップバイステップガイド","AskUserQuestion ツール","エラーリカバリメカニズム","プランの承認","React","Vue","Angular"],"ko":["AI 오케스트레이터","단계별 가이드","AskUserQuestion 툴","오류 복구 메커니즘","계획 승인","React","Vue","Angular"],"es":["orquestador de AI","ejecución de tareas paso a paso","AskUserQuestion","aprobación del plan","continuación de los pasos","recuperación de errores","React","Vue","Angular","desarrollo de software"],"fr":["orchestrateur d''IA","exécution de tâches étape par étape","AskUserQuestion","approbation du plan","poursuite des étapes","récupération des erreurs","React","Vue","Angular","développement de logiciels"],"de":["AI-Orchestrierer","Ausführung von Aufgaben schrittweise","AskUserQuestion","Planbestätigung","Fortsetzung der Schritte","Fehlerbehebung","React","Vue","Angular","Softwareentwicklung"],"pt":["agentes de IA","orquestrador de IA","step-by-step","AskUserQuestion","React","Vue","Angular","desenvolvimento de software","programação de IA"],"ru":["ИИ Агенты","оркестратор ИИ","пошаговый","AskUserQuestion","React","Vue","Angular","разработка программного обеспечения","программирование ИИ"],"ar":["واجهات برمجة التطبيقات الاصطناعية","مشرف على واجهات برمجة التطبيقات الاصطناعية","خطوة بخطوة","AskUserQuestion","React","Vue","Angular","تطوير البرمجيات","برمجة واجهات برمجة التطبيقات الاصطناعية"]}},"owner":"emirrtopaloglu","repo":"claude-code-virtuoso","repoPath":"emirrtopaloglu/claude-code-virtuoso","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.312Z","topics":[],"category":"community","skillMd":{"name":"step-by-step","description":"Execute a task one atomic step at a time, requiring approval for each.","bodyPreview":"You will execute the task: \"$ARGUMENTS\"\n\n**CRITICAL RULES:**\n1. Execute ONLY ONE step at a time\n2. **MANDATORY:** Use `AskUserQuestion` tool for ALL user interactions\n3. NEVER proceed without explicit user approval via `AskUserQuestion`\n\n# Mandatory Tool Usage\n\n**You MUST use `AskUserQuestion` for:**\n- Plan approval: \"Approve this plan? (Yes/No/Modify)\"\n- Step continuation: \"Continue to Step N? (Yes/No/Skip)\"\n- Clarifying questions: \"Which technology? (React/Vue/Angular)\"\n- Error recovery: \"Retr","body":"You will execute the task: \"$ARGUMENTS\"\n\n**CRITICAL RULES:**\n1. Execute ONLY ONE step at a time\n2. **MANDATORY:** Use `AskUserQuestion` tool for ALL user interactions\n3. NEVER proceed without explicit user approval via `AskUserQuestion`\n\n# Mandatory Tool Usage\n\n**You MUST use `AskUserQuestion` for:**\n- Plan approval: \"Approve this plan? (Yes/No/Modify)\"\n- Step continuation: \"Continue to Step N? (Yes/No/Skip)\"\n- Clarifying questions: \"Which technology? (React/Vue/Angular)\"\n- Error recovery: \"Retry/Skip/Abort?\"\n\n**DO NOT use plain text questions.** Always invoke `AskUserQuestion` tool.\n\n# Optional Agent Collaboration\n\nDepending on the task, you may need:\n- `@backend-architect` - For backend implementation\n- `@frontend-architect` - For UI implementation\n- `@mobile-architect` - For mobile implementation\n\n# Workflow\n\n1.  **Parse Task:** Understand \"$ARGUMENTS\"\n   - If empty: Error (see error handling)\n\n2.  **Create Plan:** Break task into 3-7 atomic steps\n   - Show full plan to user\n   - **USE `AskUserQuestion`:** \"Approve this plan? (Yes/No/Modify)\"\n\n3.  **Execute Step 1:**\n   - Show: \"📍 Step 1/N: [Description]\"\n   - Perform the action (create file, edit code, etc.)\n   - Show: \"✅ Step 1 completed: [What was done]\"\n\n4.  **Ask for Approval:**\n   - **USE `AskUserQuestion`:** \"Continue to Step 2? (Yes/No/Skip)\"\n   - If No: Stop and exit\n   - If Skip: Move to Step 3\n\n5.  **Repeat for Each Step**\n\n6.  **Final Summary:**\n   - Show all completed steps\n   - Suggest next action (e.g., \"Run /polish to clean up\")\n\n# Step Planning Guidelines\n\n**Good Steps (Atomic):**\n- ✅ \"Create user model in database schema\"\n- ✅ \"Add API endpoint GET /users/:id\"\n- ✅ \"Create UserProfile component\"\n\n**Bad Steps (Too broad):**\n- ❌ \"Implement the entire user system\"\n- ❌ \"Build the frontend\"\n\n# Example Flow\n\n```\nUser: /step-by-step \"Implement the login page\"\n\nAssistant:\n📋 Task Plan:\n1. Create Login.tsx component with email/password form\n2. Add form validation (email format, password length)\n3. Create POST /auth/login API endpoint\n4. Connect frontend form to API\n5. Add error handling and loading states\n6. Add \"Forgot Password?\" link\n\nApprove this plan? (Yes/No/Modify)\n\nUser: Yes\n\nAssistant:\n📍 Step 1/6: Create Login.tsx component with email/password form\n\n[Creates file with code]\n\n✅ Step 1 completed: Created src/components/Login.tsx with form structure\n\nContinue to Step 2? (Yes/No/Skip)\n```\n\n# Error Handling\n\n**If $ARGUMENTS is empty:**\n- Error: \"❌ No task provided. Usage: /step-by-step [task description]\"\n- Example: `/step-by-step \"Add user authentication\"`\n\n**If task is too vague:**\n- **USE `AskUserQuestion`:** Ask clarifying questions first\n- \"What technology should I use? (React/Vue/etc.)\"\n- \"Should this be frontend or backend?\"\n\n**If step fails (e.g., file creation error):**\n- Report error with details\n- **USE `AskUserQuestion`:** \"Retry this step? (Yes/Skip/Abort)\"\n- If Abort: Stop execution and summarize what was completed\n\n**If user says \"No\" to continue:**\n- Summarize completed steps\n- **USE `AskUserQuestion`:** \"Would you like to resume later or abort?\"\n- Save progress context if possible\n\n**If step limit exceeded (>20 steps):**\n- Warn: \"⚠️ This task has >20 steps. Consider breaking it into smaller tasks.\"\n- Ask: \"Continue anyway or split the task?\"\n\n# Success Criteria\n\n- [ ] Task broken into clear atomic steps\n- [ ] Each step executed only after approval\n- [ ] Progress visible at each stage\n- [ ] Final summary provided\n- [ ] User knows what to do next\n"},"lastSynced":"2026-03-08T02:02:38.194Z","agentAnalysis":{"suitability":{"en":"Perfect for Methodical Agents needing controlled and transparent task execution via the AskUserQuestion tool.","zh":"非常适合需要通过AskUserQuestion工具进行受控和透明任务执行的方法论代理。","ja":"AskUserQuestionツールを使用して制御された透明なタスク実行が必要な方法論エージェントに適しています。","ko":"AskUserQuestion 도구를 통해 제어되고 투명한 작업 실행이 필요한 방법론 에이전트에 적합합니다.","es":"Perfecto para Agentes Metódicos que necesitan una ejecución de tareas controlada y transparente a través de la herramienta AskUserQuestion.","fr":"Parfait pour les Agents Méthodiques ayant besoin d''une exécution de tâches contrôlée et transparente via l''outil AskUserQuestion.","de":"Perfekt für methodische Agenten, die eine kontrollierte und transparente Aufgabenausführung über das Tool AskUserQuestion benötigen.","pt":"Perfeito para Agentes Metodológicos que necessitam de execução de tarefas controlada e transparente via a ferramenta AskUserQuestion.","ru":"Идеально подходит для Методичных Агентов, требующих контролируемого и прозрачного выполнения задач с помощью инструмента AskUserQuestion.","ar":"مثالي للوكلاء المنهجيين الذين يحتاجون إلى تنفيذ مهام مراقب وشفاف من خلال أداة AskUserQuestion."},"recommendation":{"en":"Empowers agents to execute tasks one step at a time, utilizing AskUserQuestion for user interactions and approval, ensuring transparent and controlled workflow management with explicit user consent via protocols like step continuation and error recovery.","zh":"赋予代理执行任务的能力，一步一步地利用AskUserQuestion进行用户交互和批准，确保透明和受控的工作流管理，通过协议如步骤继续和错误恢复获得显式用户同意。","ja":"エージェントにタスクを1ステップずつ実行する能力を与え、AskUserQuestionを使用してユーザーとのやり取りや承認を行い、明示的なユーザー同意を得ることで透明性と制御されたワークフローの管理を可能にします。","ko":"에이전트가 작업을 하나씩 실행할 수 있는 능력을 부여하여 AskUserQuestion를 사용하여 사용자와의 상호작용 및 승인을 수행하고, 명시적인 사용자 동의를 통해 투명하고 제어되는 워크플로우 관리를 보장합니다.","es":"Habilita a los agentes a ejecutar tareas paso a paso, utilizando AskUserQuestion para las interacciones con el usuario y la aprobación, garantizando una gestión de flujo de trabajo transparente y controlada con consentimiento explícito del usuario a través de protocolos como la continuación de pasos y la recuperación de errores.","fr":"Permet aux agents d''exécuter des tâches étape par étape, en utilisant AskUserQuestion pour les interactions avec l''utilisateur et l''approbation, assurant une gestion de flux de travail transparente et contrôlée avec un consentement explicite de l''utilisateur via des protocoles tels que la poursuite d''étapes et la récupération d''erreurs.","de":"Ermächtigt Agenten, Aufgaben schrittweise auszuführen, indem AskUserQuestion für Benutzerinteraktionen und Genehmigung verwendet wird, und stellt so eine transparente und kontrollierte Workflow-Verwaltung mit expliziter Benutzerzustimmung über Protokolle wie Schritterweiterung und Fehlertoleranz sicher.","pt":"Habilita os agentes a executar tarefas passo a passo, utilizando AskUserQuestion para interações com o usuário e aprovação, garantindo gestão de fluxo de trabalho transparente e controlada com consentimento explícito do usuário via protocolos como continuação de passo e recuperação de erros.","ru":"Позволяет агентам выполнять задачи шаг за шагом, используя AskUserQuestion для взаимодействия с пользователем и утверждения, обеспечивая прозрачное и контролируемое управление рабочим процессом с явным согласием пользователя через протоколы, такие как продолжение шага и восстановление после ошибок.","ar":"تمكّن الوكلاء من تنفيذ المهام خطوة بخطوة، مستخدمين AskUserQuestion للتفاعلات مع المستخدم والموافقة، مما يضمن إدارة تدفق عمل شفافة ومراقبة مع موافقة المستخدم الصريحة من خلال بروتوكولات مثل استمرار الخطوة واستعادة الخطأ."},"useCases":{"en":["Executing complex workflows with explicit user approval","Debugging tasks through step-by-step analysis and user clarification","Automating processes with transparent plan approval and modification"],"zh":["执行需要显式用户批准的复杂工作流程","通过一步一步的分析和用户澄清进行任务调试","通过透明的计划批准和修改实现自动化过程"],"ja":["明示的なユーザー承認を必要とする複雑なワークフローを実行する","ステップバイステップの分析とユーザーの明確化を通じてタスクのデバッグを行う","透明な計画の承認と変更を通じて自動化プロセスを実現する"],"ko":["명시적인 사용자 승인을 필요로 하는 복잡한 워크플로우를 실행하는 것","一步一步의 분석과 사용자의 명확화를 통해 작업 디버깅을 수행하는 것","투명한 계획 승인 및 수정을 통해 자동화 프로세스를 구현하는 것"],"es":["Ejecutar flujos de trabajo complejos con aprobación explícita del usuario","Depurar tareas a través de un análisis y aclaración paso a paso del usuario","Automatizar procesos con aprobación y modificación transparente de planes"],"fr":["Exécuter des flux de travail complexes avec approbation explicite de l''utilisateur","Déboguer des tâches à travers une analyse et une clarification étape par étape de l''utilisateur","Automatiser des processus avec approbation et modification transparente de plans"],"de":["Ausführen komplexer Workflows mit expliziter Benutzerzustimmung","Debuggen von Aufgaben durch schrittweise Analyse und Benutzerklärung","Automatisieren von Prozessen mit transparenter Planzustimmung und -modifikation"],"pt":["Execução de fluxos de trabalho complexos com aprovação explícita do usuário","Depuração de tarefas por meio de análise passo a passo e esclarecimento do usuário","Automação de processos com aprovação e modificação de planos transparentes"],"ru":["Выполнение сложных рабочих процессов с явным одобрением пользователя","Отладка задач посредством пошагового анализа и уточнения пользователя","Автоматизация процессов с прозрачным одобрением и изменением планов"],"ar":["تنفيذ سلاسل عمل معقدة مع موافقة المستخدم الصريحة","تصحيح أخطاء المهام من خلال التحليل الخطوة بخطوة وتوضيح المستخدم","تأتمة العمليات مع موافقة وتعديل خطط شفافة"]},"limitations":{"en":["Requires explicit user approval via AskUserQuestion for each step","Mandatory use of AskUserQuestion tool for all user interactions","Execution limited to one step at a time"],"zh":["需要通过AskUserQuestion为每个步骤获得显式用户批准","必须使用AskUserQuestion工具进行所有用户交互","执行仅限于一步一步"],"ja":["各ステップごとにAskUserQuestionを使用して明示的なユーザー承認を必要とする","すべてのユーザーとのやり取りにAskUserQuestionツールを使用する必要がある","実行は1ステップずつに限定される"],"ko":["각 단계에서 AskUserQuestion를 통해 명시적인 사용자 승인을 필요로 함","모든 사용자 상호작용에 AskUserQuestion 도구를 사용해야 함","실행은 하나의 단계씩으로 제한됨"],"es":["Requiere aprobación explícita del usuario a través de AskUserQuestion para cada paso","Uso obligatorio de la herramienta AskUserQuestion para todas las interacciones con el usuario","Ejecución limitada a un paso a la vez"],"fr":["Nécessite une approbation explicite de l''utilisateur via AskUserQuestion pour chaque étape","Utilisation obligatoire de l''outil AskUserQuestion pour toutes les interactions avec l''utilisateur","Exécution limitée à une étape à la fois"],"de":["Erfordert explizite Benutzerzustimmung über AskUserQuestion für jeden Schritt","Verpflichtende Verwendung des Tools AskUserQuestion für alle Benutzerinteraktionen","Ausführung beschränkt auf einen Schritt auf einmal"],"pt":["Exige aprovação explícita do usuário via AskUserQuestion para cada passo","Uso obrigatório da ferramenta AskUserQuestion para todas as interações com o usuário","Execução limitada a um passo de cada vez"],"ru":["Требует явного одобрения пользователя через AskUserQuestion для каждого шага","Обязательное использование инструмента AskUserQuestion для всех взаимодействий с пользователем","Выполнение ограничено одним шагом за раз"],"ar":["يتطلب موافقة المستخدم الصريحة من خلال AskUserQuestion لكل خطوة","استخدام إجباري لأداة AskUserQuestion لجميع التفاعلات مع المستخدم","التنفيذ مقيد بخطوة واحدة في كل مرة"]},"version":4},"contentHash":"2a19f25063b54ff2244ed6f87484d660cde958712d88d36f30cf8a9f4cc4bc57","qualityScore":45}');
