INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('untangledfinance/untangled-web/pptx', 'pptx', 'untangledfinance', 'untangled-web', 'community', 'pptx untangledfinance untangled-web community The pptx skill enables AI agents to create, edit, and analyze PPTX files, a ZIP archive containing XML files and resources, benefiting developers and users alike. PPTX 框架是一种用于构建 web 应用的工具，支持 PPTX 文件的创建、编辑和分析 PPTX フレームワークは、Web アプリケーションを構築するためのツールで、PPTX ファイルの作成、編集、分析をサポートします PPTX 프레임워크는 웹 애플리케이션을 구축하기 위한 도구로 PPTX 파일의 생성, 편집 및 분석을 지원합니다 PPTX es un framework para construir aplicaciones web en la plataforma Untangled, que permite la creación, edición y análisis de archivos PPTX PPTX est un framework pour construire des applications web sur la plateforme Untangled, qui permet la création, l''édition et l''analyse de fichiers PPTX PPTX ist ein Framework zum Erstellen von Webanwendungen auf der Untangled-Plattform, das die Erstellung, Bearbeitung und Analyse von PPTX-Dateien ermöglicht O PPTX é um framework para construir aplicações web na plataforma Untangled, permitindo a criação, edição e análise de apresentações PPTX - это фреймворк для построения веб-приложений на платформе Untangled, позволяющий создавать, редактировать и анализировать презентации PPTX هو إطار عمل لإنشاء تطبيقات الويب على منصة Untangled، مما يسمح بإنشاء وتحرير وعرض العروض التقديمية how to use pptx what is pptx pptx alternative pptx vs openxml pptx install pptx setup guide pptx file format pptx creation and editing pptx analysis and text extraction PPTX 框架 PPTX 文件创建 PPTX 文件编辑 PPTX 文件分析 Untangled 平台 web 应用开发 ZIP 档案 XML 文件 markdown 转换 Converts PPTX documents to markdown for text extraction Reads and analyzes the contents of a .pptx file Utilizes ZIP archive and XML files for PPTX creation and editing Supports different tools and workflows for various tasks Enables text extraction from PPTX files using markdown conversion pptx is a framework for building web applications and working with PPTX files, a file format used for presentations.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('nevir/agentfill/skill', 'community', 'nevir', 'agentfill', 'nevir/agentfill', 'skill', 0, 0, 45, '2026-03-08T01:57:15.326Z', '2026-03-08T02:03:04.035Z', '2a832e482ce790961b446226bc13d0ed7701facf32c522ced914c06eefa6c5ac', '{"id":"nevir/agentfill/skill","name":"skill","description":{"en":"The skill standardizes and centralizes AGENTS.md configuration, enabling portable agent skills that work across various agents, including Claude Code and Gemini CLI.","zh":"Skill是一个polyfill，标准化和集中管理AGENTS.md配置和Agent Skills支持，跨多个平台","ja":"SkillはPolyfillで、AGENTS.mdの設定とAgent Skillsのサポートを標準化し、複数のプラットフォームで利用","ko":"스킬은 폴리필로서 AGENTS.md 설정과 에이전트 스킬 지원을 표준화하고 여러 플랫폼에서 사용","es":"El skill de polyfill estandariza y centraliza la configuración de AGENTS.md y el soporte de habilidades de agentes en tu repositorio","fr":"Le skill de polyfill standardise et centralise la configuration de AGENTS.md et le support des compétences d''agents dans votre référentiel","de":"Das Polyfill-Skill standardisiert und zentralisiert die Konfiguration von AGENTS.md und die Unterstützung von Agentenfähigkeiten in Ihrem Repository","pt":"O polyfill de habilidades de agente é uma ferramenta que standardiza e centraliza a configuração de habilidades de agente em seu repositório","ru":"Polyfill навыков агента - это инструмент, который стандартизирует и централизует настройку навыков ИИ агентов в вашем репозитории","ar":"polyfill مهارات الوكيل هو أداة تقوم بتوحيد وتسهيل إعداد مهارات الوكيل في مستودعك"},"seo":{"title":{"en":"Skill: Standardize Agent Configuration for AI Agents | AI...","zh":"AI工具Skill配置指南","ja":"AIエージェントSkill設定ガイド","ko":"AI 에이전트 Skill 설정 가이드","es":"Guía de configuración de habilidades de agentes AI","fr":"Guide de configuration des compétences d''agents IA","de":"Konfigurationsleitfaden für KI-Agentenfähigkeiten","pt":"Guia de Configuração de Habilidades de Agente","ru":"Настройка Навыков ИИ Агентов","ar":"دليل إعداد مهارات الوكيل"},"description":{"en":"Discover how to centralize AGENTS.md configuration and unlock seamless Agent Skills support across Claude Code, Gemini CLI, and more - get started now!","zh":"标准化和集中管理AGENTS.md配置和Agent Skills支持，跨Claude Code、Gemini CLI等平台","ja":"AGENTS.mdの設定とAgent Skillsのサポートを標準化し、Claude Code、Gemini CLIなどのプラットフォームで利用","ko":"AGENTS.md 설정과 에이전트 스킬 지원을 표준화하고 Claude Code, Gemini CLI 등의 플랫폼에서 사용","es":"Aprende a configurar y actualizar habilidades de agentes en tu repositorio con nuestra guía paso a paso para desarrolladores","fr":"Découvrez comment configurer et mettre à jour les compétences d''agents dans votre référentiel avec notre guide étape par étape pour les développeurs","de":"Erfahren Sie, wie Sie Agentenfähigkeiten in Ihrem Repository konfigurieren und aktualisieren können, mit unserer Schritt-für-Schritt-Anleitung für Entwickler","pt":"Aprenda a configurar habilidades de agente portáteis em seu repositório com o polyfill de habilidades de agente","ru":"Узнайте, как настроить переносные навыки ИИ агентов в вашем репозитории с помощью polyfill навыков агента","ar":"تعرف على كيفية إعداد مهارات وكيل قابلة للنقل في مستودعك باستخدام polyfill مهارات الوكيل"},"definition":{"en":"Skill is a polyfill that standardizes AGENTS.md configuration and Agent Skills support within a repository.","zh":"Skill是标准化和集中管理AGENTS.md配置和Agent Skills支持的Polyfill","ja":"SkillはAGENTS.mdの設定とAgent Skillsのサポートを標準化するPolyfill","ko":"스킬은 AGENTS.md 설정과 에이전트 스킬 지원을 표준화하는 폴리필","es":"Un polyfill que estandariza la configuración de habilidades de agentes AI en un repositorio","fr":"Un polyfill qui standardise la configuration des compétences d''agents IA dans un référentiel","de":"Ein Polyfill, der die Konfiguration von KI-Agentenfähigkeiten in einem Repository standardisiert","pt":"Polyfill de habilidades de agente é uma ferramenta que permite criar e atualizar habilidades de agente portáteis","ru":"Polyfill навыков агента - это инструмент, который позволяет создавать и обновлять переносные навыки ИИ агентов","ar":"polyfill مهارات الوكيل هو أداة تسمح بإنشاء وتحديث مهارات وكيل قابلة للنقل"},"features":{"en":["Creates or updates portable agent skills in .agents/skills/","Supports Agent Skills specification","Works across Claude Code, Gemini CLI, and other agents","Enables creation of new skills or updating existing ones","Follows a full workflow for creating new skills","Reads existing SKILL.md and supporting files for updates"],"zh":["跨Claude Code、Gemini CLI等平台支持","标准化AGENTS.md配置","集中管理Agent Skills支持","支持创建和更新portable agent skills","兼容多种Agent Skills specification"],"ja":["Claude Code、Gemini CLIなどのプラットフォームで利用","AGENTS.mdの設定を標準化","Agent Skillsのサポートを集中管理","portable agent skillsの作成と更新をサポート","複数のAgent Skills specificationに対応"],"ko":["클라우드 코드, 젬리니 CLI 등의 플랫폼에서 사용","AGENTS.md 설정을 표준화","에이전트 스킬 지원을集中 관리","이동식 에이전트 스킬의 생성과 업데이트 지원","여러 에이전트 스킬 사양에 대응"],"es":["Creación y actualización de habilidades de agentes portátiles en `.agents/skills/`","Soporte para Claude Code, Gemini CLI y otros agentes que siguen la especificación de habilidades de agentes","Configuración centralizada de AGENTS.md","Compatibilidad con múltiples agentes y tecnologías","Actualización de habilidades existentes en `.agents/skills/`"],"fr":["Création et mise à jour de compétences d''agents portables dans `.agents/skills/`","Prise en charge de Claude Code, Gemini CLI et d''autres agents qui suivent la spécification des compétences d''agents","Configuration centralisée de AGENTS.md","Compatibilité avec plusieurs agents et technologies","Mise à jour de compétences existantes dans `.agents/skills/`"],"de":["Erstellung und Aktualisierung von portablen Agentenfähigkeiten in `.agents/skills/`","Unterstützung für Claude Code, Gemini CLI und andere Agenten, die die Agentenfähigkeitsspezifikation einhalten","Zentralisierte Konfiguration von AGENTS.md","Kompatibilität mit mehreren Agenten und Technologien","Aktualisierung von bestehenden Fähigkeiten in `.agents/skills/`"],"pt":["Criação de habilidades de agente portáteis","Suporte a múltiplos agentes, incluindo Claude Code e Gemini CLI","Compatibilidade com a especificação de habilidades de agente","Atualização de habilidades de agente existentes","Trabalho com arquivos em `.agents/skills/`"],"ru":["Создание переносных навыков ИИ агентов","Поддержка нескольких агентов, включая Claude Code и Gemini CLI","Совместимость с спецификацией навыков агента","Обновление существующих навыков ИИ агентов","Работа с файлами в `.agents/skills/`"],"ar":["إنشاء مهارات وكيل قابلة للنقل","دعم عدة وكلاء، بما في ذلك Claude Code وGemini CLI","التوافق مع مواصفات مهارات الوكيل","تحديث مهارات الوكيل الحالية","العمل مع الملفات في `.agents/skills/`"]},"keywords":{"en":["how to use skill","what is skill","skill alternative","skill vs agent skills","skill install guide","skill setup for AI agents","Agent Skills specification","Claude Code integration","Gemini CLI support"],"zh":["AI工具","Agent Skills","AGENTS.md","Polyfill","Claude Code","Gemini CLI","AIエージェント开发","AI工具配置"],"ja":["AIエージェント","Agent Skills","AGENTS.md","Polyfill","Claude Code","Gemini CLI","AIエージェント開発","AIツール設定"],"ko":["AI 에이전트","에이전트 스킬","AGENTS.md","폴리필","클라우드 코드","젬리니 CLI","AI 에이전트 개발","AI 툴 설정"],"es":["habilidades de agentes AI","polyfill","configuración de AGENTS.md","Claude Code","Gemini CLI","especificación de habilidades de agentes","desarrollo de agentes","tecnologías de agentes","integración de agentes"],"fr":["compétences d''agents IA","polyfill","configuration de AGENTS.md","Claude Code","Gemini CLI","spécification des compétences d''agents","développement d''agents","technologies d''agents","intégration d''agents"],"de":["KI-Agentenfähigkeiten","Polyfill","Konfiguration von AGENTS.md","Claude Code","Gemini CLI","Agentenfähigkeitsspezifikation","Agentenentwicklung","Agententechnologien","Agentenintegration"],"pt":["habilidades de agente","polyfill de habilidades de agente","configuração de habilidades de agente","agentes de IA","ferramentas de agente","desenvolvimento de habilidades de agente","criação de habilidades de agente","atualização de habilidades de agente"],"ru":["навыки ИИ агентов","polyfill навыков агента","настройка навыков ИИ агентов","ИИ агенты","инструменты агента","разработка навыков ИИ агентов","создание навыков ИИ агентов","обновление навыков ИИ агентов"],"ar":["مهارات الوكيل","polyfill مهارات الوكيل","إعداد مهارات الوكيل","وكلاء الذكاء الاصطناعي","أدوات الوكيل","تطوير مهارات الوكيل","إنشاء مهارات الوكيل","تحديث مهارات الوكيل"]}},"owner":"nevir","repo":"agentfill","repoPath":"nevir/agentfill","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.326Z","topics":[],"category":"community","skillMd":{"name":"skill","description":">-","bodyPreview":"# /skill\n\nCreate or update portable agent skills in `.agents/skills/` that work across Claude Code, Gemini CLI, and other agents supporting the [Agent Skills specification](https://agentskills.io).\n\n## Determine the Mode\n\n**Creating a new skill** — the user wants a skill that doesn''t exist yet. Follow the full workflow below.\n\n**Updating an existing skill** — the user wants to modify a skill in `.agents/skills/`. Read the existing SKILL.md and supporting files first, then apply changes following","body":"# /skill\n\nCreate or update portable agent skills in `.agents/skills/` that work across Claude Code, Gemini CLI, and other agents supporting the [Agent Skills specification](https://agentskills.io).\n\n## Determine the Mode\n\n**Creating a new skill** — the user wants a skill that doesn''t exist yet. Follow the full workflow below.\n\n**Updating an existing skill** — the user wants to modify a skill in `.agents/skills/`. Read the existing SKILL.md and supporting files first, then apply changes following the same quality principles.\n\n## Creating a New Skill\n\n### Step 1: Understand\n\nAsk the user to describe what they want the skill to do. Gather:\n\n- **Purpose**: What task does this skill help with?\n- **Trigger**: When should an agent activate this skill? What would the user say?\n- **Examples**: 2-3 concrete examples of the skill in action (input/output or before/after)\n\nIf the user is vague, suggest concrete examples to refine the scope. A good skill is focused — it does one thing well. If the request covers multiple distinct tasks, suggest splitting into separate skills.\n\n### Step 2: Research\n\nBefore writing the skill:\n\n- Search for existing patterns, conventions, and code related to the skill''s domain\n- Check `.agents/skills/` for existing skills that might overlap\n- Identify project-specific conventions the skill should follow\n- Note any tools, scripts, or references the skill might need to bundle\n\n### Step 3: Plan\n\nDesign the skill and present the plan to the user before writing:\n\n- **Name**: lowercase-hyphenated, 1-64 characters, descriptive. This becomes the `/slash-command`.\n- **Description**: 1-2 sentences covering WHAT it does and WHEN to use it. Include keywords matching how users naturally phrase the request. This is the most important field — it determines when agents auto-activate the skill.\n- **Instructions outline**: Key steps, rules, and examples. Only include information the agent doesn''t already know.\n- **Supporting files**: Decide what goes in SKILL.md vs `references/`:\n  - **In SKILL.md**: Rules and content the agent needs in every or most activations\n  - **In references/**: Content needed only in specific scenarios (e.g., \"when creating a new script from scratch\")\n  - Each reference file needs a clear trigger condition — not just \"overflow\"\n  - Multiple focused files are better than one monolithic reference\n\n### Step 4: Create\n\nCreate the skill directory and files:\n\n1. Create `.agents/skills/<name>/`\n2. Write `SKILL.md` with YAML frontmatter and markdown body\n3. Add supporting files as needed (`references/`, `scripts/`, `assets/`)\n\nUse the SKILL.md template below. For the full frontmatter reference, read `references/skill-specification.md`.\n\n**SKILL.md template:**\n\n```yaml\n---\nname: <lowercase-hyphenated-name>\ndescription: >-\n  <What it does>. <When to use it — include trigger keywords>.\n---\n\n# <Skill Title>\n\n<Brief overview — 1-2 sentences.>\n\n## <Main workflow or instructions>\n\n<Steps, rules, examples. Only include what the agent doesn''t already know.>\n```\n\n**Key rules:**\n- Keep the body under 500 lines (aim for under 200 for workflow skills; up to 400 for style/rules skills)\n- Use universal frontmatter fields (`name`, `description`) for portability\n- Agent-specific fields (like Claude''s `allowed-tools`) are safe to add but will be ignored by other agents\n- Use input/output examples — they''re more effective than descriptions\n- Reference supporting files from the body so the agent knows when to load them\n\n### Step 5: Validate\n\nRun the validation script to check structure and frontmatter:\n\n```sh\n.agents/skills/skill/scripts/validate-skill.sh .agents/skills/<name>\n```\n\nAlso verify manually:\n\n- [ ] `name` is lowercase-hyphenated, 1-64 characters\n- [ ] `description` explains WHAT and WHEN (includes trigger keywords)\n- [ ] Body is focused — no information the agent already knows\n- [ ] No unnecessary agent-specific assumptions in instructions\n- [ ] Supporting files are referenced from SKILL.md\n- [ ] Scripts are executable (`chmod +x`)\n\n### Step 6: Test\n\nSuggest the user test the skill:\n\n1. Start a new agent session (skills are discovered at session start)\n2. Ask the agent to perform the task the skill handles\n3. Verify the skill activates and produces correct results\n4. If it doesn''t activate, check the description for missing trigger keywords\n\n## Updating an Existing Skill\n\n1. **Read** the existing SKILL.md and all supporting files\n2. **Understand** what changes are needed and why\n3. **Update** the files, keeping the same quality principles (conciseness, portability, good description)\n4. **Validate** with the validation script\n5. **Note**: Claude Code hot-reloads skill changes (v2.1.0+) — no restart needed\n\n## Design Principles\n\n### Description Quality Matters Most\n\nThe description determines whether agents auto-activate the skill. Write it as if explaining to a colleague when they should reach for this tool. Include the 3-5 most natural phrasings a user would use.\n\n### Concise is Key\n\nOnly include information the agent doesn''t already know. If the agent can figure something out from context, don''t spell it out. Challenge every paragraph.\n\n### Portability First\n\nSkills in `.agents/skills/` are shared across all configured agents. Stick to universal frontmatter fields. Describe actions rather than naming agent-specific tools. Use forward slashes for paths.\n\n### One Skill, One Job\n\nEach skill should have a focused purpose. If a skill tries to do too many things, it will either trigger too broadly or its instructions will be too vague to be useful. Split into separate skills instead.\n\n### Right-Size Your References\n\nNot all content belongs in `references/`. If the agent needs content in most activations, it belongs in SKILL.md. Reference files are for content needed only in specific scenarios.\n\n**In SKILL.md** (loaded every activation):\n- Core rules, conventions, and patterns\n- Examples of correct/incorrect usage\n- Common decision guidance\n\n**In focused reference files** (loaded on demand):\n- Full code templates (e.g., \"read when creating a new script from scratch\")\n- Detailed rules for uncommon scenarios (e.g., \"read when formatting tables\")\n- Extended examples for edge cases\n\n**Reference file guidelines:**\n- Each file should have a clear load trigger stated in SKILL.md\n- Name files by scenario: `new-script-template.md` not `full-guide.md`\n- Multiple small files (50-150 lines each) beat one large file\n- A reference that''s always loaded defeats the purpose — merge it into SKILL.md\n"},"lastSynced":"2026-03-08T02:03:04.035Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing portable and standardized skill configurations across various platforms, including Claude Code and Gemini CLI.","zh":"非常适合需要在各个平台（包括 Claude Code 和 Gemini CLI）上实现便携和标准化技能配置的 AI Agent。","ja":"様々なプラットフォーム（Claude Code および Gemini CLI を含む）でポータブルで標準化されたスキル設定が必要な AI エージェントに最適です。","ko":"클라우드 코드 및 제미니 CLI를 포함한 다양한 플랫폼에서 이식 가능하고 표준화된 스킬 구성을 필요로 하는 AI 에이전트에 적합합니다.","es":"Perfecto para agentes de IA que necesitan configuraciones de habilidades portátiles y estandarizadas en varias plataformas, incluyendo Claude Code y Gemini CLI.","fr":"Parfait pour les agents IA ayant besoin de configurations de compétences portables et standardisées sur différentes plateformes, notamment Claude Code et Gemini CLI.","de":"Perfekt für KI-Agents, die portable und standardisierte Fähigkeitskonfigurationen über verschiedene Plattformen hinweg benötigen, einschließlich Claude Code und Gemini CLI.","pt":"Perfeito para Agentes de IA que precisam de configurações de habilidades portáteis e padronizadas em várias plataformas, incluindo Claude Code e Gemini CLI.","ru":"Идеально для ИИ-агентов, которым необходимы переносные и стандартизированные конфигурации навыков на различных платформах, включая Claude Code и Gemini CLI.","ar":"مثالي للموكلين الذكيين الذين يحتاجون إلى إعدادات مهارات قابلة للنقل ومتوافقة عبر منصات مختلفة، بما في ذلك Claude Code وGemini CLI."},"recommendation":{"en":"Empowers agents to create and manage portable skills using the Agent Skills specification, supporting seamless integration with multiple agents and enabling efficient skill development and deployment using .agents/skills/ directory and AGENTS.md configuration.","zh":"赋予代理创建和管理便携式技能的能力，使用 Agent Skills 规范，支持与多个代理的无缝集成，并使用 .agents/skills/ 目录和 AGENTS.md 配置实现高效的技能开发和部署。","ja":"エージェント スキル仕様を使用して、エージェントがポータブル スキルを作成および管理できるようにし、複数のエージェントとのシームレスな統合をサポートし、.agents/skills/ ディレクトリおよび AGENTS.md 構成を使用して効率的なスキル開発およびデプロイを可能にします。","ko":"에이전트가 에이전트 스킬 사양을 사용하여 이식 가능한 스킬을 만들고 관리할 수 있도록 해주며, 여러 에이전트와의 무縫한 통합을 지원하며, .agents/skills/ 디렉토리 및 AGENTS.md 구성으로 효율적인 스킬 개발 및 배포를 가능하게 합니다.","es":"Permite a los agentes crear y administrar habilidades portátiles utilizando la especificación de habilidades del agente, lo que admite una integración sin problemas con varios agentes y permite un desarrollo y despliegue eficientes de habilidades utilizando el directorio .agents/skills/ y la configuración de AGENTS.md.","fr":"Permet aux agents de créer et de gérer des compétences portables en utilisant la spécification des compétences de l''agent, ce qui prend en charge une intégration transparente avec de multiples agents et permet un développement et un déploiement efficaces de compétences en utilisant le répertoire .agents/skills/ et la configuration de AGENTS.md.","de":"Ermöglicht es Agents, portable Fähigkeiten zu erstellen und zu verwalten, indem sie die Fähigkeits-Spezifikation des Agents verwenden, was eine nahtlose Integration mit mehreren Agents ermöglicht und einen effizienten Fähigkeits-Entwicklung und -Einsatz unter Verwendung des Verzeichnisses .agents/skills/ und der Konfiguration von AGENTS.md ermöglicht.","pt":"Habilita os agentes a criar e gerenciar habilidades portáteis usando a especificação de Habilidades do Agente, suportando integração transparente com vários agentes e permitindo desenvolvimento e implantação eficientes de habilidades usando o diretório .agents/skills/ e a configuração AGENTS.md.","ru":"Предоставляет агентам возможность создавать и управлять переносными навыками с использованием спецификации навыков агента, поддерживая бесшовную интеграцию с несколькими агентами и позволяя эффективно разрабатывать и развертывать навыки с использованием каталога .agents/skills/ и конфигурации AGENTS.md.","ar":"تمكّن الوكلاء من إنشاء إدارة مهارات قابلة للنقل باستخدام مواصفات مهارات الوكيل، داعمة للتكامل السلس مع عدة وكلاء وتمكين تطوير و 部署 كفء للمهارات باستخدام دليل .agents/skills/ و إعدادات AGENTS.md."},"useCases":{"en":["Creating new portable agent skills","Updating existing skills for compatibility across agents","Standardizing skill configurations for efficient deployment"],"zh":["创建新的便携式代理技能","更新现有技能以实现代理之间的兼容性","标准化技能配置以实现高效部署"],"ja":["新しいポータブル エージェント スキルの作成","既存のスキルの更新によるエージェント間の互換性の確保","スキル構成の標準化による効率的なデプロイ"],"ko":["新的便携式 에이전트 스킬 생성","既存 스킬의 업데이트를 통해 에이전트 간의 호환성 보장","스킬 구성의 표준화를 통한 효율적인 배포"],"es":["Crear nuevas habilidades de agente portátiles","Actualizar habilidades existentes para la compatibilidad entre agentes","Estandarizar configuraciones de habilidades para un despliegue eficiente"],"fr":["Créer de nouvelles compétences d''agent portables","Mettre à jour des compétences existantes pour la compatibilité entre agents","Standardiser les configurations de compétences pour un déploiement efficace"],"de":["Erstellen neuer portabler Agentenfähigkeiten","Aktualisieren bestehender Fähigkeiten für die Kompatibilität zwischen Agents","Standardisieren von Fähigkeitskonfigurationen für einen effizienten Einsatz"],"pt":["Criar novas habilidades de agente portáteis","Atualizar habilidades existentes para compatibilidade entre agentes","Padronizar configurações de habilidades para implantação eficiente"],"ru":["Создание новых переносных навыков агента","Обновление существующих навыков для совместимости между агентами","Стандартизация конфигураций навыков для эффективного развертывания"],"ar":["إنشاء مهارات وكلاء قابلة للنقل جديدة","تحديث المهارات الحالية لتوافقها بين الوكلاء","توحيد إعدادات المهارات من أجل نشر فعال"]},"limitations":{"en":["Requires adherence to Agent Skills specification","Limited to agents supporting the specification"],"zh":["需要遵守 Agent Skills 规范","仅限支持规范的代理"],"ja":["エージェント スキル仕様への準拠が必要","仕様をサポートするエージェントのみ"],"ko":["에이전트 스킬 사양을 준수해야 함","사양을 지원하는 에이전트만 해당"],"es":["Requiere el cumplimiento de la especificación de habilidades del agente","Limitado a agentes que admiten la especificación"],"fr":["Nécessite le respect de la spécification des compétences de l''agent","Limité aux agents prenant en charge la spécification"],"de":["Erfordert die Einhaltung der Fähigkeits-Spezifikation des Agents","Begrenzt auf Agents, die die Spezifikation unterstützen"],"pt":["Exige aderência à especificação de Habilidades do Agente","Limitado a agentes que suportam a especificação"],"ru":["Требует соблюдения спецификации навыков агента","Ограничен агентами, поддерживающими спецификацию"],"ar":["يتطلب الالتزام بمواصفات مهارات الوكيل","محدود بالوكلاء الذين يدعمون المواصفة"]},"version":4},"contentHash":"2a832e482ce790961b446226bc13d0ed7701facf32c522ced914c06eefa6c5ac","qualityScore":45}');
