INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('nevir/agentfill/skill', 'skill', 'nevir', 'agentfill', 'community', 'skill nevir agentfill community The skill standardizes and centralizes AGENTS.md configuration, enabling portable agent skills that work across various agents, including Claude Code and Gemini CLI. Skill是一个polyfill，标准化和集中管理AGENTS.md配置和Agent Skills支持，跨多个平台 SkillはPolyfillで、AGENTS.mdの設定とAgent Skillsのサポートを標準化し、複数のプラットフォームで利用 스킬은 폴리필로서 AGENTS.md 설정과 에이전트 스킬 지원을 표준화하고 여러 플랫폼에서 사용 El skill de polyfill estandariza y centraliza la configuración de AGENTS.md y el soporte de habilidades de agentes en tu repositorio Le skill de polyfill standardise et centralise la configuration de AGENTS.md et le support des compétences d''agents dans votre référentiel Das Polyfill-Skill standardisiert und zentralisiert die Konfiguration von AGENTS.md und die Unterstützung von Agentenfähigkeiten in Ihrem Repository O polyfill de habilidades de agente é uma ferramenta que standardiza e centraliza a configuração de habilidades de agente em seu repositório Polyfill навыков агента - это инструмент, который стандартизирует и централизует настройку навыков ИИ агентов в вашем репозитории polyfill مهارات الوكيل هو أداة تقوم بتوحيد وتسهيل إعداد مهارات الوكيل في مستودعك how to use skill what is skill skill alternative skill vs agent skills skill install guide skill setup for AI agents Agent Skills specification Claude Code integration Gemini CLI support AI工具 Agent Skills AGENTS.md Polyfill Claude Code Gemini CLI AIエージェント开发 AI工具配置 Creates or updates portable agent skills in .agents/skills/ Supports Agent Skills specification Works across Claude Code, Gemini CLI, and other agents Enables creation of new skills or updating existing ones Follows a full workflow for creating new skills Reads existing SKILL.md and supporting files for updates Skill is a polyfill that standardizes AGENTS.md configuration and Agent Skills support within a repository.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mindfold-ai/Trellis/onboard', 'community', 'mindfold-ai', 'Trellis', 'mindfold-ai/Trellis', 'onboard', 0, 0, 45, '2026-03-08T01:57:15.327Z', '2026-03-08T02:03:04.210Z', 'ca110533dba054447c4e51de55af8269ad789e42704fc362cc46d03d70e69dd8', '{"id":"mindfold-ai/Trellis/onboard","name":"onboard","description":{"en":"The onboard skill is an AI framework and toolkit for Claude Code and Cursor, designed to facilitate AI-assisted workflow systems. It benefits senior developers and new team members alike by providing a comprehensive onboarding process.","zh":"Onboard是用于Claude Code和Cursor的AI框架和工具包，提供核心概念、系统结构和命令深度解析","ja":"Onboardは、Claude CodeとCursor向けのAIフレームワークとツールキットで、コアコンセプト、システム構造、コマンドの深い分析を提供します","ko":"Onboard는 Claude Code와 Cursor를 위한 AI 프레임워크와 툴킷으로,核心 개념, 시스템 구조, 명령어 深度 解析을 제공합니다","es":"El marco de trabajo de AI para Claude Code y Cursor, con una guía de configuración para onboard","fr":"L''outil de workflow d''IA pour Claude Code et Cursor, avec un guide d''intégration pour onboard","de":"Das AI-Workflowsystem für Claude Code und Cursor, mit einem Einrichtungsleitfaden für onboard","pt":"O Onboard é uma estrutura de IA completa para desenvolvedores, oferecendo uma abordagem integrada para o fluxo de trabalho de desenvolvimento.","ru":"Onboard - это комплексная структура ИИ для разработчиков, предлагающая интегрированный подход к рабочему процессу разработки.","ar":"Onboard هو إطار عمل ذكاء اصطناعي شامل للمطورين، يوفر نهجًا متكاملًا لتدفق العمل التطويري."},"seo":{"title":{"en":"onboard: AI-Assisted Workflow Setup Guide | AI Agent Skill","zh":"AIエージェント入门指南：Onboard 工作流设置","ja":"AIエージェントのOnboard設定ガイド","ko":"AI 에이전트 Onboard 설정 가이드","es":"Guía de configuración para onboard: Marco de trabajo de AI","fr":"Guide d''intégration pour onboard: Outil de workflow d''IA","de":"Einrichtungsleitfaden für onboard: AI-Workflowsystem","pt":"Guia de Configuração do Onboard: Ferramentas de IA para D...","ru":"Настройка ИИ Агентов: Руководство по Onboard для Разработ...","ar":"دليل إعداد Onboard: أدوات ذكاء اصطناعي لل مطورين"},"description":{"en":"Streamline your development workflow with onboard, an all-in-one AI framework. Learn how to onboard new team members and master AI-assisted workflow systems ...","zh":"了解Onboard AI框架和工具包，用于Claude Code和Cursor，提升开发效率","ja":"Onboard AIフレームワークとツールキットを使用して、開発効率を向上させる","ko":"Onboard AI 프레임워크와 툴킷을 사용하여 개발 효율성을 향상시키는 방법","es":"Aprende a configurar el sistema de workflow de AI asistido para tu equipo con nuestra guía de onboard","fr":"Découvrez comment configurer le système de workflow d''IA assisté pour votre équipe avec notre guide d''intégration","de":"Erfahren Sie, wie Sie das AI-Workflowsystem für Ihr Team mit unserem Einrichtungsleitfaden konfigurieren","pt":"Aprenda a configurar o Onboard, uma estrutura de IA completa para desenvolvedores, e descubra como melhorar seu fluxo de trabalho com as ferramentas certas.","ru":"Узнайте, как настроить Onboard, комплексную структуру ИИ для разработчиков, и откройте для себя, как улучшить свой рабочий процесс с помощью правильных инстр...","ar":"تعلم كيفية إعداد Onboard، إطار عمل ذكاء اصطناعي شامل للمطورين، واكتشف كيفية تحسين تدفق العمل الخاص بك باستخدام الأدوات المناسبة."},"definition":{"en":"onboard is an all-in-one AI framework and toolkit for streamlining workflow systems, particularly for Claude Code and Cursor, focusing on core concepts and command deep dives.","zh":"Onboard是用于AI-assisted工作流系统的入门指南，提供核心概念、系统结构和命令深度解析","ja":"Onboardは、AIアシストワークフローシステムの入門ガイドで、コアコンセプト、システム構造、コマンドの深い分析を提供します","ko":"Onboard는 AI 에이전트 워크플로우 시스템의 입문 가이드로, 핵심 개념, 시스템 구조, 명령어 深度 解析을 제공합니다","es":"Onboard es un marco de trabajo de AI que integra Claude Code y Cursor para agilizar el desarrollo","fr":"Onboard est un outil de workflow d''IA qui intègre Claude Code et Cursor pour accélérer le développement","de":"Onboard ist ein AI-Workflowsystem, das Claude Code und Cursor integriert, um die Entwicklung zu beschleunigen","pt":"Onboard é uma ferramenta de IA que fornece uma abordagem integrada para o fluxo de trabalho de desenvolvimento.","ru":"Onboard - это инструмент ИИ, который предоставляет интегрированный подход к рабочему процессу разработки.","ar":"Onboard هو أداة ذكاء اصطناعي توفر نهجًا متكاملًا لتدفق العمل التطويري."},"features":{"en":["Explains core philosophy and system structure for AI-assisted workflows","Provides command deep dives for comprehensive understanding","Covers critical instructions for onboarding new team members","Divided into three equally important parts for thorough learning","Mentorship and teaching approach for effective knowledge transfer","Focuses on explaining underlying principles and problem-solving at a fundamental level"],"zh":["核心概念解析","系统结构概述","命令深度解析","支持Claude Code和Cursor","AI-assisted工作流系统入门指南"],"ja":["コアコンセプトの解析","システム構造の概要","コマンドの深い分析","Claude CodeとCursorのサポート","AIアシストワークフローシステムの入門ガイド"],"ko":["핵심 개념 解析","시스템 구조 개요","명령어 深度 解析","Claude Code와 Cursor의 지원","AI 에이전트 워크플로우 시스템의 입문 가이드"],"es":["Marco de trabajo de AI para Claude Code y Cursor","Guía de configuración para onboard","Explicación de los conceptos básicos del sistema de workflow de AI","Análisis de los comandos y su función en el sistema","Integración con herramientas de desarrollo como React y Python"],"fr":["Outil de workflow d''IA pour Claude Code et Cursor","Guide d''intégration pour onboard","Explication des concepts de base du système de workflow d''IA","Analyse des commandes et de leur fonction dans le système","Intégration avec des outils de développement tels que React et Python"],"de":["AI-Workflowsystem für Claude Code und Cursor","Einrichtungsleitfaden für onboard","Erklärung der grundlegenden Konzepte des AI-Workflowsystems","Analyse der Befehle und ihrer Funktion im System","Integration mit Entwicklungstools wie React und Python"],"pt":["CORE PHILOSOPHY: Explicação dos princípios básicos do Onboard","SYSTEM STRUCTURE: Visão geral da estrutura do sistema","COMMAND DEEP DIVE: Análise aprofundada dos comandos do Onboard","Integração com Claude Code e Cursor","Suporte a fluxo de trabalho de desenvolvimento"],"ru":["CORE PHILOSOPHY: Объяснение основных принципов Onboard","SYSTEM STRUCTURE: Обзор структуры системы","COMMAND DEEP DIVE: Глубокий анализ команд Onboard","Интеграция с Claude Code и Cursor","Поддержка рабочего процесса разработки"],"ar":["CORE PHILOSOPHY: شرح المبادئ الأساسية ل Onboard","SYSTEM STRUCTURE: نظرة عامة على هيكل النظام","COMMAND DEEP DIVE: تحليل深 ل أوامر Onboard","التكامل مع Claude Code و Cursor","دعم تدفق العمل التطويري"]},"keywords":{"en":["how to use onboard","onboard setup guide","what is onboard","onboard alternative","onboard vs Claude Code","onboard install","onboard for AI agents","AI-assisted workflow systems","onboard for developers","onboard workflow toolkit"],"zh":["AIエージェント入门","Onboard工作流设置","Claude Code和Cursor","AI框架和工具包","核心概念解析","系统结构概述","命令深度解析"],"ja":["AIエージェントの入門","Onboardワークフローの設定","Claude CodeとCursor","AIフレームワークとツールキット","コアコンセプトの解析","システム構造の概要","コマンドの深い分析"],"ko":["AI 에이전트 입문","Onboard 워크플로우 설정","Claude Code와 Cursor","AI 프레임워크와 툴킷","핵심 개념 解析","시스템 구조 개요","명령어 深度 解析"],"es":["onboard AI","herramientas de AI para desarrollo","marco de trabajo de AI","guía de configuración para onboard","desarrollo de software con AI","integración de AI con React y Python"],"fr":["onboard IA","outils d''IA pour le développement","outil de workflow d''IA","guide d''intégration pour onboard","développement de logiciels avec IA","intégration d''IA avec React et Python"],"de":["onboard KI","KI-Tools für die Entwicklung","AI-Workflowsystem","Einrichtungsleitfaden für onboard","Softwareentwicklung mit KI","Integration von KI mit React und Python"],"pt":["Onboard","Ferramentas de IA","Desenvolvimento de software","Fluxo de trabalho","Integração com Claude Code","Integração com Cursor","CORE PHILOSOPHY","SYSTEM STRUCTURE","COMMAND DEEP DIVE"],"ru":["Onboard","ИИ Агенты","Разработка программного обеспечения","Рабочий процесс","Интеграция с Claude Code","Интеграция с Cursor","CORE PHILOSOPHY","SYSTEM STRUCTURE","COMMAND DEEP DIVE"],"ar":["Onboard","أدوات ذكاء اصطناعي","تطوير البرمجيات","تدفق العمل","التكامل مع Claude Code","التكامل مع Cursor","CORE PHILOSOPHY","SYSTEM STRUCTURE","COMMAND DEEP DIVE"]}},"owner":"mindfold-ai","repo":"Trellis","repoPath":"mindfold-ai/Trellis","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.327Z","topics":[],"category":"community","skillMd":{"name":"onboard","description":"You are a senior developer onboarding a new team member to this projects AI-assisted workflow system.","bodyPreview":"You are a senior developer onboarding a new team member to this project''s AI-assisted workflow system.\n\nYOUR ROLE: Be a mentor and teacher. Don''t just list steps - EXPLAIN the underlying principles, why each command exists, what problem it solves at a fundamental level.\n\n## CRITICAL INSTRUCTION - YOU MUST COMPLETE ALL SECTIONS\n\nThis onboarding has THREE equally important parts:\n\n**PART 1: Core Concepts** (Sections: CORE PHILOSOPHY, SYSTEM STRUCTURE, COMMAND DEEP DIVE)\n- Explain WHY this workflow","body":"You are a senior developer onboarding a new team member to this project''s AI-assisted workflow system.\n\nYOUR ROLE: Be a mentor and teacher. Don''t just list steps - EXPLAIN the underlying principles, why each command exists, what problem it solves at a fundamental level.\n\n## CRITICAL INSTRUCTION - YOU MUST COMPLETE ALL SECTIONS\n\nThis onboarding has THREE equally important parts:\n\n**PART 1: Core Concepts** (Sections: CORE PHILOSOPHY, SYSTEM STRUCTURE, COMMAND DEEP DIVE)\n- Explain WHY this workflow exists\n- Explain WHAT each command does and WHY\n\n**PART 2: Real-World Examples** (Section: REAL-WORLD WORKFLOW EXAMPLES)\n- Walk through ALL 5 examples in detail\n- For EACH step in EACH example, explain:\n  - PRINCIPLE: Why this step exists\n  - WHAT HAPPENS: What the command actually does\n  - IF SKIPPED: What goes wrong without it\n\n**PART 3: Customize Your Development Guidelines** (Section: CUSTOMIZE YOUR DEVELOPMENT GUIDELINES)\n- Check if project guidelines are still empty templates\n- If empty, guide the developer to fill them with project-specific content\n- Explain the customization workflow\n\nDO NOT skip any part. All three parts are essential:\n- Part 1 teaches the concepts\n- Part 2 shows how concepts work in practice\n- Part 3 ensures the project has proper guidelines for AI to follow\n\nAfter completing ALL THREE parts, ask the developer about their first task.\n\n---\n\n## CORE PHILOSOPHY: Why This Workflow Exists\n\nAI-assisted development has three fundamental challenges:\n\n### Challenge 1: AI Has No Memory\n\nEvery AI session starts with a blank slate. Unlike human engineers who accumulate project knowledge over weeks/months, AI forgets everything when a session ends.\n\n**The Problem**: Without memory, AI asks the same questions repeatedly, makes the same mistakes, and can''t build on previous work.\n\n**The Solution**: The `.trellis/workspace/` system captures what happened in each session - what was done, what was learned, what problems were solved. The `/trellis:start` command reads this history at session start, giving AI \"artificial memory.\"\n\n### Challenge 2: AI Has Generic Knowledge, Not Project-Specific Knowledge\n\nAI models are trained on millions of codebases - they know general patterns for React, TypeScript, databases, etc. But they don''t know YOUR project''s conventions.\n\n**The Problem**: AI writes code that \"works\" but doesn''t match your project''s style. It uses patterns that conflict with existing code. It makes decisions that violate unwritten team rules.\n\n**The Solution**: The `.trellis/spec/` directory contains project-specific guidelines. The `/before-*-dev` commands inject this specialized knowledge into AI context before coding starts.\n\n### Challenge 3: AI Context Window Is Limited\n\nEven after injecting guidelines, AI has limited context window. As conversation grows, earlier context (including guidelines) gets pushed out or becomes less influential.\n\n**The Problem**: AI starts following guidelines, but as the session progresses and context fills up, it \"forgets\" the rules and reverts to generic patterns.\n\n**The Solution**: The `/check-*` commands re-verify code against guidelines AFTER writing, catching drift that occurred during development. The `/trellis:finish-work` command does a final holistic review.\n\n---\n\n## SYSTEM STRUCTURE\n\n```\n.trellis/\n|-- .developer              # Your identity (gitignored)\n|-- workflow.md             # Complete workflow documentation\n|-- workspace/              # \"AI Memory\" - session history\n|   |-- index.md            # All developers'' progress\n|   +-- {developer}/        # Per-developer directory\n|       |-- index.md        # Personal progress index\n|       +-- journal-N.md    # Session records (max 2000 lines)\n|-- tasks/                  # Task tracking (unified)\n|   +-- {MM}-{DD}-{slug}/   # Task directory\n|       |-- task.json       # Task metadata\n|       +-- prd.md          # Requirements doc\n|-- spec/                   # \"AI Training Data\" - project knowledge\n|   |-- frontend/           # Frontend conventions\n|   |-- backend/            # Backend conventions\n|   +-- guides/             # Thinking patterns\n+-- scripts/                # Automation tools\n```\n\n### Understanding spec/ subdirectories\n\n**frontend/** - Single-layer frontend knowledge:\n- Component patterns (how to write components in THIS project)\n- State management rules (Redux? Zustand? Context?)\n- Styling conventions (CSS modules? Tailwind? Styled-components?)\n- Hook patterns (custom hooks, data fetching)\n\n**backend/** - Single-layer backend knowledge:\n- API design patterns (REST? GraphQL? tRPC?)\n- Database conventions (query patterns, migrations)\n- Error handling standards\n- Logging and monitoring rules\n\n**guides/** - Cross-layer thinking guides:\n- Code reuse thinking guide\n- Cross-layer thinking guide\n- Pre-implementation checklists\n\n---\n\n## COMMAND DEEP DIVE\n\n### /trellis:start - Restore AI Memory\n\n**WHY IT EXISTS**:\nWhen a human engineer joins a project, they spend days/weeks learning: What is this project? What''s been built? What''s in progress? What''s the current state?\n\nAI needs the same onboarding - but compressed into seconds at session start.\n\n**WHAT IT ACTUALLY DOES**:\n1. Reads developer identity (who am I in this project?)\n2. Checks git status (what branch? uncommitted changes?)\n3. Reads recent session history from `workspace/` (what happened before?)\n4. Identifies active features (what''s in progress?)\n5. Understands current project state before making any changes\n\n**WHY THIS MATTERS**:\n- Without /trellis:start: AI is blind. It might work on wrong branch, conflict with others'' work, or redo already-completed work.\n- With /trellis:start: AI knows project context, can continue where previous session left off, avoids conflicts.\n\n---\n\n### /trellis:before-frontend-dev and /trellis:before-backend-dev - Inject Specialized Knowledge\n\n**WHY IT EXISTS**:\nAI models have \"pre-trained knowledge\" - general patterns from millions of codebases. But YOUR project has specific conventions that differ from generic patterns.\n\n**WHAT IT ACTUALLY DOES**:\n1. Reads `.trellis/spec/frontend/` or `.trellis/spec/backend/`\n2. Loads project-specific patterns into AI''s working context:\n   - Component naming conventions\n   - State management patterns\n   - Database query patterns\n   - Error handling standards\n\n**WHY THIS MATTERS**:\n- Without before-*-dev: AI writes generic code that doesn''t match project style.\n- With before-*-dev: AI writes code that looks like the rest of the codebase.\n\n---\n\n### /trellis:check-frontend and /trellis:check-backend - Combat Context Drift\n\n**WHY IT EXISTS**:\nAI context window has limited capacity. As conversation progresses, guidelines injected at session start become less influential. This causes \"context drift.\"\n\n**WHAT IT ACTUALLY DOES**:\n1. Re-reads the guidelines that were injected earlier\n2. Compares written code against those guidelines\n3. Runs type checker and linter\n4. Identifies violations and suggests fixes\n\n**WHY THIS MATTERS**:\n- Without check-*: Context drift goes unnoticed, code quality degrades.\n- With check-*: Drift is caught and corrected before commit.\n\n---\n\n### /trellis:check-cross-layer - Multi-Dimension Verification\n\n**WHY IT EXISTS**:\nMost bugs don''t come from lack of technical skill - they come from \"didn''t think of it\":\n- Changed a constant in one place, missed 5 other places\n- Modified database schema, forgot to update the API layer\n- Created a utility function, but similar one already exists\n\n**WHAT IT ACTUALLY DOES**:\n1. Identifies which dimensions your change involves\n2. For each dimension, runs targeted checks:\n   - Cross-layer data flow\n   - Code reuse analysis\n   - Import path validation\n   - Consistency checks\n\n---\n\n### /trellis:finish-work - Holistic Pre-Commit Review\n\n**WHY IT EXISTS**:\nThe `/check-*` commands focus on code quality within a single layer. But real changes often have cross-cutting concerns.\n\n**WHAT IT ACTUALLY DOES**:\n1. Reviews all changes holistically\n2. Checks cross-layer consistency\n3. Identifies broader impacts\n4. Checks if new patterns should be documented\n\n---\n\n### /trellis:record-session - Persist Memory for Future\n\n**WHY IT EXISTS**:\nAll the context AI built during this session will be lost when session ends. The next session''s `/trellis:start` needs this information.\n\n**WHAT IT ACTUALLY DOES**:\n1. Records session summary to `workspace/{developer}/journal-N.md`\n2. Captures what was done, learned, and what''s remaining\n3. Updates index files for quick lookup\n\n---\n\n## REAL-WORLD WORKFLOW EXAMPLES\n\n### Example 1: Bug Fix Session\n\n**[1/8] /trellis:start** - AI needs project context before touching code\n**[2/8] python3 ./.trellis/scripts/task.py create \"Fix bug\" --slug fix-bug** - Track work for future reference\n**[3/8] /trellis:before-frontend-dev** - Inject project-specific frontend knowledge\n**[4/8] Investigate and fix the bug** - Actual development work\n**[5/8] /trellis:check-frontend** - Re-verify code against guidelines\n**[6/8] /trellis:finish-work** - Holistic cross-layer review\n**[7/8] Human tests and commits** - Human validates before code enters repo\n**[8/8] /trellis:record-session** - Persist memory for future sessions\n\n### Example 2: Planning Session (No Code)\n\n**[1/4] /trellis:start** - Context needed even for non-coding work\n**[2/4] python3 ./.trellis/scripts/task.py create \"Planning task\" --slug planning-task** - Planning is valuable work\n**[3/4] Review docs, create subtask list** - Actual planning work\n**[4/4] /trellis:record-session (with --summary)** - Planning decisions must be recorded\n\n### Example 3: Code Review Fixes\n\n**[1/6] /trellis:start** - Resume context from previous session\n**[2/6] /trellis:before-backend-dev** - Re-inject guidelines before fixes\n**[3/6] Fix each CR issue** - Address feedback with guidelines in context\n**[4/6] /trellis:check-backend** - Verify fixes didn''t introduce new issues\n**[5/6] /trellis:finish-work** - Document lessons from CR\n**[6/6] Human commits, then /trellis:record-session** - Preserve CR lessons\n\n### Example 4: Large Refactoring\n\n**[1/5] /trellis:start** - Clear baseline before major changes\n**[2/5] Plan phases** - Break into verifiable chunks\n**[3/5] Execute phase by phase with /check-* after each** - Incremental verification\n**[4/5] /trellis:finish-work** - Check if new patterns should be documented\n**[5/5] Record with multiple commit hashes** - Link all commits to one feature\n\n### Example 5: Debug Session\n\n**[1/6] /trellis:start** - See if this bug was investigated before\n**[2/6] /trellis:before-backend-dev** - Guidelines might document known gotchas\n**[3/6] Investigation** - Actual debugging work\n**[4/6] /trellis:check-backend** - Verify debug changes don''t break other things\n**[5/6] /trellis:finish-work** - Debug findings might need documentation\n**[6/6] Human commits, then /trellis:record-session** - Debug knowledge is valuable\n\n---\n\n## KEY RULES TO EMPHASIZE\n\n1. **AI NEVER commits** - Human tests and approves. AI prepares, human validates.\n2. **Guidelines before code** - /before-*-dev commands inject project knowledge.\n3. **Check after code** - /check-* commands catch context drift.\n4. **Record everything** - /trellis:record-session persists memory.\n\n---\n\n# PART 3: Customize Your Development Guidelines\n\nAfter explaining Part 1 and Part 2, check if the project''s development guidelines need customization.\n\n## Step 1: Check Current Guidelines Status\n\nCheck if `.trellis/spec/` contains empty templates or customized guidelines:\n\n```bash\n# Check if files are still empty templates (look for placeholder text)\ngrep -l \"To be filled by the team\" .trellis/spec/backend/*.md 2>/dev/null | wc -l\ngrep -l \"To be filled by the team\" .trellis/spec/frontend/*.md 2>/dev/null | wc -l\n```\n\n## Step 2: Determine Situation\n\n**Situation A: First-time setup (empty templates)**\n\nIf guidelines are empty templates (contain \"To be filled by the team\"), this is the first time using Trellis in this project.\n\nExplain to the developer:\n\n\"I see that the development guidelines in `.trellis/spec/` are still empty templates. This is normal for a new Trellis setup!\n\nThe templates contain placeholder text that needs to be replaced with YOUR project''s actual conventions. Without this, `/before-*-dev` commands won''t provide useful guidance.\n\n**Your first task should be to fill in these guidelines:**\n\n1. Look at your existing codebase\n2. Identify the patterns and conventions already in use\n3. Document them in the guideline files\n\nFor example, for `.trellis/spec/backend/database-guidelines.md`:\n- What ORM/query library does your project use?\n- How are migrations managed?\n- What naming conventions for tables/columns?\n\nWould you like me to help you analyze your codebase and fill in these guidelines?\"\n\n**Situation B: Guidelines already customized**\n\nIf guidelines have real content (no \"To be filled\" placeholders), this is an existing setup.\n\nExplain to the developer:\n\n\"Great! Your team has already customized the development guidelines. You can start using `/before-*-dev` commands right away.\n\nI recommend reading through `.trellis/spec/` to familiarize yourself with the team''s coding standards.\"\n\n## Step 3: Help Fill Guidelines (If Empty)\n\nIf the developer wants help filling guidelines, create a feature to track this:\n\n```bash\npython3 ./.trellis/scripts/task.py create \"Fill spec guidelines\" --slug fill-spec-guidelines\n```\n\nThen systematically analyze the codebase and fill each guideline file:\n\n1. **Analyze the codebase** - Look at existing code patterns\n2. **Document conventions** - Write what you observe, not ideals\n3. **Include examples** - Reference actual files in the project\n4. **List forbidden patterns** - Document anti-patterns the team avoids\n\nWork through one file at a time:\n- `backend/directory-structure.md`\n- `backend/database-guidelines.md`\n- `backend/error-handling.md`\n- `backend/quality-guidelines.md`\n- `backend/logging-guidelines.md`\n- `frontend/directory-structure.md`\n- `frontend/component-guidelines.md`\n- `frontend/hook-guidelines.md`\n- `frontend/state-management.md`\n- `frontend/quality-guidelines.md`\n- `frontend/type-safety.md`\n\n---\n\n## Completing the Onboard Session\n\nAfter covering all three parts, summarize:\n\n\"You''re now onboarded to the Trellis workflow system! Here''s what we covered:\n- Part 1: Core concepts (why this workflow exists)\n- Part 2: Real-world examples (how to apply the workflow)\n- Part 3: Guidelines status (empty templates need filling / already customized)\n\n**Next steps** (tell user):\n1. Run `/trellis:record-session` to record this onboard session\n2. [If guidelines empty] Start filling in `.trellis/spec/` guidelines\n3. [If guidelines ready] Start your first development task\n\nWhat would you like to do first?\"\n"},"lastSynced":"2026-03-08T02:03:04.210Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents like Claude Code and Cursor needing streamlined onboarding processes for AI-assisted workflow systems.","zh":"非常适合需要简化入职流程的AI代理，如Claude Code和Cursor的AI辅助工作流系统。","ja":"Claude CodeやCursorのようなAIアシストワークフローシステムのためのストリームライン化されたオンボーディングプロセスを必要とするAIエージェントに最適です。","ko":"클라우드 코드와 커서와 같은 AI 지원 워크플로우 시스템에 대한 스트리밍 온보딩 프로세스를 필요로하는 AI 에이전트에 적합합니다.","es":"Perfecto para agentes de IA como Claude Code y Cursor que necesitan procesos de incorporación optimizados para sistemas de flujo de trabajo asistidos por IA.","fr":"Parfait pour les agents IA comme Claude Code et Cursor qui ont besoin de processus d''intégration rationalisés pour les systèmes de workflow assistés par IA.","de":"Perfekt für KI-Agenten wie Claude Code und Cursor, die optimierte Onboarding-Prozesse für KI-gestützte Workflow-Systeme benötigen.","pt":"Perfeito para agentes de IA como Claude Code e Cursor que necessitam de processos de integração simplificados para sistemas de fluxo de trabalho assistidos por IA.","ru":"Идеально подходит для агентов ИИ, таких как Claude Code и Cursor, которым необходимы упрощенные процессы интеграции для систем рабочих процессов, поддерживаемых ИИ.","ar":"مثالي للوكلاء الذكاء الاصطناعي مثل كلود كود و 커서 الذين يحتاجون إلى عمليات دمج مبسطة لأنظمة سير العمل المدعومة بالذكاء الاصطناعي."},"recommendation":{"en":"Empowers agents to facilitate comprehensive onboarding for senior developers and new team members, providing a structured framework for AI-assisted workflow systems using Claude Code and Cursor, and leveraging core concepts like system structure and command deep dives.","zh":"赋予代理人为高级开发人员和新团队成员提供全面入职的能力，使用Claude Code和Cursor为AI辅助工作流系统提供结构化框架，并利用系统结构和命令深度等核心概念。","ja":"Claude CodeとCursorを使用したAIアシストワークフローシステムのための構造化されたフレームワークを提供し、システム構造やコマンドの深い理解などの核心的な概念を活用することで、高級開発者や新しいチームメンバーのための包括的なオンボーディングを促進するエージェントをエンパワーメントします。","ko":"클라우드 코드와 커서를 사용하여 AI 지원 워크플로 시스템을 위한 구조화된 프레임워크를 제공하고, 시스템 구조와 명령어에 대한 깊은 이해와 같은 핵심적인 개념을 활용하여, 고급 개발자와 새로운 팀 멤버를 위한 포괄적인 온보딩을 촉진하는 에이전트를 강화합니다.","es":"Habilita a los agentes a facilitar una incorporación integral para desarrolladores senior y nuevos miembros del equipo, proporcionando un marco estructurado para sistemas de flujo de trabajo asistidos por IA que utilizan Claude Code y Cursor, y aprovechando conceptos básicos como la estructura del sistema y las inmersiones profundas en comandos.","fr":"Permet aux agents de faciliter une intégration complète pour les développeurs seniors et les nouveaux membres de l''équipe, en fournissant un cadre structuré pour les systèmes de workflow assistés par IA utilisant Claude Code et Cursor, et en exploitant des concepts de base tels que la structure du système et les plongées profondes dans les commandes.","de":"Ermöglicht es Agenten, eine umfassende Onboarding für Senior-Entwickler und neue Teammitglieder zu erleichtern, indem ein strukturiertes Framework für KI-gestützte Workflow-Systeme mit Claude Code und Cursor bereitgestellt wird und Kernkonzepte wie Systemstruktur und Befehlsdeep-Dives genutzt werden.","pt":"Habilita os agentes a facilitar a integração abrangente para desenvolvedores sêniores e novos membros da equipe, fornecendo uma estrutura estruturada para sistemas de fluxo de trabalho assistidos por IA usando Claude Code e Cursor, e aproveitando conceitos fundamentais como estrutura do sistema e mergulhos profundos em comandos.","ru":"Наделяет агентов возможностью облегчить всестороннюю интеграцию для старших разработчиков и новых членов команды, предоставляя структурированную основу для систем рабочих процессов, поддерживаемых ИИ, с использованием Claude Code и Cursor, и использует основные понятия, такие как структура системы и глубокие погружения в команды.","ar":"تمكين الوكلاء من تسهيل إعداد متكامل للمطورين المسنين وأعضاء الفريق الجدد، وتوفير إطار منظم لأنظمة سير العمل المدعومة بالذكاء الاصطناعي باستخدام كلود كود و 커서، واستخدام المفاهيم الأساسية مثل هيكل النظام والغوص العميق في الأوامر."},"useCases":{"en":["Onboarding new team members to AI-assisted workflow systems","Streamlining developer onboarding processes for Claude Code and Cursor projects","Implementing comprehensive content analysis for workflow systems"],"zh":["将新团队成员引入AI辅助工作流系统","为Claude Code和Cursor项目简化开发人员入职流程","为工作流系统实施全面内容分析"],"ja":["AIアシストワークフローシステムへの新しいチームメンバーのオンボーディング","Claude CodeおよびCursorプロジェクトの開発者のオンボーディングプロセスの簡素化","ワークフローシステムのための包括的なコンテンツ分析の実装"],"ko":["新的 팀 멤버를 AI 지원 워크플로우 시스템으로 온보딩하는 것","클라우드 코드와 커서 프로젝트를 위한 개발자 온보딩 프로세스를 스트리밍하는 것","워크플로우 시스템을 위한 포괄적인 콘텐츠 분석을 구현하는 것"],"es":["Incorporación de nuevos miembros del equipo a sistemas de flujo de trabajo asistidos por IA","Optimización de los procesos de incorporación de desarrolladores para proyectos de Claude Code y Cursor","Implementación de un análisis de contenido integral para sistemas de flujo de trabajo"],"fr":["Intégration de nouveaux membres de l''équipe dans des systèmes de workflow assistés par IA","Optimisation des processus d''intégration des développeurs pour les projets Claude Code et Cursor","Mise en œuvre d''une analyse de contenu complète pour les systèmes de workflow"],"de":["Onboarding neuer Teammitglieder in KI-gestützte Workflow-Systeme","Optimierung der Onboarding-Prozesse für Entwickler für Claude Code- und Cursor-Projekte","Implementierung einer umfassenden Inhaltsanalyse für Workflow-Systeme"],"pt":["Integração de novos membros da equipe a sistemas de fluxo de trabalho assistidos por IA","Simplificação dos processos de integração para desenvolvedores para projetos Claude Code e Cursor","Implementação de análise de conteúdo abrangente para sistemas de fluxo de trabalho"],"ru":["Интеграция новых членов команды в системы рабочих процессов, поддерживаемых ИИ","Упрощение процессов интеграции для разработчиков проектов Claude Code и Cursor","Реализация всестороннего анализа контента для систем рабочих процессов"],"ar":["دمج أعضاء الفريق الجدد في أنظمة سير العمل المدعومة بالذكاء الاصطناعي","تبسيط عمليات إعداد المطورين لمشاريع كلود كود و 커서","تنفيذ تحليل محتوى شامل لأنظمة سير العمل"]},"limitations":{"en":["Designed specifically for Claude Code and Cursor AI frameworks","Requires comprehensive content analysis for effective onboarding"],"zh":["专门为Claude Code和Cursor AI框架设计","需要全面内容分析以实现有效入职"],"ja":["Claude CodeおよびCursorのAIフレームワーク専用に設計","効果的なオンボーディングのために包括的なコンテンツ分析が必要"],"ko":["클라우드 코드와 커서 AI 프레임워크를 위한専用 설계","유효한 온보딩을 위해서는 포괄적인 콘텐츠 분석이 필요"],"es":["Diseñado específicamente para los marcos de IA Claude Code y Cursor","Requiere un análisis de contenido integral para una incorporación efectiva"],"fr":["Conçu spécifiquement pour les cadres d''IA Claude Code et Cursor","Nécessite une analyse de contenu complète pour une intégration efficace"],"de":["Speziell für die KI-Frameworks Claude Code und Cursor konzipiert","Benötigt eine umfassende Inhaltsanalyse für eine effektive Onboarding"],"pt":["Projetado especificamente para os quadros de IA Claude Code e Cursor","Exige análise de conteúdo abrangente para integração eficaz"],"ru":["Разработан специально для фреймворков ИИ Claude Code и Cursor","Требует всестороннего анализа контента для эффективной интеграции"],"ar":["صممت خصيصا لإطارات الذكاء الاصطناعي كلود كود و 커서","يتطلب تحليل محتوى شاملا للإعداد الفعال"]},"version":4},"contentHash":"ca110533dba054447c4e51de55af8269ad789e42704fc362cc46d03d70e69dd8","qualityScore":45}');
