INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mindfold-ai/Trellis/onboard', 'onboard', 'mindfold-ai', 'Trellis', 'community', 'onboard mindfold-ai Trellis community The onboard skill is an AI framework and toolkit for Claude Code and Cursor, designed to facilitate AI-assisted workflow systems. It benefits senior developers and new team members alike by providing a comprehensive onboarding process. Onboard是用于Claude Code和Cursor的AI框架和工具包，提供核心概念、系统结构和命令深度解析 Onboardは、Claude CodeとCursor向けのAIフレームワークとツールキットで、コアコンセプト、システム構造、コマンドの深い分析を提供します Onboard는 Claude Code와 Cursor를 위한 AI 프레임워크와 툴킷으로,核心 개념, 시스템 구조, 명령어 深度 解析을 제공합니다 El marco de trabajo de AI para Claude Code y Cursor, con una guía de configuración para onboard L''outil de workflow d''IA pour Claude Code et Cursor, avec un guide d''intégration pour onboard Das AI-Workflowsystem für Claude Code und Cursor, mit einem Einrichtungsleitfaden für onboard O Onboard é uma estrutura de IA completa para desenvolvedores, oferecendo uma abordagem integrada para o fluxo de trabalho de desenvolvimento. Onboard - это комплексная структура ИИ для разработчиков, предлагающая интегрированный подход к рабочему процессу разработки. Onboard هو إطار عمل ذكاء اصطناعي شامل للمطورين، يوفر نهجًا متكاملًا لتدفق العمل التطويري. how to use onboard onboard setup guide what is onboard onboard alternative onboard vs Claude Code onboard install onboard for AI agents AI-assisted workflow systems onboard for developers onboard workflow toolkit AIエージェント入门 Onboard工作流设置 Claude Code和Cursor AI框架和工具包 核心概念解析 系统结构概述 命令深度解析 Explains core philosophy and system structure for AI-assisted workflows Provides command deep dives for comprehensive understanding Covers critical instructions for onboarding new team members Divided into three equally important parts for thorough learning Mentorship and teaching approach for effective knowledge transfer Focuses on explaining underlying principles and problem-solving at a fundamental level onboard is an all-in-one AI framework and toolkit for streamlining workflow systems, particularly for Claude Code and Cursor, focusing on core concepts and command deep dives.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('digitarald/product-brain/frontend-slides', 'community', 'digitarald', 'product-brain', 'digitarald/product-brain', 'frontend-slides', 0, 0, 45, '2026-03-08T01:57:15.328Z', '2026-03-08T02:03:06.445Z', '518b41cc9b9135e7c53f1e9ff27e6e9e06e79a36e15b2b9696c1cbfe35fddedf', '{"id":"digitarald/product-brain/frontend-slides","name":"frontend-slides","description":{"en":"The frontend-slides skill creates zero-dependency, animation-rich HTML presentations that run entirely in the browser, helping non-designers discover their preferred aesthetic through visual exploration.","zh":"前端幻灯片技能帮助非设计师通过视觉探索发现他们的首选美学，并生成生产质量的幻灯片","ja":"フロントエンドスライドスキルは、非デザイナーが視覚的な探索を通じて彼らの好みの美学を発見するのを助け、そして生産品質のスライドを生成します","ko":"프론트엔드 슬라이드 스킬은 비디자이너가 시각적 탐색을 통해 그들의 선호하는 미학을 발견하도록 도와주고 생산품질의 슬라이드를 생성합니다","es":"Frontend-slides es una habilidad de AI Agent que crea presentaciones HTML en el navegador, sin dependencias y con animaciones. Ayuda a los no diseñadores a descubrir su estética preferida","fr":"Frontend-slides est une compétence d''outil d''IA qui crée des présentations HTML riches en animations, sans dépendances. Elle aide les non-designers à découvrir leur esthétique préférée","de":"Frontend-slides ist eine Fähigkeit von AI-Tools, die animationsreiche HTML-Präsentationen im Browser erstellt, ohne Abhängigkeiten. Sie hilft Nicht-Designern, ihre bevorzugte Ästhetik zu entdecken","pt":"A habilidade de Frontend Slides permite criar apresentações HTML enriquecidas com animações, sem dependências. Ela ajuda a gerar decks de slides de alta qualidade.","ru":"Навык Frontend Slides позволяет создать HTML-презентации с анимациями, без зависимостей. Он помогает генерировать decks слайдов высокого качества.","ar":"تسمح مهارة Frontend Slides بإنشاء عروض HTML متحركة بدون зависимости. تساعد في إنشاء عروض شرائح عالية الجودة."},"seo":{"title":{"en":"frontend-slides: Zero-Dependency Presentation Setup Guide...","zh":"前端幻灯片技能：零依赖HTML演示文稿设置指南","ja":"フロントエンドスライドスキル：ゼロ依存HTMLプレゼンテーションのベストプラクティス","ko":"프론트엔드 슬라이드 스킬: 제로 의존성 HTML 프레젠테이션 생성 가이드","es":"Guía de configuración de frontend-slides: Presentaciones ...","fr":"Mise en place de frontend-slides: Présentations HTML rich...","de":"Einrichtungsleitfaden für frontend-slides: Animationsreic...","pt":"Guia de Configuração de Frontend Slides - Ferramentas de ...","ru":"Руководство по настройке Frontend Slides - ИИ Агенты","ar":"دليل إعدادSlides الأمامي - أدوات ذكاء اصطناعي"},"description":{"en":"Discover how to create animation-rich HTML presentations with frontend-slides. Learn how to generate production-quality slide decks without dependencies. Get...","zh":"使用前端幻灯片技能创建零依赖、动画丰富的HTML演示文稿，运行于浏览器中，无需npm或构建工具","ja":"フロントエンドスライドスキルを使用して、ゼロ依存のアニメーション豊富なHTMLプレゼンテーションを作成します。ブラウザで実行され、npmやビルドツールは不要です","ko":"프론트엔드 슬라이드 스킬을 사용하여 제로 의존성, 애니메이션 풍부한 HTML 프레젠테이션을 생성합니다. 브라우저에서 실행되며 npm 또는 빌드 도구가 필요하지 않습니다","es":"Crea presentaciones HTML en el navegador con frontend-slides, sin dependencias y con animaciones. Descubre cómo funciona esta habilidad de AI Agent","fr":"Créez des présentations HTML riches en animations avec frontend-slides, sans dépendances. Découvrez comment fonctionne cet outil d''IA","de":"Erstellen Sie animationsreiche HTML-Präsentationen im Browser mit frontend-slides, ohne Abhängigkeiten. Erfahren Sie, wie diese AI-Tool-Fähigkeit funktioniert","pt":"Crie apresentações HTML enriquecidas com animações, sem dependências, com a habilidade de Frontend Slides. Aprenda a criar decks de slides de alta qualidade.","ru":"Создайте HTML-презентации с анимациями, без зависимостей, с помощью навыка Frontend Slides. Узнайте, как создать decks слайдов высокого качества.","ar":"أنشئ عروض HTML متحركة بدون зависимости باستخدام مهارة Frontend Slides. تعلم كيفية إنشاء عروض شرائح عالية الجودة."},"definition":{"en":"frontend-slides is a skill that generates single HTML files with inline CSS/JS for creating production-quality slide decks without dependencies.","zh":"前端幻灯片技能是一种创建零依赖、动画丰富的HTML演示文稿的技术","ja":"フロントエンドスライドスキルは、ゼロ依存のアニメーション豊富なHTMLプレゼンテーションを作成する技術です","ko":"프론트엔드 슬라이드 스킬은 제로 의존성, 애니메이션 풍부한 HTML 프레젠테이션을 생성하는 기술입니다","es":"Frontend-slides es una habilidad de AI Agent que crea presentaciones HTML en el navegador, sin dependencias","fr":"Frontend-slides est une compétence d''outil d''IA qui crée des présentations HTML riches en animations, sans dépendances","de":"Frontend-slides ist eine Fähigkeit von AI-Tools, die animationsreiche HTML-Präsentationen im Browser erstellt, ohne Abhängigkeiten","pt":"O que é Frontend Slides? É uma habilidade que cria apresentações HTML enriquecidas com animações, sem dependências.","ru":"Что такое Frontend Slides? Это навык, который создает HTML-презентации с анимациями, без зависимостей.","ar":"ما هي Frontend Slides؟ إنه مهارة تتيح إنشاء عروض HTML متحركة بدون зависимости."},"features":{"en":["Generates single HTML files with inline CSS/JS","Creates animation-rich presentations that run entirely in the browser","Supports visual exploration for non-designers to discover their preferred aesthetic","Produces zero-dependency presentations without requiring npm or build tools","Enables generation of production-quality slide decks"],"zh":["零依赖：单个HTML文件，内联CSS/JS，无需npm或构建工具","动画丰富：生成视觉预览，而不是抽象的概念","生产质量：生成可用于生产环境的幻灯片","浏览器运行：无需额外的软件或插件","视觉探索：帮助非设计师发现他们的首选美学"],"ja":["ゼロ依存：単一のHTMLファイル、インラインCSS/JS、npmやビルドツールは不要","アニメーション豊富：視覚的なプレビューを生成する、抽象的な概念ではなく","生産品質：生産環境で使用できるスライドを生成する","ブラウザで実行：追加のソフトウェアやプラグインは不要","視覚的な探索：非デザイナーが彼らの好みの美学を発見するのを助ける"],"ko":["제로 의존성: 단일 HTML 파일, 인라인 CSS/JS, npm 또는 빌드 도구가 필요하지 않음","애니메이션 풍부: 시각적预览을 생성함, 추상적인 개념이 아님","생산품질: 생산 환경에서 사용할 수 있는 슬라이드를 생성함","브라우저에서 실행: 추가적인 소프트웨어 또는 플러그인이 필요하지 않음","시각적 탐색: 비디자이너가 그들의 선호하는 미학을 발견하도록 도와줌"],"es":["Crea presentaciones HTML en el navegador","Sin dependencias ni herramientas de compilación","Animaciones ricas y efectos visuales","Ayuda a los no diseñadores a descubrir su estética preferida","Crea archivos HTML únicos con CSS y JavaScript incrustados"],"fr":["Crée des présentations HTML riches en animations","Sans dépendances ni outils de construction","Animations riches et effets visuels","Aide les non-designers à découvrir leur esthétique préférée","Crée des fichiers HTML uniques avec CSS et JavaScript intégrés"],"de":["Erstellt animationsreiche HTML-Präsentationen im Browser","Ohne Abhängigkeiten oder Build-Tools","Reiche Animationen und visuelle Effekte","Hilft Nicht-Designern, ihre bevorzugte Ästhetik zu entdecken","Erstellt einzigartige HTML-Dateien mit eingebettetem CSS und JavaScript"],"pt":["Criação de apresentações HTML com animações","Zero dependências, sem uso de npm ou ferramentas de build","Geração de decks de slides de alta qualidade","Uso de CSS e JS inline","Suporte a visualização de pré-visualização"],"ru":["Создание HTML-презентаций с анимациями","Нет зависимостей, без использования npm или инструментов сборки","Генерация decks слайдов высокого качества","Использование CSS и JS inline","Поддержка предварительного просмотра"],"ar":["إنشاء عروض HTML متحركة","لا يوجد зависимости، بدون استخدام npm أو أدوات بناء","إنشاء عروض شرائح عالية الجودة","استخدام CSS و JS inline","دعم معاينة مسبقة"]},"keywords":{"en":["how to use frontend-slides","what is frontend-slides","frontend-slides alternative","frontend-slides vs reveal.js","frontend-slides install","frontend-slides setup guide","zero-dependency presentation tools","animation-rich HTML presentations","frontend-slides for non-designers"],"zh":["前端幻灯片","零依赖HTML","动画丰富的HTML演示文稿","浏览器运行的幻灯片","视觉探索","非设计师的幻灯片设计","AIエージェント","HTML演示文稿生成"],"ja":["フロントエンドスライド","ゼロ依存HTML","アニメーション豊富なHTMLプレゼンテーション","ブラウザで実行されるスライド","視覚的な探索","非デザイナーのスライドデザイン","AIエージェント","HTMLプレゼンテーション生成"],"ko":["프론트엔드 슬라이드","제로 의존성 HTML","애니메이션 풍부한 HTML 프레젠테이션","브라우저에서 실행되는 슬라이드","시각적 탐색","비디자이너의 슬라이드 디자인","AI 에이전트","HTML 프레젠테이션 생성"],"es":["frontend-slides","presentaciones HTML","animaciones en el navegador","AI Agent","herramientas de desarrollo web","diseño de presentaciones","creación de diapositivas","HTML CSS JavaScript"],"fr":["frontend-slides","présentations HTML","animations dans le navigateur","outil d''IA","outils de développement web","conception de présentations","création de diapositives","HTML CSS JavaScript"],"de":["frontend-slides","HTML-Präsentationen","Animationen im Browser","AI-Tool","Webentwicklungstools","Präsentationsdesign","Erstellung von Folien","HTML CSS JavaScript"],"pt":["Frontend Slides","apresentações HTML","animações","zero dependências","Ferramentas de Inteligência Artificial","desenvolvimento web","criação de slides"],"ru":["Frontend Slides","HTML-презентации","анимации","нет зависимостей","ИИ Агенты","веб-разработка","создание слайдов"],"ar":["Frontend Slides","عروض HTML","متحركة","لا يوجد зависимости","أدوات ذكاء اصطناعي","تطوير الويب","إنشاء شرائح"]}},"owner":"digitarald","repo":"product-brain","repoPath":"digitarald/product-brain","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.328Z","topics":[],"category":"community","skillMd":{"name":"frontend-slides","description":"Create stunning, animation-rich HTML presentations from scratch or by converting PowerPoint files. Use when the user wants to build a presentation, convert a PPT/PPTX to web, or create slides for a talk/pitch. Helps non-designers discover their aesthetic through visual exploration rather than abstract choices.","bodyPreview":"# Frontend Slides Skill\n\nCreate zero-dependency, animation-rich HTML presentations that run entirely in the browser. This skill helps non-designers discover their preferred aesthetic through visual exploration (\"show, don''t tell\"), then generates production-quality slide decks.\n\n## Core Philosophy\n\n1. **Zero Dependencies** — Single HTML files with inline CSS/JS. No npm, no build tools.\n2. **Show, Don''t Tell** — People don''t know what they want until they see it. Generate visual previews, not abs","body":"# Frontend Slides Skill\n\nCreate zero-dependency, animation-rich HTML presentations that run entirely in the browser. This skill helps non-designers discover their preferred aesthetic through visual exploration (\"show, don''t tell\"), then generates production-quality slide decks.\n\n## Core Philosophy\n\n1. **Zero Dependencies** — Single HTML files with inline CSS/JS. No npm, no build tools.\n2. **Show, Don''t Tell** — People don''t know what they want until they see it. Generate visual previews, not abstract choices.\n3. **Distinctive Design** — Avoid generic \"AI slop\" aesthetics. Every presentation should feel custom-crafted.\n4. **Production Quality** — Code should be well-commented, accessible, and performant.\n5. **Viewport Fitting (CRITICAL)** — Every slide MUST fit exactly within the viewport. No scrolling within slides, ever. This is non-negotiable.\n\n---\n\n## CRITICAL: Viewport Fitting Requirements\n\n**This section is mandatory for ALL presentations. Every slide must be fully visible without scrolling on any screen size.**\n\n### The Golden Rule\n\n```\nEach slide = exactly one viewport height (100vh/100dvh)\nContent overflows? → Split into multiple slides or reduce content\nNever scroll within a slide.\n```\n\n### Content Density Limits\n\nTo guarantee viewport fitting, enforce these limits per slide:\n\n| Slide Type | Maximum Content |\n|------------|-----------------|\n| Title slide | 1 heading + 1 subtitle + optional tagline |\n| Content slide | 1 heading + 4-6 bullet points OR 1 heading + 2 paragraphs |\n| Feature grid | 1 heading + 6 cards maximum (2x3 or 3x2 grid) |\n| Code slide | 1 heading + 8-10 lines of code maximum |\n| Quote slide | 1 quote (max 3 lines) + attribution |\n| Image slide | 1 heading + 1 image (max 60vh height) |\n\n**If content exceeds these limits → Split into multiple slides**\n\n### Required CSS Architecture\n\nEvery presentation MUST include this base CSS for viewport fitting:\n\n```css\n/* ===========================================\n   VIEWPORT FITTING: MANDATORY BASE STYLES\n   These styles MUST be included in every presentation.\n   They ensure slides fit exactly in the viewport.\n   =========================================== */\n\n/* 1. Lock html/body to viewport */\nhtml, body {\n    height: 100%;\n    overflow-x: hidden;\n}\n\nhtml {\n    scroll-snap-type: y mandatory;\n    scroll-behavior: smooth;\n}\n\n/* 2. Each slide = exact viewport height */\n.slide {\n    width: 100vw;\n    height: 100vh;\n    height: 100dvh; /* Dynamic viewport height for mobile browsers */\n    overflow: hidden; /* CRITICAL: Prevent ANY overflow */\n    scroll-snap-align: start;\n    display: flex;\n    flex-direction: column;\n    position: relative;\n}\n\n/* 3. Content container with flex for centering */\n.slide-content {\n    flex: 1;\n    display: flex;\n    flex-direction: column;\n    justify-content: center;\n    max-height: 100%;\n    overflow: hidden; /* Double-protection against overflow */\n    padding: var(--slide-padding);\n}\n\n/* 4. ALL typography uses clamp() for responsive scaling */\n:root {\n    /* Titles scale from mobile to desktop */\n    --title-size: clamp(1.5rem, 5vw, 4rem);\n    --h2-size: clamp(1.25rem, 3.5vw, 2.5rem);\n    --h3-size: clamp(1rem, 2.5vw, 1.75rem);\n\n    /* Body text */\n    --body-size: clamp(0.75rem, 1.5vw, 1.125rem);\n    --small-size: clamp(0.65rem, 1vw, 0.875rem);\n\n    /* Spacing scales with viewport */\n    --slide-padding: clamp(1rem, 4vw, 4rem);\n    --content-gap: clamp(0.5rem, 2vw, 2rem);\n    --element-gap: clamp(0.25rem, 1vw, 1rem);\n}\n\n/* 5. Cards/containers use viewport-relative max sizes */\n.card, .container, .content-box {\n    max-width: min(90vw, 1000px);\n    max-height: min(80vh, 700px);\n}\n\n/* 6. Lists auto-scale with viewport */\n.feature-list, .bullet-list {\n    gap: clamp(0.4rem, 1vh, 1rem);\n}\n\n.feature-list li, .bullet-list li {\n    font-size: var(--body-size);\n    line-height: 1.4;\n}\n\n/* 7. Grids adapt to available space */\n.grid {\n    display: grid;\n    grid-template-columns: repeat(auto-fit, minmax(min(100%, 250px), 1fr));\n    gap: clamp(0.5rem, 1.5vw, 1rem);\n}\n\n/* 8. Images constrained to viewport */\nimg, .image-container {\n    max-width: 100%;\n    max-height: min(50vh, 400px);\n    object-fit: contain;\n}\n\n/* ===========================================\n   RESPONSIVE BREAKPOINTS\n   Aggressive scaling for smaller viewports\n   =========================================== */\n\n/* Short viewports (< 700px height) */\n@media (max-height: 700px) {\n    :root {\n        --slide-padding: clamp(0.75rem, 3vw, 2rem);\n        --content-gap: clamp(0.4rem, 1.5vw, 1rem);\n        --title-size: clamp(1.25rem, 4.5vw, 2.5rem);\n        --h2-size: clamp(1rem, 3vw, 1.75rem);\n    }\n}\n\n/* Very short viewports (< 600px height) */\n@media (max-height: 600px) {\n    :root {\n        --slide-padding: clamp(0.5rem, 2.5vw, 1.5rem);\n        --content-gap: clamp(0.3rem, 1vw, 0.75rem);\n        --title-size: clamp(1.1rem, 4vw, 2rem);\n        --body-size: clamp(0.7rem, 1.2vw, 0.95rem);\n    }\n\n    /* Hide non-essential elements */\n    .nav-dots, .keyboard-hint, .decorative {\n        display: none;\n    }\n}\n\n/* Extremely short (landscape phones, < 500px height) */\n@media (max-height: 500px) {\n    :root {\n        --slide-padding: clamp(0.4rem, 2vw, 1rem);\n        --title-size: clamp(1rem, 3.5vw, 1.5rem);\n        --h2-size: clamp(0.9rem, 2.5vw, 1.25rem);\n        --body-size: clamp(0.65rem, 1vw, 0.85rem);\n    }\n}\n\n/* Narrow viewports (< 600px width) */\n@media (max-width: 600px) {\n    :root {\n        --title-size: clamp(1.25rem, 7vw, 2.5rem);\n    }\n\n    /* Stack grids vertically */\n    .grid {\n        grid-template-columns: 1fr;\n    }\n}\n\n/* ===========================================\n   REDUCED MOTION\n   Respect user preferences\n   =========================================== */\n@media (prefers-reduced-motion: reduce) {\n    *, *::before, *::after {\n        animation-duration: 0.01ms !important;\n        transition-duration: 0.2s !important;\n    }\n\n    html {\n        scroll-behavior: auto;\n    }\n}\n```\n\n### Overflow Prevention Checklist\n\nBefore generating any presentation, mentally verify:\n\n1. ✅ Every `.slide` has `height: 100vh; height: 100dvh; overflow: hidden;`\n2. ✅ All font sizes use `clamp(min, preferred, max)`\n3. ✅ All spacing uses `clamp()` or viewport units\n4. ✅ Content containers have `max-height` constraints\n5. ✅ Images have `max-height: min(50vh, 400px)` or similar\n6. ✅ Grids use `auto-fit` with `minmax()` for responsive columns\n7. ✅ Breakpoints exist for heights: 700px, 600px, 500px\n8. ✅ No fixed pixel heights on content elements\n9. ✅ Content per slide respects density limits\n\n### When Content Doesn''t Fit\n\nIf you find yourself with too much content:\n\n**DO:**\n- Split into multiple slides\n- Reduce bullet points (max 5-6 per slide)\n- Shorten text (aim for 1-2 lines per bullet)\n- Use smaller code snippets\n- Create a \"continued\" slide\n\n**DON''T:**\n- Reduce font size below readable limits\n- Remove padding/spacing entirely\n- Allow any scrolling\n- Cram content to fit\n\n### Testing Viewport Fit\n\nAfter generating, recommend the user test at these sizes:\n- Desktop: 1920×1080, 1440×900, 1280×720\n- Tablet: 1024×768, 768×1024 (portrait)\n- Mobile: 375×667, 414×896\n- Landscape phone: 667×375, 896×414\n\n---\n\n## Phase 0: Detect Mode\n\nFirst, determine what the user wants:\n\n**Mode A: New Presentation**\n- User wants to create slides from scratch\n- Proceed to Phase 1 (Content Discovery)\n\n**Mode B: PPT Conversion**\n- User has a PowerPoint file (.ppt, .pptx) to convert\n- Proceed to Phase 4 (PPT Extraction)\n\n**Mode C: Existing Presentation Enhancement**\n- User has an HTML presentation and wants to improve it\n- Read the existing file, understand the structure, then enhance\n\n---\n\n## Phase 1: Content Discovery (New Presentations)\n\nBefore designing, understand the content. Ask via AskUserQuestion:\n\n### Step 1.1: Presentation Context\n\n**Question 1: Purpose**\n- Header: \"Purpose\"\n- Question: \"What is this presentation for?\"\n- Options:\n  - \"Pitch deck\" — Selling an idea, product, or company to investors/clients\n  - \"Teaching/Tutorial\" — Explaining concepts, how-to guides, educational content\n  - \"Conference talk\" — Speaking at an event, tech talk, keynote\n  - \"Internal presentation\" — Team updates, strategy meetings, company updates\n\n**Question 2: Slide Count**\n- Header: \"Length\"\n- Question: \"Approximately how many slides?\"\n- Options:\n  - \"Short (5-10)\" — Quick pitch, lightning talk\n  - \"Medium (10-20)\" — Standard presentation\n  - \"Long (20+)\" — Deep dive, comprehensive talk\n\n**Question 3: Content**\n- Header: \"Content\"\n- Question: \"Do you have the content ready, or do you need help structuring it?\"\n- Options:\n  - \"I have all content ready\" — Just need to design the presentation\n  - \"I have rough notes\" — Need help organizing into slides\n  - \"I have a topic only\" — Need help creating the full outline\n\nIf user has content, ask them to share it (text, bullet points, images, etc.).\n\n---\n\n## Phase 2: Style Discovery (Visual Exploration)\n\n**CRITICAL: This is the \"show, don''t tell\" phase.**\n\nMost people can''t articulate design preferences in words. Instead of asking \"do you want minimalist or bold?\", we generate mini-previews and let them react.\n\n### How Users Choose Presets\n\nUsers can select a style in **two ways**:\n\n**Option A: Guided Discovery (Default)**\n- User answers mood questions\n- Skill generates 3 preview files based on their answers\n- User views previews in browser and picks their favorite\n- This is best for users who don''t have a specific style in mind\n\n**Option B: Direct Selection**\n- If user already knows what they want, they can request a preset by name\n- Example: \"Use the Bold Signal style\" or \"I want something like Dark Botanical\"\n- Skip to Phase 3 immediately\n\n**Available Presets:**\n| Preset | Vibe | Best For |\n|--------|------|----------|\n| Bold Signal | Confident, high-impact | Pitch decks, keynotes |\n| Electric Studio | Clean, professional | Agency presentations |\n| Creative Voltage | Energetic, retro-modern | Creative pitches |\n| Dark Botanical | Elegant, sophisticated | Premium brands |\n| Notebook Tabs | Editorial, organized | Reports, reviews |\n| Pastel Geometry | Friendly, approachable | Product overviews |\n| Split Pastel | Playful, modern | Creative agencies |\n| Vintage Editorial | Witty, personality-driven | Personal brands |\n| Neon Cyber | Futuristic, techy | Tech startups |\n| Terminal Green | Developer-focused | Dev tools, APIs |\n| Swiss Modern | Minimal, precise | Corporate, data |\n| Paper & Ink | Literary, thoughtful | Storytelling |\n\n### Step 2.0: Style Path Selection\n\nFirst, ask how the user wants to choose their style:\n\n**Question: Style Selection Method**\n- Header: \"Style\"\n- Question: \"How would you like to choose your presentation style?\"\n- Options:\n  - \"Show me options\" — Generate 3 previews based on my needs (recommended for most users)\n  - \"I know what I want\" — Let me pick from the preset list directly\n\n**If \"Show me options\"** → Continue to Step 2.1 (Mood Selection)\n\n**If \"I know what I want\"** → Show preset picker:\n\n**Question: Pick a Preset**\n- Header: \"Preset\"\n- Question: \"Which style would you like to use?\"\n- Options:\n  - \"Bold Signal\" — Vibrant card on dark, confident and high-impact\n  - \"Dark Botanical\" — Elegant dark with soft abstract shapes\n  - \"Notebook Tabs\" — Editorial paper look with colorful section tabs\n  - \"Pastel Geometry\" — Friendly pastels with decorative pills\n\n(If user picks one, skip to Phase 3. If they want to see more options, show additional presets or proceed to guided discovery.)\n\n### Step 2.1: Mood Selection (Guided Discovery)\n\n**Question 1: Feeling**\n- Header: \"Vibe\"\n- Question: \"What feeling should the audience have when viewing your slides?\"\n- Options:\n  - \"Impressed/Confident\" — Professional, trustworthy, this team knows what they''re doing\n  - \"Excited/Energized\" — Innovative, bold, this is the future\n  - \"Calm/Focused\" — Clear, thoughtful, easy to follow\n  - \"Inspired/Moved\" — Emotional, storytelling, memorable\n- multiSelect: true (can choose up to 2)\n\n### Step 2.2: Generate Style Previews\n\nBased on their mood selection, generate **3 distinct style previews** as mini HTML files in a temporary directory. Each preview should be a single title slide showing:\n\n- Typography (font choices, heading/body hierarchy)\n- Color palette (background, accent, text colors)\n- Animation style (how elements enter)\n- Overall aesthetic feel\n\n**Preview Styles to Consider (pick 3 based on mood):**\n\n| Mood | Style Options |\n|------|---------------|\n| Impressed/Confident | \"Bold Signal\", \"Electric Studio\", \"Dark Botanical\" |\n| Excited/Energized | \"Creative Voltage\", \"Neon Cyber\", \"Split Pastel\" |\n| Calm/Focused | \"Notebook Tabs\", \"Paper & Ink\", \"Swiss Modern\" |\n| Inspired/Moved | \"Dark Botanical\", \"Vintage Editorial\", \"Pastel Geometry\" |\n\n**IMPORTANT: Never use these generic patterns:**\n- Purple gradients on white backgrounds\n- Inter, Roboto, or system fonts\n- Standard blue primary colors\n- Predictable hero layouts\n\n**Instead, use distinctive choices:**\n- Unique font pairings (Clash Display, Satoshi, Cormorant Garamond, DM Sans, etc.)\n- Cohesive color themes with personality\n- Atmospheric backgrounds (gradients, subtle patterns, depth)\n- Signature animation moments\n\n### Step 2.3: Present Previews\n\nCreate the previews in: `.claude-design/slide-previews/`\n\n```\n.claude-design/slide-previews/\n├── style-a.html   # First style option\n├── style-b.html   # Second style option\n├── style-c.html   # Third style option\n└── assets/        # Any shared assets\n```\n\nEach preview file should be:\n- Self-contained (inline CSS/JS)\n- A single \"title slide\" showing the aesthetic\n- Animated to demonstrate motion style\n- ~50-100 lines, not a full presentation\n\nPresent to user:\n```\nI''ve created 3 style previews for you to compare:\n\n**Style A: [Name]** — [1 sentence description]\n**Style B: [Name]** — [1 sentence description]\n**Style C: [Name]** — [1 sentence description]\n\nOpen each file to see them in action:\n- .claude-design/slide-previews/style-a.html\n- .claude-design/slide-previews/style-b.html\n- .claude-design/slide-previews/style-c.html\n\nTake a look and tell me:\n1. Which style resonates most?\n2. What do you like about it?\n3. Anything you''d change?\n```\n\nThen use AskUserQuestion:\n\n**Question: Pick Your Style**\n- Header: \"Style\"\n- Question: \"Which style preview do you prefer?\"\n- Options:\n  - \"Style A: [Name]\" — [Brief description]\n  - \"Style B: [Name]\" — [Brief description]\n  - \"Style C: [Name]\" — [Brief description]\n  - \"Mix elements\" — Combine aspects from different styles\n\nIf \"Mix elements\", ask for specifics.\n\n---\n\n## Phase 3: Generate Presentation\n\nNow generate the full presentation based on:\n- Content from Phase 1\n- Style from Phase 2\n\n### File Structure\n\nFor single presentations:\n```\npresentation.html    # Self-contained presentation\nassets/              # Images, if any\n```\n\nFor projects with multiple presentations:\n```\n[presentation-name].html\n[presentation-name]-assets/\n```\n\n### HTML Architecture\n\nFollow this structure for all presentations:\n\n```html\n<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Presentation Title</title>\n\n    <!-- Fonts (use Fontshare or Google Fonts) -->\n    <link rel=\"stylesheet\" href=\"https://api.fontshare.com/v2/css?f[]=...\">\n\n    <style>\n        /* ===========================================\n           CSS CUSTOM PROPERTIES (THEME)\n           Easy to modify: change these to change the whole look\n           =========================================== */\n        :root {\n            /* Colors */\n            --bg-primary: #0a0f1c;\n            --bg-secondary: #111827;\n            --text-primary: #ffffff;\n            --text-secondary: #9ca3af;\n            --accent: #00ffcc;\n            --accent-glow: rgba(0, 255, 204, 0.3);\n\n            /* Typography - MUST use clamp() for responsive scaling */\n            --font-display: ''Clash Display'', sans-serif;\n            --font-body: ''Satoshi'', sans-serif;\n            --title-size: clamp(2rem, 6vw, 5rem);\n            --subtitle-size: clamp(0.875rem, 2vw, 1.25rem);\n            --body-size: clamp(0.75rem, 1.2vw, 1rem);\n\n            /* Spacing - MUST use clamp() for responsive scaling */\n            --slide-padding: clamp(1.5rem, 4vw, 4rem);\n            --content-gap: clamp(1rem, 2vw, 2rem);\n\n            /* Animation */\n            --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);\n            --duration-normal: 0.6s;\n        }\n\n        /* ===========================================\n           BASE STYLES\n           =========================================== */\n        * {\n            margin: 0;\n            padding: 0;\n            box-sizing: border-box;\n        }\n\n        html {\n            scroll-behavior: smooth;\n            scroll-snap-type: y mandatory;\n            height: 100%;\n        }\n\n        body {\n            font-family: var(--font-body);\n            background: var(--bg-primary);\n            color: var(--text-primary);\n            overflow-x: hidden;\n            height: 100%;\n        }\n\n        /* ===========================================\n           SLIDE CONTAINER\n           CRITICAL: Each slide MUST fit exactly in viewport\n           - Use height: 100vh (NOT min-height)\n           - Use overflow: hidden to prevent scroll\n           - Content must scale with clamp() values\n           =========================================== */\n        .slide {\n            width: 100vw;\n            height: 100vh; /* EXACT viewport height - no scrolling */\n            height: 100dvh; /* Dynamic viewport height for mobile */\n            padding: var(--slide-padding);\n            scroll-snap-align: start;\n            display: flex;\n            flex-direction: column;\n            justify-content: center;\n            position: relative;\n            overflow: hidden; /* Prevent any content overflow */\n        }\n\n        /* Content wrapper that prevents overflow */\n        .slide-content {\n            flex: 1;\n            display: flex;\n            flex-direction: column;\n            justify-content: center;\n            max-height: 100%;\n            overflow: hidden;\n        }\n\n        /* ===========================================\n           RESPONSIVE BREAKPOINTS\n           Adjust content for different screen sizes\n           =========================================== */\n        @media (max-height: 600px) {\n            :root {\n                --slide-padding: clamp(1rem, 3vw, 2rem);\n                --content-gap: clamp(0.5rem, 1.5vw, 1rem);\n            }\n        }\n\n        @media (max-width: 768px) {\n            :root {\n                --title-size: clamp(1.5rem, 8vw, 3rem);\n            }\n        }\n\n        @media (max-height: 500px) and (orientation: landscape) {\n            /* Extra compact for landscape phones */\n            :root {\n                --title-size: clamp(1.25rem, 5vw, 2rem);\n                --slide-padding: clamp(0.75rem, 2vw, 1.5rem);\n            }\n        }\n\n        /* ===========================================\n           ANIMATIONS\n           Trigger via .visible class (added by JS on scroll)\n           =========================================== */\n        .reveal {\n            opacity: 0;\n            transform: translateY(30px);\n            transition: opacity var(--duration-normal) var(--ease-out-expo),\n                        transform var(--duration-normal) var(--ease-out-expo);\n        }\n\n        .slide.visible .reveal {\n            opacity: 1;\n            transform: translateY(0);\n        }\n\n        /* Stagger children */\n        .reveal:nth-child(1) { transition-delay: 0.1s; }\n        .reveal:nth-child(2) { transition-delay: 0.2s; }\n        .reveal:nth-child(3) { transition-delay: 0.3s; }\n        .reveal:nth-child(4) { transition-delay: 0.4s; }\n\n        /* ... more styles ... */\n    </style>\n</head>\n<body>\n    <!-- Progress bar (optional) -->\n    <div class=\"progress-bar\"></div>\n\n    <!-- Navigation dots (optional) -->\n    <nav class=\"nav-dots\">\n        <!-- Generated by JS -->\n    </nav>\n\n    <!-- Slides -->\n    <section class=\"slide title-slide\">\n        <h1 class=\"reveal\">Presentation Title</h1>\n        <p class=\"reveal\">Subtitle or author</p>\n    </section>\n\n    <section class=\"slide\">\n        <h2 class=\"reveal\">Slide Title</h2>\n        <p class=\"reveal\">Content...</p>\n    </section>\n\n    <!-- More slides... -->\n\n    <script>\n        /* ===========================================\n           SLIDE PRESENTATION CONTROLLER\n           Handles navigation, animations, and interactions\n           =========================================== */\n\n        class SlidePresentation {\n            constructor() {\n                // ... initialization\n            }\n\n            // ... methods\n        }\n\n        // Initialize\n        new SlidePresentation();\n    </script>\n</body>\n</html>\n```\n\n### Required JavaScript Features\n\nEvery presentation should include:\n\n1. **SlidePresentation Class** — Main controller\n   - Keyboard navigation (arrows, space)\n   - Touch/swipe support\n   - Mouse wheel navigation\n   - Progress bar updates\n   - Navigation dots\n\n2. **Intersection Observer** — For scroll-triggered animations\n   - Add `.visible` class when slides enter viewport\n   - Trigger CSS animations efficiently\n\n3. **Optional Enhancements** (based on style):\n   - Custom cursor with trail\n   - Particle system background (canvas)\n   - Parallax effects\n   - 3D tilt on hover\n   - Magnetic buttons\n   - Counter animations\n\n### Code Quality Requirements\n\n**Comments:**\nEvery section should have clear comments explaining:\n- What it does\n- Why it exists\n- How to modify it\n\n```javascript\n/* ===========================================\n   CUSTOM CURSOR\n   Creates a stylized cursor that follows mouse with a trail effect.\n   - Uses lerp (linear interpolation) for smooth movement\n   - Grows larger when hovering over interactive elements\n   =========================================== */\nclass CustomCursor {\n    constructor() {\n        // ...\n    }\n}\n```\n\n**Accessibility:**\n- Semantic HTML (`<section>`, `<nav>`, `<main>`)\n- Keyboard navigation works\n- ARIA labels where needed\n- Reduced motion support\n\n```css\n@media (prefers-reduced-motion: reduce) {\n    .reveal {\n        transition: opacity 0.3s ease;\n        transform: none;\n    }\n}\n```\n\n**Responsive & Viewport Fitting (CRITICAL):**\n\n**See the \"CRITICAL: Viewport Fitting Requirements\" section above for complete CSS and guidelines.**\n\nQuick reference:\n- Every `.slide` must have `height: 100vh; height: 100dvh; overflow: hidden;`\n- All typography and spacing must use `clamp()`\n- Respect content density limits (max 4-6 bullets, max 6 cards, etc.)\n- Include breakpoints for heights: 700px, 600px, 500px\n- When content doesn''t fit → split into multiple slides, never scroll\n\n---\n\n## Phase 4: PPT Conversion\n\nWhen converting PowerPoint files:\n\n### Step 4.1: Extract Content\n\nUse Python with `python-pptx` to extract:\n\n```python\nfrom pptx import Presentation\nfrom pptx.util import Inches, Pt\nimport json\nimport os\nimport base64\n\ndef extract_pptx(file_path, output_dir):\n    \"\"\"\n    Extract all content from a PowerPoint file.\n    Returns a JSON structure with slides, text, and images.\n    \"\"\"\n    prs = Presentation(file_path)\n    slides_data = []\n\n    # Create assets directory\n    assets_dir = os.path.join(output_dir, ''assets'')\n    os.makedirs(assets_dir, exist_ok=True)\n\n    for slide_num, slide in enumerate(prs.slides):\n        slide_data = {\n            ''number'': slide_num + 1,\n            ''title'': '''',\n            ''content'': [],\n            ''images'': [],\n            ''notes'': ''''\n        }\n\n        for shape in slide.shapes:\n            # Extract title\n            if shape.has_text_frame:\n                if shape == slide.shapes.title:\n                    slide_data[''title''] = shape.text\n                else:\n                    slide_data[''content''].append({\n                        ''type'': ''text'',\n                        ''content'': shape.text\n                    })\n\n            # Extract images\n            if shape.shape_type == 13:  # Picture\n                image = shape.image\n                image_bytes = image.blob\n                image_ext = image.ext\n                image_name = f\"slide{slide_num + 1}_img{len(slide_data[''images'']) + 1}.{image_ext}\"\n                image_path = os.path.join(assets_dir, image_name)\n\n                with open(image_path, ''wb'') as f:\n                    f.write(image_bytes)\n\n                slide_data[''images''].append({\n                    ''path'': f\"assets/{image_name}\",\n                    ''width'': shape.width,\n                    ''height'': shape.height\n                })\n\n        # Extract notes\n        if slide.has_notes_slide:\n            notes_frame = slide.notes_slide.notes_text_frame\n            slide_data[''notes''] = notes_frame.text\n\n        slides_data.append(slide_data)\n\n    return slides_data\n```\n\n### Step 4.2: Confirm Content Structure\n\nPresent the extracted content to the user:\n\n```\nI''ve extracted the following from your PowerPoint:\n\n**Slide 1: [Title]**\n- [Content summary]\n- Images: [count]\n\n**Slide 2: [Title]**\n- [Content summary]\n- Images: [count]\n\n...\n\nAll images have been saved to the assets folder.\n\nDoes this look correct? Should I proceed with style selection?\n```\n\n### Step 4.3: Style Selection\n\nProceed to Phase 2 (Style Discovery) with the extracted content in mind.\n\n### Step 4.4: Generate HTML\n\nConvert the extracted content into the chosen style, preserving:\n- All text content\n- All images (referenced from assets folder)\n- Slide order\n- Any speaker notes (as HTML comments or separate file)\n\n---\n\n## Phase 5: Delivery\n\n### Final Output\n\nWhen the presentation is complete:\n\n1. **Clean up temporary files**\n   - Delete `.claude-design/slide-previews/` if it exists\n\n2. **Open the presentation**\n   - Use `open [filename].html` to launch in browser\n\n3. **Provide summary**\n```\nYour presentation is ready!\n\n📁 File: [filename].html\n🎨 Style: [Style Name]\n📊 Slides: [count]\n\n**Navigation:**\n- Arrow keys (← →) or Space to navigate\n- Scroll/swipe also works\n- Click the dots on the right to jump to a slide\n\n**To customize:**\n- Colors: Look for `:root` CSS variables at the top\n- Fonts: Change the Fontshare/Google Fonts link\n- Animations: Modify `.reveal` class timings\n\nWould you like me to make any adjustments?\n```\n\n---\n\n## Style Reference: Effect → Feeling Mapping\n\nUse this guide to match animations to intended feelings:\n\n### Dramatic / Cinematic\n- Slow fade-ins (1-1.5s)\n- Large scale transitions (0.9 → 1)\n- Dark backgrounds with spotlight effects\n- Parallax scrolling\n- Full-bleed images\n\n### Techy / Futuristic\n- Neon glow effects (box-shadow with accent color)\n- Particle systems (canvas background)\n- Grid patterns\n- Monospace fonts for accents\n- Glitch or scramble text effects\n- Cyan, magenta, electric blue palette\n\n### Playful / Friendly\n- Bouncy easing (spring physics)\n- Rounded corners (large radius)\n- Pastel or bright colors\n- Floating/bobbing animations\n- Hand-drawn or illustrated elements\n\n### Professional / Corporate\n- Subtle, fast animations (200-300ms)\n- Clean sans-serif fonts\n- Navy, slate, or charcoal backgrounds\n- Precise spacing and alignment\n- Minimal decorative elements\n- Data visualization focus\n\n### Calm / Minimal\n- Very slow, subtle motion\n- High whitespace\n- Muted color palette\n- Serif typography\n- Generous padding\n- Content-focused, no distractions\n\n### Editorial / Magazine\n- Strong typography hierarchy\n- Pull quotes and callouts\n- Image-text interplay\n- Grid-breaking layouts\n- Serif headlines, sans-serif body\n- Black and white with one accent\n\n---\n\n## Animation Patterns Reference\n\n### Entrance Animations\n\n```css\n/* Fade + Slide Up (most common) */\n.reveal {\n    opacity: 0;\n    transform: translateY(30px);\n    transition: opacity 0.6s var(--ease-out-expo),\n                transform 0.6s var(--ease-out-expo);\n}\n\n.visible .reveal {\n    opacity: 1;\n    transform: translateY(0);\n}\n\n/* Scale In */\n.reveal-scale {\n    opacity: 0;\n    transform: scale(0.9);\n    transition: opacity 0.6s, transform 0.6s var(--ease-out-expo);\n}\n\n/* Slide from Left */\n.reveal-left {\n    opacity: 0;\n    transform: translateX(-50px);\n    transition: opacity 0.6s, transform 0.6s var(--ease-out-expo);\n}\n\n/* Blur In */\n.reveal-blur {\n    opacity: 0;\n    filter: blur(10px);\n    transition: opacity 0.8s, filter 0.8s var(--ease-out-expo);\n}\n```\n\n### Background Effects\n\n```css\n/* Gradient Mesh */\n.gradient-bg {\n    background:\n        radial-gradient(ellipse at 20% 80%, rgba(120, 0, 255, 0.3) 0%, transparent 50%),\n        radial-gradient(ellipse at 80% 20%, rgba(0, 255, 200, 0.2) 0%, transparent 50%),\n        var(--bg-primary);\n}\n\n/* Noise Texture */\n.noise-bg {\n    background-image: url(\"data:image/svg+xml,...\"); /* Inline SVG noise */\n}\n\n/* Grid Pattern */\n.grid-bg {\n    background-image:\n        linear-gradient(rgba(255,255,255,0.03) 1px, transparent 1px),\n        linear-gradient(90deg, rgba(255,255,255,0.03) 1px, transparent 1px);\n    background-size: 50px 50px;\n}\n```\n\n### Interactive Effects\n\n```javascript\n/* 3D Tilt on Hover */\nclass TiltEffect {\n    constructor(element) {\n        this.element = element;\n        this.element.style.transformStyle = ''preserve-3d'';\n        this.element.style.perspective = ''1000px'';\n        this.bindEvents();\n    }\n\n    bindEvents() {\n        this.element.addEventListener(''mousemove'', (e) => {\n            const rect = this.element.getBoundingClientRect();\n            const x = (e.clientX - rect.left) / rect.width - 0.5;\n            const y = (e.clientY - rect.top) / rect.height - 0.5;\n\n            this.element.style.transform = `\n                rotateY(${x * 10}deg)\n                rotateX(${-y * 10}deg)\n            `;\n        });\n\n        this.element.addEventListener(''mouseleave'', () => {\n            this.element.style.transform = ''rotateY(0) rotateX(0)'';\n        });\n    }\n}\n```\n\n---\n\n## Troubleshooting\n\n### Common Issues\n\n**Fonts not loading:**\n- Check Fontshare/Google Fonts URL\n- Ensure font names match in CSS\n\n**Animations not triggering:**\n- Verify Intersection Observer is running\n- Check that `.visible` class is being added\n\n**Scroll snap not working:**\n- Ensure `scroll-snap-type` on html/body\n- Each slide needs `scroll-snap-align: start`\n\n**Mobile issues:**\n- Disable heavy effects at 768px breakpoint\n- Test touch events\n- Reduce particle count or disable canvas\n\n**Performance issues:**\n- Use `will-change` sparingly\n- Prefer `transform` and `opacity` animations\n- Throttle scroll/mousemove handlers\n\n---\n\n## Related Skills\n\n- **learn** — Generate FORZARA.md documentation for the presentation\n- **frontend-design** — For more complex interactive pages beyond slides\n- **design-and-refine:design-lab** — For iterating on component designs\n\n---\n\n## Example Session Flow\n\n1. User: \"I want to create a pitch deck for my AI startup\"\n2. Skill asks about purpose, length, content\n3. User shares their bullet points and key messages\n4. Skill asks about desired feeling (Impressed + Excited)\n5. Skill generates 3 style previews\n6. User picks Style B (Neon Cyber), asks for darker background\n7. Skill generates full presentation with all slides\n8. Skill opens the presentation in browser\n9. User requests tweaks to specific slides\n10. Final presentation delivered\n\n---\n\n## Conversion Session Flow\n\n1. User: \"Convert my slides.pptx to a web presentation\"\n2. Skill extracts content and images from PPT\n3. Skill confirms extracted content with user\n4. Skill asks about desired feeling/style\n5. Skill generates style previews\n6. User picks a style\n7. Skill generates HTML presentation with preserved assets\n8. Final presentation delivered"},"lastSynced":"2026-03-08T02:03:06.445Z","agentAnalysis":{"suitability":{"en":"Perfect for Visual AI Agents needing to create zero-dependency, animation-rich HTML presentations.","zh":"适合需要创建零依赖、动画丰富的HTML演示文档的视觉AI代理。","ja":"ビジュアルAIエージェントがゼロ依存のアニメーション豊かなHTMLプレゼンテーションを作成する必要がある場合に最適です。","ko":"시각 AI 에이전트가 제로 의존성, 애니메이션豊かな HTML 프레젠테이션을 생성해야 하는 경우에 적합합니다.","es":"Perfecto para Agentes de IA Visuales que necesitan crear presentaciones HTML ricas en animaciones y sin dependencias.","fr":"Parfait pour les Agents d''IA Visuels ayant besoin de créer des présentations HTML riches en animations et sans dépendances.","de":"Perfekt für Visuelle KI-Agents, die zero-Abhängigkeits-, animationsreiche HTML-Präsentationen erstellen müssen.","pt":"Perfeito para Agentes de IA Visuais que precisam criar apresentações HTML ricas em animação e sem dependências.","ru":"Идеально для визуальных агентов ИИ, которым нужно создавать презентации HTML с нулевыми зависимостями и богатыми анимациями.","ar":"مثالي للوكلاء الإلكترونيين البصريين الذين يحتاجون إلى إنشاء عروض HTML غنية بالرسوم المتحركة وخالية من الاعتماديات."},"recommendation":{"en":"Empowers agents to generate production-quality slide decks with inline CSS/JS, leveraging the power of single HTML files to create immersive visual experiences without relying on npm or build tools, utilizing ''show, don''t tell'' principles for aesthetic discovery.","zh":"赋予代理生成生产级幻灯片的能力，利用内联CSS/JS，利用单个HTML文件的力量创建身临其境的视觉体验，而无需依赖npm或构建工具，利用“展示，而不是告诉”原则进行美学发现。","ja":"エージェントがインラインCSS/JSを利用してプロダクション品質のスライドデッキを生成する能力を提供し、単一のHTMLファイルの力によりビルドツールやnpmに依存せずに没入感のある視覚体験を作成することができ、“見せる、語ることではない”の原則に従った美学的発見を可能にします。","ko":"에이전트가 프로덕션 품질의 슬라이드 데크를 생성할 수 있는 기능을 제공하여 인라인 CSS/JS를 활용하고 단일 HTML 파일의 힘을 이용하여 npm 또는 빌드 도구에 의존하지 않고 몰입감 있는 시각적 경험을 생성할 수 있으며, ''보여주기, 말하지 않기'' 원칙에 따라 미학적 발견을 가능하게 합니다.","es":"Habilita a los agentes a generar presentaciones de diapositivas de producción de alta calidad con CSS/JS integrados, aprovechando el poder de archivos HTML únicos para crear experiencias visuales inmersivas sin depender de npm o herramientas de compilación, utilizando principios de ''mostrar, no contar'' para el descubrimiento estético.","fr":"Permet aux agents de générer des présentations de diapositives de production de haute qualité avec CSS/JS intégrés, en exploitant le pouvoir de fichiers HTML uniques pour créer des expériences visuelles immersives sans s''appuyer sur npm ou des outils de construction, en utilisant des principes de ''montrer, ne pas dire'' pour la découverte esthétique.","de":"Ermächtigt Agents, Produktionsqualitäts-Foliensätze mit integriertem CSS/JS zu generieren, die Kraft von einzelnen HTML-Dateien nutzend, um immersive visuelle Erfahrungen zu schaffen, ohne auf npm oder Build-Tools angewiesen zu sein, unter Verwendung von ''zeigen, nicht erzählen''-Prinzipien für ästhetische Entdeckung.","pt":"Habilita os agentes a gerar decks de slides de qualidade de produção com CSS/JS embutido, aproveitando o poder de arquivos HTML únicos para criar experiências visuais imersivas sem depender de npm ou ferramentas de compilação, utilizando princípios de ''mostrar, não contar'' para descoberta estética.","ru":"Наделяет агентов возможностью генерировать слайд-шоу высокого качества с встроенным CSS/JS, используя силу единого файла HTML для создания погружающих визуальных опытов без полагания на npm или инструменты сборки, используя принципы ''покажите, не говорите'' для эстетического открытия.","ar":"تمكّن الوكلاء من إنشاء عروض توضيحية من الدرجة الأولى مع CSS/JS مدمج، مستفيدة من قوة الملفات HTML الفردية ل创ATION تجارب بصرية غامرة بدون الاعتماد على npm أو أدوات البناء، مستخدمة مبادئ ''أظهر، لا تحكي'' لاكتشاف جمالي."},"useCases":{"en":["Generating interactive, animation-rich HTML presentations for client pitches","Creating immersive visual experiences for non-designers to explore different aesthetics","Developing production-quality slide decks that run entirely in the browser"],"zh":["为客户推介生成交互式、动画丰富的HTML演示文档","为非设计师创建沉浸式视觉体验，以探索不同的美学","开发完全在浏览器中运行的生产级幻灯片"],"ja":["クライアント向けのプレゼンテーションにインタラクティブでアニメーション豊かなHTMLプレゼンテーションを生成する","非デザイナー向けに没入感のある視覚体験を作成し、さまざまな美学を探索する","ブラウザ内で完全に動作するプロダクション品質のスライドデッキを開発する"],"ko":["클라이언트 피치에 대한 상호 작용형, 애니메이션豊かな HTML 프레젠테이션을 생성합니다.","비디자이너를 위한 몰입감 있는 시각적 경험을 생성하여 다양한 미학을 탐색합니다.","브라우저에서 완전히 실행되는 프로덕션 품질의 슬라이드 데크를 개발합니다."],"es":["Generar presentaciones HTML interactivas y ricas en animaciones para presentaciones a clientes","Crear experiencias visuales inmersivas para no diseñadores para explorar diferentes estéticas","Desarrollar presentaciones de diapositivas de producción de alta calidad que se ejecutan completamente en el navegador"],"fr":["Générer des présentations HTML interactives et riches en animations pour des présentations à clients","Créer des expériences visuelles immersives pour les non-concepteurs pour explorer différentes esthétiques","Développer des présentations de diapositives de production de haute qualité qui s''exécutent entièrement dans le navigateur"],"de":["Interaktive, animationsreiche HTML-Präsentationen für Kundenpräsentationen generieren","Immersive visuelle Erfahrungen für Nicht-Designer erstellen, um unterschiedliche Ästhetiken zu erkunden","Produktionsqualitäts-Foliensätze entwickeln, die vollständig im Browser ausgeführt werden"],"pt":["Gerar apresentações HTML interativas e ricas em animação para pitches de clientes","Criar experiências visuais imersivas para não-designers explorarem diferentes estéticas","Desenvolver decks de slides de qualidade de produção que funcionam inteiramente no navegador"],"ru":["Генерировать интерактивные презентации HTML с богатыми анимациями для клиентских презентаций","Создавать погружающие визуальные опыты для не-дизайнеров, чтобы они могли исследовать разные эстетики","Разрабатывать слайд-шоу высокого качества, которые работают полностью в браузере"],"ar":["إنشاء عروض HTML تفاعلية وغنية بالرسوم المتحركة لمقترحات العملاء","创ATION تجارب بصرية غامرة للمصممين غير المحترفين لاستكشاف جماليات مختلفة","تطوير عروض توضيحية من الدرجة الأولى تعمل بالكامل في المتصفح"]},"limitations":{"en":["Limited to single HTML file output with inline CSS/JS","No support for external dependencies or build tools"],"zh":["仅限单个HTML文件输出，内联CSS/JS","不支持外部依赖或构建工具"],"ja":["単一のHTMLファイル出力のみ、インラインCSS/JS","外部依存またはビルドツールはサポートされません"],"ko":["단일 HTML 파일 출력만 가능, 인라인 CSS/JS","외부 의존성 또는 빌드 도구를 지원하지 않음"],"es":["Limitado a la salida de un solo archivo HTML con CSS/JS integrados","No admite dependencias externas o herramientas de compilación"],"fr":["Limité à la sortie d''un seul fichier HTML avec CSS/JS intégrés","N''admet pas les dépendances externes ou les outils de construction"],"de":["Begrenzt auf die Ausgabe von einzelnen HTML-Dateien mit integriertem CSS/JS","Unterstützt keine externen Abhängigkeiten oder Build-Tools"],"pt":["Limitado a saída de arquivo HTML único com CSS/JS embutido","Sem suporte para dependências externas ou ferramentas de compilação"],"ru":["Ограничен выводом единственного файла HTML с встроенным CSS/JS","Нет поддержки для внешних зависимостей или инструментов сборки"],"ar":["محدود بالملف HTML المنفرد مع CSS/JS مدمج","لا يدعم الاعتماديات الخارجية أو أدوات البناء"]},"version":4},"contentHash":"518b41cc9b9135e7c53f1e9ff27e6e9e06e79a36e15b2b9696c1cbfe35fddedf","qualityScore":45}');
