INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('digitarald/product-brain/frontend-slides', 'frontend-slides', 'digitarald', 'product-brain', 'community', 'frontend-slides digitarald product-brain community The frontend-slides skill creates zero-dependency, animation-rich HTML presentations that run entirely in the browser, helping non-designers discover their preferred aesthetic through visual exploration. 前端幻灯片技能帮助非设计师通过视觉探索发现他们的首选美学，并生成生产质量的幻灯片 フロントエンドスライドスキルは、非デザイナーが視覚的な探索を通じて彼らの好みの美学を発見するのを助け、そして生産品質のスライドを生成します 프론트엔드 슬라이드 스킬은 비디자이너가 시각적 탐색을 통해 그들의 선호하는 미학을 발견하도록 도와주고 생산품질의 슬라이드를 생성합니다 Frontend-slides es una habilidad de AI Agent que crea presentaciones HTML en el navegador, sin dependencias y con animaciones. Ayuda a los no diseñadores a descubrir su estética preferida Frontend-slides est une compétence d''outil d''IA qui crée des présentations HTML riches en animations, sans dépendances. Elle aide les non-designers à découvrir leur esthétique préférée Frontend-slides ist eine Fähigkeit von AI-Tools, die animationsreiche HTML-Präsentationen im Browser erstellt, ohne Abhängigkeiten. Sie hilft Nicht-Designern, ihre bevorzugte Ästhetik zu entdecken A habilidade de Frontend Slides permite criar apresentações HTML enriquecidas com animações, sem dependências. Ela ajuda a gerar decks de slides de alta qualidade. Навык Frontend Slides позволяет создать HTML-презентации с анимациями, без зависимостей. Он помогает генерировать decks слайдов высокого качества. تسمح مهارة Frontend Slides بإنشاء عروض HTML متحركة بدون зависимости. تساعد في إنشاء عروض شرائح عالية الجودة. how to use frontend-slides what is frontend-slides frontend-slides alternative frontend-slides vs reveal.js frontend-slides install frontend-slides setup guide zero-dependency presentation tools animation-rich HTML presentations frontend-slides for non-designers 前端幻灯片 零依赖HTML 动画丰富的HTML演示文稿 浏览器运行的幻灯片 视觉探索 非设计师的幻灯片设计 AIエージェント HTML演示文稿生成 Generates single HTML files with inline CSS/JS Creates animation-rich presentations that run entirely in the browser Supports visual exploration for non-designers to discover their preferred aesthetic Produces zero-dependency presentations without requiring npm or build tools Enables generation of production-quality slide decks frontend-slides is a skill that generates single HTML files with inline CSS/JS for creating production-quality slide decks without dependencies.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Aias/red-cliff-record/rcr-backend', 'community', 'Aias', 'red-cliff-record', 'Aias/red-cliff-record', 'rcr-backend', 0, 0, 45, '2026-03-08T01:57:15.328Z', '2026-03-08T02:03:06.504Z', '641d679890673282006d147c38d38baf556c9c4f970ccf6a64436a1628ec88a9', '{"id":"Aias/red-cliff-record/rcr-backend","name":"rcr-backend","description":{"en":"rcr-backend is a personal knowledge management system that utilizes a local-first approach, ideal for developers seeking data ownership. It supplements the typescript-guidelines skill.","zh":"RCR Backend是一种本地优先的个人知识管理方法，使用Drizzle ORM实现高效查询和数据操作","ja":"RCR Backendはローカルファーストのパーソナルナレッジマネジメントアプローチで、Drizzle ORMを使用して効率的なクエリとデータ操作を実現","ko":"RCR Backend는 로컬 우선의 개인 지식 관리 방법으로 Drizzle ORM을 사용하여 효율적인 쿼리와 데이터操作을 제공","es":"rcr-backend es un enfoque de gestión de conocimiento personal que utiliza Drizzle ORM y TypeScript para proporcionar una experiencia de usuario segura y eficiente","fr":"rcr-backend est une approche de gestion des connaissances personnelles qui utilise Drizzle ORM et TypeScript pour offrir une expérience utilisateur sécurisée et efficace","de":"rcr-backend ist ein Ansatz für die persönliche Wissensverwaltung, der Drizzle ORM und TypeScript verwendet, um eine sichere und effiziente Benutzererfahrung zu bieten","pt":"O RCR Backend é uma abordagem de gerenciamento de conhecimento pessoal local-first, que utiliza Drizzle ORM e TypeScript para fornecer uma experiência de desenvolvimento robusta.","ru":"RCR Backend - это локально-ориентированный подход к личному управлению знаниями, который использует Drizzle ORM и TypeScript для обеспечения прочного опыта разработки ИИ Агентов","ar":"RCR Backend هو نهج إدارة المعرفة الشخصية من الأول إلى الأول، يستخدم Drizzle ORM وTypeScript لتقديم تجربة تطوير قوية لأدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"rcr-backend: Drizzle ORM Setup 