INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Aias/red-cliff-record/rcr-backend', 'rcr-backend', 'Aias', 'red-cliff-record', 'community', 'rcr-backend Aias red-cliff-record community rcr-backend is a personal knowledge management system that utilizes a local-first approach, ideal for developers seeking data ownership. It supplements the typescript-guidelines skill. RCR Backend是一种本地优先的个人知识管理方法，使用Drizzle ORM实现高效查询和数据操作 RCR Backendはローカルファーストのパーソナルナレッジマネジメントアプローチで、Drizzle ORMを使用して効率的なクエリとデータ操作を実現 RCR Backend는 로컬 우선의 개인 지식 관리 방법으로 Drizzle ORM을 사용하여 효율적인 쿼리와 데이터操作을 제공 rcr-backend es un enfoque de gestión de conocimiento personal que utiliza Drizzle ORM y TypeScript para proporcionar una experiencia de usuario segura y eficiente rcr-backend est une approche de gestion des connaissances personnelles qui utilise Drizzle ORM et TypeScript pour offrir une expérience utilisateur sécurisée et efficace rcr-backend ist ein Ansatz für die persönliche Wissensverwaltung, der Drizzle ORM und TypeScript verwendet, um eine sichere und effiziente Benutzererfahrung zu bieten O RCR Backend é uma abordagem de gerenciamento de conhecimento pessoal local-first, que utiliza Drizzle ORM e TypeScript para fornecer uma experiência de desenvolvimento robusta. RCR Backend - это локально-ориентированный подход к личному управлению знаниями, который использует Drizzle ORM и TypeScript для обеспечения прочного опыта разработки ИИ Агентов RCR Backend هو نهج إدارة المعرفة الشخصية من الأول إلى الأول، يستخدم Drizzle ORM وTypeScript لتقديم تجربة تطوير قوية لأدوات الذكاء الاصطناعي how to use rcr-backend rcr-backend drizzle orm rcr-backend alternative rcr-backend setup guide what is rcr-backend rcr-backend vs barnsworthburning rcr-backend install local-first personal knowledge management RCR Backend AIエージェント 本地数据管理 Drizzle ORM typescript query builder mutation upsert onConflictDoUpdate Utilizes Drizzle v2 query syntax for reads via db.query.<table>.findMany/findFirst Provides object-style where, built-in with for relations, and columns selection Supports mutations via db.insert(), db.update(), and db.delete() with upsert capability Avoids raw SQL in favor of query builder APIs Enables external-source data handling rcr-backend is a local-first, own-your-data approach to personal knowledge management, utilizing Drizzle ORM for efficient data handling.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('adophilus/norahealth/effect-ts', 'community', 'adophilus', 'norahealth', 'adophilus/norahealth', 'effect-ts', 0, 0, 45, '2026-03-08T01:57:15.332Z', '2026-03-08T02:03:15.604Z', '83cf744de0548ee7665bfff50975ec7df3dd744bd5609be2fbfbd8081a0ec432', '{"id":"adophilus/norahealth/effect-ts","name":"effect-ts","description":{"en":"The effect-ts skill provides expert guidance for functional programming with the Effect library, benefiting developers who need help with error handling and dependency injection. It covers composability and testing patterns.","zh":"Effect-TS 是一个函数式编程库，提供错误处理、依赖注入、可组合性和测试模式的功能。","ja":"Effect-TS は、エラー処理、依存性の注入、組み合わせ可能性、テストパターンを提供する関数型プログラミングライブラリです。","ko":"Effect-TS는 함수형 프로그래밍 라이브러리로서 오류 처리, 의존성 주입, 조합 가능성 및 테스트 패턴 기능을 제공합니다.","es":"Effect-TS es una biblioteca para programación funcional que ofrece patrones de manejo de errores, inyección de dependencias y pruebas","fr":"Effect-TS est une bibliothèque pour la programmation fonctionnelle qui propose des modèles de gestion d''erreurs, d''injection de dépendances et de tests","de":"Effect-TS ist eine Bibliothek für funktionale Programmierung, die Muster für Fehlerbehandlung, Abhängigkeitseinjektion und Tests bietet","pt":"Effect-TS é uma biblioteca para programação funcional que proporciona tratamento de erros e injeção de dependência. Aprenda a configurá-la e usá-la.","ru":"Effect-TS - это библиотека для функционального программирования, которая обеспечивает обработку ошибок и внедрение зависимостей. Узнайте, как её настроить и использовать.","ar":"Effect-TS هي مكتبة للبرمجة الوظيفية توفر معالجة الأخطاء والحقن التلقائي لل依赖ات. تعلم كيفية إعدادها واستخدامها."},"seo":{"title":{"en":"effect-ts: Expert Guidance for Functional Programming | A...","zh":"Effect-TS 专家指南：函数式编程最佳实践","ja":"Effect-TS エキスパートガイド：関数型プログラミングのベストプラクティス","ko":"Effect-TS 전문가 가이드: 함수형 프로그래밍 Setup Guide","es":"Guía de configuración de Effect-TS para programación func...","fr":"Guide de configuration d''Effect-TS pour la programmation ...","de":"Effect-TS-Konfigurationsleitfaden für funktionale Program...","pt":"Guia de Configuração Effect-TS: Programação Funcional com...","ru":"Effect-TS: Руководство по Настройке для Функционального П...","ar":"دليل إعداد Effect-TS: البرمجة الوظيفية مع مكتبة Effect"},"description":{"en":"Unlock the full potential of Effect-TS with expert guidance on error handling, dependency injection, and testing patterns. Get started with our setup guide t...","zh":"了解 Effect-TS 的错误处理、依赖注入、可组合性和测试模式，实现函数式编程的最佳实践。AIエージェント","ja":"Effect-TS を使用した関数型プログラミングのエラー処理、依存性の注入、組み合わせ可能性、テストパターンについて学びましょう。AIエージェント","ko":"Effect-TS를 사용한 함수형 프로그래밍의 오류 처리, 의존성 주입, 조합 가능성 및 테스트 패턴에 대한 전문가 가이드를 확인하세요. AI 도구","es":"Aprende a configurar Effect-TS para mejorar tus habilidades en programación funcional con nuestra guía paso a paso","fr":"Découvrez comment configurer Effect-TS pour améliorer vos compétences en programmation fonctionnelle avec notre guide étape par étape","de":"Erfahren Sie, wie Sie Effect-TS konfigurieren, um Ihre Fähigkeiten in der funktionalen Programmierung zu verbessern, mit unserem Schritt-für-Schritt-Leitfaden","pt":"Aprenda a configurar e usar a biblioteca Effect-TS para programação funcional, incluindo tratamento de erros e injeção de dependência.","ru":"Узнайте, как настроить и использовать библиотеку Effect-TS для функционального программирования, включая обработку ошибок и внедрение зависимостей.","ar":"تعلم كيفية إعداد واستخدام مكتبة Effect-TS للبرمجة الوظيفية، بما في ذلك معالجة الأخطاء والحقن التلقائي لل依赖ات."},"definition":{"en":"effect-ts is a library for functional programming that provides expert guidance on error handling, dependency injection, composability, and testing patterns.","zh":"Effect-TS 是一个函数式编程库，用于处理错误、依赖注入和可组合性。","ja":"Effect-TS は、エラー処理、依存性の注入、組み合わせ可能性を提供する関数型プログラミングライブラリです。","ko":"Effect-TS는 함수형