INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mich3333/mich3333/subagents-discipline', 'subagents-discipline', 'mich3333', 'mich3333', 'community', 'subagents-discipline mich3333 mich3333 community The subagents-discipline skill provides config files for GitHub profiles, focusing on testing features and external data handling. It benefits developers by ensuring accurate data integration and robust testing. subagents-discipline配置文件设置指南，帮助您正确配置GitHub配置文件 AIエージェントのsubagents-discipline設定ガイドです。GitHubの設定ファイルを正しく設定する方法を学びます AI 에이전트 subagents-discipline 설정 안내입니다. GitHub 구성 파일을 올바르게 설정하는 방법을 배웁니다 Subagents-discipline es una habilidad que te permite configurar archivos para mejorar la calidad de tus proyectos de desarrollo de AI Agentes. Se centra en probar la función, no solo el componente. Subagents-discipline est une compétence qui vous permet de configurer des fichiers pour améliorer la qualité de vos projets de développement d''outils d''IA. Elle se concentre sur le test de la fonctionnalité, et non seulement du composant. Subagents-discipline ist eine Fähigkeit, die es Ihnen ermöglicht, Konfigurationsdateien für die Verbesserung der Qualität Ihrer KI-Tool-Projekte zu erstellen. Sie konzentriert sich auf das Testen der Funktion, nicht nur des Komponenten. subagents-discipline é uma abordagem para melhorar a disciplina de implementação em projetos de desenvolvimento, com foco em testar recursos e não apenas componentes subagents-discipline - это подход к улучшению дисциплины реализации в проектах разработки, с фокусом на тестировании функций, а не только компонентов с помощью ИИ Агентов subagents-discipline هو نهج لتحسين انضباط التنفيذ في مشاريع التطوير، مع التركيز على اختبار الميزات وليس فقط المكونات باستخدام أدوات الذكاء الاصطناعي how to use subagents-discipline subagents-discipline GitHub setup subagents-discipline vs traditional testing subagents-discipline implementation guide what is subagents-discipline subagents-discipline alternative approaches subagents-discipline install and configure subagents-discipline best practices for AI agents subagents-discipline for robust data handling subagents-discipline setup guide for developers subagents-discipline AI配置文件 GitHub配置文件 配置文件设置 测试功能 查看实际数据 记录字段名称 Fetches and reads actual data from external sources before coding Notes exact field names, types, and formats from observed data Codes against observed data to prevent field name mismatches and wrong data shapes Applies the ''Look Before You Code'' principle to ensure data accuracy Enforces the ''Test the FEATURE, not just the component'' core principle subagents-discipline is a set of implementation principles emphasizing thorough testing and data validation, ensuring reliable interactions with external data sources like APIs and databases');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('tominhphong/dfw-viet-biz/knowns.task.brainstorm', 'community', 'tominhphong', 'dfw-viet-biz', 'tominhphong/dfw-viet-biz', 'knowns.task.brainstorm', 0, 0, 45, '2026-03-08T01:57:15.345Z', '2026-03-08T02:03:35.852Z', '35ba22358662fbcbbe0c6720d3bc8313872f21c112dfb8d0be79ec1385e4541a', '{"id":"tominhphong/dfw-viet-biz/knowns.task.brainstorm","name":"knowns.task.brainstorm","description":{"en":"The knowns.task.brainstorm skill helps developers convert vague task requirements into concrete designs through structured questioning and exploration, benefiting AI agent developers and project managers.","zh":"knowns.task.brainstorm技能通过结构化提问和探索，将模糊的需求转化为具体的设计","ja":"knowns.task.brainstormスキルは、構造化された質問と探索を通じて、タスクのブレインストーミングを実施する","ko":"knowns.task.brainstorm 스킬은 태스크 브레인스토밍을 통해 구체적인 설계를 생성합니다","es":"knowns.task.brainstorm es una habilidad que convierte requisitos vagos en diseños concretos a través de preguntas estructuradas y exploración","fr":"knowns.task.brainstorm est une compétence qui transforme des exigences vagues en conceptions concrètes grâce à des questions structurées et une exploration","de":"knowns.task.brainstorm ist eine Fähigkeit, die vage Anforderungen in konkrete Designs durch strukturierte Fragen und Exploration umwandelt","pt":"O knowns.task.brainstorm é uma habilidade que ajuda a converter requisitos vagos em design concreto através de questionamento estruturado","ru":"Известные задачи ИИ Агентов: knowns.task.brainstorm - это навык, который помогает преобразовать неясные требования в конкретный дизайн","ar":"knowns.task.brainstorm هو مهارة تساعد على تحويل المتطلبات الغامضة إلى تصميم ملموس من خلال الاستعلام الهيكلي"},"seo":{"title":{"en":"knowns.task.brainstorm: Structured Task Design Guide | AI...","zh":"AIエージェント任务脑暴技巧：knowns.task.brainstorm Setup Guide","ja":"AIエージェントのタスクブレインストーミング：knowns.task.brainstorm ベストプラクティス","ko":"AI 에이전트 태스크 브레인스토밍：knowns.task.brainstorm 시작 가이드","es":"Guía de configuración de knowns.task.brainstorm para agen...","fr":"Guide d''utilisation de knowns.task.brainstorm pour les ou...","de":"Einrichtungsleitfaden für knowns.task.brainstorm in KI-Ag...","pt":"Guia de Configuração do knowns.task.brainstorm para Desen...","ru":"Настройка известных задач ИИ Агентов: knowns.task.brainstorm","ar":"دليل إعداد knowns.task.brainstorm للأجهزة الذكية"},"description":{"en":"Unlock efficient task design with knowns.task.brainstorm. Explore approaches and convert vague requirements into concrete designs. Learn how to get started t...","zh":"了解knowns.task.brainstorm技能，通过结构化提问和探索将模糊的需求转化为具体的设计","ja":"knowns.task.brainstormスキルを使用して、タスクのブレインストーミングを実施し、具体的な設計を作成する","ko":"knowns.task.brainstorm 스킬을 사용하여 태스크 브레인스토밍을 통해 구체적인 설계를 생성하십시오","es":"Aprende a utilizar knowns.task.brainstorm para convertir requisitos vagos en diseños concretos mediante preguntas estructuradas","fr":"Découvrez comment utiliser knowns.task.brainstorm pour transformer des exigences vagues en conceptions concrètes grâce à des questions structurées","de":"Erfahren Sie, wie Sie knowns.task.brainstorm verwenden, um vage Anforderungen in konkrete Designs durch strukturierte Fragen umzuwandeln","pt":"Aprenda a configurar o knowns.task.brainstorm para converter requisitos vagos em design concreto através de questionamento estruturado","ru":"Узнайте, как настроить известные задачи ИИ Агентов для структурированного вопроса и изучения","ar":"اكتشف كيفية إعداد knowns.task.brainstorm لتحويل المتطلبات الغامضة إلى تصميم ملموس من خلال الاستعلام الهيكلي"},"definition":{"en":"knowns.task.brainstorm is a task design skill that uses structured questioning to understand problems before proposing solutions, utilizing a phased approach for efficient design.","zh":"knowns.task.brainstorm是一种AI技能，用于通过结构化提问和探索将模糊的需求转化为具体的设计","ja":"knowns.task.brainstormは、タスクのブレインストーミングを実施するAIスキルです","ko":"knowns.task.brainstorm은 태스크 브레인스토밍을 위해 구조化된 질문과 탐색을 사용하는 AI 스킬입니다","es":"knowns.task.brainstorm es una habilidad de agente de IA que utiliza preguntas estructuradas para explorar enfoques y convertir requisitos vagos en diseños concretos","fr":"knowns.task.brainstorm est une compétence d''outil d''IA qui utilise des questions structurées pour explorer les approches et transformer des exigences vagues en conceptions concrètes","de":"knowns.task.brainstorm ist eine Fähigkeit von KI-Agenten, die strukturierte Fragen verwendet, um Ansätze zu erkunden und vage Anforderungen in konkrete Designs umzuwandeln","pt":"knowns.task.brainstorm é uma habilidade de questionamento estruturado para entender problemas antes de propor soluções","ru":"Известные задачи ИИ Агентов: knowns.task.brainstorm - это навык структурированного вопроса для понимания проблем до предложения решений","ar":"knowns.task.brainstorm هي مهارة استعلام هيكلي لفهم المشكلات قبل اقتراح الحلول"},"features":{"en":["Utilizes a phased approach, starting with Phase 1: Discovery","Employs one question at a time to avoid overwhelming users","Prefers multiple-choice questions for efficient decision-making","Announces the use of the knowns.task.brainstorm skill at the start of the process","Adheres to the core principle of understanding the problem before proposing solutions"],"zh":["结构化提问和探索","多选题支持","一个问题一个问题的提问方式"," UNDERSTAND THE PROBLEM BEFORE PROPOSING SOLUTIONS核心原则"],"ja":["構造化された質問と探索","多選択式のサポート","一問一答の質問方式","UNDERSTAND THE PROBLEM BEFORE PROPOSING SOLUTIONSコアプリンシプル"],"ko":["구조화된 질문과 탐색","다중 선택지 지원","하나의 질문당 하나의 답변 방식","UNDERSTAND THE PROBLEM BEFORE PROPOSING SOLUTIONS 핵심 원칙"],"es":["Preguntas estructuradas para explorar enfoques","Opción de selección múltiple para preferencias","Fase de descubrimiento para comprender el problema","Enfoque en entender el problema antes de proponer soluciones","Uso de preguntas una a la vez para evitar sobrecarga"],"fr":["Questions structurées pour explorer les approches","Option de sélection multiple pour les préférences","Phase de découverte pour comprendre le problème","Focus sur la compréhension du problème avant de proposer des solutions","Utilisation de questions une à la fois pour éviter la surcharge"],"de":["Strukturierte Fragen zur Erkundung von Ansätzen","Mehrfachauswahl für Präferenzen","Entdeckungsphase zum Verständnis des Problems","Fokus auf das Verständnis des Problems vor der Lösungsvorschlag","Verwendung von Fragen eine nach der anderen, um Überlastung zu vermeiden"],"pt":["Fase de Descoberta com questionamento estruturado","Uso de múltipla escolha quando possível","Análise de abordagens para resolver problemas","Desenvolvimento de design concreto a partir de requisitos vagos","Utilização de princípios de questionamento para entender problemas"],"ru":["Фаза открытия со структурированным вопросом","Использование множественного выбора, когда это возможно","Анализ подходов для решения проблем","Разработка конкретного дизайна из неясных требований","Применение принципов вопроса для понимания проблем"],"ar":["مرحلة الاستكشاف بالاستعلام الهيكلي","استخدام متعدد الخيارات عند الإمكان","تحليل المناهج لحل المشكلات","تطوير تصميم ملموس من المتطلبات الغامضة","تطبيق مبادئ الاستعلام لفهم المشكلات"]},"keywords":{"en":["how to use knowns.task.brainstorm","what is knowns.task.brainstorm","knowns.task.brainstorm alternative","knowns.task.brainstorm vs competing design skills","knowns.task.brainstorm setup guide","knowns.task.brainstorm install for AI agents"],"zh":["AIエージェント","knowns.task.brainstorm","任务脑暴","结构化提问","多选题","UNDERSTAND THE PROBLEM BEFORE PROPOSING SOLUTIONS"],"ja":["AIエージェント","knowns.task.brainstorm","タスクブレインストーミング","構造化された質問","多選択式","UNDERSTAND THE PROBLEM BEFORE PROPOSING SOLUTIONS"],"ko":["AI 에이전트","knowns.task.brainstorm","태스크 브레인스토밍","구조화된 질문","다중 선택지","UNDERSTAND THE PROBLEM BEFORE PROPOSING SOLUTIONS"],"es":["agentes de IA","knowns.task.brainstorm","diseño de tareas","preguntas estructuradas","exploración de enfoques","configuración de agentes de IA","desarrollo de software","ingeniería de requisitos"],"fr":["outils d''IA","knowns.task.brainstorm","conception de tâches","questions structurées","exploration d''approches","configuration des outils d''IA","développement de logiciels","ingénierie des exigences"],"de":["KI-Agenten","knowns.task.brainstorm","Aufgabenentwurf","strukturierte Fragen","Erkundung von Ansätzen","Einrichtung von KI-Agenten","Softwareentwicklung","Anforderungsingenieur"],"pt":["knowns.task.brainstorm","desenvolvimento de software","questionamento estruturado","design de sistemas","análise de requisitos","desenvolvedores de software","ferramentas de desenvolvimento"],"ru":["известные задачи ИИ Агентов","разработка программного обеспечения","структурированный вопрос","дизайн систем","анализ требований","разработчики программного обеспечения","инструменты разработки"],"ar":["knowns.task.brainstorm","تطوير البرمجيات","الاستعلام الهيكلي","تصميم الأنظمة","تحليل المتطلبات","مطورو البرمجيات","أدوات التطوير"]}},"owner":"tominhphong","repo":"dfw-viet-biz","repoPath":"tominhphong/dfw-viet-biz","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.345Z","topics":[],"category":"community","skillMd":{"name":"knowns.task.brainstorm","description":"Use when requirements are unclear, multiple approaches exist, or you need to explore solutions before planning","bodyPreview":"# Brainstorming for Tasks\n\nConvert vague requirements into concrete design through structured questioning and exploration.\n\n**Announce at start:** \"I''m using the knowns.task.brainstorm skill to explore approaches.\"\n\n**Core principle:** UNDERSTAND THE PROBLEM BEFORE PROPOSING SOLUTIONS.\n\n## The Process\n\n### Phase 1: Discovery\n\n**One question at a time.** Don''t overwhelm with multiple questions.\n\nPrefer multiple-choice when possible:\n```\nWhich approach do you prefer?\nA) Quick solution with trade-o","body":"# Brainstorming for Tasks\n\nConvert vague requirements into concrete design through structured questioning and exploration.\n\n**Announce at start:** \"I''m using the knowns.task.brainstorm skill to explore approaches.\"\n\n**Core principle:** UNDERSTAND THE PROBLEM BEFORE PROPOSING SOLUTIONS.\n\n## The Process\n\n### Phase 1: Discovery\n\n**One question at a time.** Don''t overwhelm with multiple questions.\n\nPrefer multiple-choice when possible:\n```\nWhich approach do you prefer?\nA) Quick solution with trade-offs\nB) Comprehensive solution, more effort\nC) Something else (describe)\n```\n\nQuestions to clarify:\n- What problem are we solving?\n- Who are the users/stakeholders?\n- What are the constraints?\n- What does success look like?\n\n### Phase 2: Research Existing Patterns\n\n```json\n// Search docs for related patterns\nmcp__knowns__search_docs({ \"query\": \"<topic>\" })\n\n// Check how similar things were done\nmcp__knowns__search_tasks({ \"query\": \"<keywords>\" })\n```\n\n**Learn from history** - completed tasks often contain implementation insights.\n\n### Phase 3: Explore Approaches\n\nPresent 2-3 options with trade-offs:\n\n```markdown\n## Option A: [Name]\n- **Approach**: Brief description\n- **Pros**: What''s good\n- **Cons**: What''s challenging\n- **Effort**: Low/Medium/High\n\n## Option B: [Name]\n- **Approach**: Brief description\n- **Pros**: What''s good\n- **Cons**: What''s challenging\n- **Effort**: Low/Medium/High\n```\n\n**Lead with your recommendation** and explain why.\n\n### Phase 4: Validate and Document\n\nAfter agreement:\n- Summarize the chosen approach\n- Identify potential risks\n- Define acceptance criteria\n\nIf creating a new task:\n```json\nmcp__knowns__create_task({\n  \"title\": \"<title>\",\n  \"description\": \"Based on brainstorm: <key decisions>\",\n  \"acceptanceCriteria\": [\"Criterion 1\", \"Criterion 2\"]\n})\n```\n\nIf updating existing task:\n```json\nmcp__knowns__update_task({\n  \"taskId\": \"$ARGUMENTS\",\n  \"description\": \"Updated based on brainstorm...\"\n})\n```\n\n## When to Use This Skill\n\n**Good candidates:**\n- Vague requirements (\"make it faster\", \"improve UX\")\n- Multiple valid approaches exist\n- Significant effort involved\n- New territory for the project\n\n**Skip for:**\n- Clear, well-defined tasks\n- Bug fixes with obvious solutions\n- Simple additions following existing patterns\n\n## Red Flags\n\n**You''re doing it wrong if:**\n- Proposing solutions before understanding the problem\n- Asking too many questions at once\n- Not researching existing patterns first\n- Skipping trade-off analysis\n\n## Remember\n\n- One question at a time\n- Research existing patterns first\n- Present options with trade-offs\n- Lead with your recommendation\n- Document the decision"},"lastSynced":"2026-03-08T02:03:35.852Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Project Managers and Developers needing structured task requirement analysis through multiple-choice questioning and exploration.","zh":"非常适合需要通过多项选择提问和探索进行结构化任务需求分析的AI项目经理和开发人员。","ja":"複数選択式の質問と探索を通じて構造化されたタスク要件分析を必要とするAIプロジェクトマネージャーと開発者に最適です。","ko":"다중 선택 질문과 탐색을 통한 구조화된 작업 요구사항 분석이 필요한 AI 프로젝트 관리자 및 개발자에게 이상적입니다.","es":"Ideal para Gerentes de Proyectos de IA y Desarrolladores que necesitan un análisis de requisitos de tareas estructurado a través de preguntas de opción múltiple y exploración.","fr":"Idéal pour les responsables de projets d''IA et les développeurs ayant besoin d''une analyse de requisitions de tâches structurée via des questions à choix multiple et une exploration.","de":"Ideal für AI-Projektmanager und Entwickler, die eine strukturierte Analyse von Aufgabenanforderungen durch multiple-choice-Fragen und Exploration benötigen.","pt":"Ideal para Gerentes de Projetos de IA e Desenvolvedores que necessitam de análise de requisitos de tarefas estruturadas por meio de questionamento de múltipla escolha e exploração.","ru":"Идеально подходит для менеджеров проектов ИИ и разработчиков, которым требуется структурированный анализ требований к задачам посредством вопросов с несколькими вариантами ответов и изучения.","ar":"مثالي لمنسقي المشاريع الذكية والأخصائيين الذين يحتاجون إلى تحليل متطلبات المهام المنظمة من خلال الاستجواب المتعدد والاستكشاف."},"recommendation":{"en":"Empowers agents to convert vague task requirements into concrete designs using UNDERSTAND THE PROBLEM BEFORE PROPOSING SOLUTIONS principle, leveraging structured questioning and exploration techniques, and preferring multiple-choice approaches when possible.","zh":"使智能体能够利用''先理解问题再提出解决方案''原则，通过结构化提问和探索技术，并在可能时优先采用多项选择方法，将模糊的任务需求转化为具体设计。","ja":"構造化された質問と探索技術を活用し、可能な場合は複数選択アプローチを優先する「ソリューション提案前に問題を理解する」原則を使用して、あいまいなタスク要件を具体的な設計に変換するようエージェントを強化します。","ko":"구조화된 질문과 탐색 기술을 활용하고 가능할 때마다 다중 선택 접근법을 선호하는 ''솔루션 제안 전에 문제 이해'' 원칙을 사용하여 모호한 작업 요구사항을 구체적인 설계로 전환하도록 에이전트를 강화합니다.","es":"Habilita a los agentes a convertir requisitos de tareas vagos en diseños concretos utilizando el principio ENTENDER EL PROBLEMA ANTES DE PROponer SOLUCIONES, aprovechando técnicas de preguntas estructuradas y exploración, y prefiere enfoques de opción múltiple cuando sea posible.","fr":"Habilite les agents à convertir les exigences de tâches vagues en conceptions concrètes en utilisant le principe COMPRENDRE LE PROBLÈME AVANT DE PROPOSER DES SOLUTIONS, en exploitant les techniques de questions structurées et d''exploration, et en préférant les approches à choix multiple lorsque cela est possible.","de":"Ermächtigt Agenten, vage Aufgabenanforderungen in konkrete Designs umzuwandeln, indem sie das Prinzip VERSTEHE DAS PROBLEM BEVOR DU LÖSUNGEN VORSCHLÄGST anwenden, strukturierte Frage- und Explorationstechniken nutzend und multiple-choice-Ansätze bevorzugend, wenn möglich.","pt":"Habilita agentes a converter requisitos de tarefas vagos em designs concretos utilizando o princípio ENTENDER O PROBLEMA ANTES DE PROPOR SOLUÇÕES, aproveitando técnicas de questionamento e exploração estruturadas e preferindo abordagens de múltipla escolha sempre que possível.","ru":"Наделяет агентов возможностью преобразовывать нечеткие требования к задачам в конкретные проекты, используя принцип ПОНЯТЬ ПРОБЛЕМУ ПЕРЕД ПРЕДЛОЖЕНИЕМ РЕШЕНИЙ, опираясь на структурированные вопросы и методы изучения, и отдающих предпочтение подходам с несколькими вариантами ответов, когда это возможно.","ar":"تمكن الوكلاء من تحويل متطلبات المهام الغامضة إلى تصاميم ملموسة باستخدام مبدأ الفهم المشكلة قبل اقتراح الحلول، واستخدام تقنيات الاستجواب والاستكشاف المنظمة، والتفضيل للمقاربات متعددة الخيارات عند الإمكان."},"useCases":{"en":["Exploring approaches for task requirement analysis","Converting vague requirements into concrete designs","Enhancing project planning through structured discovery"],"zh":["探索任务需求分析的方法","将模糊需求转化为具体设计","通过结构化发现增强项目规划"],"ja":["タスク要件分析のアプローチの探索","あいまいな要件の具体的な設計への変換","構造化された発見によるプロジェクト計画の強化"],"ko":["작업 요구사항 분석 접근법 탐색","모호한 요구사항을 구체적인 설계로 전환","구조화된 발견을 통한 프로젝트 계획 강화"],"es":["Explorar enfoques para el análisis de requisitos de tareas","Convertir requisitos vagos en diseños concretos","Mejorar la planificación de proyectos a través de la exploración estructurada"],"fr":["Explorer les approches pour l''analyse des exigences de tâches","Convertir les exigences vagues en conceptions concrètes","Améliorer la planification de projet via la découverte structurée"],"de":["Ansätze für die Analyse von Aufgabenanforderungen erkunden","Vage Anforderungen in konkrete Designs umwandeln","Projektplanung durch strukturierte Entdeckung verbessern"],"pt":["Explorar abordagens para análise de requisitos de tarefas","Converter requisitos vagos em designs concretos","Melhorar o planejamento de projetos por meio de descoberta estruturada"],"ru":["Изучение подходов для анализа требований к задачам","Преобразование нечетких требований в конкретные проекты","Усиление планирования проектов за счет структурированного открытия"],"ar":["استكشاف مناهج لتحليل متطلبات المهام","تحويل متطلبات المهام الغامضة إلى تصاميم ملموسة","تعزيز التخطيط للمشاريع من خلال الاستكشاف المنظم"]},"limitations":{"en":["Requires one question at a time approach to avoid overwhelming","Preferable to use multiple-choice when possible"],"zh":["需要采用一次一个问题的方法以避免信息过载","尽可能优先使用多项选择方式"],"ja":["圧倒されるのを避けるために一度に一つの質問アプローチが必要","可能な場合は複数選択方式を使用することが望ましい"],"ko":["정보 과부하를 피하기 위해 한 번에 하나의 질문 방식이 필요함","가능할 때마다 다중 선택 방식 사용이 바람직함"],"es":["Requiere un enfoque de una pregunta a la vez para evitar abrumar","Es preferible utilizar opción múltiple cuando sea posible"],"fr":["Nécessite une approche d''une question à la fois pour éviter de submerger","Il est préférable d''utiliser le choix multiple lorsque cela est possible"],"de":["Erfordert einen Ansatz von einer Frage nach der anderen, um Überforderung zu vermeiden","Es ist vorzuziehen, multiple-choice zu verwenden, wenn möglich"],"pt":["Exige abordagem de uma pergunta por vez para evitar sobrecarga","Preferível usar múltipla escolha quando possível"],"ru":["Требует подхода один вопрос за раз, чтобы избежать перегрузки","Предпочтительно использовать несколько вариантов ответов, когда это возможно"],"ar":["يتطلب نهج سؤال واحد في المرة لتجنب الحمل الزائد","يفضل استخدام متعدد الخيارات عند الإمكان"]},"version":4},"contentHash":"35ba22358662fbcbbe0c6720d3bc8313872f21c112dfb8d0be79ec1385e4541a","qualityScore":45}');
