INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('tominhphong/dfw-viet-biz/knowns.task.brainstorm', 'knowns.task.brainstorm', 'tominhphong', 'dfw-viet-biz', 'community', 'knowns.task.brainstorm tominhphong dfw-viet-biz community The knowns.task.brainstorm skill helps developers convert vague task requirements into concrete designs through structured questioning and exploration, benefiting AI agent developers and project managers. knowns.task.brainstorm技能通过结构化提问和探索，将模糊的需求转化为具体的设计 knowns.task.brainstormスキルは、構造化された質問と探索を通じて、タスクのブレインストーミングを実施する knowns.task.brainstorm 스킬은 태스크 브레인스토밍을 통해 구체적인 설계를 생성합니다 knowns.task.brainstorm es una habilidad que convierte requisitos vagos en diseños concretos a través de preguntas estructuradas y exploración knowns.task.brainstorm est une compétence qui transforme des exigences vagues en conceptions concrètes grâce à des questions structurées et une exploration knowns.task.brainstorm ist eine Fähigkeit, die vage Anforderungen in konkrete Designs durch strukturierte Fragen und Exploration umwandelt O knowns.task.brainstorm é uma habilidade que ajuda a converter requisitos vagos em design concreto através de questionamento estruturado Известные задачи ИИ Агентов: knowns.task.brainstorm - это навык, который помогает преобразовать неясные требования в конкретный дизайн knowns.task.brainstorm هو مهارة تساعد على تحويل المتطلبات الغامضة إلى تصميم ملموس من خلال الاستعلام الهيكلي how to use knowns.task.brainstorm what is knowns.task.brainstorm knowns.task.brainstorm alternative knowns.task.brainstorm vs competing design skills knowns.task.brainstorm setup guide knowns.task.brainstorm install for AI agents AIエージェント knowns.task.brainstorm 任务脑暴 结构化提问 多选题 UNDERSTAND THE PROBLEM BEFORE PROPOSING SOLUTIONS Utilizes a phased approach, starting with Phase 1: Discovery Employs one question at a time to avoid overwhelming users Prefers multiple-choice questions for efficient decision-making Announces the use of the knowns.task.brainstorm skill at the start of the process Adheres to the core principle of understanding the problem before proposing solutions knowns.task.brainstorm is a task design skill that uses structured questioning to understand problems before proposing solutions, utilizing a phased approach for efficient design.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('hmislk/hmis/jsf-ajax', 'community', 'hmislk', 'hmis', 'hmislk/hmis', 'jsf-ajax', 0, 0, 45, '2026-03-08T01:57:15.347Z', '2026-03-08T02:03:37.187Z', '620fecf52aa7b16e46a71a694f7633bdaf7c0ce97b5977f0e5d13337c9687863', '{"id":"hmislk/hmis/jsf-ajax","name":"jsf-ajax","description":{"en":"jsf-ajax is an Open Source Java EE based Hospital Information Management System, benefiting developers with efficient AJAX updates and expert guidelines","zh":"JSF AJAX是一种用于构建动态Web应用的技术，需要遵循特定的规则和最佳实践","ja":"JSF AJAXは、ダイナミックWebアプリケーションを構築するために使用される技術であり、特定のルールとベストプラクティスに従う必要がある","ko":"JSF AJAX는 동적 웹 애플리케이션을 구축하는 데 사용되는 기술로, 특정 규칙과 모범 사례를 따라야 합니다","es":"jsf-ajax es una técnica para mejorar el rendimiento de aplicaciones Java EE mediante actualizaciones AJAX. Sigue nuestras reglas críticas para una implementación exitosa","fr":"jsf-ajax est une technique pour améliorer les performances des applications Java EE via des mises à jour AJAX. Suivez nos règles critiques pour une mise en œuvre réussie","de":"jsf-ajax ist eine Technik, um die Leistung von Java-EE-Anwendungen durch AJAX-Aktualisierungen zu verbessern. Befolgen Sie unsere kritischen Regeln für eine erfolgreiche Implementierung","pt":"O JSF-AJAX é uma tecnologia de código aberto para sistemas de gerenciamento de informações de hospital, permitindo atualizações AJAX eficientes","ru":"JSF-AJAX - это открытая технология для систем управления информацией больницы, обеспечивающая эффективные обновления AJAX","ar":"JSF-AJAX هو تكنولوجيا مفتوحة المصدر لنظم إدارة المعلومات الصحية، مما يسمح بالتحديثات AJAX الفعالة"},"seo":{"title":{"en":"jsf-ajax: Best Practices for AJAX Updates | AI Agent Skill","zh":"JSF AJAX Setup Guide - AI智能代理","ja":"JSF AJAX ベストプラクティス - AIエージェント","ko":"JSF AJAX 구성 가이드 - AI 에이전트","es":"Guía de configuración de jsf-ajax para desarrolladores","fr":"Guide de confi