INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('hmislk/hmis/jsf-ajax', 'jsf-ajax', 'hmislk', 'hmis', 'community', 'jsf-ajax hmislk hmis community jsf-ajax is an Open Source Java EE based Hospital Information Management System, benefiting developers with efficient AJAX updates and expert guidelines JSF AJAX是一种用于构建动态Web应用的技术，需要遵循特定的规则和最佳实践 JSF AJAXは、ダイナミックWebアプリケーションを構築するために使用される技術であり、特定のルールとベストプラクティスに従う必要がある JSF AJAX는 동적 웹 애플리케이션을 구축하는 데 사용되는 기술로, 특정 규칙과 모범 사례를 따라야 합니다 jsf-ajax es una técnica para mejorar el rendimiento de aplicaciones Java EE mediante actualizaciones AJAX. Sigue nuestras reglas críticas para una implementación exitosa jsf-ajax est une technique pour améliorer les performances des applications Java EE via des mises à jour AJAX. Suivez nos règles critiques pour une mise en œuvre réussie jsf-ajax ist eine Technik, um die Leistung von Java-EE-Anwendungen durch AJAX-Aktualisierungen zu verbessern. Befolgen Sie unsere kritischen Regeln für eine erfolgreiche Implementierung O JSF-AJAX é uma tecnologia de código aberto para sistemas de gerenciamento de informações de hospital, permitindo atualizações AJAX eficientes JSF-AJAX - это открытая технология для систем управления информацией больницы, обеспечивающая эффективные обновления AJAX JSF-AJAX هو تكنولوجيا مفتوحة المصدر لنظم إدارة المعلومات الصحية، مما يسمح بالتحديثات AJAX الفعالة how to use jsf-ajax jsf-ajax setup guide jsf-ajax alternative jsf-ajax vs primefaces what is jsf-ajax jsf-ajax install jsf-ajax best practices jsf-ajax tutorial jsf-ajax examples JSF AJAX Java EE h:panelGroup p:outputPanel AJAX更新 渲染属性 AI智能代理 Uses JSF components like h:panelGroup and p:outputPanel for AJAX updates Applies rendered attribute rules with h:panelGroup layout="block" Utilizes p:resolveFirstComponentWithId for component references Follows critical rules for AJAX updates, such as avoiding plain HTML elements Supports efficient updates with clientId using p:resolveFirstComponentWithId jsf-ajax is an Open Source Java EE based skill for efficient AJAX updates in Hospital Information Management Systems');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dojoengine/dojo.js/dojo-react', 'community', 'dojoengine', 'dojo.js', 'dojoengine/dojo.js', 'dojo-react', 0, 0, 45, '2026-03-08T01:57:15.347Z', '2026-03-08T02:03:39.022Z', 'd5d1a5597b6a0cdd2cafe3835274eefc3164a52a27d562f07dca92190c365e39', '{"id":"dojoengine/dojo.js/dojo-react","name":"dojo-react","description":{"en":"The dojo-react skill provides official JavaScript packages for Dojo, helping developers set up React provider hierarchy and implement complex async state management.","zh":"dojo-react 是官方的 JavaScript 包，为 React 应用提供了强大的功能，包括设置提供者层次结构、处理复杂异步状态和实现无限滚动等","ja":"dojo-react は公式の JavaScript パッケージであり、React アプリケーションに強力な機能を提供します。提供者階層の設定、複雑な非同期ステートの処理、無限スクロールの実装などが含まれます","ko":"dojo-react는 공식 JavaScript 패키지로 React 애플리케이션에 강력한 기능을 제공합니다. 제공자 계층 구조 설정, 복잡한 비동기 상태 처리, 무한 스크롤 구현 등이 포함됩니다","es":"dojo-react es un conjunto de paquetes de JavaScript oficiales para Dojo que facilitan la creación de aplicaciones React con patrones de proveedor y manejo de estados","fr":"dojo-react est un ensemble de packages JavaScript officiels pour Dojo qui facilitent la création d''applications React avec des modèles de fournisseur et de gestion d''états","de":"dojo-react ist eine Sammlung von offiziellen JavaScript-Paketen für Dojo, die die Erstellung von React-Anwendungen mit Anbieternmustern und Statusverwaltung erleichtern","pt":"O Dojo-React é um conjunto de pacotes JavaScript oficiais para Dojo, projetados para fornecer uma hierarquia de provedores e gerenciamento de estado eficazes","ru":"Dojo-React - это официальные пакеты JavaScript для Dojo, предназначенные для предоставления эффективной иерархии провайдеров и управления состоянием","ar":"dojo-react هو مجموعة من الحزم الجافا سكريبت الرسمية ل Dojo، مصممة لتقديم تسلسل هرمي للموفرين وإدارة الحالة فعالين"},"seo":{"title":{"en":"dojo-react: Setup Guide for AI Agents | AI Agent Skill","zh":"dojo-react 设置指南：React 提供者层次结构和异步状态管理","ja":"dojo-react セットアップガイド：React プロバイダー階層と非同期ステート管理","ko":"dojo-react 설정 가이드: React 제공자 계층 구조 및 비동기 상태 관리","es":"Guía de configuración de dojo-react para React","fr":"Guide de mise en place de dojo-react pour React","de":"Einrichtungsleitfaden für dojo-react mit React","pt":"Guia de Configuração do Dojo-React: Práticas Recomendadas","ru":"Настройка Dojo-React: Лучшие Практики для Разработчиков","ar":"إعداد dojo-react: دليل أفضل الممارسات للاستفادة من أدوات ..."},"description":{"en":"Unlock the power of Dojo.js with dojo-react! Learn how to set up React provider hierarchy and implement infinite scroll with our expert guide.","zh":"了解如何使用 dojo-react 设置 React 提供者层次结构、处理复杂异步状态和实现无限滚动等功能","ja":"dojo-react を使用して React プロバイダー階層を設定し、複雑な非同期ステートを処理し、無限スクロールを実装する方法について学びます","ko":"dojo-react를 사용하여 React 제공자 계층 구조를 설정하고 복잡한 비동기 상태를 처리하며 무한 스크롤을 구현하는 방법에 대해 알아보세요","es":"Aprende a configurar dojo-react para mejorar tus aplicaciones React con patrones de proveedor y manejo de estados","fr":"Découvrez comment configurer dojo-react pour améliorer vos applications React avec des modèles de fournisseur et de gestion d''états","de":"Erfahren Sie, wie Sie dojo-react für verbesserte React-Anwendungen mit Anbieternmustern und Statusverwaltung konfigurieren","pt":"Aprenda a configurar o Dojo-React com as práticas recomendadas para obter o máximo proveito da hierarquia de provedores e do gerenciamento de estado","ru":"Узнайте, как настроить Dojo-React с рекомендуемыми практиками для эффективного использования провайдера иерархии и управления состоянием","ar":"تعرف على كيفية إعداد dojo-react باستخدام أفضل الممارسات للاستفادة القصوى من التسلسل الهرمي للموفرين وإدارة الحالة"},"definition":{"en":"dojo-react is a set of official JavaScript packages for Dojo, enabling developers to build robust React applications with features like infinite scroll and loading/error states.","zh":"dojo-react 是一种 JavaScript 包，用于设置 React 提供者层次结构和处理复杂异步状态","ja":"dojo-react は、React プロバイダー階層を設定し、複雑な非同期ステートを処理するための JavaScript パッケージです","ko":"dojo-react는 React 제공자 계층 구조를 설정하고 복잡한 비동기 상태를 처리하기 위한 JavaScript 패키지입니다","es":"dojo-react es un conjunto de herramientas de desarrollo para crear aplicaciones React con patrones de proveedor y manejo de estados","fr":"dojo-react est un ensemble d''outils de développement pour créer des applications React avec des modèles de fournisseur et de gestion d''états","de":"dojo-react ist eine Sammlung von Entwicklungstools für die Erstellung von React-Anwendungen mit Anbieternmustern und Statusverwaltung","pt":"Dojo-React é um conjunto de ferramentas de código aberto para React que fornece uma hierarquia de provedores e gerenciamento de estado","ru":"Dojo-React - это набор инструментов с открытым исходным кодом для React, который предоставляет иерархию провайдеров и управление состоянием","ar":"dojo-react هو مجموعة من أدوات مفتوحة المصدر ل React التي توفر تسلسل هرمي للموفرين وإدارة الحالة"},"features":{"en":["Sets up React provider hierarchy with StarknetConfig and DojoSdkProvider","Implements infinite scroll for seamless user experience","Handles loading and error states with Effect atoms","Supports complex async state management with @starknet-react/core","Provides a recommended order for importing dependencies, including @dojoengine/sdk/react"],"zh":["设置 React 提供者层次结构","处理复杂异步状态","实现无限滚动","处理加载和错误状态","使用 Effect 原子处理异步操作"],"ja":["React プロバイダー階層の設定","複雑な非同期ステートの処理","無限スクロールの実装","ロードとエラー状態の処理","Effect 原子を使用した非同期操作の処理"],"ko":["React 제공자 계층 구조 설정","복잡한 비동기 상태 처리","무한 스크롤 구현","로딩 및 오류 상태 처리","Effect 원자를 사용한 비동기 작업 처리"],"es":["Configuración de la jerarquía de proveedores","Uso de átomos de efecto para estados asíncronos complejos","Implementación de desplazamiento infinito","Manejo de estados de carga y error"],"fr":["Configuration de la hiérarchie des fournisseurs","Utilisation d''atomes d''effet pour des états asynchrones complexes","Mise en œuvre du défilement infini","Gestion des états de chargement et d''erreur"],"de":["Konfiguration der Anbieterhierarchie","Verwendung von Effektatomen für komplexe asynchrone Zustände","Implementierung des unendlichen Scrollens","Verwaltung von Lade- und Fehlerzuständen"],"pt":["Hierarquia de provedores personalizada","Gerenciamento de estado eficaz com Effect atoms","Implementação de rolagem infinita","Manipulação de estados de carregamento e erro"],"ru":["Пользовательская иерархия провайдеров","Эффективное управление состоянием с помощью Effect atoms","Реализация бесконечной прокрутки","Обработка состояний загрузки и ошибки"],"ar":["تسلسل هرمي للموفرين مخصص","إدارة الحالة الفعالة باستخدام Effect atoms","تنفيذ التمرير اللانهائي","تعامل مع حالات التحميل والخطأ"]},"keywords":{"en":["how to use dojo-react","dojo-react setup guide","dojo-react vs react-redux","dojo-react install","what is dojo-react","dojo-react alternative","dojo-react react provider hierarchy","dojo-react infinite scroll","dojo-react loading error states"],"zh":["dojo-react","React 提供者层次结构","异步状态管理","无限滚动","加载和错误状态处理","Effect 原子","JavaScript 包","React开发","前端开发"],"ja":["dojo-react","React プロバイダー階層","非同期ステート管理","無限スクロール","ロードとエラー状態の処理","Effect 原子","JavaScript パッケージ","React開発","フロントエンド開発"],"ko":["dojo-react","React 제공자 계층 구조","비동기 상태 관리","무한 스크롤","로딩 및 오류 상태 처리","Effect 원자","JavaScript 패키지","React 개발","프론트엔드 개발"],"es":["dojo-react","React","patrones de proveedor","manejo de estados","desplazamiento infinito","herramientas de desarrollo","framework de JavaScript"],"fr":["dojo-react","React","modèles de fournisseur","gestion d''états","défilement infini","outils de développement","framework JavaScript"],"de":["dojo-react","React","Anbieternmuster","Statusverwaltung","unendliches Scrolling","Entwicklungstools","JavaScript-Framework"],"pt":["dojo-react","react provider hierarchy","-effect atoms","infinite scroll","loading error states","ferramentas de react","desenvolvimento web"],"ru":["dojo-react","иерархия провайдеров react","эффект атомов","бесконечная прокрутка","состояния загрузки и ошибки","инструменты react","веб-разработка"],"ar":["dojo-react","تسلسل هرمي للموفرين react","ذرات التأثير","التمرير اللانهائي","حالات التحميل والخطأ","أدوات react","تطوير ويب","أدوات الذكاء الاصطناعي"]}},"owner":"dojoengine","repo":"dojo.js","repoPath":"dojoengine/dojo.js","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.347Z","topics":[],"category":"community","skillMd":{"name":"dojo-react","description":"|","bodyPreview":"# Dojo.js React Patterns\n\n## When to Use\n\nUse this skill when:\n- Setting up React provider hierarchy\n- Using Effect atoms for complex async state\n- Implementing infinite scroll\n- Handling loading/error states\n\n## Provider Hierarchy\n\nRecommended order:\n\n```tsx\nimport { StarknetConfig } from \"@starknet-react/core\";\nimport { DojoSdkProvider } from \"@dojoengine/sdk/react\";\n\nfunction Providers({ children }) {\n    return (\n        <StarknetConfig connectors={connectors}>\n            <DojoSdkProvider","body":"# Dojo.js React Patterns\n\n## When to Use\n\nUse this skill when:\n- Setting up React provider hierarchy\n- Using Effect atoms for complex async state\n- Implementing infinite scroll\n- Handling loading/error states\n\n## Provider Hierarchy\n\nRecommended order:\n\n```tsx\nimport { StarknetConfig } from \"@starknet-react/core\";\nimport { DojoSdkProvider } from \"@dojoengine/sdk/react\";\n\nfunction Providers({ children }) {\n    return (\n        <StarknetConfig connectors={connectors}>\n            <DojoSdkProvider\n                dojoConfig={dojoConfig}\n                sdk={sdk}\n                clientFn={createClient}\n            >\n                {children}\n            </DojoSdkProvider>\n        </StarknetConfig>\n    );\n}\n```\n\n## useDojoSDK Hook\n\n```tsx\nimport { useDojoSDK } from \"@dojoengine/sdk/react\";\n\nfunction GameComponent() {\n    const {\n        sdk,          // SDK instance\n        config,       // DojoConfig\n        client,       // Client from clientFn\n        provider,     // DojoProvider\n        useDojoStore  // Zustand store hook\n    } = useDojoSDK();\n}\n```\n\n## Effect Atoms (Recommended)\n\nEffect atoms provide robust async state management:\n\n### Entity Query Atom\n\n```tsx\nimport { createEntityQueryAtom } from \"@dojoengine/react/effect\";\nimport { Result } from \"@dojoengine/react/effect\";\n\nconst playersAtom = createEntityQueryAtom(\n    runtime,\n    new ToriiQueryBuilder().addEntityModel(\"game-Player\").withLimit(100)\n);\n\nfunction PlayerList() {\n    const players = useAtomValue(playersAtom);\n\n    return Result.match(players, {\n        onSuccess: ({ value }) => (\n            <ul>\n                {value.items.map(p => <li key={p.entityId}>{p.models.game.Player.name}</li>)}\n            </ul>\n        ),\n        onFailure: (error) => <div>Error: {error.message}</div>,\n        onInitial: () => <div>Loading...</div>\n    });\n}\n```\n\n### Entity Updates Atom (Real-time)\n\n```tsx\nimport { createEntityUpdatesAtom } from \"@dojoengine/react/effect\";\n\nconst updatesAtom = createEntityUpdatesAtom(\n    runtime,\n    KeysClause([\"game-Player\"], [], \"VariableLen\").build()\n);\n```\n\n### Combined Query + Updates\n\n```tsx\nimport { createEntityQueryWithUpdatesAtom } from \"@dojoengine/react/effect\";\n\nconst livePlayersAtom = createEntityQueryWithUpdatesAtom(\n    runtime,\n    query,\n    clause\n);\n```\n\n## Infinite Scroll\n\n```tsx\nimport { createEntitiesInfiniteScrollAtom } from \"@dojoengine/react/effect\";\n\nconst infinitePlayersAtom = createEntitiesInfiniteScrollAtom(\n    runtime,\n    new ToriiQueryBuilder().addEntityModel(\"game-Player\"),\n    20 // page size\n);\n\nfunction InfinitePlayerList() {\n    const [state, loadMore] = useAtom(infinitePlayersAtom);\n\n    return Result.match(state, {\n        onSuccess: ({ value }) => (\n            <>\n                <ul>\n                    {value.items.map(p => (\n                        <li key={p.entityId}>{p.models.game.Player.name}</li>\n                    ))}\n                </ul>\n                {value.hasMore && (\n                    <button onClick={loadMore}>Load More</button>\n                )}\n            </>\n        ),\n        onFailure: (error) => <div>Error: {error.message}</div>,\n        onInitial: () => <div>Loading...</div>\n    });\n}\n```\n\n## Token Balance Atoms\n\n```tsx\nimport {\n    createTokenBalanceQueryAtom,\n    createTokenBalanceUpdatesAtom\n} from \"@dojoengine/react/effect\";\n\n// One-time query\nconst balanceAtom = createTokenBalanceQueryAtom(runtime, {\n    contractAddresses: [\"0x...\"],\n    accountAddresses: [playerAddress]\n});\n\n// Polling updates\nconst liveBalanceAtom = createTokenBalanceUpdatesAtom(\n    runtime,\n    { contractAddresses: [\"0x...\"], accountAddresses: [playerAddress] },\n    5000 // poll every 5 seconds\n);\n```\n\n## Data Formatters\n\nTransform data before rendering:\n\n```tsx\nconst formatters = {\n    models: {\n        \"game-Player\": (player) => ({\n            ...player,\n            displayName: player.name || \"Anonymous\",\n            displayScore: `${player.score.toLocaleString()} pts`\n        })\n    },\n    fields: {\n        \"game-Player.score\": (score) => Math.floor(score / 100)\n    }\n};\n\nconst playersAtom = createEntityQueryAtom(runtime, query, formatters);\n```\n\n## Custom Subscription Hooks\n\n```tsx\nimport { createSubscriptionHook } from \"@dojoengine/sdk/react\";\n\nconst usePlayerSubscription = createSubscriptionHook({\n    subscribeMethod: (sdk, params) => sdk.subscribeEntityQuery(params),\n    processInitialData: (data) => data.items,\n    processUpdateData: (update) => update\n});\n\nfunction PlayerTracker({ entityId }) {\n    const { data, error, isLoading } = usePlayerSubscription({\n        query: new ToriiQueryBuilder()\n            .withClause(KeysClause([\"game-Player\"], [entityId]).build())\n    });\n}\n```\n\n## Zustand Selectors\n\nOptimize re-renders with selectors:\n\n```tsx\nfunction PlayerScore({ entityId }) {\n    const { useDojoStore } = useDojoSDK();\n\n    // Only re-render when score changes\n    const score = useDojoStore(\n        state => state.entities[entityId]?.models?.game?.Player?.score,\n        (a, b) => a === b // equality function\n    );\n\n    return <span>{score}</span>;\n}\n```\n\n## useEntityId Hook\n\n```tsx\nimport { useEntityId } from \"@dojoengine/sdk/react\";\n\nfunction PlayerCard({ address, gameId }) {\n    // Memoized entity ID computation\n    const entityId = useEntityId(address, gameId);\n    const player = useModel(entityId, \"game-Player\");\n}\n```\n\n## Error Boundaries\n\n```tsx\nimport { ErrorBoundary } from \"react-error-boundary\";\n\nfunction GameErrorFallback({ error, resetErrorBoundary }) {\n    return (\n        <div>\n            <p>Something went wrong: {error.message}</p>\n            <button onClick={resetErrorBoundary}>Retry</button>\n        </div>\n    );\n}\n\nfunction App() {\n    return (\n        <ErrorBoundary FallbackComponent={GameErrorFallback}>\n            <Game />\n        </ErrorBoundary>\n    );\n}\n```\n\n## Common Pitfalls\n\n1. **Missing provider**: Ensure DojoSdkProvider wraps all Dojo-using components\n2. **Effect runtime**: Create runtime once at app startup, not in components\n3. **Selector stability**: Use stable selector functions to prevent re-renders\n4. **Cleanup**: Effect atoms handle cleanup, but manual subscriptions need cleanup\n5. **Result.match**: Always handle all three cases (success, failure, initial)\n"},"lastSynced":"2026-03-08T02:03:39.022Z","agentAnalysis":{"suitability":{"en":"Ideal for Frontend Agents needing to set up React provider hierarchies and manage complex async state with Dojo","zh":"适用于需要设置React提供者层次结构并使用Dojo管理复杂异步状态的前端代理","ja":"Reactプロバイダ階層を設定し、Dojoを使用して複雑な非同期状態を管理する必要があるフロントエンドエージェントに最適","ko":"Dojo를 사용하여 복잡한 비동기 상태를 관리하고 React 제공자 계층 구조를 설정해야 하는 프런트엔드 에이전트에 적합","es":"Ideal para Agentes de Frontend que necesitan configurar jerarquías de proveedores de React y administrar estados asíncronos complejos con Dojo","fr":"Idéal pour les agents Frontend qui ont besoin de configurer des hiérarchies de fournisseurs React et de gérer des états asynchrones complexes avec Dojo","de":"Ideal für Frontend-Agenten, die React-Anbieterhierarchien einrichten und komplexe asynchrone Zustände mit Dojo verwalten müssen","pt":"Ideal para Agentes Frontend que precisam configurar hierarquias de provedores React e gerenciar estados assíncronos complexos com Dojo","ru":"Идеально для фронтенд-агентов, которым необходимо настраивать иерархии провайдеров React и управлять сложными асинхронными состояниями с помощью Dojo","ar":"مثالي لعميل واجهة المستخدم التي تحتاج إلى ضبط هرمية مزودي React وإدارة حالات متزامنة معقدة مع Dojo"},"recommendation":{"en":"Empowers agents to implement infinite scroll, handle loading and error states, and utilize Effect atoms for advanced state management using Dojo''s official JavaScript packages and React provider hierarchy","zh":"赋予代理实现无限滚动、处理加载和错误状态、并利用Effect原子使用Dojo的官方JavaScript包和React提供者层次结构进行高级状态管理的能力","ja":"エージェントが無限スクロールを実装し、読み込みとエラーステートを処理し、Dojoの公式JavaScriptパッケージとReactプロバイダ階層を使用してEffectアトムで高度なステート管理を行う能力を付与","ko":"에이전트가 무한 스크롤을 구현하고 로딩 및 오류 상태를 처리하며 Dojo의 공식 JavaScript 패키지와 React 제공자 계층을 사용하여 Effect 원자를 통해 고급 상태 관리를 수행할 수 있는 능력을 부여","es":"Permite a los agentes implementar desplazamiento infinito, controlar los estados de carga y error, y utilizar átomos Effect para una gestión de estado avanzada utilizando los paquetes de JavaScript oficiales de Dojo y la jerarquía de proveedores de React","fr":"Permet aux agents de mettre en œuvre un défilement infini, de gérer les états de chargement et d''erreur, et d''utiliser des atomes Effect pour une gestion d''état avancée en utilisant les packages JavaScript officiels de Dojo et la hiérarchie de fournisseurs React","de":"Ermöglicht es Agenten, unendliches Scrollen zu implementieren, Lade- und Fehlerzustände zu handhaben und Effect-Atome für eine erweiterte Zustandsverwaltung unter Verwendung der offiziellen JavaScript-Pakete von Dojo und der React-Anbieterhierarchie zu nutzen","pt":"Habilita os agentes a implementar rolagem infinita, lidar com estados de carregamento e erro e utilizar átomos de efeito para gerenciamento avançado de estado usando pacotes oficiais de JavaScript do Dojo e hierarquia de provedores React","ru":"Наделяет агентов возможностью реализовать бесконечную прокрутку, обрабатывать состояния загрузки и ошибок, а также использовать атомы эффекта для расширенного управления состоянием с помощью официальных пакетов JavaScript от Dojo и иерархии провайдеров React","ar":"يتمكن العملاء من تنفيذ التمرير اللانهائي ومعالجة حالات التحميل والأخطاء واستخدام ذرات التأثير لإدارة الحالة المتقدمة باستخدام الحزم الرسمية لجافا سكريبت من Dojo وهرمية مزودي React"},"useCases":{"en":["Setting up React provider hierarchies with DojoSdkProvider","Implementing infinite scroll with async state management","Handling loading and error states in React applications"],"zh":["使用DojoSdkProvider设置React提供者层次结构","使用异步状态管理实现无限滚动","在React应用程序中处理加载和错误状态"],"ja":["DojoSdkProviderを使用してReactプロバイダ階層を設定する","非同期状態管理を使用して無限スクロールを実装する","Reactアプリケーションで読み込みとエラーステートを処理する"],"ko":["DojoSdkProvider를 사용하여 React 제공자 계층 구조를 설정","비동기 상태 관리를 사용하여 무한 스크롤을 구현","React 애플리케이션에서 로딩 및 오류 상태를 처리"],"es":["Configuración de jerarquías de proveedores de React con DojoSdkProvider","Implementación de desplazamiento infinito con administración de estado asíncrono","Control de los estados de carga y error en aplicaciones de React"],"fr":["Configuration des hiérarchies de fournisseurs React avec DojoSdkProvider","Mise en œuvre du défilement infini avec gestion d''état asynchrone","Gestion des états de chargement et d''erreur dans les applications React"],"de":["Einrichtung von React-Anbieterhierarchien mit DojoSdkProvider","Implementierung von unendlichem Scrollen mit asynchroner Zustandsverwaltung","Handhabung von Lade- und Fehlerzuständen in React-Anwendungen"],"pt":["Configuração de hierarquias de provedores React com DojoSdkProvider","Implementação de rolagem infinita com gerenciamento de estado assíncrono","Manipulação de estados de carregamento e erro em aplicações React"],"ru":["Настройка иерархий провайдеров React с помощью DojoSdkProvider","Реализация бесконечной прокрутки с управлением асинхронным состоянием","Обработка состояний загрузки и ошибок в приложениях React"],"ar":["ضبط هرمية مزودي React باستخدام DojoSdkProvider","تنفيذ التمرير اللانهائي بإدارة حالات متزامنة","معالجة حالات التحميل والأخطاء في تطبيقات React"]},"limitations":{"en":["Requires Dojo and React setup","Limited to JavaScript and React ecosystems"],"zh":["需要Dojo和React设置","仅限于JavaScript和React生态系统"],"ja":["DojoとReactの設定が必要","JavaScriptとReactのエコシステムに限定"],"ko":["Dojo 및 React 설정이 필요","JavaScript 및 React 생태계에만 제한"],"es":["Requiere configuración de Dojo y React","Limitado a los ecosistemas de JavaScript y React"],"fr":["Nécessite une configuration de Dojo et React","Limité aux écosystèmes JavaScript et React"],"de":["Erfordert Dojo- und React-Setup","Begrenzt auf die JavaScript- und React-Ökosysteme"],"pt":["Exige configuração do Dojo e React","Limitado aos ecossistemas JavaScript e React"],"ru":["Требует настройки Dojo и React","Ограничен экосистемами JavaScript и React"],"ar":["يتطلب إعداد Dojo و React","محدود بنطاق بيئات جافا سكريبت و React"]},"version":4},"contentHash":"d5d1a5597b6a0cdd2cafe3835274eefc3164a52a27d562f07dca92190c365e39","qualityScore":45}');
