INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dojoengine/dojo.js/dojo-react', 'dojo-react', 'dojoengine', 'dojo.js', 'community', 'dojo-react dojoengine dojo.js community The dojo-react skill provides official JavaScript packages for Dojo, helping developers set up React provider hierarchy and implement complex async state management. dojo-react 是官方的 JavaScript 包，为 React 应用提供了强大的功能，包括设置提供者层次结构、处理复杂异步状态和实现无限滚动等 dojo-react は公式の JavaScript パッケージであり、React アプリケーションに強力な機能を提供します。提供者階層の設定、複雑な非同期ステートの処理、無限スクロールの実装などが含まれます dojo-react는 공식 JavaScript 패키지로 React 애플리케이션에 강력한 기능을 제공합니다. 제공자 계층 구조 설정, 복잡한 비동기 상태 처리, 무한 스크롤 구현 등이 포함됩니다 dojo-react es un conjunto de paquetes de JavaScript oficiales para Dojo que facilitan la creación de aplicaciones React con patrones de proveedor y manejo de estados dojo-react est un ensemble de packages JavaScript officiels pour Dojo qui facilitent la création d''applications React avec des modèles de fournisseur et de gestion d''états dojo-react ist eine Sammlung von offiziellen JavaScript-Paketen für Dojo, die die Erstellung von React-Anwendungen mit Anbieternmustern und Statusverwaltung erleichtern O Dojo-React é um conjunto de pacotes JavaScript oficiais para Dojo, projetados para fornecer uma hierarquia de provedores e gerenciamento de estado eficazes Dojo-React - это официальные пакеты JavaScript для Dojo, предназначенные для предоставления эффективной иерархии провайдеров и управления состоянием dojo-react هو مجموعة من الحزم الجافا سكريبت الرسمية ل Dojo، مصممة لتقديم تسلسل هرمي للموفرين وإدارة الحالة فعالين how to use dojo-react dojo-react setup guide dojo-react vs react-redux dojo-react install what is dojo-react dojo-react alternative dojo-react react provider hierarchy dojo-react infinite scroll dojo-react loading error states dojo-react React 提供者层次结构 异步状态管理 无限滚动 加载和错误状态处理 Effect 原子 JavaScript 包 React开发 前端开发 Sets up React provider hierarchy with StarknetConfig and DojoSdkProvider Implements infinite scroll for seamless user experience Handles loading and error states with Effect atoms Supports complex async state management with @starknet-react/core Provides a recommended order for importing dependencies, including @dojoengine/sdk/react dojo-react is a set of official JavaScript packages for Dojo, enabling developers to build robust React applications with features like infinite scroll and loading/error states.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('stacklok/toolhive-rfcs/write-rfc', 'community', 'stacklok', 'toolhive-rfcs', 'stacklok/toolhive-rfcs', 'write-rfc', 0, 0, 45, '2026-03-08T01:57:15.348Z', '2026-03-08T02:03:41.354Z', '2f7c52bbc5f05bc117c14892aa05ad235ff55ea37bc7d842ab1b4fa0375c419f', '{"id":"stacklok/toolhive-rfcs/write-rfc","name":"write-rfc","description":{"en":"The write-rfc skill helps developers create high-quality RFCs for the ToolHive ecosystem, following a specific format with naming convention THV-{NUMBER}-{descriptive-name}.md. This skill benefits developers working within the ToolHive ecosystem.","zh":"write-rfc 技术是一种用于编写高质量 ToolHive 生态系统 RFC 的工具，遵循特定的格式和命名约定","ja":"write-rfc 技術は、特定のフォーマットと命名規則に従って、高品質の ToolHive エコシステム RFC を作成するためのツールです","ko":"write-rfc 기술은 특정 형식 및 명명 규칙을 따라 높은 품질의 ToolHive 생태계 RFC를 작성하기 위한 도구입니다","es":"El skill write-rfc ayuda a crear RFCs de alta calidad para el ecosistema ToolHive siguiendo patrones y convenciones establecidos","fr":"Le skill write-rfc aide à créer des RFCs de haute qualité pour l''écosystème ToolHive en suivant les modèles et conventions établis","de":"Das write-rfc-Skill hilft bei der Erstellung von hochwertigen RFCs für das ToolHive-Ökosystem unter Einhaltung etablierter Muster und Konventionen","pt":"O write-rfc é uma habilidade que ajuda a escrever RFCs de alta qualidade para o ecossistema ToolHive, seguindo padrões e convenções estabelecidos.","ru":"Write-rfc - это навык, который помогает создавать качественные RFC для экосистемы ToolHive, следуя установленным стандартам и соглашениям для ИИ Агентов.","ar":"write-rfc هو مهارة تساعد على كتابة RFCs عالية الجودة لمنصة ToolHive، متبعة المعايير والمواصفات المتبعة لأدوات الذكاء الاصطناعي."},"seo":{"title":{"en":"write-rfc: ToolHive RFC Setup Guide | AI Agent Skill","zh":"write-rfc 技术指南：ToolHive 生态系统 RFC 编写最佳实践","ja":"write-rfc セットアップガイド：ToolHive エコシステムのRFCを作成する","ko":"write-rfc 설정 가이드: ToolHive 생태계를 위한 RFC 작성 모범 사례","es":"Guía de configuración para write-rfc: Herramientas de AI ...","fr":"Guide de démarrage pour write-rfc: Outils d''agents IA","de":"Einrichtungsleitfaden für write-rfc: KI-Tool","pt":"Guia de Configuração do write-rfc: Escrevendo RFCs de Alt...","ru":"Настройка write-rfc: Руководство по созданию качественных...","ar":"دليل إعداد write-rfc: كتابة RFCs عالية الجودة لادوات الذك..."},"description":{"en":"Discover how to create high-quality RFCs for ToolHive with the write-rfc skill. Learn how to follow established patterns and conventions for THV-{NUMBER}-{de...","zh":"了解 write-rfc 技术的详细信息，包括 ToolHive 生态系统的 RFC 编写格式和工作流程","ja":"write-rfc 技術の詳細を学び、ToolHive エコシステムの RFC 作成フォーマットとワークフローを理解する","ko":"write-rfc 기술에 대한 자세한 정보를 알아보고 ToolHive 생태계의 RFC 작성 형식 및 워크플로우를 이해하십시오","es":"Aprende a escribir RFCs de alta calidad para el ecosistema ToolHive con nuestra guía de write-rfc","fr":"Découvrez comment écrire des RFCs de haute qualité pour l''écosystème ToolHive avec notre guide de write-rfc","de":"Erfahren Sie, wie Sie hochwertige RFCs für das ToolHive-Ökosystem mit unserer write-rfc-Anleitung erstellen","pt":"Aprenda a escrever RFCs de alta qualidade para o ecossistema ToolHive com o write-rfc. Siga nossas práticas recomendadas e padrões estabelecidos.","ru":"Узнайте, как создать качественные RFC для экосистемы ToolHive с помощью write-rfc. Следуйте нашим рекомендациям и установленным стандартам для ИИ Агентов.","ar":"تعرف على كيفية كتابة RFCs عالية الجودة لمنصة ToolHive باستخدام write-rfc. اتبع أفضل الممارسات والمعايير المتبعة لأدوات الذكاء الاصطناعي."},"definition":{"en":"write-rfc is a skill that assists in creating ToolHive RFCs following established patterns and conventions, using a specific format for THV-{NUMBER}-{descriptive-name}.md files","zh":"write-rfc 是一种用于创建 ToolHive 生态系统 RFC 的技术，具有特定的格式和命名约定","ja":"write-rfc は、ToolHive エコシステムの RFC を作成するための技術で、特定のフォーマットと命名規則を持っています","ko":"write-rfc는 ToolHive 생태계의 RFC를 생성하기 위한 기술로 특정 형식 및 명명 규칙을 가지고 있습니다","es":"write-rfc es un skill que permite crear RFCs para el ecosistema ToolHive","fr":"write-rfc est un skill qui permet de créer des RFCs pour l''écosystème ToolHive","de":"write-rfc ist ein Skill, der die Erstellung von RFCs für das ToolHive-Ökosystem ermöglicht","pt":"O write-rfc é uma ferramenta que facilita a criação de RFCs para o ecossistema ToolHive, garantindo a qualidade e a consistência.","ru":"Write-rfc - это инструмент, который облегчает создание RFC для экосистемы ToolHive, обеспечивая качество и согласованность для ИИ Агентов.","ar":"write-rfc هو أداة تسهل إنشاء RFCs لمنصة ToolHive، مما يضمن الجودة والاتساق لأدوات الذكاء الاصطناعي."},"features":{"en":["Generates THV-{NUMBER}-{descriptive-name}.md files with zero-padded 4-digit PR numbers","Follows established ToolHive RFC patterns and conventions","Asks for problem statement and target repository information","Creates high-quality RFCs for the ToolHive ecosystem","Uses a specific naming convention for RFC files","Supports the ToolHive ecosystem workflow"],"zh":["支持 ToolHive 生态系统的 RFC 编写格式","遵循特定的命名约定：THV-{NUMBER}-{descriptive-name}.md","需要用户提供问题陈述和目标仓库信息","支持零填充的 4 位数字 PR 号码","提供详细的工作流程指南"],"ja":["ToolHive エコシステムの RFC 作成フォーマットをサポート","特定の命名規則：THV-{NUMBER}-{descriptive-name}.md に従う","問題文とターゲット リポジトリ情報の入力をユーザーに要求","ゼロ埋めの 4 桁の PR 番号をサポート","詳細なワークフロー ガイドを提供"],"ko":["ToolHive 생태계의 RFC 작성 형식을 지원합니다","특정 명명 규칙: THV-{NUMBER}-{descriptive-name}.md를 따릅니다","문제 문과 대상 저장소 정보를 사용자에게 입력하도록 요청","0填充 4자리 PR 번호를 지원","상세한 워크플로우 가이드를 제공합니다"],"es":["Seguimiento de patrones y convenciones establecidos para RFCs","Nombre de archivo con convención THV-{NUMBER}-{descriptive-name}.md","Número de PR con cero a la izquierda a 4 dígitos","Flujo de trabajo para recopilar requisitos","Soporte para la creación de RFCs de alta calidad"],"fr":["Suivi de modèles et de conventions établis pour les RFCs","Nom de fichier avec convention THV-{NUMBER}-{descriptive-name}.md","Numéro de PR avec zéro à gauche à 4 chiffres","Flux de travail pour recueillir les exigences","Prise en charge de la création de RFCs de haute qualité"],"de":["Einhalten etablierter Muster und Konventionen für RFCs","Dateiname mit Konvention THV-{NUMBER}-{descriptive-name}.md","PR-Nummer mit führender Null zu 4 Stellen","Arbeitsablauf zur Erfassung von Anforderungen","Unterstützung für die Erstellung von hochwertigen RFCs"],"pt":["Seguimento de padrões estabelecidos para RFCs","Nomeação de arquivos com convenção `THV-{NUMBER}-{descriptive-name}.md`","Requisitos de problema e repositório alvo","Fluxo de trabalho para gather de requisitos","Suporte à criação de RFCs de alta qualidade"],"ru":["Следование установленным стандартам для RFC","Именование файлов с соглашением `THV-{NUMBER}-{descriptive-name}.md`","Требования к проблеме и целевому репозиторию для ИИ Агентов","Рабочий процесс для сбора требований","Поддержка создания качественных RFC"],"ar":["متابعة المعايير المتبعة لكتابة RFCs","تسمية الملفات بالصيغة `THV-{NUMBER}-{descriptive-name}.md`","متطلبات البيان المشكل والمنصة المستهدفة لأدوات الذكاء الاصطناعي","سير عمل لجمع المتطلبات","دعم كتابة RFCs عالية الجودة"]},"keywords":{"en":["how to use write-rfc","what is write-rfc","write-rfc setup guide","ToolHive RFC format","THV-{NUMBER}-{descriptive-name}.md","write-rfc alternative","write-rfc vs other RFC tools","write-rfc install","ToolHive ecosystem workflow"],"zh":["write-rfc 技术","ToolHive 生态系统","RFC 编写格式","命名约定","问题陈述","目标仓库","PR 号码","零填充"],"ja":["write-rfc 技術","ToolHive エコシステム","RFC 作成フォーマット","命名規則","問題文","ターゲット リポジトリ","PR 番号","ゼロ埋め"],"ko":["write-rfc 기술","ToolHive 생태계","RFC 작성 형식","명명 규칙","문제 문","대상 저장소","PR 번호","0填充"],"es":["write-rfc","RFCs ToolHive","Herramientas de AI Agent","Guía de configuración write-rfc","Ecosistema ToolHive","Patrones y convenciones para RFCs","Creación de RFCs de alta calidad"],"fr":["write-rfc","RFCs ToolHive","Outils d''agents IA","Guide de démarrage write-rfc","Écosystème ToolHive","Modèles et conventions pour les RFCs","Création de RFCs de haute qualité"],"de":["write-rfc","RFCs ToolHive","KI-Tool","Einrichtungsleitfaden write-rfc","ToolHive-Ökosystem","Muster und Konventionen für RFCs","Erstellung von hochwertigen RFCs"],"pt":["write-rfc","RFCs de alta qualidade","ecossistema ToolHive","padrões estabelecidos","criação de RFCs","ferramenta de escrita de RFCs","desenvolvimento de software","engenharia de software"],"ru":["write-rfc","качественные RFC","экосистема ToolHive","установленные стандарты","создание RFC","инструмент для создания RFC","разработка программного обеспечения","инженерия программного обеспечения для ИИ Агентов"],"ar":["write-rfc","RFCs عالية الجودة","منصة ToolHive","المعايير المتبعة","كتابة RFCs","أداة كتابة RFCs","تطوير البرمجيات","هندسة البرمجيات لأدوات الذكاء الاصطناعي"]}},"owner":"stacklok","repo":"toolhive-rfcs","repoPath":"stacklok/toolhive-rfcs","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.348Z","topics":[],"category":"community","skillMd":{"name":"write-rfc","description":"Write RFCs for the ToolHive ecosystem. Use when the user wants to create a new RFC, proposal, or design document for toolhive, toolhive-studio, toolhive-registry, toolhive-registry-server, toolhive-cloud-ui, or dockyard projects.","bodyPreview":"# Write RFC Skill\n\nThis skill helps you write high-quality RFCs for the ToolHive ecosystem following established patterns and conventions.\n\n## Overview\n\nToolHive RFCs follow a specific format with the naming convention `THV-{NUMBER}-{descriptive-name}.md`. The NUMBER must match the PR number and be zero-padded to 4 digits.\n\n## Workflow\n\n### Step 1: Gather Requirements\n\nBefore writing an RFC, ask the user about:\n\n1. **Problem Statement**: What problem are they trying to solve?\n2. **Target Reposit","body":"# Write RFC Skill\n\nThis skill helps you write high-quality RFCs for the ToolHive ecosystem following established patterns and conventions.\n\n## Overview\n\nToolHive RFCs follow a specific format with the naming convention `THV-{NUMBER}-{descriptive-name}.md`. The NUMBER must match the PR number and be zero-padded to 4 digits.\n\n## Workflow\n\n### Step 1: Gather Requirements\n\nBefore writing an RFC, ask the user about:\n\n1. **Problem Statement**: What problem are they trying to solve?\n2. **Target Repository**: Which repo does this affect?\n   - `toolhive` - Core runtime, CLI (`thv`), operator (`thv-operator`), proxy-runner (`thv-proxyrunner`), virtual MCP (`vmcp`)\n   - `toolhive-studio` - Desktop UI application (Electron/TypeScript)\n   - `toolhive-registry` - MCP server registry data\n   - `toolhive-registry-server` - Registry API server (`thv-registry-api`)\n   - `toolhive-cloud-ui` - Cloud/Enterprise web UI (Next.js)\n   - `dockyard` - Container packaging for MCP servers\n   - `multiple` - Cross-cutting changes\n3. **Scope**: What are the goals and explicit non-goals?\n\n### Step 2: Research the Ecosystem\n\nBefore drafting, research the relevant codebase:\n\n#### 2.1 Fetch Architectural Documentation\n\nUse `mcp__github__get_file_contents` to read from `stacklok/toolhive` repo''s `docs/arch/` directory:\n\n| Document | Content |\n|----------|---------|\n| `00-overview.md` | Platform overview, key components |\n| `01-deployment-modes.md` | Local vs Kubernetes modes |\n| `02-core-concepts.md` | Nouns (Workloads, Transports, Proxy, etc.) and Verbs |\n| `03-transport-architecture.md` | stdio, SSE, streamable-http transports |\n| `04-secrets-management.md` | Secrets handling, providers |\n| `05-runconfig-and-permissions.md` | Configuration format, permission profiles |\n| `06-registry-system.md` | Registry architecture, MCPRegistry CRD |\n| `07-groups.md` | Server grouping concepts |\n| `08-workloads-lifecycle.md` | Lifecycle management |\n| `09-operator-architecture.md` | K8s operator, CRDs |\n| `10-virtual-mcp-architecture.md` | Virtual MCP aggregation |\n\n#### 2.2 Review Existing RFCs\n\nRead `rfcs/` directory in this repository to understand patterns and check for related proposals.\n\n#### 2.3 Search Relevant Codebases\n\nUse `mcp__github__search_code` or `mcp__github__get_file_contents` to explore:\n\n| Repository | Purpose |\n|------------|---------|\n| `stacklok/toolhive` | Core platform, CLI, operator, proxy |\n| `stacklok/toolhive-studio` | Desktop UI |\n| `stacklok/toolhive-registry-server` | Registry API server |\n| `stacklok/toolhive-registry` | Registry data |\n| `stacklok/toolhive-cloud-ui` | Cloud/Enterprise UI |\n| `stacklok/dockyard` | Container packaging |\n\n### Step 3: Draft the RFC\n\nCreate the RFC following the template structure from `rfcs/0000-template.md`.\n\n#### Required Metadata\n\n```markdown\n# RFC-XXXX: Title\n\n- **Status**: Draft\n- **Author(s)**: Name (@github-handle)\n- **Created**: YYYY-MM-DD\n- **Last Updated**: YYYY-MM-DD\n- **Target Repository**: [from step 1]\n- **Related Issues**: [links if applicable]\n```\n\n#### Core Sections\n\n1. **Summary** - 2-3 sentences capturing the essence\n2. **Problem Statement** - Current limitation, who''s affected, why it matters\n3. **Goals** - Specific objectives (bulleted)\n4. **Non-Goals** - Explicit scope boundaries\n5. **Proposed Solution**\n   - High-Level Design (with Mermaid diagrams)\n   - Detailed Design: Component changes, API changes, configuration changes, data model changes\n6. **Security Considerations** (REQUIRED) - See security checklist below\n7. **Alternatives Considered** - Other approaches evaluated\n8. **Compatibility** - Backward and forward compatibility\n9. **Implementation Plan** - Phased approach with tasks\n10. **Testing Strategy** - Unit, integration, E2E, performance, security tests\n11. **Documentation** - What needs documenting\n12. **Open Questions** - Unresolved items\n13. **References** - Related links\n\n#### Security Considerations Checklist (REQUIRED)\n\nEvery RFC MUST address:\n\n- [ ] **Threat Model** - Potential threats, attacker capabilities\n- [ ] **Authentication and Authorization** - Auth changes, permission models\n- [ ] **Data Security** - Sensitive data handling, encryption\n- [ ] **Input Validation** - User input, injection vectors\n- [ ] **Secrets Management** - Credentials storage, rotation\n- [ ] **Audit and Logging** - Security events, compliance\n- [ ] **Mitigations** - Security controls implemented\n\n### Step 4: Use Proper Conventions\n\n#### Code Examples\n\n- Use **Go** for API changes in toolhive, toolhive-registry-server\n- Use **TypeScript** for toolhive-studio, toolhive-cloud-ui changes\n- Use **YAML** for configuration examples\n- Use **Mermaid** for diagrams (flowcharts, sequence diagrams)\n\n#### Kubernetes CRDs\n\nIf the RFC involves Kubernetes, include CRD examples:\n\n```yaml\napiVersion: toolhive.stacklok.dev/v1alpha1\nkind: MCPServer\nmetadata:\n  name: example\nspec:\n  # ...\n```\n\nCRD types: `MCPServer`, `MCPRegistry`, `MCPToolConfig`, `MCPExternalAuthConfig`, `MCPGroup`, `VirtualMCPServer`\n\n### Step 5: File Naming\n\nThe RFC file should be named `THV-XXXX-{descriptive-name}.md` where XXXX is the PR number. Since you don''t know the PR number yet, use a placeholder like `THV-XXXX-{name}.md` and remind the user to rename it to match the PR number after creating the PR.\n\n### Step 6: Review Checklist\n\nBefore finalizing, verify:\n\n- [ ] Problem is clearly stated\n- [ ] Goals and non-goals are explicit\n- [ ] Security section is complete (all 7 areas addressed)\n- [ ] Alternatives are discussed\n- [ ] Diagrams illustrate complex flows\n- [ ] Code examples are concrete and in the correct language\n- [ ] Implementation phases are defined\n- [ ] Testing strategy covers all levels\n- [ ] File follows naming convention\n\n## ToolHive Architecture Summary\n\n### Platform Overview\n\nToolHive is a **platform** for MCP server management (not just a container runner):\n\n- **Proxy layer** with middleware (auth, authz, audit, rate limiting)\n- **Security** by default (network isolation, permission profiles)\n- **Aggregation** via Virtual MCP Server\n- **Registry** for curated MCP servers\n- **Multi-deployment**: Local (CLI/UI) and Kubernetes (operator)\n\n### Key Binaries\n\n| Binary | Location | Purpose |\n|--------|----------|---------|\n| `thv` | toolhive | Main CLI |\n| `thv-operator` | toolhive | Kubernetes operator |\n| `thv-proxyrunner` | toolhive | K8s proxy container |\n| `vmcp` | toolhive | Virtual MCP server (aggregation) |\n| `thv-registry-api` | toolhive-registry-server | Registry API server |\n\n### Transport Types\n\n- **stdio** - Standard input/output (requires protocol translation)\n- **SSE** - Server-Sent Events (HTTP, transparent proxy)\n- **streamable-http** - HTTP streaming (transparent proxy)\n\n### Design Principles\n\n1. Platform abstraction over direct execution\n2. Security by default (network isolation, permissions)\n3. Extensibility through middleware\n4. Cloud-native (K8s operators, containers)\n5. RunConfig as portable API contract\n\n## Reference Files\n\n- Template: `rfcs/0000-template.md`\n- Contributing guide: `CONTRIBUTING.md`\n- Existing RFCs: `rfcs/THV-*.md`\n"},"lastSynced":"2026-03-08T02:03:41.354Z","agentAnalysis":{"suitability":{"en":"Perfect for Developer Agents needing standardized documentation generation within the ToolHive ecosystem.","zh":"非常适合需要在 ToolHive 生态系统中生成标准化文档的开发者代理。","ja":"ToolHive エコシステム内で標準化されたドキュメント生成を必要とする Developer Agents に最適です。","ko":"ToolHive 생태계 내에서 표준화된 문서 생성을 필요한 개발자 에이전트에 적합합니다.","es":"Perfecto para Agentes de Desarrollador que necesitan generación de documentación estandarizada dentro del ecosistema ToolHive.","fr":"Parfait pour les agents de développement ayant besoin d''une génération de documentation standardisée dans l''écosystème ToolHive.","de":"Perfekt für Entwickleragenten, die eine standardisierte Dokumentenerstellung innerhalb des ToolHive-Ökosystems benötigen.","pt":"Perfeito para Agentes de Desenvolvedor que necessitam de geração de documentação padronizada dentro do ecossistema ToolHive.","ru":"Идеально подходит для агентов-разработчиков, которым требуется стандартизированная генерация документации в рамках экосистемы ToolHive.","ar":"مثالي لعميل التطوير الذي يحتاج إلى توليد توثيق معياري داخل نظام ToolHive."},"recommendation":{"en":"Empowers agents to create high-quality RFCs following established ToolHive patterns and conventions, utilizing Markdown files with the naming convention THV-{NUMBER}-{descriptive-name}.md, ensuring consistency and compliance with ecosystem standards.","zh":"赋予代理创建高质量的 RFC 文档的能力，遵循既定的 ToolHive 模式和约定，利用 Markdown 文件以 THV-{NUMBER}-{descriptive-name}.md 命名约定，确保与生态系统标准的一致性和符合性。","ja":"エージェントが確立された ToolHive パターンと規約に従った高品質の RFC を作成する能力を提供し、Markdown ファイルを使用して THV-{NUMBER}-{descriptive-name}.md という命名規約で命名し、エコシステムの標準に一致することを保証します。","ko":"에이전트가 확립된 ToolHive 패턴과 규약에 따라 높은 품질의 RFC를 생성할 수 있는 능력을 제공하며, Markdown 파일을 사용하여 THV-{NUMBER}-{descriptive-name}.md라는 명명 규칙으로命名하여 생태계 표준과 일致성을 보장합니다.","es":"Habilita a los agentes a crear RFC de alta calidad siguiendo patrones y convenciones establecidos de ToolHive, utilizando archivos Markdown con la convención de nomenclatura THV-{NUMBER}-{descriptive-name}.md, garantizando la coherencia y el cumplimiento de los estándares del ecosistema.","fr":"Permet aux agents de créer des RFC de haute qualité en suivant les modèles et conventions établis de ToolHive, en utilisant des fichiers Markdown avec la convention de nommage THV-{NUMBER}-{descriptive-name}.md, garantissant la cohérence et la conformité aux normes de l''écosystème.","de":"Ermöglicht es Agenten, hochwertige RFCs nach festgelegten ToolHive-Mustern und -Konventionen zu erstellen, indem Markdown-Dateien mit der Namenskonvention THV-{NUMBER}-{descriptive-name}.md verwendet werden, um Konsistenz und Einhaltung der Ökosystemstandards sicherzustellen.","pt":"Habilita os agentes a criar RFCs de alta qualidade seguindo os padrões e convenções estabelecidos do ToolHive, utilizando arquivos Markdown com a convenção de nomenclatura THV-{NUMBER}-{descriptive-name}.md, garantindo consistência e conformidade com os padrões do ecossistema.","ru":"Наделяет агентов возможностью создавать высококачественные RFC, следуя установленным шаблонам и соглашениям ToolHive, используя файлы Markdown с именами в формате THV-{NUMBER}-{descriptive-name}.md, обеспечивая последовательность и соответствие стандартам экосистемы.","ar":"يمنح العملاء القدرة على إنشاء طلبات RFC عالية الجودة اتباعًا للأنماط والمواصفات المعتمدة من ToolHive، باستخدام ملفات Markdown بالاتفاقية THV-{NUMBER}-{descriptive-name}.md، ضامنًا الاتساق والامتثال لمعايير النظام."},"useCases":{"en":["Generating compliant RFCs for ToolHive projects","Automating documentation for new features and updates","Standardizing proposal formats for ecosystem contributors"],"zh":["为 ToolHive 项目生成符合标准的 RFC 文档","自动化新功能和更新的文档","为生态系统贡献者标准化提案格式"],"ja":["ToolHive プロジェクトの標準に準拠した RFC ドキュメントを生成する","新機能と更新のドキュメントを自動化する","エコシステムの貢献者の提案書フォーマットを標準化する"],"ko":["ToolHive 프로젝트에 대한 준수 RFC 문서 생성","새로운 기능 및 업데이트 문서 자동화","생태계 기여자의 제안서 형식 표준화"],"es":["Generación de RFC compatibles para proyectos de ToolHive","Automatización de la documentación para nuevas características y actualizaciones","Estandarización de formatos de propuestas para contribuyentes del ecosistema"],"fr":["Génération de RFC compatibles pour les projets ToolHive","Automatisation de la documentation pour les nouvelles fonctionnalités et mises à jour","Standardisation des formats de propositions pour les contributeurs de l''écosystème"],"de":["Erstellung kompatibler RFCs für ToolHive-Projekte","Automatisierung der Dokumentation für neue Funktionen und Updates","Standardisierung von Vorschlagsformaten für Ökosystem-Mitwirkende"],"pt":["Geração de RFCs conformes para projetos ToolHive","Automação da documentação para novos recursos e atualizações","Padronização de formatos de propostas para contribuidores do ecossistema"],"ru":["Генерация соответствующих RFC для проектов ToolHive","Автоматизация документации для новых функций и обновлений","Стандартизация форматов предложений для участников экосистемы"],"ar":["توليد طلبات RFC متوافقة لمشاريع ToolHive","تحويل التوثيق تلقائيًا لميزات وترقيات جديدة","توحيد صيغ المقترحات للمساهمين في النظام"]},"limitations":{"en":["Requires knowledge of ToolHive ecosystem conventions","Specific to ToolHive RFC format","Zero-padded 4-digit numbering required for PR numbers"],"zh":["需要了解 ToolHive 生态系统的约定","仅限 ToolHive RFC 格式","PR 编号需要零填充的 4 位数字"],"ja":["ToolHive エコシステムの規約の知識が必要","ToolHive RFC 形式に限定される","PR 番号にはゼロパディングされた 4 桁の数字が必要"],"ko":["ToolHive 생태계의 규약에 대한 지식이 필요","ToolHive RFC 형식에 한정","PR 번호에는 0填充된 4자리 숫자가 필요"],"es":["Requiere conocimiento de las convenciones del ecosistema ToolHive","Específico del formato de RFC de ToolHive","Se requiere numeración de 4 dígitos con relleno de ceros para los números de PR"],"fr":["Nécessite une connaissance des conventions de l''écosystème ToolHive","Spécifique au format de RFC de ToolHive","Un nombre de 4 chiffres avec zéros de remplissage est requis pour les numéros de PR"],"de":["Benötigt Kenntnisse der ToolHive-Ökosystem-Konventionen","Spezifisch für das ToolHive-RFC-Format","Vierstellige Nummerierung mit führenden Nullen erforderlich für PR-Nummern"],"pt":["Requer conhecimento das convenções do ecossistema ToolHive","Específico para o formato de RFC do ToolHive","Necessário numeração com zeros à esquerda de 4 dígitos para números de PR"],"ru":["Требует знания соглашений экосистемы ToolHive","Спецефичен для формата RFC ToolHive","Требуется нумерация с ведущими нулями из 4 цифр для номеров PR"],"ar":["يتطلب معرفة المواصفات لنظام ToolHive","محدد لتنسيق طلب RFC الخاص بال أداة ToolHive","مطلوب ترقيم بأربعة أرقام مع صفر زائد لرقام الطلبات"]},"version":4},"contentHash":"2f7c52bbc5f05bc117c14892aa05ad235ff55ea37bc7d842ab1b4fa0375c419f","qualityScore":45}');
