INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('stacklok/toolhive-rfcs/write-rfc', 'write-rfc', 'stacklok', 'toolhive-rfcs', 'community', 'write-rfc stacklok toolhive-rfcs community The write-rfc skill helps developers create high-quality RFCs for the ToolHive ecosystem, following a specific format with naming convention THV-{NUMBER}-{descriptive-name}.md. This skill benefits developers working within the ToolHive ecosystem. write-rfc 技术是一种用于编写高质量 ToolHive 生态系统 RFC 的工具，遵循特定的格式和命名约定 write-rfc 技術は、特定のフォーマットと命名規則に従って、高品質の ToolHive エコシステム RFC を作成するためのツールです write-rfc 기술은 특정 형식 및 명명 규칙을 따라 높은 품질의 ToolHive 생태계 RFC를 작성하기 위한 도구입니다 El skill write-rfc ayuda a crear RFCs de alta calidad para el ecosistema ToolHive siguiendo patrones y convenciones establecidos Le skill write-rfc aide à créer des RFCs de haute qualité pour l''écosystème ToolHive en suivant les modèles et conventions établis Das write-rfc-Skill hilft bei der Erstellung von hochwertigen RFCs für das ToolHive-Ökosystem unter Einhaltung etablierter Muster und Konventionen O write-rfc é uma habilidade que ajuda a escrever RFCs de alta qualidade para o ecossistema ToolHive, seguindo padrões e convenções estabelecidos. Write-rfc - это навык, который помогает создавать качественные RFC для экосистемы ToolHive, следуя установленным стандартам и соглашениям для ИИ Агентов. write-rfc هو مهارة تساعد على كتابة RFCs عالية الجودة لمنصة ToolHive، متبعة المعايير والمواصفات المتبعة لأدوات الذكاء الاصطناعي. how to use write-rfc what is write-rfc write-rfc setup guide ToolHive RFC format THV-{NUMBER}-{descriptive-name}.md write-rfc alternative write-rfc vs other RFC tools write-rfc install ToolHive ecosystem workflow write-rfc 技术 ToolHive 生态系统 RFC 编写格式 命名约定 问题陈述 目标仓库 PR 号码 零填充 Generates THV-{NUMBER}-{descriptive-name}.md files with zero-padded 4-digit PR numbers Follows established ToolHive RFC patterns and conventions Asks for problem statement and target repository information Creates high-quality RFCs for the ToolHive ecosystem Uses a specific naming convention for RFC files Supports the ToolHive ecosystem workflow write-rfc is a skill that assists in creating ToolHive RFCs following established patterns and conventions, using a specific format for THV-{NUMBER}-{descriptive-name}.md files');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('specvital/infra/ui-ux-improve', 'community', 'specvital', 'infra', 'specvital/infra', 'ui-ux-improve', 0, 0, 45, '2026-03-08T01:57:15.349Z', '2026-03-08T02:03:46.485Z', 'f8805caf12b5bb62d92b47b071eac6e30267915c83aba10a1b48a5494731f032', '{"id":"specvital/infra/ui-ux-improve","name":"ui-ux-improve","description":{"en":"The ui-ux-improve skill provides AI-powered UI/UX analysis and real-time trend research for developers. It generates actionable improvement recommendations for specific components, pages, or features.","zh":"该工具结合 AI 驱动的 UI/UX 分析和实时趋势研究，生成可行的改进建议。使用 Docker 和 Atlas 迁移来优化您的应用程序","ja":"このツールは、AI ドリブンの UI/UX 分析とリアルタイムのトレンド研究を組み合わせて、実行可能な改善提案を生成します。Docker と Atlas マイグレーションを使用してアプリケーションを最適化します","ko":"이 도구는 AI 기반의 UI/UX 분석과 실시간 트렌드 연구를 결합하여 실행 가능한 개선 제안을 생성합니다. Docker 및 Atlas 마이그레이션을 사용하여 애플리케이션을 최적화합니다","es":"Mejora la experiencia del usuario con nuestra herramienta de análisis UI/UX que utiliza Docker y Atlas para optimizar el desarrollo local. Analiza y mejora componentes específicos o la aplicación completa.","fr":"Améliorez l''expérience utilisateur avec notre outil d''analyse UI/UX qui utilise Docker et Atlas pour optimiser le développement local. Analysez et améliorez des composants spécifiques ou l''application entière.","de":"Verbessern Sie die Benutzererfahrung mit unserem UI/UX-Analyse-Tool, das Docker und Atlas für die Optimierung der lokalen Entwicklung verwendet. Analysieren und verbessern Sie bestimmte Komponenten oder die gesamte Anwendung.","pt":"O ui-ux-improve combina análise de UI/UX com pesquisa de tendências em tempo real para gerar melhorias ação","ru":"ui-ux-improve сочетает анализ UI/UX с исследованием тенденций в реальном времени для генерации действенных улучшений с помощью ИИ Агентов","ar":"يجمع ui-ux-improve بين تحليل واجهة المستخدم وتصميمها مع بحث الاتجاهات في الوقت الفعلي لتوليد تحسينات فورية باستخدام أدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"ui-ux-improve: AI-Powered UI/UX Analysis Setup Guide | AI...","zh":"UI/UX 优化工具 - 使用 Docker 和 Atlas 迁移","ja":"UI/UX 改善ツール - Docker と Atlas マイグレーションを使用","ko":"UI/UX 개선 도구 - Docker 및 Atlas 마이그레이션 사용","es":"Herramientas de UI/UX: Mejora con Docker y Atlas","fr":"Outils UI/UX améliorés avec Docker et Atlas","de":"UI/UX-Tools: Verbesserung mit Docker und Atlas","pt":"Guia de Configuração do ui-ux-improve para Melhoria de In...","ru":"Настройка ui-ux-improve для улучшения интерфейса пользова...","ar":"دليل تكوين ui-ux-improve لتحسين واجهة المستخدم باستخدام أ..."},"description":{"en":"Unlock actionable UI/UX improvements with ui-ux-improve. Discover how to combine AI analysis with trend research for data-driven design decisions. Get starte...","zh":"使用 AI 驱动的 UI/UX 分析和实时趋势研究，生成可行的改进建议。了解如何使用 Docker 和 Atlas 迁移来优化您的应用程序","ja":"AI ドリブンの UI/UX 分析とリアルタイムのトレンド研究を使用して、実行可能な改善提案を生成します。Docker と Atlas マイグレーションを使用してアプリケーションを最適化する方法をご紹介します","ko":"AI 기반의 UI/UX 분석과 실시간 트렌드 연구를 사용하여 실행 가능한 개선 제안을 생성합니다. Docker 및 Atlas 마이그레이션을 사용하여 애플리케이션을 최적화하는 방법에 대해 알아보세요","es":"Mejora la experiencia del usuario con nuestra herramienta de análisis UI/UX que utiliza Docker y Atlas para optimizar el desarrollo local","fr":"Améliorez l''expérience utilisateur avec notre outil d''analyse UI/UX qui utilise Docker et Atlas pour optimiser le développement local","de":"Verbessern Sie die Benutzererfahrung mit unserem UI/UX-Analyse-Tool, das Docker und Atlas für die Optimierung der lokalen Entwicklung verwendet","pt":"Aprenda a configurar o ui-ux-improve para melhorar a experiência do usuário com análise de tendências e infraestrutura de desenvolvimento local","ru":"Узнайте, как настроить ui-ux-improve для улучшения пользовательского опыта с помощью анализа тенденций и локальной инфраструктуры разработки с ИИ Агентами","ar":"تعرف على كيفية تكوين ui-ux-improve لتحسين تجربة المستخدم مع تحليل الاتجاهات وبنية التطوير المحلية باستخدام أدوات الذكاء الاصطناعي"},"definition":{"en":"ui-ux-improve is a skill that combines AI-powered UI/UX analysis with real-time trend research to generate actionable improvement recommendations for developers.","zh":"UI/UX 优化工具是一种使用 AI 驱动的分析和实时趋势研究来改善应用程序用户体验的工具","ja":"UI/UX 改善ツールは、AI ドリブンの分析とリアルタイムのトレンド研究を使用してアプリケーションのユーザーエクスペリエンスを改善するツールです","ko":"UI/UX 개선 도구는 AI 기반의 분석과 실시간 트렌드 연구를 사용하여 애플리케이션의 사용자 경험을 개선하는 도구입니다","es":"Herramienta de mejora de UI/UX que analiza y optimiza la experiencia del usuario utilizando tecnologías como Docker y Atlas","fr":"Outil d''amélioration de l''UI/UX qui analyse et optimise l''expérience utilisateur en utilisant des technologies comme Docker et Atlas","de":"UI/UX-Verbesserungstool, das die Benutzererfahrung mit Technologien wie Docker und Atlas analysiert und optimiert","pt":"O ui-ux-improve é uma ferramenta de melhoria de interface que utiliza análise de UI/UX e pesquisa de tendências","ru":"ui-ux-improve - это инструмент улучшения интерфейса, использующий анализ UI/UX и исследование тенденций с ИИ Агентами","ar":"ui-ux-improve هو أداة لتحسين واجهة المستخدم تستخدم تحليل واجهة المستخدم وتصميمها وبحث الاتجاهات باستخدام أدوات الذكاء الاصطناعي"},"features":{"en":["Parses user input for focus area, mode, and scope using text arguments","Analyzes entire application with research mode by default","Supports targeted analysis for specific components, pages, or features","Generates actionable improvement recommendations using AI analysis and trend research","Allows for immediate action with implement mode","Provides flexible analysis scope with full or targeted options"],"zh":["使用 Docker 和 Atlas 迁移来优化应用程序","AI 驱动的 UI/UX 分析和实时趋势研究","生成可行的改进建议","支持研究和实施模式","可分析整个应用程序或特定区域"],"ja":["Docker と Atlas マイグレーションを使用してアプリケーションを最適化","AI ドリブンの UI/UX 分析とリアルタイムのトレンド研究","実行可能な改善提案を生成","研究と実装モードをサポート","全アプリケーションまたは特定の領域を分析"],"ko":["Docker 및 Atlas 마이그레이션을 사용하여 애플리케이션을 최적화","AI 기반의 UI/UX 분석과 실시간 트렌드 연구","실행 가능한 개선 제안을 생성","연구와 구현 모드를 지원","전체 애플리케이션 또는 특정 영역을 분석"],"es