INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('specvital/infra/ui-ux-improve', 'ui-ux-improve', 'specvital', 'infra', 'community', 'ui-ux-improve specvital infra community The ui-ux-improve skill provides AI-powered UI/UX analysis and real-time trend research for developers. It generates actionable improvement recommendations for specific components, pages, or features. 该工具结合 AI 驱动的 UI/UX 分析和实时趋势研究，生成可行的改进建议。使用 Docker 和 Atlas 迁移来优化您的应用程序 このツールは、AI ドリブンの UI/UX 分析とリアルタイムのトレンド研究を組み合わせて、実行可能な改善提案を生成します。Docker と Atlas マイグレーションを使用してアプリケーションを最適化します 이 도구는 AI 기반의 UI/UX 분석과 실시간 트렌드 연구를 결합하여 실행 가능한 개선 제안을 생성합니다. Docker 및 Atlas 마이그레이션을 사용하여 애플리케이션을 최적화합니다 Mejora la experiencia del usuario con nuestra herramienta de análisis UI/UX que utiliza Docker y Atlas para optimizar el desarrollo local. Analiza y mejora componentes específicos o la aplicación completa. Améliorez l''expérience utilisateur avec notre outil d''analyse UI/UX qui utilise Docker et Atlas pour optimiser le développement local. Analysez et améliorez des composants spécifiques ou l''application entière. Verbessern Sie die Benutzererfahrung mit unserem UI/UX-Analyse-Tool, das Docker und Atlas für die Optimierung der lokalen Entwicklung verwendet. Analysieren und verbessern Sie bestimmte Komponenten oder die gesamte Anwendung. O ui-ux-improve combina análise de UI/UX com pesquisa de tendências em tempo real para gerar melhorias ação ui-ux-improve сочетает анализ UI/UX с исследованием тенденций в реальном времени для генерации действенных улучшений с помощью ИИ Агентов يجمع ui-ux-improve بين تحليل واجهة المستخدم وتصميمها مع بحث الاتجاهات في الوقت الفعلي لتوليد تحسينات فورية باستخدام أدوات الذكاء الاصطناعي how to use ui-ux-improve ui-ux-improve setup guide ui-ux-improve alternative ui-ux-improve vs competing tools what is ui-ux-improve ui-ux-improve install ui-ux-improve for AI agents ui-ux-improve research mode ui-ux-improve implement mode ui-ux-improve trend research UI/UX 优化 AI 驱动的分析 Docker 和 Atlas 迁移 应用程序优化 用户体验改善 AI 工具 UI/UX 改善工具 Parses user input for focus area, mode, and scope using text arguments Analyzes entire application with research mode by default Supports targeted analysis for specific components, pages, or features Generates actionable improvement recommendations using AI analysis and trend research Allows for immediate action with implement mode Provides flexible analysis scope with full or targeted options ui-ux-improve is a skill that combines AI-powered UI/UX analysis with real-time trend research to generate actionable improvement recommendations for developers.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Vong3432/vibemark/nestjs-typeorm-integration', 'community', 'Vong3432', 'vibemark', 'Vong3432/vibemark', 'nestjs-typeorm-integration', 0, 0, 45, '2026-03-08T01:57:15.352Z', '2026-03-08T02:03:53.395Z', '471efb3ad31e50bd4a42412f8da4d3dd1cea17d06368aacb65e6517cbd498665', '{"id":"Vong3432/vibemark/nestjs-typeorm-integration","name":"nestjs-typeorm-integration","description":{"en":"The nestjs-typeorm-integration skill helps developers integrate TypeORM with NestJS, enabling clean and scalable data management. It benefits developers working with NestJS and TypeORM.","zh":"本技能提供了 NestJS 和 TypeORM 集成的技术指导，帮助开发者建立可扩展和生产友好的应用","ja":"このスキルは、NestJS と TypeORM のインテグレーションに関する技術ガイドを提供し、開発者が拡張可能で生産性の高いアプリケーションを構築するのに役立ちます","ko":"이 스킬은 NestJS와 TypeORM 통합에 대한 기술 가이드를 제공하여 개발자가 확장 가능하고 생산성 높은 애플리케이션을 구축하도록 도와줍니다","es":"Integra TypeORM con NestJS de manera efectiva. Configura entidades, migraciones y repositorios para una aplicación escalable.","fr":"Intégrez TypeORM avec NestJS de manière efficace. Configurez des entités, des migrations et des référentiels pour une application évolutiva.","de":"Integrieren Sie TypeORM mit NestJS effektiv. Konfigurieren Sie Entitäten, Migrationen und Repositorys für eine skalierbare Anwendung.","pt":"Integre TypeORM com NestJS para desenvolver aplicações robustas e escaláveis. Configure entidades, migrações e repositórios com facilidade.","ru":"Интегрируйте TypeORM с NestJS для разработки прочных и масштабируемых приложений. Настройте сущности, миграции и репозитории безопасно.","ar":"دمج TypeORM مع NestJS لإنشاء تطبيقات قوية ومرنة. قم بتهيئة الكيانات والهجرات والمستودعات بسهولة."},"seo":{"title":{"en":"nestjs-typeorm-integration: Setup Guide for AI Agents","zh":"NestJS + TypeORM 集成最佳实践","ja":"NestJS + TypeORM インテグレーションガイド","ko":"NestJS + TypeORM 통합 설정 가이드","es":"Guía de Integración NestJS y TypeORM","fr":"Intégration NestJS et TypeORM : Guide de Configuration","de":"NestJS und TypeORM Integration: Einrichtungsleitfaden","pt":"Guia de Integração NestJS com TypeORM","ru":"ИИ Агент для Интеграции NestJS и TypeORM","ar":"دليل دمج NestJS مع TypeORM"},"description":{"en":"Discover how to integrate TypeORM with NestJS for scalable and production-friendly applications. Learn setup, configuration, and best practices now!","zh":"学习如何在 NestJS 项目中集成 TypeORM，包括设置数据源、定义实体和关系、配置迁移等","ja":"NestJS プロジェクトで TypeORM をインテグレートする方法を学びます。データソースの設定、エンティティと関係の定義、移行の設定など","ko":"NestJS 프로젝트에서 TypeORM을 통합하는 방법을 배우세요. 데이터 소스 설정, 엔티티 및 관계 정의, 마이그레이션 설정 등","es":"Aprende a integrar TypeORM con NestJS de manera limpia y escalable. Configura entidades, migraciones y repositorios con este agente de AI Herramientas","fr":"Découvrez comment intégrer TypeORM avec NestJS de manière propre et évolutiva. Configurez des entités, des migrations et des référentiels avec cet outil d''Ag...","de":"Erfahren Sie, wie Sie TypeORM mit NestJS sauber und skalierbar integrieren. Konfigurieren Sie Entitäten, Migrationen und Repositorys mit diesem Tool für KI-A...","pt":"Aprenda a integrar TypeORM com NestJS de forma limpa e escalável. Configure entidades, migrações e repositórios com facilidade.","ru":"Освойте интеграцию TypeORM с NestJS. Настройте сущности, миграции и репозитории безопасно и масштабируемо.","ar":"تعلم كيفية دمج TypeORM مع NestJS بطريقة نظيفة ومرنة. قم بتهيئة الكيانات والهجرات والمستودعات بسهولة."},"definition":{"en":"nestjs-typeorm-integration is a specialized skill for integrating TypeORM with NestJS, focusing on setup, entity definition, migrations, and repository configuration.","zh":"NestJS + TypeORM 集成是指在 NestJS 项目中使用 TypeORM 作为对象关系映射工具","ja":"NestJS + TypeORM インテグレーションは、NestJS プロジェクトで TypeORM をオブジェクト関係マッピングツールとして使用すること","ko":"NestJS + TypeORM 통합은 NestJS 프로젝트에서 TypeORM을 객체 관계 매핑 도구로 사용하는 것을 말합니다","es":"La integración de NestJS y TypeORM es una técnica para conectar una aplicación NestJS con una base de datos utilizando TypeORM","fr":"L''intégration de NestJS et TypeORM est une technique pour connecter une application NestJS à une base de données en utilisant TypeORM","de":"Die Integration von NestJS und TypeORM ist eine Technik, um eine NestJS-Anwendung mit einer Datenbank über TypeORM zu verbinden","pt":"A integração NestJS com TypeORM é uma técnica para desenvolver aplicações robustas e escaláveis.","ru":"Интеграция NestJS с TypeORM - это техника для разработки прочных и масштабируемых приложений.","ar":"دمج NestJS مع TypeORM هو تقنية لإنشاء تطبيقات قوية ومرنة."},"features":{"en":["Sets up TypeORM in a NestJS project with data source, modules, and config","Defines or refactors entities and their relations for efficient data modeling","Configures migrations and environment-specific DB settings for flexibility","Wires repositories into services using Nest DI for seamless dependency injection","Implements transactions and query patterns safely for reliable data operations","Optimizes database interactions for production-friendly applications"],"zh":["设置 TypeORM 数据源","定义和重构实体及其关系","配置迁移和环境特定数据库设置","将存储库连接到服务使用 Nest DI","安全地实现事务和查询模式"],"ja":["TypeORM データソースの設定","エンティティとその関係の定義とリファクタリング","移行と環境特定のデータベース設定の構成","リポジトリをサービスに接続するために Nest DI を使用","トランザクションとクエリパターンの安全な実装"],"ko":["TypeORM 데이터 소스 설정","엔티티 및 관계 정의 및 리팩토링","마이그레이션 및 환경 특정 데이터베이스 설정 구성","리포지토리를 서비스에 연결하기 위해 Nest DI 사용","트랜잭션 및 쿼리 패턴의 안전한 구현"],"es":["Configuración de TypeORM en un proyecto NestJS","Definición y refactorización de entidades y relaciones","Configuración de migraciones y ajustes de base de datos específicos del entorno","Inyección de dependencias de repositorios en servicios","Implementación de transacciones y patrones de consulta de manera segura"],"fr":["Configuration de TypeORM dans un projet NestJS","Définition et refactoring d''entités et de relations","Configuration des migrations et des paramètres de base de données spécifiques à l''environnement","Injection de dépendances de référentiels dans les services","Implémentation de transactions et de modèles de requête de manière sécurisée"],"de":["Konfiguration von TypeORM in einem NestJS-Projekt","Definition und Refactoring von Entitäten und Beziehungen","Konfiguration von Migrationen und umgebungspezifischen Datenbank-Einstellungen","Einbindung von Repository-Abhängigkeiten in Dienste","Implementierung von Transaktionen und Abfragemustern auf sichere Weise"],"pt":["Configuração de TypeORM em projetos NestJS","Definição e refatoração de entidades e relações","Configuração de migrações e definições de banco de dados","Uso de repositórios em serviços com Nest DI","Implementação de transações e padrões de consulta de forma segura"],"ru":["Настройка TypeORM в проектах NestJS","Определение и рефакторинг сущностей и отношений","Настройка миграций и настроек базы данных","Использование репозиториев в сервисах с Nest DI","Реализация транзакций и шаблонов запросов безопасно"],"ar":["تهيئة TypeORM في مشاريع NestJS","تحديد واعادة بناء الكيانات والعلاقات","تهيئة الهجرات وضبط قواعد البيانات","استخدام المستودعات في الخدمات مع Nest DI","تنفيذ المعاملات وأنماط الاستعلام بأمان"]},"keywords":{"en":["how to use nestjs-typeorm-integration","nestjs-typeorm-integration setup guide","nestjs-typeorm-integration vs sequelize","nestjs-typeorm-integration install","what is nestjs-typeorm-integration","nestjs-typeorm-integration alternative","nestjs-typeorm-integration best practices","integrating typeorm with nestjs","nestjs-typeorm-integration tutorial"],"zh":["NestJS TypeORM 集成","TypeORM 数据源设置","NestJS 实体定义","TypeORM 迁移配置","NestJS 服务依赖注入","TypeORM 事务实现","AI 에이전트","AI 工具"],"ja":["NestJS TypeORM インテグレーション","TypeORM データソース設定","NestJS エンティティ定義","TypeORM 移行構成","NestJS サービス依存注入","TypeORM トランザクション実装","AI エージェント","AI ツール"],"ko":["NestJS TypeORM 통합","TypeORM 데이터 소스 설정","NestJS 엔티티 정의","TypeORM 마이그레이션 구성","NestJS 서비스 의존성 주입","TypeORM 트랜잭션 구현","AI 에이전트","AI 도구"],"es":["integración NestJS TypeORM","configuración TypeORM","entidades y relaciones","migraciones de base de datos","inYEcción de dependencias","transacciones y patrones de consulta","desarrollo de aplicaciones escalables","herramientas de AI para desarrolladores"],"fr":["intégration NestJS TypeORM","configuration TypeORM","entités et relations","migrations de base de données","injection de dépendances","transactions et modèles de requête","développement d''applications évolutivas","outils d''IA pour les développeurs"],"de":["Integration von NestJS und TypeORM","Konfiguration von TypeORM","Entitäten und Beziehungen","Datenbankmigrationen","Einbindung von Abhängigkeiten","Transaktionen und Abfragemuster","Entwicklung von skalierbaren Anwendungen","KI-Tools für Entwickler"],"pt":["nestjs typeorm integração","typeorm nestjs setup","nestjs typeorm configuração","typeorm nestjs tutorial","nestjs typeorm exemplos","typeorm nestjs melhores práticas"],"ru":["nestjs typeorm интеграция","typeorm nestjs настройка","nestjs typeorm конфигурация","typeorm nestjs уроки","nestjs typeorm примеры","typeorm nestjs лучшие практики"],"ar":["nestjs typeorm دمج","typeorm nestjs إعداد","nestjs typeorm تهيئة","typeorm nestjs دروس","nestjs typeorm أمثلة","typeorm nestjs أفضل ممارسات"]}},"owner":"Vong3432","repo":"vibemark","repoPath":"Vong3432/vibemark","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.352Z","topics":[],"category":"community","skillMd":{"name":"nestjs-typeorm-integration","description":"Use this skill whenever the user wants to set up, configure, or refactor TypeORM within a NestJS TypeScript project, including data sources, entities, migrations, repositories, relations, and transactional patterns.","bodyPreview":"# NestJS + TypeORM Integration Skill\n\n## Purpose\n\nYou are a specialized assistant for **integrating TypeORM with NestJS** in a clean, scalable,\nand production-friendly way.\n\nUse this skill to:\n\n- Set up **TypeORM** in a NestJS project (data source, modules, config)\n- Define or refactor **entities** and their relations\n- Configure **migrations** and environment-specific DB settings\n- Wire **repositories** into services using Nest DI\n- Implement **transactions** and **query patterns** safely\n- Opt","body":"# NestJS + TypeORM Integration Skill\n\n## Purpose\n\nYou are a specialized assistant for **integrating TypeORM with NestJS** in a clean, scalable,\nand production-friendly way.\n\nUse this skill to:\n\n- Set up **TypeORM** in a NestJS project (data source, modules, config)\n- Define or refactor **entities** and their relations\n- Configure **migrations** and environment-specific DB settings\n- Wire **repositories** into services using Nest DI\n- Implement **transactions** and **query patterns** safely\n- Optimize DB usage (indexes, query patterns, relations loading) at a structural level\n\nDo **not** use this skill for:\n\n- General NestJS module/service/controller scaffolding → use `nestjs-project-scaffold` / `nestjs-modules-services-controllers`\n- Authentication logic → use `nestjs-authentication`\n- Supabase-specific flows → use Supabase skills (unless Supabase Postgres is accessed via TypeORM as a plain DB)\n\nIf `CLAUDE.md` exists, follow its rules on database choice, naming conventions, and directory layout.\n\n---\n\n## When To Apply This Skill\n\nTrigger this skill when the user asks for things like:\n\n- “Set up TypeORM in this NestJS API.”\n- “Create entities and migrations for these tables in NestJS + TypeORM.”\n- “Wire repositories into my Nest services.”\n- “Fix or refactor our NestJS TypeORM config.”\n- “Add relations between these entities and update the service logic.”\n- “Handle transactions for this multi-step operation.”\n\nAvoid using this skill when:\n\n- Only high-level REST API contracts are changing without DB impact.\n- Only pure in-memory logic is being implemented.\n\n---\n\n## Assumptions & Defaults\n\nUnless the project states otherwise, assume:\n\n- Database: Postgres (can be adapted to MySQL, SQLite, etc.)\n- TypeORM version: current stable for NestJS\n- Connection is configured via Nest’s `TypeOrmModule`\n- Config is environment-driven via `@nestjs/config` and `.env` files\n- Entities live in `src/modules/<feature>/entities` or `src/entities` depending on project style\n- Migrations live in `src/migrations` or `migrations` directory\n\n---\n\n## High-Level Architecture\n\nRecommended structure (adapt as needed):\n\n```text\nproject-root/\n  src/\n    config/\n      database.config.ts\n    modules/\n      user/\n        user.module.ts\n        user.service.ts\n        user.controller.ts\n        entities/\n          user.entity.ts\n      post/\n        post.module.ts\n        post.service.ts\n        post.controller.ts\n        entities/\n          post.entity.ts\n    infrastructure/\n      database/\n        ormconfig.ts or data-source.ts (optional central place)\n  migrations/\n    1710000000000-CreateUserTable.ts\n    1710000001000-CreatePostTable.ts\n```\n\nThis skill should align with the existing structure rather than forcing a totally new one, unless the project is greenfield.\n\n---\n\n## Step-by-Step Workflow\n\nWhen this skill is active, follow these steps:\n\n### 1. Set Up TypeORM Module Configuration\n\nIf TypeORM is not configured yet:\n\n- Install TypeORM + DB driver for the chosen database.\n- Configure `TypeOrmModule` in `AppModule` or a dedicated `DatabaseModule`.\n\nExample using `@nestjs/config`:\n\n```ts\n// src/config/database.config.ts\nimport { registerAs } from \"@nestjs/config\";\n\nexport default registerAs(\"database\", () => ({\n  type: \"postgres\",\n  host: process.env.DB_HOST ?? \"localhost\",\n  port: parseInt(process.env.DB_PORT ?? \"5432\", 10),\n  username: process.env.DB_USERNAME ?? \"postgres\",\n  password: process.env.DB_PASSWORD ?? \"postgres\",\n  database: process.env.DB_NAME ?? \"app_db\",\n}));\n```\n\n```ts\n// src/app.module.ts\nimport { Module } from \"@nestjs/common\";\nimport { ConfigModule, ConfigService } from \"@nestjs/config\";\nimport databaseConfig from \"./config/database.config\";\nimport { TypeOrmModule } from \"@nestjs/typeorm\";\n\n@Module({\n  imports: [\n    ConfigModule.forRoot({\n      isGlobal: true,\n      load: [databaseConfig],\n    }),\n    TypeOrmModule.forRootAsync({\n      inject: [ConfigService],\n      useFactory: (config: ConfigService) => {\n        const db = config.get(\"database\");\n        return {\n          ...db,\n          autoLoadEntities: true,\n          synchronize: false, // prefer migrations in production\n        };\n      },\n    }),\n    // feature modules...\n  ],\n})\nexport class AppModule {}\n```\n\nKey rules:\n\n- `synchronize: false` in all non-dev environments (this skill encourages migrations).\n- `autoLoadEntities: true` is acceptable for many apps; for stricter control, explicitly list entities.\n\n### 2. Environment Variables\n\nEnsure `.env` (and `.env.example`) contain:\n\n```env\nDB_HOST=localhost\nDB_PORT=5432\nDB_USERNAME=postgres\nDB_PASSWORD=postgres\nDB_NAME=app_db\n```\n\nThis skill should help keep secrets out of code and only in env/config.\n\n### 3. Entities Design\n\nFor each feature, create entity classes:\n\n```ts\n// src/modules/user/entities/user.entity.ts\nimport {\n  Column,\n  CreateDateColumn,\n  Entity,\n  PrimaryGeneratedColumn,\n  UpdateDateColumn,\n} from \"typeorm\";\n\n@Entity({ name: \"users\" })\nexport class User {\n  @PrimaryGeneratedColumn(\"uuid\")\n  id!: string;\n\n  @Column({ unique: true })\n  email!: string;\n\n  @Column()\n  passwordHash!: string;\n\n  @Column({ default: true })\n  isActive!: boolean;\n\n  @CreateDateColumn()\n  createdAt!: Date;\n\n  @UpdateDateColumn()\n  updatedAt!: Date;\n}\n```\n\nRelations example:\n\n```ts\n// src/modules/post/entities/post.entity.ts\nimport {\n  Column,\n  CreateDateColumn,\n  Entity,\n  ManyToOne,\n  PrimaryGeneratedColumn,\n} from \"typeorm\";\nimport { User } from \"../../user/entities/user.entity\";\n\n@Entity({ name: \"posts\" })\nexport class Post {\n  @PrimaryGeneratedColumn(\"uuid\")\n  id!: string;\n\n  @Column()\n  title!: string;\n\n  @Column({ type: \"text\" })\n  content!: string;\n\n  @ManyToOne(() => User, (user) => user.posts, { onDelete: \"CASCADE\" })\n  author!: User;\n\n  @CreateDateColumn()\n  createdAt!: Date;\n}\n```\n\nThis skill should:\n\n- Encourage using `uuid` or bigint for IDs consistently (per project preference).\n- Use clear relation options (`onDelete`, `eager`, `lazy`) thoughtfully.\n- Avoid putting heavy business logic directly into entities.\n\n### 4. Module & Repository Wiring\n\nUse `TypeOrmModule.forFeature` to inject repositories into feature modules:\n\n```ts\n// src/modules/user/user.module.ts\nimport { Module } from \"@nestjs/common\";\nimport { TypeOrmModule } from \"@nestjs/typeorm\";\nimport { User } from \"./entities/user.entity\";\nimport { UserService } from \"./user.service\";\nimport { UserController } from \"./user.controller\";\n\n@Module({\n  imports: [TypeOrmModule.forFeature([User])],\n  controllers: [UserController],\n  providers: [UserService],\n  exports: [UserService],\n})\nexport class UserModule {}\n```\n\nIn `UserService`, inject the repository:\n\n```ts\n// src/modules/user/user.service.ts\nimport { Injectable } from \"@nestjs/common\";\nimport { InjectRepository } from \"@nestjs/typeorm\";\nimport { Repository } from \"typeorm\";\nimport { User } from \"./entities/user.entity\";\nimport { CreateUserDto } from \"./dto/create-user.dto\";\n\n@Injectable()\nexport class UserService {\n  constructor(\n    @InjectRepository(User)\n    private readonly usersRepo: Repository<User>,\n  ) {}\n\n  create(dto: CreateUserDto) {\n    const entity = this.usersRepo.create({\n      email: dto.email,\n      passwordHash: dto.passwordHash,\n    });\n    return this.usersRepo.save(entity);\n  }\n\n  findAll() {\n    return this.usersRepo.find();\n  }\n\n  findOne(id: string) {\n    return this.usersRepo.findOne({ where: { id } });\n  }\n\n  // etc...\n}\n```\n\nThis skill should enforce:\n\n- Repositories are injected via DI, not instantiated manually.\n- Services depend on repositories, not on the data source directly (except in advanced scenarios).\n\n### 5. Migrations\n\nEncourage using migrations instead of `synchronize` for schema changes.\n\n- Create a `data-source.ts` file if needed for CLI migrations:\n\n```ts\n// data-source.ts (or src/infrastructure/database/data-source.ts)\nimport \"reflect-metadata\";\nimport { DataSource } from \"typeorm\";\nimport databaseConfig from \"./src/config/database.config\";\nimport { config as loadEnv } from \"dotenv\";\n\nloadEnv();\n\nconst db = databaseConfig();\n\nexport const AppDataSource = new DataSource({\n  type: \"postgres\",\n  host: db.database.host,\n  port: db.database.port,\n  username: db.database.username,\n  password: db.database.password,\n  database: db.database.database,\n  entities: [\"src/**/*.entity.{ts,js}\"],\n  migrations: [\"migrations/*.{ts,js}\"],\n});\n```\n\n- Add package.json scripts for migrations (exact form depends on project):\n\n```jsonc\n{\n  \"scripts\": {\n    \"typeorm:run\": \"typeorm-ts-node-commonjs migration:run -d data-source.ts\",\n    \"typeorm:revert\": \"typeorm-ts-node-commonjs migration:revert -d data-source.ts\",\n    \"typeorm:generate\": \"typeorm-ts-node-commonjs migration:generate -d data-source.ts migrations/AutoMigration\"\n  }\n}\n```\n\nThis skill should:\n\n- Prefer explicit migration generation (`migration:generate`) over schema sync.\n- Keep migration files small, ordered, and committed to version control.\n\n### 6. Transactions & Complex Operations\n\nFor operations that require multiple DB writes, this skill should:\n\n- Use `QueryRunner` or `manager.transaction` where needed.\n\nExample:\n\n```ts\nimport { DataSource } from \"typeorm\";\n\n@Injectable()\nexport class OrderService {\n  constructor(private readonly dataSource: DataSource) {}\n\n  async createOrderAndItems(dto: CreateOrderDto) {\n    return this.dataSource.transaction(async (manager) => {\n      const order = manager.create(Order, { /* ... */ });\n      await manager.save(order);\n\n      const items = dto.items.map((itemDto) =>\n        manager.create(OrderItem, {\n          order,\n          // ...\n        }),\n      );\n      await manager.save(items);\n\n      return order;\n    });\n  }\n}\n```\n\nGuidelines:\n\n- Use transactions only where needed; avoid wrapping everything by default.\n- Handle error propagation correctly; if the transaction throws, it rolls back.\n\n### 7. Performance & Query Patterns\n\nThis skill should guide towards:\n\n- Using `select` and projections instead of always loading entire entities.\n- Avoiding N+1 queries with relation loading patterns when necessary.\n- Adding indexes in migrations for frequently queried columns.\n- Using pagination strategies (offset/limit or cursor-based) for large lists.\n\n### 8. Refactoring Existing TypeORM Usage\n\nWhen refactoring:\n\n- Identify anti-patterns:\n  - Manual connection creation (bypassing Nest DI)\n  - Direct use of global `getRepository` instead of injected repositories\n  - `synchronize: true` in production\n- Replace with:\n  - `TypeOrmModule` configuration\n  - Injected `Repository<T>` or `DataSource`\n  - Migrations for schema changes\n\nThis skill should try to minimize breaking changes while improving structure.\n\n---\n\n## Interaction with Other Skills\n\n- `nestjs-project-scaffold`:\n  - Provides the base Nest structure; this skill plugs DB configuration into it.\n- `nestjs-modules-services-controllers`:\n  - Uses modules/services; this skill adds entities + repositories behind those services.\n- `nestjs-authentication`:\n  - Depends on user entities and user repository; this skill provides that layer.\n- TypeORM-specific skills (`typeorm-schema-design`, `typeorm-migrations-workflow`):\n  - Can be used in addition for deeper DB design and migration strategies.\n\n---\n\n## Example Prompts That Should Use This Skill\n\n- “Connect this NestJS app to Postgres via TypeORM and create User & Post entities.”\n- “Refactor this hand-rolled DB code into proper TypeORM modules and services.”\n- “Add migrations for these schema changes and wire them into our NestJS project.”\n- “Implement a transactional operation that creates an order and its items.”\n- “Fix this TypeORM config; it works locally but fails in production.”\n\nFor such prompts, rely on this skill to design and implement **NestJS + TypeORM integration** that\nis robust, maintainable, and ready for production, while delegating non-DB concerns to other skills.\n"},"lastSynced":"2026-03-08T02:03:53.395Z","agentAnalysis":{"suitability":{"en":"Perfect for Full Stack Agents needing scalable and clean data management with NestJS and TypeORM integration.","zh":"非常适合需要可扩展和干净的数据管理的全栈代理，具有NestJS和TypeORM集成。","ja":"NestJSとTypeORMの統合を備えたスケーラブルでクリーンなデータ管理が必要なフルスタックエージェントに最適です。","ko":"NestJS와 TypeORM 통합을 통해 확장 가능하고 깨끗한 데이터 관리가 필요한 풀스택 에이전트에게 적합합니다.","es":"Perfecto para Agentes Full Stack que necesitan una gestión de datos escalable y limpia con integración de NestJS y TypeORM.","fr":"Parfait pour les agents Full Stack qui ont besoin d''une gestion de données évolutive et propre avec une intégration de NestJS et TypeORM.","de":"Perfekt für Full-Stack-Agenten, die eine skalierbare und saubere Datenverwaltung mit NestJS- und TypeORM-Integration benötigen.","pt":"Perfeito para Agentes Full Stack que precisam de gerenciamento de dados escalável e limpo com integração do NestJS e TypeORM.","ru":"Идеально для полнофункциональных агентов, которым требуется масштабируемое и чистое управление данными с помощью интеграции NestJS и TypeORM.","ar":"مثالي للوكلاء الكاملون الذين يحتاجون إلى إدارة بيانات قابلة للتوسعة وتنظيفها مع التكامل بين NestJS و TypeORM."},"recommendation":{"en":"Empowers agents to configure and manage data sources, entities, and migrations using TypeORM, and wire repositories into services using NestJS Dependency Injection, enabling safe transactions and query patterns.","zh":"赋予代理配置和管理数据源、实体和迁移使用TypeORM，并使用NestJS依赖注入将存储库连接到服务，从而实现安全的事务和查询模式。","ja":"TypeORMを使用してデータソース、エンティティ、およびマイグレーションを構成および管理し、NestJSの依存性注入を使用してリポジトリをサービスに接続し、安全なトランザクションとクエリパターンを可能にします。","ko":"TypeORM을 사용하여 데이터 소스, 엔티티 및 마이그레이션을 구성 및 관리하며, NestJS 의존성 주입을 사용하여 저장소를 서비스에 연결하여 안전한 트랜잭션 및 쿼리 패턴을 가능하게 합니다.","es":"Habilita a los agentes a configurar y gestionar fuentes de datos, entidades y migraciones utilizando TypeORM, y a conectar repositorios con servicios utilizando la inyección de dependencias de NestJS, lo que permite transacciones y patrones de consulta seguros.","fr":"Permet aux agents de configurer et de gérer des sources de données, des entités et des migrations à l''aide de TypeORM, et de connecter des référentiels à des services à l''aide de l''injection de dépendances de NestJS, ce qui permet des transactions et des modèles de requête sécurisés.","de":"Ermöglicht es Agenten, Datenquellen, Entitäten und Migrationen mit TypeORM zu konfigurieren und zu verwalten, und Repositorys mit Diensten über die Abhängigkeitsinjektion von NestJS zu verbinden, was sichere Transaktionen und Abfrageverhaltensmuster ermöglicht.","pt":"Habilita os agentes a configurar e gerenciar fontes de dados, entidades e migrações usando TypeORM, e conectar repositórios em serviços usando Injeção de Dependência do NestJS, permitindo transações e padrões de consulta seguros.","ru":"Позволяет агентам настраивать и управлять источниками данных, сущностями и миграциями с помощью TypeORM, а также подключать репозитории к сервисам с помощью внедрения зависимостей NestJS, обеспечивая безопасные транзакции и шаблоны запросов.","ar":"تمكين الوكلاء من تكوين وإدارة مصادر البيانات والكيانات والهجرات باستخدام TypeORM، وربط المستودعات بالخدمات باستخدام حقن التبعية في NestJS، مما يتيح معاملات وأنماط استعلام آمنة."},"useCases":{"en":["Setting up TypeORM in a NestJS project for production-friendly data management","Defining and refactoring entities and their relations for scalable data modeling","Configuring migrations and environment-specific DB settings for seamless deployment"],"zh":["在NestJS项目中设置TypeORM以进行生产友好的数据管理","定义和重构实体及其关系以进行可扩展的数据建模","配置迁移和环境特定的DB设置以进行无缝部署"],"ja":["プロダクション向けのデータ管理のためにNestJSプロジェクトでTypeORMを設定する","スケーラブルなデータモデリングのためにエンティティとその関係を定義およびリファクタリングする","シームレスなデプロイのためにマイグレーションと環境特定のDB設定を構成する"],"ko":["생산 친화적 인 데이터 관리를 위해 NestJS 프로젝트에서 TypeORM 설정","확장 가능한 데이터 모델링을 위해 엔티티 및 해당 관계 정의 및 리팩토링","无缝 배포를 위한 마이그레이션 및 환경 특정 DB 설정 구성"],"es":["Configuración de TypeORM en un proyecto NestJS para una gestión de datos amigable con la producción","Definir y refactorizar entidades y sus relaciones para un modelado de datos escalable","Configuración de migraciones y configuraciones de base de datos específicas del entorno para una implementación sin problemas"],"fr":["Configuration de TypeORM dans un projet NestJS pour une gestion de données conviviale avec la production","Définition et refactoring d''entités et de leurs relations pour un modelage de données évolutive","Configuration des migrations et des paramètres de base de données spécifiques à l''environnement pour un déploiement sans problèmes"],"de":["Einrichtung von TypeORM in einem NestJS-Projekt für eine produktionssichere Datenverwaltung","Definieren und Refactoring von Entitäten und ihren Beziehungen für ein skalierbares Datenmodell","Konfiguration von Migrationen und umgebungspezifischen Datenbank-einstellungen für eine reibungslose Bereitstellung"],"pt":["Configurar o TypeORM em um projeto NestJS para gerenciamento de dados amigável à produção","Definir e reestruturar entidades e suas relações para modelagem de dados escalável","Configurar migrações e configurações de BD específicas do ambiente para implantação sem problemas"],"ru":["Настройка TypeORM в проекте NestJS для управления данными в продакшене","Определение и рефакторинг сущностей и их отношений для масштабируемой модели данных","Настройка миграций и окружение-специфичных настроек БД для бесшовного развертывания"],"ar":["تكوين TypeORM في مشروع NestJS لإدارة البيانات الصديقة للإنتاج","تحديد وإعادة هيكلة الكيانات وعلاقاتها لنمذجة البيانات القابلة للتوسعة","تكوين الهجرات وإعدادات قاعدة البيانات الخاصة بالبيئة لنشر بدون مشاكل"]},"limitations":{"en":["Requires NestJS and TypeORM setup","Limited to TypeScript-based projects","Dependent on NestJS Dependency Injection for repository wiring"],"zh":["需要NestJS和TypeORM设置","仅限TypeScript基于项目","依赖于NestJS依赖注入进行存储库连接"],"ja":["NestJSとTypeORMの設定が必要","TypeScriptベースのプロジェクトのみ","リポジトリの接続にはNestJSの依存性注入に依存"],"ko":["NestJS 및 TypeORM 설정이 필요함","TypeScript 기반 프로젝트에만限함","저장소 연결에는 NestJS 의존성 주입에 의존"],"es":["Requiere configuración de NestJS y TypeORM","Limitado a proyectos basados en TypeScript","Dependiente de la inyección de dependencias de NestJS para el cableado del repositorio"],"fr":["Nécessite une configuration de NestJS et TypeORM","Limité aux projets basés sur TypeScript","Dépendant de l''injection de dépendances de NestJS pour le câblage du référentiel"],"de":["Benötigt NestJS- und TypeORM-Setup","Begrenzt auf TypeScript-basierte Projekte","Abhängig von der Abhängigkeitsinjektion von NestJS für die Verkabelung des Repositorys"],"pt":["Exige configuração do NestJS e TypeORM","Limitado a projetos baseados em TypeScript","Dependente da Injeção de Dependência do NestJS para ligação do repositório"],"ru":["Требует настройки NestJS и TypeORM","Ограничен проектами на основе TypeScript","Зависит от внедрения зависимостей NestJS для подключения репозитория"],"ar":["يتطلب إعداد NestJS و TypeORM","محدود بمشاريع قائمة على TypeScript","يعتمد على حقن التبعية في NestJS لربط المستودع"]},"version":4},"contentHash":"471efb3ad31e50bd4a42412f8da4d3dd1cea17d06368aacb65e6517cbd498665","qualityScore":45}');
