INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Vong3432/vibemark/nestjs-typeorm-integration', 'nestjs-typeorm-integration', 'Vong3432', 'vibemark', 'community', 'nestjs-typeorm-integration Vong3432 vibemark community The nestjs-typeorm-integration skill helps developers integrate TypeORM with NestJS, enabling clean and scalable data management. It benefits developers working with NestJS and TypeORM. 本技能提供了 NestJS 和 TypeORM 集成的技术指导，帮助开发者建立可扩展和生产友好的应用 このスキルは、NestJS と TypeORM のインテグレーションに関する技術ガイドを提供し、開発者が拡張可能で生産性の高いアプリケーションを構築するのに役立ちます 이 스킬은 NestJS와 TypeORM 통합에 대한 기술 가이드를 제공하여 개발자가 확장 가능하고 생산성 높은 애플리케이션을 구축하도록 도와줍니다 Integra TypeORM con NestJS de manera efectiva. Configura entidades, migraciones y repositorios para una aplicación escalable. Intégrez TypeORM avec NestJS de manière efficace. Configurez des entités, des migrations et des référentiels pour une application évolutiva. Integrieren Sie TypeORM mit NestJS effektiv. Konfigurieren Sie Entitäten, Migrationen und Repositorys für eine skalierbare Anwendung. Integre TypeORM com NestJS para desenvolver aplicações robustas e escaláveis. Configure entidades, migrações e repositórios com facilidade. Интегрируйте TypeORM с NestJS для разработки прочных и масштабируемых приложений. Настройте сущности, миграции и репозитории безопасно. دمج TypeORM مع NestJS لإنشاء تطبيقات قوية ومرنة. قم بتهيئة الكيانات والهجرات والمستودعات بسهولة. how to use nestjs-typeorm-integration nestjs-typeorm-integration setup guide nestjs-typeorm-integration vs sequelize nestjs-typeorm-integration install what is nestjs-typeorm-integration nestjs-typeorm-integration alternative nestjs-typeorm-integration best practices integrating typeorm with nestjs nestjs-typeorm-integration tutorial NestJS TypeORM 集成 TypeORM 数据源设置 NestJS 实体定义 TypeORM 迁移配置 NestJS 服务依赖注入 TypeORM 事务实现 AI 에이전트 AI 工具 Sets up TypeORM in a NestJS project with data source, modules, and config Defines or refactors entities and their relations for efficient data modeling Configures migrations and environment-specific DB settings for flexibility Wires repositories into services using Nest DI for seamless dependency injection Implements transactions and query patterns safely for reliable data operations Optimizes database interactions for production-friendly applications nestjs-typeorm-integration is a specialized skill for integrating TypeORM with NestJS, focusing on setup, entity definition, migrations, and repository configuration.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dpalfery/motorcycle-rag-system/clean-architecture', 'community', 'dpalfery', 'motorcycle-rag-system', 'dpalfery/motorcycle-rag-system', 'clean-architecture', 0, 0, 45, '2026-03-08T01:57:15.356Z', '2026-03-08T02:04:02.686Z', 'd11bd15d25178b13a5d4ab8bd2288db79049509c0c3bae573edf36e4c0ce60cb', '{"id":"dpalfery/motorcycle-rag-system/clean-architecture","name":"clean-architecture","description":{"en":"Clean-architecture is a technical approach that enforces the Dependency Rule, Independence of Frameworks, and Testability for AI-powered motorcycle information retrieval systems. It benefits developers working with multi-agent architectures.","zh":"Clean Architecture 是一种软件设计模式，强调内外层之间的依赖关系和框架的独立性，适用于构建复杂的 AI 系统","ja":"Clean Architecture は、内外層間の依存関係とフレームワークの独立性を重視するソフトウェア設計パターンであり、複雑な AI システムの構築に適しています","ko":"Clean Architecture는 내부와 외부 계층 사이의 의존 관계와 프레임워크의 독립성을 강조하는 소프트웨어 디자인 패턴으로, 복잡한 AI 시스템 구축에 적합합니다","es":"La arquitectura limpia es un enfoque de diseño de software que separa las preocupaciones y reduce la dependencia de los frameworks","fr":"L''architecture propre est une approche de conception de logiciels qui sépare les préoccupations et réduit la dépendance aux frameworks","de":"Die Clean-Architecture ist ein Software-Designansatz, der die Bedenken trennt und die Abhängigkeit von Frameworks reduziert","pt":"A Arquitetura Limpa é um padrão de design de software que separa a lógica de negócios da infraestrutura, melhorando a manutenção e escalabilidade","ru":"Чистая Архитектура - это шаблон проектирования программного обеспечения, который отделяет логику бизнеса от инфраструктуры, улучшая поддержку и масштабируемость","ar":"هندسة نظيفة هي نمط تصميم برمجي يفصل المنطق التجاري عن البنية التحتية، مما يحسن الصيانة والتوسيع"},"seo":{"title":{"en":"Clean-Architecture: Implementation Guide for AI Agents | ...","zh":"Clean Architecture 设计指南 - AI 电动摩托车信息检索系统","ja":"Clean Architecture 導入ガイド - AIエージェントによるオートバイ情報検索システム","ko":"Clean Architecture 구축 가이드 - AI 에이전트 기반 오토바이 정보 검색 시스템","es":"Guía de Configuración de Arquitectura Limpia para Agentes...","fr":"Guide de Mise en Place de l''Architecture Propre pour les ...","de":"Einrichtungsleitfaden für Clean Architecture in KI-Agenten","pt":"Guia de Configuração de Arquitetura Limpa para Desenvolve...","ru":"Настройка Чистой Архитектуры для ИИ Агентов: Руководство","ar":"دليل تركيب هندسة نظيفة لمنصة الاسترجاع المعلوماتي للدراجا..."},"description":{"en":"Unlock the power of Clean Architecture for your AI-powered projects. Learn how to enforce the Dependency Rule, achieve Independence of Frameworks, and ensure...","zh":"了解 Clean Architecture 的核心原则和实施方法，用于构建可扩展和可测试的 AI 电动摩托车信息检索系统","ja":"Clean Architecture の基本原則と実装方法を学び、拡張性とテスト性の高い AIエージェントによるオートバイ情報検索システムを構築しよう","ko":"Clean Architecture의 핵심 원칙과 구현 방법을 알아보고 확장 가능하고 테스트 가능한 AI 에이전트 기반 오토바이 정보 검색 시스템을 구축하세요","es":"Aprenda a implementar la arquitectura limpia en sus proyectos de inteligencia artificial con nuestra guía paso a paso","fr":"Découvrez comment mettre en place l''architecture propre dans vos projets d''intelligence artificielle avec notre guide étape par étape","de":"Erfahren Sie, wie Sie die Clean-Architecture in Ihren KI-Projekten implementieren können, mit unserer Schritt-für-Schritt-Anleitung","pt":"Aprenda a implementar a Arquitetura Limpa com DDD e C# para melhorar a manutenção e escalabilidade dos seus projetos de software","ru":"Узнайте, как настроить Чистую Архитектуру с DDD и C# для улучшения поддержки и масштабируемости ваших проектов","ar":"تعلم كيفية تطبيق هندسة نظيفة مع DDD و C# لتحسين صيانة وتوسيع مشاريعك البرمجية"},"definition":{"en":"Clean-architecture is a software design pattern that separates the application''s business logic from its infrastructure and presentation layers, based on Uncle Bob Martin''s principles.","zh":"Clean Architecture 是一种强调内外层之间的依赖关系和框架的独立性的软件设计模式","ja":"Clean Architecture は、内外層間の依存関係とフレームワークの独立性を重視するソフトウェア設計パターンである","ko":"Clean Architecture는 내부와 외부 계층 사이의 의존 관계와 프레임워크의 독립성을 강조하는 소프트웨어 디자인 패턴입니다","es":"La arquitectura limpia es un patrón de diseño de software que se basa en la separación de preocupaciones y la independencia de los frameworks","fr":"L''architecture propre est un modèle de conception de logiciels basé sur la séparation des préoccupations et l''indépendance des frameworks","de":"Die Clean-Architecture ist ein Software-Designmuster, das auf der Trennung von Bedenken und der Unabhängigkeit von Frameworks basiert","pt":"Arquitetura Limpa é um padrão de design de software que segue os princípios de Uncle Bob Martin","ru":"Чистая Архитектура - это шаблон проектирования программного обеспечения, основанный на принципах Анкла Боба Мартина","ar":"هندسة نظيفة هي نمط تصميم برمجي يتبع مبادئ أنكل بوب مارتين"},"features":{"en":["Enforces the Dependency Rule, ensuring source code dependencies point inward","Achieves Independence of Frameworks, making the architecture framework-agnostic","Ensures Testability, allowing business rules to be tested without UI or external elements","Follows Uncle Bob Martin''s Clean Architecture principles","Supports a multi-agent architecture for AI-powered systems","Implements a DDD Folder Structure using C#"],"zh":["基于 Uncle Bob Martin 的 Clean Architecture 原则","实现依赖规则和框架独立性","支持业务规则的单元测试","无需 UI、数据库或外部元素即可测试业务规则","C# 语言实现"],"ja":["Uncle Bob Martin の Clean Architecture 原則に基づく設計","依存規則とフレームワークの独立性の実現","ビジネスルールの単体テストのサポート","UI、データベース、または外部要素なしでビジネスルールをテスト可能","C# 言語による実装"],"ko":["Uncle Bob Martin의 Clean Architecture 원칙에 기반한 설계","의존 규칙과 프레임워크의 독립성 구현","비즈니스 규칙의 단위 테스트 지원","UI, 데이터베이스 또는 외부 요소 없이 비즈니스 규칙 테스트 가능","C# 언어로 구현"],"es":["Separación de preocupaciones","Independencia de frameworks","Principio de dependencia","Testabilidad de reglas de negocio","Estructura de carpetas basada en DDD"],"fr":["Séparation des préoccupations","Indépendance des frameworks","Principe de dépendance","Testabilité des règles métier","Structure de dossiers basée sur DDD"],"de":["Trennung von Bedenken","Unabhängigkeit von Frameworks","Abhängigkeitsprinzip","Testbarkeit von Geschäftsregeln","Verzeichnisstruktur basierend auf DDD"],"pt":["Separação da lógica de negócios da infraestrutura","Independência de frameworks","Testabilidade sem UI, Banco de Dados ou elementos externos","Estrutura de pastas baseada em DDD","Implementação em C#"],"ru":["Отделение логики бизнеса от инфраструктуры","Независимость от фреймворков","Тестирование без UI, Базы Данных или внешних элементов","Структура папок на основе DDD","Реализация на C#"],"ar":["فصل المنطق التجاري عن البنية التحتية","استقلالية من الإطارات","اختبار بدون واجهة المستخدم، قاعدة البيانات أو العناصر الخارجية","هيكل المجلدات dựa على DDD","تنفيذ بلغة C#"]},"keywords":{"en":["how to implement clean-architecture","clean-architecture vs monolithic architecture","clean-architecture setup guide","what is clean-architecture","clean-architecture alternative","clean-architecture install","clean-architecture best practices","clean-architecture for AI agents","Uncle Bob Martin''s Clean Architecture","C# clean-architecture example"],"zh":["Clean Architecture","AI 电动摩托车信息检索系统","依赖规则","框架独立性","业务规则测试","C# 实现","软件设计模式","AI 系统构建"],"ja":["Clean Architecture","AIエージェントによるオートバイ情報検索システム","依存規則","フレームワークの独立性","ビジネスルールテスト","C# 実装","ソフトウェア設計パターン","AI システム構築"],"ko":["Clean Architecture","AI 에이전트 기반 오토바이 정보 검색 시스템","의존 규칙","프레임워크의 독립성","비즈니스 규칙 테스트","C# 구현","소프트웨어 디자인 패턴","AI 시스템 구축"],"es":["arquitectura limpia","agentes de inteligencia artificial","diseño de software","separación de preocupaciones","independencia de frameworks","principio de dependencia","testabilidad de reglas de negocio","estructura de carpetas basada en DDD","desarrollo de software"],"fr":["architecture propre","outils d''intelligence artificielle","conception de logiciels","séparation des préoccupations","indépendance des frameworks","principe de dépendance","testabilité des règles métier","structure de dossiers basée sur DDD","développement de logiciels"],"de":["clean-architecture","KI-Agenten","Software-Design","Trennung von Bedenken","Unabhängigkeit von Frameworks","Abhängigkeitsprinzip","Testbarkeit von Geschäftsregeln","Verzeichnisstruktur basierend auf DDD","Software-Entwicklung"],"pt":["arquitetura limpa","ddd","c#","desenvolvimento de software","padrões de design","manutenção de software","escalabilidade de software","iia agents","ferramentas de ai"],"ru":["чистая архитектура","ddd","c#","разработка программного обеспечения","шаблоны проектирования","поддержка программного обеспечения","масштабируемость программного обеспечения","ии агенты","инструменты ai"],"ar":["هندسة نظيفة","ddd","c#","تطوير البرمجيات","أنماط التصميم","صيانة البرمجيات","توسيع البرمجيات","وكلاء الذكاء الاصطناعي","أدوات الذكاء الاصطناعي"]}},"owner":"dpalfery","repo":"motorcycle-rag-system","repoPath":"dpalfery/motorcycle-rag-system","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.356Z","topics":[],"category":"community","skillMd":{"name":"clean-architecture","description":"Apply when creating, moving, adding, or searching files to maintain the Dependency Rule and separation of concerns across all development activities.","bodyPreview":"# Clean Architecture + DDD Folder Structure (C#)\n\n## **Core Architecture Principles**\n\nBased on Uncle Bob Martin''s Clean Architecture, this structure enforces:\n\n1. **The Dependency Rule**: Source code dependencies can only point inward. Nothing in an inner circle can know anything about an outer circle.\n2. **Independence of Frameworks**: Architecture doesn''t depend on frameworks; frameworks are tools.\n3. **Testability**: Business rules can be tested without UI, Database, or external elements.\n4.","body":"# Clean Architecture + DDD Folder Structure (C#)\n\n## **Core Architecture Principles**\n\nBased on Uncle Bob Martin''s Clean Architecture, this structure enforces:\n\n1. **The Dependency Rule**: Source code dependencies can only point inward. Nothing in an inner circle can know anything about an outer circle.\n2. **Independence of Frameworks**: Architecture doesn''t depend on frameworks; frameworks are tools.\n3. **Testability**: Business rules can be tested without UI, Database, or external elements.\n4. **Independence of UI**: The UI can change without changing business rules.\n5. **Independence of Database**: You can swap databases without affecting business rules.\n6. **Independence of External Agencies**: Business rules don''t know about the outside world.\n\n### **Dependency Direction (Critical)**\n```\nPresentation → Application → Domain ← Persistence\n     ↓              ↓            ↑         ↓\n   Base ←──────────┴────────────┴─────────┘\n```\n\n**Allowed Dependencies:**\n- Presentation → Application, Base\n- Application → Domain, Base\n- Persistence → Domain, Base\n- Domain → Base (minimal, only for shared utilities)\n\n**Forbidden Dependencies:**\n- Domain → Application, Persistence, or Presentation\n- Application → Persistence or Presentation\n- Any layer → outer layer\n\n**Key Rules for Code Generation:**\n\n1. **Always respect the Dependency Rule** - inner layers never depend on outer layers\n2. **Keep domain pure** - no framework code in domain entities\n3. **Use interfaces for boundaries** - Application defines interfaces, Infrastructure implements\n4. **Thin controllers** - only call use cases and map responses\n5. **Rich domain models** - behavior with data, not anemic models\n6. **Test without infrastructure** - domain and application tests need no database\n7. **1 class or interface per file** - no multiple classes in one file\n8. **Single Responsibility Principle** - each class has one job\n9. **Open/Closed Principle** - open for extension, closed for modification\n10. **Liskov Substitution Principle** - derived classes must be substitutable for their base classes\n11. **Interface Segregation Principle** - many client-specific interfaces instead of one general-purpose interface\n12. **Dependency Inversion Principle** - high-level modules shouldn''t depend on low-level ones; both should depend on abstractions\n\n---\n\n## **Quick Reference: Layer Dependencies**\n```\nLayer           | Can Depend On\n----------------|------------------\nPresentation    | Application, Base\nApplication     | Domain, Contracts, Base\nDomain          | Base (minimal)\nContracts       | Domain, Base\nPersistence     | Domain, Contracts, Base\nTests           | Anything (for testing)\n```\n\n**Important Note on Contracts → Domain Dependency:**\nContracts referencing Domain is **CORRECT** in this architecture because:\n- Repository interfaces need to reference Domain entities (e.g., `IRepository<Document>`)\n- Service interfaces need to use Domain value objects and entities in method signatures\n- DTOs in Contracts may need to reference Domain types for proper contract definitions\n- Both projects are conceptually part of the \"Domain Layer\" (3-Domain folder)\n- This follows the Dependency Inversion Principle: Application depends on Contracts (abstractions), Persistence implements them using Domain entities\n\n## **Key Benefits Achieved**\n\n✓ **Framework Independence:** Can swap ASP.NET for another framework\n✓ **Database Independence:** Can swap SQL Server for PostgreSQL, Cosmos DB, etc.\n✓ **UI Independence:** Can add mobile app without changing business logic\n✓ **Testability:** Can test business rules without UI, database, or frameworks\n✓ **Maintainability:** Clear boundaries make changes predictable\n✓ **Azure Migration Friendly:** Can modernize infrastructure without touching domain\n✓ **Vector Store Agnostic:** Can switch between Azure AI Search, Pinecone, Weaviate, etc.\n\n---\n\n*This architecture follows Uncle Bob Martin''s Clean Architecture principles, ensuring that business logic remains independent of frameworks, databases, and delivery mechanisms, resulting in a system that is testable, maintainable, and adaptable to changing requirements.*\n---\n\n## **0-Base Layer (Shared Kernel)**\n\n**Purpose:** Cross-cutting concerns and shared abstractions used across layers. Keep minimal to avoid coupling.\n\n**Project:** `MotorcycleRAG.Core`\n\n**Clean Architecture Alignment:** This is infrastructure for all layers but must not contain business logic or create circular dependencies.\n\n**Contents:**\n\n* **Constants / Enums:** Shared value constants\n  *Folder:* `Constants`, `Enums`\n* **Utilities:** Pure functions with no business logic\n  *Folder:* `Utilities`\n* **Base Exceptions:** Custom exception types\n  *Folder:* `Exceptions`\n* **Result Types:** Success/failure wrappers\n  *Folder:* `Results`\n* **Logging Abstractions:** ILogger interfaces (not implementations)\n  *Folder:* `Abstractions/Logging`\n* **External API Contracts:** Interface definitions only\n  *Folder:* `Abstractions/External`\n\n**⚠️ Warning:** This layer should contain NO implementations that depend on external frameworks (EF Core, Azure SDK, etc.). Only abstractions and pure utilities.\n\n> Minimize dependencies on this layer to prevent tight coupling across your architecture.\n\n---\n\n## **1-Presentation Layer (Frameworks & Drivers)**\n\n**Purpose:** Entry point for external interactions. This is the outermost layer where delivery mechanisms live.\n\n**Projects:** `MotorcycleRAG.Api`, `MotorcycleRAG.UI`, or `MotorcycleRAG.Web`\n\n**Clean Architecture Alignment:** Frameworks and Drivers layer - contains delivery mechanisms (web, API) as details that can be swapped.\n\n**Contents:**\n\n* **Controllers / Endpoints:** ASP.NET Core API controllers or minimal APIs\n  *Folder:* `Controllers`\n* **Hubs:** SignalR hubs for real-time updates\n  *Folder:* `Hubs`\n* **Filters / Middleware:** Exception handling, logging, request validation\n  *Folder:* `Middleware`\n* **ViewModels / DTOs:** Request/response payloads (Interface Adapters)\n  *Folder:* `Models` or `ViewModels`\n* **Mappers:** Convert between external DTOs and Application DTOs\n  *Folder:* `Mappers`\n* **Static Content / Pages:** Razor pages or SPA static assets\n  *Folder:* `wwwroot` or `Pages`\n* **Program.cs / Startup.cs:** Composition root, DI setup, and pipeline config\n\n**Dependencies:** Application, Base\n**Dependency Rule:** ✓ Points inward to Application\n\n> **Key Principle:** Controllers are thin adapters. They receive requests, call Application use cases, and format responses. No business logic here.\n\n---\n\n## **2-Application Layer (Use Cases)**\n\n**Purpose:** Contains application-specific business rules. Orchestrates the flow of data between entities and implements use cases.\n\n**Project:** `MotorcycleRAG.Application`\n\n**Clean Architecture Alignment:** Use Cases layer - implements all application-specific business rules.\n\n**Contents:**\n\n* **Use Cases / Handlers:** CQRS commands and queries implementing business workflows\n  *Folder:* `Features/{FeatureName}/Commands`, `Features/{FeatureName}/Queries`\n  *Example:* `Features/Documents/Commands/IndexDocument/IndexDocumentCommand.cs`\n* **Services:** Application services coordinating between domain and infrastructure\n  *Folder:* `Services`\n* **DTOs:** Input/output models for use cases\n  *Folder:* `DTOs` or within feature folders\n* **Validators:** Input validation (FluentValidation)\n  *Folder:* `Validators` or within feature folders\n* **Authorization:** Application-level policy enforcement\n  *Folder:* `Authorization`\n* **Interfaces:** Abstractions for external dependencies (repositories, external services)\n  *Folder:* `Interfaces`\n* **Events / Notifications:** Application events\n  *Folder:* `Events`\n* **Dependency Injection Extensions:**\n  *File:* `DependencyInjection.cs`\n\n**Dependencies:** Domain, Base\n**Dependency Rule:** ✓ Points inward to Domain\n\n**Critical Rules:**\n- No references to Presentation or Persistence projects\n- No Entity Framework, SQL, HTTP, or framework-specific code\n- All external dependencies accessed through interfaces defined here\n- Orchestrates domain entities but doesn''t contain domain logic\n\n> **Use Case Pattern:** Each use case handles one specific application action (IndexDocument, SearchMotorcycles, RetrieveContext). Use cases call domain entities to execute business rules and use interfaces to persist changes.\n\n---\n\n## **3-Domain Layer (Entities - Core Business Rules)**\n\n**Purpose:** Pure business logic and rules. The heart of the application. Enterprise-wide business rules that could be shared across applications.\n\n**Projects:**\n\n* `MotorcycleRAG.Domain` → Concrete domain models and logic\n* `MotorcycleRAG.Contracts` → Interfaces only (abstractions owned by the domain)\n* `MotorcycleRAG.Contracts.Models` → Shared contract models/DTOs (data shapes) used across boundaries; no infrastructure dependencies\n\n**Clean Architecture Alignment:** Entities layer (innermost circle) - most stable, highest-level policies.\n\n**DTO Placement Rules:**\n* **Presentation DTOs** = API request/response models, UI models (transport).\n* **Application DTOs** = use case request/response (input/output models for use cases).\n* **Domain** = entities/value objects only. If it enforces business rules/invariants, it belongs here.\n* **`MotorcycleRAG.Contracts`** = interfaces only (repositories/services/factories). Never DTOs/models.\n* **`MotorcycleRAG.Contracts.Models`** = shared contract DTOs/models only (no interfaces, no implementations).\n\n### **3a. Domain (Entities)**\n\n**Contents:**\n\n* **Entities:** Aggregate roots with identity\n  *Folder:* `Entities`\n  *Example:* `Document.cs`, `MotorcycleManual.cs`, `VectorChunk.cs`\n  *Rule:* Rich domain models with behavior, not anemic data bags\n* **Value Objects:** Immutable types without identity\n  *Folder:* `ValueObjects`\n  *Example:* `DocumentMetadata.cs`, `Embedding.cs`, `SearchQuery.cs`\n* **Domain Services:** Business rules spanning multiple entities\n  *Folder:* `Services`\n  *Example:* `DocumentChunkingService.cs`\n* **Domain Events:** State change notifications\n  *Folder:* `Events`\n  *Example:* `DocumentIndexedEvent.cs`\n* **Specifications:** Reusable business rules for querying\n  *Folder:* `Specifications`\n* **Factories:** Complex object construction with invariants\n  *Folder:* `Factories`\n* **Exceptions:** Domain-specific exceptions\n  *Folder:* `Exceptions`\n* **Enums:** Domain-specific enums types\n  *Folder:* `Exceptions`\n\n**Dependencies:** Base (minimal - only utilities/enums)\n**Dependency Rule:** ✓ No outward dependencies. Most stable layer.\n\n### **3b. Contracts (Abstractions Owned by Domain)**\n\n**Contents:**\n\n* **Repository Interfaces:** Persistence contracts defined by domain needs\n  *Folder:* `Repositories`\n  *Example:* `IDocumentRepository.cs`, `IVectorStoreRepository.cs`\n* **External Service Interfaces:** Contracts for external dependencies\n  *Folder:* `Services`\n  *Example:* `IEmbeddingService.cs`, `ILlmService.cs`\n* **Factories (Domain Contracts):** Factory abstractions for creating aggregates/value objects while enforcing invariants\n  *Folder:* `Factories`\n  *Example names:* `IDocumentFactory`, `IMotorcycleManualFactory`, `IVectorChunkFactory`\n\n* **Rule:** `MotorcycleRAG.Contracts` contains interfaces only (no DTOs/models)\n\n**Dependencies:** Domain, Base\n\n**Why Contracts → Domain is Correct:**\n- Interfaces must reference Domain entities to define proper contracts\n- Example: `Task<Document> GetDocumentAsync(Guid id)` requires `Document` from Domain\n- Prevents duplicate model definitions between Contracts and Domain\n- Maintains single source of truth for domain entities\n- Both are in 3-Domain layer, conceptually part of the core domain\n\n**Critical Rules:**\n- NO references to any infrastructure concerns (EF Core, Azure, SQL, HTTP, etc.)\n- NO persistence logic - only interfaces defining what domain needs\n- CAN reference Domain entities and value objects for interface definitions\n- All domain logic testable without any infrastructure\n\n> **Key Principle:** If you removed all outer layers (UI, DB, frameworks), your domain layer should still compile and contain all core business rules. This is the \"screaming architecture\" - the domain tells you what the system does.\n\n### **3c. Contracts.Models (Shared contract DTOs/models only)**\n\n**Purpose:** Shared data shapes used across boundaries (API/Application/Persistence) without introducing infrastructure dependencies into the core.\n\n**Project:** `MotorcycleRAG.Contracts.Models`\n\n**Contents:**\n* **DTOs / Models:** Simple data-only shapes for requests/responses between layers\n* **Enums (shared):** Shared enum types required by contract models\n\n**Dependencies:** Domain, Base (minimal)\n\n**Allowed:** Plain C# types (records/classes), nullable annotations, simple enums, Domain value objects/types only when necessary.\n\n**Forbidden (strict):**\n- Interfaces (those belong in `MotorcycleRAG.Contracts`)\n- Implementations (no services, no repositories, no factories)\n- Any infrastructure/framework dependencies (ASP.NET, EF Core, Azure SDKs, SQL clients, etc.)\n- Business logic (domain behavior stays in `MotorcycleRAG.Domain`)\n\n---\n\n## **4-Persistence Layer (Frameworks & Drivers - Data)**\n\n**Purpose:** Implements data storage and retrieval. A detail that can be swapped.\n\n**Project:** `MotorcycleRAG.Persistence`\n\n**Clean Architecture Alignment:** Frameworks and Drivers layer - infrastructure detail.\n\n**Contents:**\n\n* **DbContext:** EF Core database context\n  *Folder:* `Contexts`\n  *File:* `MotorcycleRAGDbContext.cs`\n* **Entity Configurations:** EF Core mappings, relationships, constraints\n  *Folder:* `Configurations`\n  *Example:* `DocumentConfiguration.cs`\n* **Repositories:** Implementation of Domain.Contracts repository interfaces\n  *Folder:* `Repositories`\n  *Rule:* Implement interfaces from Domain.Contracts\n* **Migrations:** Database schema migrations\n  *Folder:* `Migrations`\n* **Seed Data:** Initial data seeding\n  *Folder:* `Seed`\n* **ReadModels / Projections:** Query-optimized models (CQRS read side)\n  *Folder:* `ReadModels`\n* **Vector Store Implementations:** Azure AI Search, Pinecone, etc.\n  *Folder:* `VectorStores`\n* **Dependency Injection Extensions:**\n  *File:* `DependencyInjection.cs`\n\n**Dependencies:** Domain, Contracts, Base\n**Dependency Rule:** ✓ Points inward to Domain\n\n**Critical Rules:**\n- NEVER reference Presentation or Application\n- Implements interfaces defined in Domain.Contracts\n- Contains all SQL, EF Core, vector database, and database-specific code\n- Can be swapped for Dapper, Cosmos DB, or file storage without affecting domain\n\n> **Dependency Inversion:** Domain defines `IDocumentRepository`, Persistence implements it. Application depends on the interface, not the implementation. This allows the database to be swapped without changing business logic.\n\n---\n\n## **5-Test Layer**\n\n**Purpose:** Comprehensive testing at all levels, proving independence of frameworks and testability.\n\n**Projects:**\n\n* `MotorcycleRAG.Domain.Tests` → Unit tests for domain logic\n* `MotorcycleRAG.Application.Tests` → Unit tests for use cases\n* `MotorcycleRAG.Api.Tests` → Integration tests for API endpoints\n* `MotorcycleRAG.IntegrationTests` → Full integration tests with database\n* `MotorcycleRAG.Playwright-UI.Tests` → End-to-end UI tests\n\n**Test Strategy:**\n\n* **Domain Tests (Unit):**\n  - Test entities, value objects, domain services\n  - NO external dependencies (DB, APIs, frameworks)\n  - Fast, isolated, pure logic tests\n  \n* **Application Tests (Unit):**\n  - Test use cases with mocked repositories\n  - Verify orchestration logic\n  - No real database or external services\n  \n* **Integration Tests:**\n  - Test full slices through Application → Domain → Persistence\n  - Use real database (in-memory or TestContainers)\n  - Verify data persistence and retrieval\n  \n* **API Tests:**\n  - Test Controllers → Application integration\n  - Use WebApplicationFactory\n  - Verify HTTP contracts\n  \n* **UI Tests (E2E):**\n  - Full user workflows\n  - Real browser automation\n\n**Contents:**\n\n* **Unit Tests:** Test individual classes in isolation\n* **Test Data Builders:** Fluent builders for test data\n  *Folder:* `Builders`\n* **Fixtures:** Shared test setup\n  *Folder:* `Fixtures`\n* **Mocks/Fakes:** Test doubles for external dependencies\n  *Folder:* `Mocks`\n\n> **Clean Architecture Benefit:** Because business logic is decoupled from infrastructure, you can test most of your system without databases, APIs, or UI frameworks.\n\n---\n\n## **6-Docs**\n\n**Purpose:** Internal documentation, architectural decisions, and design rationale.\n\n* `architecture-general.md` - This file\n* `adr/` - Architecture Decision Records\n* `diagrams/` - System diagrams (C4 model, sequence diagrams)\n* `rag-pipeline.md` - RAG pipeline documentation\n\n---\n\n## **7-Deployment**\n\n**Purpose:** CI/CD scripts, containerization, infrastructure as code.\n\n**Contents:**\n\n* **Docker:**\n  *Folder:* `docker/`\n  *Files:* `Dockerfile`, `docker-compose.yml`\n* **Azure Bicep/Terraform:**\n  *Folder:* `infrastructure/`\n* **CI/CD Pipelines:**\n  *Folder:* `.github/workflows/` or `azure-pipelines.yml`\n* **Scripts:**\n  *Folder:* `scripts/`\n\n**Azure SKU Rule:** When deploying to Azure, use free tier SKUs from the 1-year Azure free account:\n- App Service: F1 (Free)\n- SQL Database: Basic (if needed)\n- Storage: Standard GRS (5 GB free)\n- Azure Functions: Consumption plan\n- Azure AI Search: Free tier\n\n> **Clean Architecture Benefit:** Your deployment choices are details. You can deploy to Azure App Service, Container Apps, AKS, or even AWS without changing your application code.\n\n---\n"},"lastSynced":"2026-03-08T02:04:02.686Z","agentAnalysis":{"suitability":{"en":"Perfect for Multi-Agent Architecture Developers needing modular and testable codebases with Uncle Bob Martin''s Clean Architecture principles.","zh":"适合于需要模块化和可测试代码库的多代理架构开发人员，遵循Bob Martin的Clean Architecture原则。","ja":"Clean Architectureの原則に従ってモジュラーでテスト可能なコードベースを必要とするマルチエージェントアーキテクチャ開発者に最適です。","ko":"Clean Architecture 원칙을 따르는 모듈화되고 테스트 가능한 코드베이스가 필요한 多代理 아키텍처 개발자를 위한 최적의 선택입니다.","es":"Perfecto para desarrolladores de Arquitectura de Multi-Agente que necesitan código modular y verificable con los principios de Clean Architecture de Uncle Bob Martin.","fr":"Parfait pour les développeurs d''Architecture Multi-Agent nécessitant des bases de code modulaires et testables avec les principes de Clean Architecture d''Uncle Bob Martin.","de":"Perfekt für Entwickler von Multi-Agent-Architektur, die modularen und testbaren Codebasen mit den Clean Architecture-Prinzipien von Uncle Bob Martin benötigen.","pt":"Perfeito para Desenvolvedores de Arquitetura de Múltiplos Agentes que necessitam de código modular e testável com os princípios de Arquitetura Limpa do Uncle Bob Martin.","ru":"Идеально подходит для разработчиков архитектуры многоагентных систем, которым необходимы модульный и тестируемый код с принципами чистой архитектуры от Uncle Bob Martin.","ar":"مثالي لمنطقيو هندسة معمارية متعددة الوكلاء الذين يحتاجون إلى قواعد код متوافقة وذات صلاحية اختبار مع مبادئ هندسة بوب مارتن النظيفة."},"recommendation":{"en":"Empowers agents to enforce the Dependency Rule, achieve Independence of Frameworks, and ensure Testability, resulting in robust and maintainable AI-powered systems using frameworks like C# and principles from Domain-Driven Design (DDD).","zh":"赋予代理人执行依赖规则、实现框架独立性和确保可测试性，使用诸如C#和领域驱动设计（DDD）原则的框架，实现强大且可维护的AI系统。","ja":"依存ルールの実施、フレームワークの独立性の実現、テスト可能性の確保をエージェントに可能にし、C#やドメイン駆動設計（DDD）などのフレームワークや原則を使用して、強固で保守可能なAIシステムを実現します。","ko":"의존 규칙의 적용, 프레임워크의 독립성 및 테스트 가능성을 보장하여, C# 및 도메인 주도 설계(DDD)와 같은 프레임워크 및 원칙을 사용하여 강력하고 유지 보수 가능한 AI 시스템을 구축합니다.","es":"Habilita a los agentes para aplicar la Regla de Dependencia, lograr la Independencia de Frameworks y garantizar la Testabilidad, lo que resulta en sistemas de inteligencia artificial robustos y mantenibles que utilizan frameworks como C# y principios de Domain-Driven Design (DDD).","fr":"Permet aux agents d''appliquer la Règle de Dépendance, d''atteindre l''Indépendance des Frameworks et d''assurer la Testabilité, aboutissant à des systèmes d''intelligence artificielle robustes et maintenables utilisant des frameworks comme C# et des principes de Domain-Driven Design (DDD).","de":"Ermöglich es den Agenten, die Abhängigkeitsregel durchzusetzen, die Unabhängigkeit von Frameworks zu erreichen und die Testbarkeit sicherzustellen, was zu robusten und wartbaren künstlich intelligenten Systemen mit Frameworks wie C# und Prinzipien von Domain-Driven Design (DDD) führt.","pt":"Habilita os agentes a impor a Regra de Dependência, alcançar Independência de Frameworks e garantir Testabilidade, resultando em sistemas impulsionados por IA robustos e mantidos usando frameworks como C# e princípios do Domain-Driven Design (DDD).","ru":"Позволяет агентам обеспечивать соблюдение правила зависимости, добиваться независимости от фреймворков и гарантировать тестируемость, в результате чего получаются надежные и поддерживаемые системы на основе ИИ, использующие фреймворки типа C# и принципы Domain-Driven Design (DDD).","ar":"تمكين الوكلاء من فرض قاعدة الاعتماد وتحقيق استقلالية الإطار وضمان اختبار القدرة مما يؤدي إلى أنظمة مدفوعة بالذكاء الاصطناعي قوية وقابلة للصيانة باستخدام الإطارات مثل C# ومبادئ تصميم قائم على النطاق (DDD)."},"useCases":{"en":["Enforcing the Dependency Rule in multi-layered applications","Achieving framework independence for flexible system integration","Improving testability of business rules without UI or database dependencies"],"zh":["在多层应用程序中执行依赖规则","实现框架独立性以实现灵活的系统集成","在不依赖UI或数据库的情况下提高业务规则的可测试性"],"ja":["マルチレイヤーアプリケーションで依存ルールを実施する","フレームワークの独立性を実現してシステム統合の柔軟性を高める","UIやデータベースに依存しない状態でビジネスルールのテスト可能性を高める"],"ko":["다층 애플리케이션에서 의존 규칙을 적용","프레임워크 독립성을 구현하여 시스템 통합의 유연성을 높임","UI 또는 데이터베이스에 의존하지 않고 비즈니스 규칙의 테스트 가능성을 향상"],"es":["Aplicar la Regla de Dependencia en aplicaciones mult capas","Lograr la independencia del framework para una integración de sistema flexible","Mejorar la testabilidad de las reglas de negocio sin dependencias de UI o base de datos"],"fr":["Appliquer la Règle de Dépendance dans des applications multi-couches","Atteindre l''indépendance du framework pour une intégration de système flexible","Améliorer la testabilité des règles métier sans dépendances de l''interface utilisateur ou de base de données"],"de":["Die Abhängigkeitsregel in mehrschichtigen Anwendungen durchsetzen","Die Unabhängigkeit von Frameworks für eine flexible Systemintegration erreichen","Die Testbarkeit von Geschäftsregeln ohne UI- oder Datenbankabhängigkeiten verbessern"],"pt":["Impor a Regra de Dependência em aplicações em camadas múltiplas","Alcançar independência de framework para integração de sistema flexível","Melhorar a testabilidade de regras de negócios sem dependências de UI ou banco de dados"],"ru":["Обеспечение соблюдения правила зависимости в многослойных приложениях","Добиваться независимости от фреймворка для гибкой интеграции системы","Улучшение тестируемости бизнес-правил без зависимостей от UI или базы данных"],"ar":["فرض قاعدة الاعتماد في التطبيقات متعددة الطبقات","تحقيق استقلالية الإطار لتكامل النظام المرن","تحسين اختبار القدرة لقواعد العمل بدون تبعيات واجهة المستخدم أو قاعدة البيانات"]},"limitations":{"en":["Requires adherence to specific architecture principles","May necessitate significant code refactoring for existing projects"],"zh":["需要遵循特定的架构原则","可能需要对现有项目进行大量的代码重构"],"ja":["特定のアーキテクチャ原則に従う必要がある","既存のプロジェクトでは大量のコードリファクタリングが必要になる可能性がある"],"ko":["특정 아키텍처 원칙을 따라야 함","기존 프로젝트의 경우大量의 코드 리팩토링이 필요할 수 있음"],"es":["Requiere la adhesión a principios de arquitectura específicos","Puede necesitar una refactorización significativa del código para proyectos existentes"],"fr":["Nécessite l''adhésion à des principes d''architecture spécifiques","Peut nécessiter une refactoring significative du code pour les projets existants"],"de":["Erfordert die Einhaltung spezifischer Architekturprinzipien","Kann eine erhebliche Neukodierung für bestehende Projekte erfordern"],"pt":["Exige aderência a princípios de arquitetura específicos","Pode necessitar de refatoração de código significativa para projetos existentes"],"ru":["Требует соблюдения конкретных принципов архитектуры","Может потребовать значительной рефакторинга кода для существующих проектов"],"ar":["يتطلب الالتزام بمبادئ هندسة معمارية محددة","يمكن أن يتطلب إعادة هيكلة شاملة للكود لمشاريع موجودة"]},"version":4},"contentHash":"d11bd15d25178b13a5d4ab8bd2288db79049509c0c3bae573edf36e4c0ce60cb","qualityScore":45}');
