INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('antialias/abaci-one/add-tts', 'add-tts', 'antialias', 'abaci-one', 'community', 'add-tts antialias abaci-one community The add-tts skill enables developers to add text-to-speech audio to features in the Abaci.One interactive soroban learning platform, benefiting educators and students alike. Abaci.One 平台的 add-tts 技能允许开发者添加文本转语音音频功能，支持多种音频生成方式 Abaci.One プラットフォームの add-tts スキルは、開発者がテキストを音声に変換する音频機能を追加できるようにします Abaci.One 플랫폼의 add-tts 기능은 개발자가 텍스트를 음성으로 변환하는 오디오 기능을 추가할 수 있게 해줍니다 El skill add-tts permite agregar audio de texto a voz a una característica, utilizando una cadena de voz y generación de mp3 de alta calidad Le skill add-tts permet d''ajouter de l''audio de texte à voix à une fonctionnalité, en utilisant une chaîne de voix et une génération de mp3 de haute qualité Das Skill add-tts ermöglicht die Hinzufügung von Audio von Text zu Sprache zu einer Funktion, indem es eine Voice-Kette und eine Generierung von mp3 in hoher Qualität verwendet O skill add-tts permite adicionar áudio TTS ao seu aplicativo, utilizando uma cadeia de voz que inclui geração de áudio via OpenAI e reprodução via browser SpeechSynthesis Навык add-tts позволяет добавлять аудио TTS в ваше приложение, используя цепочку голоса, которая включает генерацию аудио через ИИ Агентов и воспроизведение через browser SpeechSynthesis المهارة add-tts تمكنك من إضافة صوت TTS إلى تطبيقك، باستخدام سلسلة صوت تشمل генерация الصوت عبر أدوات الذكاء الاصطناعي و تشغيل عبر متصفح SpeechSynthesis how to use add-tts add-tts setup guide text-to-speech audio integration OpenAI TTS mp3 generation add-tts vs Google Text-to-Speech add-tts alternative solutions install add-tts configure voice chains for TTS Abaci.One TTS audio integration AIエージェント TTS 音频 Abaci.One 文本转语音 OpenAI SpeechSynthesis 音频生成 实时生成 预生成 Generates high-quality OpenAI TTS mp3s for audio playback Configures voice chains for seamless audio playback via pregenerated mp3, on-demand generation, or browser SpeechSynthesis Persists audio clips to the database for later use Supports batch generation of TTS mp3s from the admin panel Enables on-the-fly TTS mp3 generation during playback via the generate chain entry Integrates with the Abaci.One interactive soroban learning platform add-tts is a skill that allows developers to integrate text-to-speech audio into their applications using a voice chain and OpenAI TTS mp3 generation');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('reubenjohn/reeve-bot/plan-with-subagents', 'community', 'reubenjohn', 'reeve-bot', 'reubenjohn/reeve-bot', 'plan-with-subagents', 0, 0, 45, '2026-03-08T01:57:15.361Z', '2026-03-08T02:04:13.738Z', 'd46f85de4c82f3c6f3bdfe4a95f80ec259343b2967642ddd27ac0cbade8adf96', '{"id":"reubenjohn/reeve-bot/plan-with-subagents","name":"plan-with-subagents","description":{"en":"The plan-with-subagents skill enables proactive AI automation, filtering noise and managing digital life through scheduled pulses and intelligent sub-agents, benefiting developers and AI enthusiasts.","zh":"计划与子代理技能是一种AI代理技术，通过并行执行、减少上下文和故障隔离来优化您的数字生活","ja":"プランとサブエージェントは、並列実行、コンテキストの削減、障害の分離を通じて、デジタルライフを最適化するAIエージェント技術です","ko":"플랜과 서브 에이전트는 병렬 실행, 컨텍스트 감소, 장애 격리를 통해 디지털 생활을 최적화하는 AI 에이전트 기술입니다","es":"Plan-with-subagents es una habilidad que permite la ejecución paralela y la reducción de contexto mediante el uso de subagentes","fr":"Plan-with-subagents est une compétence qui permet l''exécution parallèle et la réduction du contexte grâce à l''utilisation de sous-agents","de":"Plan-with-subagents ist eine Fähigkeit, die die parallele Ausführung und die Reduzierung des Kontexts durch den Einsatz von Subagenten ermöglicht","pt":"O skill plan-with-subagents permite a execução paralela e reduz o contexto com subagentes baratos e eficazes, melhorando a eficiência da automação inteligente","ru":"Навык планирования с подагентами позволяет выполнять параллельные вычисления и снижать контекст с помощью дешевых и эффективных подагентов, повышая эффективность интеллектуальной автоматизации","ar":"مهارة خطة مع وكلاء فرعيين تسمح بالتنفيذ المتوازي وتقليل السياق باستخدام وكلاء فرعيين رخيصين وفعالين، مما يحسن كفاءة الأتمتة الذكية"},"seo":{"title":{"en":"plan-with-subagents: Proactive AI Automation Setup Guide ...","zh":"计划与子代理技能Setup Guide - AI代理技术","ja":"プランとサブエージェントのベストプラクティス - AIエージェント","ko":"플랜과 서브 에이전트 기능구성 안내 - AI 에이전트 도구","es":"Guía de configuración de plan-with-subagents para Agentes...","fr":"Guide de mise en œuvre de plan-with-subagents pour les Ou...","de":"Einrichtungsleitfaden für plan-with-subagents bei KI-Agenten","pt":"Guia de Configuração do Plan-with-Subagents: Otimização d...","ru":"Настройка Планирования с Подагентами: Руководство по Пара...","ar":"دليل إعداد خطة مع وكلاء فرعيين: تحسين التنفيذ المتوازي"},"description":{"en":"Unlock efficient digital life management with plan-with-subagents. Discover how to automate tasks and filter noise with scheduled pulses and intelligent sub-...","zh":"了解计划与子代理技能的核心原则，包括并行执行、减少上下文和故障隔离，优化您的AI代理开发","ja":"プランとサブエージェントの仕組みを理解し、並列実行、コンテキストの削減、障害の分離を活用してAIエージェント開発を最適化する","ko":"계획과 서브 에이전트의 핵심 원리를 알아보고, 병렬 실행, 컨텍스트 감소, 장애 격리를 통해 AI 에이전트 개발을 최적화하세요","es":"Aprende a utilizar plan-with-subagents para gestionar tu vida digital con programación paralela y automatización inteligente","fr":"Découvrez comment utiliser plan-with-subagents pour gérer votre vie numérique avec une programmation parallèle et une automatisation intelligente","de":"Erfahren Sie, wie Sie plan-with-subagents verwenden können, um Ihr digitales Leben mit paralleler Programmierung und intelligenter Automatisierung zu verwalten","pt":"Aprenda a configurar o skill plan-with-subagents para melhorar a eficiência da execução paralela e reduzir o contexto com subagentes baratos e eficazes","ru":"Узнайте, как настроить навык планирования с подагентами, чтобы повысить эффективность параллельных вычислений и снизить контекст с помощью дешевых и эффектив...","ar":"تعرف على كيفية إعداد مهارة خطة مع وكلاء فرعيين لتحسين كفاءة التنفيذ المتوازي وتقليل السياق باستخدام وكلاء فرعيين رخيصين وفعالين"},"definition":{"en":"plan-with-subagents is a push-paradigm AI assistant that anticipates needs and manages digital life through parallel execution, reduced context, and fault isolation.","zh":"计划与子代理技能是一种AI代理技术，通过子代理的并行执行来管理数字生活","ja":"プランとサブエージェントは、サブエージェントの並列実行を通じて、デジタルライフを管理するAIエージェント技術です","ko":"플랜과 서브 에이전트는 서브 에이전트의 병렬 실행을 통해 디지털 생활을 관리하는 AI 에이전트 기술입니다","es":"Plan-with-subagents es una habilidad de Agentes de IA que permite la planificación y gestión de tareas de manera paralela y eficiente","fr":"Plan-with-subagents est une compétence des Outils d''IA qui permet la planification et la gestion de tâches de manière parallèle et efficace","de":"Plan-with-subagents ist eine Fähigkeit von KI-Agenten, die die Planung und Verwaltung von Aufgaben auf parallele und effiziente Weise ermöglicht","pt":"O plan-with-subagents é um skill que permite a criação de subagentes para execução paralela e redução de contexto","ru":"Планирование с подагентами - это навык, который позволяет создавать подагентов для параллельных вычислений и снижения контекста","ar":"خطة مع وكلاء فرعيين هي مهارة تسمح بإنشاء وكلاء فرعيين للتنفيذ المتوازي وتقليل السياق"},"features":{"en":["Utilizes parallel execution for simultaneous task management","Reduces context for each sub-agent, improving efficiency","Provides fault isolation to prevent single-point failures","Supports scheduled pulses for automated task execution","Enables intelligent automation for proactive digital life management"],"zh":["并行执行","减少上下文","故障隔离","子代理的无限扩展","智能自动化","计划模式下的复杂性管理"],"ja":["並列実行","コンテキストの削減","障害の分離","サブエージェントの無限拡張","インテリジェント自動化","プランモードでの複雑性管理"],"ko":["병렬 실행","컨텍스트 감소","장애 격리","서브 에이전트의 무한 확장","지능형 자동화","계획 모드下的 복잡성 관리"],"es":["Ejecución paralela de tareas","Reducción de contexto mediante subagentes","Aislamiento de errores para evitar bloqueos","Diseño para la minimización del contexto","Automatización inteligente de tareas"],"fr":["Exécution parallèle de tâches","Réduction du contexte grâce aux sous-agents","Isolement des erreurs pour éviter les blocages","Conception pour la minimisation du contexte","Automatisation intelligente de tâches"],"de":["Parallele Ausführung von Aufgaben","Reduzierung des Kontexts durch Subagenten","Fehlerisolation zur Vermeidung von Blockierungen","Entwurf für die Minimierung des Kontexts","Intelligente Automatisierung von Aufgaben"],"pt":["Execução paralela com múltiplos agentes","Redução de contexto com subagentes","Isolamento de falhas com subagentes","Criação de subagentes baratos e eficazes","Otimização da automação inteligente"],"ru":["Параллельные вычисления с множеством агентов","Снижение контекста с помощью подагентов","Изоляция сбоев с помощью подагентов","Создание дешевых и эффективных подагентов","Оптимизация интеллектуальной автоматизации"],"ar":["التنفيذ المتوازي مع وكلاء متعددين","تقليل السياق مع وكلاء فرعيين","عزل الأعطال مع وكلاء فرعيين","إنشاء وكلاء فرعيين رخيصين وفعالين","تحسين الأتمتة الذكية"]},"keywords":{"en":["how to use plan-with-subagents","plan-with-subagents setup guide","proactive AI automation","plan-with-subagents vs traditional automation","plan-with-subagents install","what is plan-with-subagents","plan-with-subagents alternative","intelligent sub-agents","scheduled pulses","digital life management"],"zh":["AI代理技术","计划与子代理技能","并行执行","子代理","智能自动化","计划模式","故障隔离","减少上下文"],"ja":["AIエージェント","プランとサブエージェント","並列実行","サブエージェント","インテリジェント自動化","プランモード","障害の分離","コンテキストの削減"],"ko":["AI 에이전트 도구","플랜과 서브 에이전트","병렬 실행","서브 에이전트","지능형 자동화","계획 모드","장애 격리","컨텍스트 감소"],"es":["Agentes de IA","plan-with-subagents","programación paralela","automatización inteligente","gestión de tareas","subagentes","ejecución paralela","reducción de contexto","aislamiento de errores"],"fr":["Outils d''IA","plan-with-subagents","programmation parallèle","automatisation intelligente","gestion de tâches","sous-agents","exécution parallèle","réduction du contexte","isolement des erreurs"],"de":["KI-Agenten","plan-with-subagents","parallele Programmierung","intelligente Automatisierung","Aufgabenverwaltung","Subagenten","parallele Ausführung","Reduzierung des Kontexts","Fehlerisolation"],"pt":["plan-with-subagents","execução paralela","subagentes","automação inteligente","otimização de processo","desenvolvimento de software","IA","ferramentas de desenvolvimento","_agentes de software"],"ru":["планирование с подагентами","ИИ Агенты","параллельные вычисления","подагенты","интеллектуальная автоматизация","оптимизация процесса","разработка программного обеспечения","ИИ","инструменты разработки","агенты программного обеспечения"],"ar":["خطة مع وكلاء فرعيين","وكلاء ذكاء اصطناعي","التنفيذ المتوازي","وكلاء فرعيين","أتمتة ذكية","تحسين العملية","تطوير البرمجيات","ذكاء اصطناعي","أدوات التطوير","وكلاء البرمجيات"]}},"owner":"reubenjohn","repo":"reeve-bot","repoPath":"reubenjohn/reeve-bot","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.361Z","topics":[],"category":"community","skillMd":{"name":"plan-with-subagents","description":"Plan multi-step implementation tasks to minimize context usage and maximize parallelism. Automatically applies whenever plan mode is active.","bodyPreview":"# Plan with Sub-Agents Skill\n\n**These guidelines apply automatically whenever plan mode is active.** Plan mode implies complexity, so always design for parallelism and minimal context.\n\n## Core Principle: Use Sub-Agents Generously\n\nSub-agents are cheap and effective. When in doubt, spawn an agent. Benefits:\n- **Parallel execution** - Multiple agents work simultaneously\n- **Reduced context** - Each agent only sees what it needs\n- **Fault isolation** - One agent''s failure doesn''t block others\n- **","body":"# Plan with Sub-Agents Skill\n\n**These guidelines apply automatically whenever plan mode is active.** Plan mode implies complexity, so always design for parallelism and minimal context.\n\n## Core Principle: Use Sub-Agents Generously\n\nSub-agents are cheap and effective. When in doubt, spawn an agent. Benefits:\n- **Parallel execution** - Multiple agents work simultaneously\n- **Reduced context** - Each agent only sees what it needs\n- **Fault isolation** - One agent''s failure doesn''t block others\n- **Cleaner commits** - Each agent commits its own work\n\n**Default to spawning agents** for:\n- Any exploration or research (use `Explore` agent)\n- Designing approaches (use `Plan` agent)\n- Independent file modifications (use `general-purpose` agents in parallel)\n- Error-prone steps that involve noisy logs (e.g. running tests)\n- Shell operations (use `Bash` agent)\n\n## When Sub-Agents Apply\n\n- Any task in plan mode (plan mode = complexity assumed)\n- Tasks with 4+ distinct steps\n- Work that touches multiple unrelated files\n- Tasks where exploration and execution can be separated\n- Long-running operations that benefit from parallel execution\n\n## Phase Design Principles\n\n### 1. Break by File Independence\n\nGroup work by which files are touched. Phases that modify **different files** can run in parallel.\n\n```\nPhase A: modifies src/api/server.py, src/api/models.py\nPhase B: modifies tests/test_api.py, tests/conftest.py\nPhase C: modifies README.md, docs/API.md\n→ All three can run in parallel\n```\n\n### 2. Identify Sequential Dependencies\n\nSome phases MUST run in order:\n- Phase that creates a file → Phase that references it\n- Phase that changes API → Phase that updates tests for that API\n- Phase that installs deps → Phase that uses those deps\n\n### 3. Minimize Context per Agent\n\nEach sub-agent should receive ONLY the context it needs:\n- Specific file paths to modify\n- Exact changes to make\n- Commit message to use\n\nAvoid passing full project history or unrelated requirements.\n\n## Agent Type Selection\n\n| Task Type | Agent | Why |\n|-----------|-------|-----|\n| Run shell commands (git, gh, npm) | `Bash` | Direct command execution |\n| Find files/patterns in codebase | `Explore` | Optimized for search |\n| Design implementation approach | `Plan` | Architectural thinking |\n| Write/modify code | `general-purpose` | Full tool access |\n| Research questions | `general-purpose` | Web + file access |\n\n## Execution Prompt Template\n\nWhen spawning sub-agents, use this structure:\n\n```\n**Task:** [One sentence describing the goal]\n\n**Files to modify:**\n- path/to/file1.py - [what to change]\n- path/to/file2.py - [what to change]\n\n**Specific changes:**\n1. [Concrete change 1]\n2. [Concrete change 2]\n\n**Commit when done:**\n\"[type]: [description]\"\n```\n\n## Example Plan Structure\n\n```markdown\n## Phase 0: Setup (sequential)\n- Create directory structure\n→ COMMIT: \"chore: Add project scaffolding\"\n\n## Phase 1: Research (sequential)\n- Explore codebase to understand patterns\n- No commit (exploration only)\n\n## Phases 2, 3, 4 (PARALLEL)\nAgent A - Phase 2: Backend changes\n- Modify src/api/*.py\n→ COMMIT: \"feat: Add new endpoint\"\n\nAgent B - Phase 3: Frontend changes\n- Modify src/ui/*.tsx\n→ COMMIT: \"feat: Add UI component\"\n\nAgent C - Phase 4: Documentation\n- Modify docs/*.md\n→ COMMIT: \"docs: Document new feature\"\n\n## Phase 5: Integration (sequential, after 2-4)\n- Update tests that depend on all changes\n→ COMMIT: \"test: Add integration tests\"\n\n## Phase 6: Validation\n- Run tests, linting, type checks\n→ COMMIT only if fixes needed\n```\n\n## Parallelization Checklist\n\nBefore marking phases as parallel, verify:\n\n- [ ] No shared files between parallel phases\n- [ ] No phase reads output from another parallel phase\n- [ ] Each phase can commit independently\n- [ ] Merge conflicts are impossible\n\n## Anti-Patterns\n\n**Don''t:** Create one giant phase with all changes\n**Do:** Split by logical units that can be tested independently\n\n**Don''t:** Pass entire CLAUDE.md to every sub-agent\n**Do:** Extract only relevant sections for each task\n\n**Don''t:** Have parallel phases commit to the same file\n**Do:** Sequence phases that touch shared files\n\n## Commit Strategy\n\nEach phase should commit its own work immediately when done. This provides:\n- Clear git history\n- Easy rollback if one phase fails\n- Parallel agents don''t block each other\n\nUse conventional commit prefixes:\n- `feat:` - New feature\n- `fix:` - Bug fix\n- `chore:` - Maintenance\n- `docs:` - Documentation\n- `test:` - Tests\n- `refactor:` - Code restructuring\n"},"lastSynced":"2026-03-08T02:04:13.738Z","agentAnalysis":{"suitability":{"en":"Ideal for Autonomous Agents requiring advanced task automation and parallel execution capabilities.","zh":"适合需要高级任务自动化和并行执行能力的自主代理。","ja":"高度なタスクの自動化と並行実行機能を必要とする自律エージェントに最適です。","ko":"고급 태스크 자동화 및 병렬 실행 기능을 필요로 하는 자율 에이전트에 적합합니다.","es":"Ideal para Agentes Autónomos que requieren automatización de tareas avanzada y capacidades de ejecución paralela.","fr":"Idéal pour les Agents Autonomes nécessitant une automatisation de tâches avancée et des capacités d''exécution parallèle.","de":"Ideal für autonome Agenten, die eine erweiterte Aufgabenautomatisierung und parallele Ausführungsfähigkeiten erfordern.","pt":"Ideal para Agentes Autônomos que exigem automação de tarefas avançada e capacidades de execução paralela.","ru":"Идеально для автономных агентов, требующих продвинутой автоматизации задач и возможностей параллельного выполнения.","ar":"مثالي للوكلاء الأوتوماتيكيين الذين يحتاجون إلى توفير تلقائي متقدم وقدرات تنفيذ متوازي."},"recommendation":{"en":"Empowers agents to manage complexity through scheduled pulses and intelligent sub-agents, leveraging parallel execution, reduced context, and fault isolation for robust automation, utilizing protocols like parallelism and minimal context switching.","zh":"通过调度的脉冲和智能子代理，利用并行执行、减少上下文和故障隔离来赋予代理管理复杂性和实现强大的自动化的能力，利用如并行性和最小上下文切换的协议。","ja":"スケジュールされたパルスとインテリジェントなサブエージェントを使用して、並行実行、コンテキストの削減、フォルトアイソレーションを活用し、強力な自動化を実現することで、エージェントが複雑さを管理できるようにします。並行性や最小限のコンテキスト切り替えなどのプロトコルを使用しています。","ko":"예약된 펄스와 지능형 하위 에이전트를 통해 병렬 실행, 컨텍스트 감소, 고장 격리를 활용하여 복잡성을 관리하고 강력한 자동화를 실현하는 에이전트의 능력을 부여함으로써, 병렬성 및 최소한의 컨텍스트 전환과 같은 프로토콜을 사용합니다.","es":"Habilita a los agentes a gestionar la complejidad a través de pulsos programados y subagentes inteligentes, aprovechando la ejecución paralela, el contexto reducido y el aislamiento de fallos para una automatización robusta, utilizando protocolos como el paralelismo y el commutación de contexto mínima.","fr":"Permet aux agents de gérer la complexité grâce à des impulsions planifiées et à des sous-agents intelligents, en exploitant l''exécution parallèle, le contexte réduit et l''isolement des défaillances pour une automatisation robuste, en utilisant des protocoles tels que le parallélisme et la commutation de contexte minimale.","de":"Ermöglicht es den Agenten, die Komplexität durch geplante Impulse und intelligente Subagenten zu verwalten, indem sie die parallele Ausführung, den reduzierten Kontext und die Fehlerisolation für eine robuste Automatisierung nutzen, unter Verwendung von Protokollen wie Parallelerverarbeitung und minimalem Kontextwechsel.","pt":"Habilita os agentes a gerenciar complexidade por meio de pulsos agendados e sub-agentes inteligentes, aproveitando a execução paralela, contexto reduzido e isolamento de falhas para automação robusta, utilizando protocolos como paralelismo e commutação de contexto mínima.","ru":"Наделяет агентов возможностью управлять сложностью посредством запланированных импульсов и интеллектуальных субагентов, используя параллельное выполнение, уменьшенный контекст и изоляцию неисправностей для Надежной автоматизации, используя протоколы, такие как параллелизм и минимальная коммутация контекста.","ar":"يمنح الوكلاء القدرة على إدارة التعقيد من خلال النبضات المجدولة والوكلاء الفرعيين الذكية، واستخدام التنفيذ الموازي والسياق المخفض وعزل الأعطال للتحكم الآلي القوي، باستخدام بروتوكولات مثل التوالى والتبديل الاصغر للسياق."},"useCases":{"en":["Automating complex workflows with multiple sub-agents","Managing digital life through intelligent agent scheduling","Debugging agent failures with fault isolation"],"zh":["使用多个子代理自动化复杂的工作流程","通过智能代理调度管理数字生活","使用故障隔离调试代理故障"],"ja":["複数のサブエージェントを使用して複雑なワークフローを自動化する","インテリジェントなエージェントのスケジューリングを使用してデジタルライフを管理する","フォルトアイソレーションを使用してエージェントの故障をデバッグする"],"ko":["여러 하위 에이전트를 사용하여 복잡한 워크플로우 자동화","지능형 에이전트 스케줄링을 사용하여 디지털 생활 관리","고장 격리를 사용하여 에이전트 고장 디버깅"],"es":["Automatizar flujos de trabajo complejos con múltiples subagentes","Gestionar la vida digital a través de la programación de agentes inteligentes","Depurar fallos de agentes con aislamiento de fallos"],"fr":["Automatiser des flux de travail complexes avec plusieurs sous-agents","Gérer la vie numérique grâce à la planification d''agents intelligents","Déboguer les défaillances d''agents avec une isolation des défaillances"],"de":["Automatisieren komplexer Workflows mit mehreren Subagenten","Verwalten des digitalen Lebens durch intelligente Agentenplanung","Fehler von Agenten mit Fehlerisolation debuggen"],"pt":["Automatizar fluxos de trabalho complexos com vários sub-agentes","Gerenciar a vida digital por meio de programação de agentes inteligentes","Depurar falhas de agentes com isolamento de falhas"],"ru":["Автоматизация сложных рабочих процессов с несколькими субагентами","Управление цифровой жизнью посредством планирования интеллектуальных агентов","Отладка сбоев агентов с изоляцией неисправностей"],"ar":["تحسين سير العمل المعقد مع وكلاء فرعيين متعددين","إدارة الحياة الرقمية من خلال جدولة وكلاء ذكية","تصحيح أعطال الوكلاء مع عزل الأعطال"]},"limitations":{"en":["Requires plan mode activation","Design must account for parallelism and minimal context"],"zh":["需要计划模式激活","设计必须考虑并行性和最小上下文"],"ja":["プランモードのアクティベーションが必要","設計では並行性と最小限のコンテキストを考慮する必要がある"],"ko":["계획 모드 활성화가 필요","설계에서 병렬성과 최소한의 컨텍스트를 고려해야 함"],"es":["Requiere la activación del modo de plan","El diseño debe tener en cuenta el paralelismo y el contexto mínimo"],"fr":["Nécessite l''activation du mode plan","La conception doit tenir compte du parallélisme et du contexte minimal"],"de":["Benötigt die Aktivierung des Planmodus","Das Design muss den Parallelerverarbeitung und den minimalen Kontext berücksichtigen"],"pt":["Exige ativação do modo de plano","O design deve levar em conta o paralelismo e o contexto mínimo"],"ru":["Требует активации режима планирования","Проектирование должно учитывать параллелизм и минимальный контекст"],"ar":["يتطلب تفعيل وضع الخطة","يجب أن يأخذ التصميم في الاعتبار التوالى والسياق الأقل"]},"version":4},"contentHash":"d46f85de4c82f3c6f3bdfe4a95f80ec259343b2967642ddd27ac0cbade8adf96","qualityScore":45}');
