INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('reubenjohn/reeve-bot/plan-with-subagents', 'plan-with-subagents', 'reubenjohn', 'reeve-bot', 'community', 'plan-with-subagents reubenjohn reeve-bot community The plan-with-subagents skill enables proactive AI automation, filtering noise and managing digital life through scheduled pulses and intelligent sub-agents, benefiting developers and AI enthusiasts. 计划与子代理技能是一种AI代理技术，通过并行执行、减少上下文和故障隔离来优化您的数字生活 プランとサブエージェントは、並列実行、コンテキストの削減、障害の分離を通じて、デジタルライフを最適化するAIエージェント技術です 플랜과 서브 에이전트는 병렬 실행, 컨텍스트 감소, 장애 격리를 통해 디지털 생활을 최적화하는 AI 에이전트 기술입니다 Plan-with-subagents es una habilidad que permite la ejecución paralela y la reducción de contexto mediante el uso de subagentes Plan-with-subagents est une compétence qui permet l''exécution parallèle et la réduction du contexte grâce à l''utilisation de sous-agents Plan-with-subagents ist eine Fähigkeit, die die parallele Ausführung und die Reduzierung des Kontexts durch den Einsatz von Subagenten ermöglicht O skill plan-with-subagents permite a execução paralela e reduz o contexto com subagentes baratos e eficazes, melhorando a eficiência da automação inteligente Навык планирования с подагентами позволяет выполнять параллельные вычисления и снижать контекст с помощью дешевых и эффективных подагентов, повышая эффективность интеллектуальной автоматизации مهارة خطة مع وكلاء فرعيين تسمح بالتنفيذ المتوازي وتقليل السياق باستخدام وكلاء فرعيين رخيصين وفعالين، مما يحسن كفاءة الأتمتة الذكية how to use plan-with-subagents plan-with-subagents setup guide proactive AI automation plan-with-subagents vs traditional automation plan-with-subagents install what is plan-with-subagents plan-with-subagents alternative intelligent sub-agents scheduled pulses digital life management AI代理技术 计划与子代理技能 并行执行 子代理 智能自动化 计划模式 故障隔离 减少上下文 Utilizes parallel execution for simultaneous task management Reduces context for each sub-agent, improving efficiency Provides fault isolation to prevent single-point failures Supports scheduled pulses for automated task execution Enables intelligent automation for proactive digital life management plan-with-subagents is a push-paradigm AI assistant that anticipates needs and manages digital life through parallel execution, reduced context, and fault isolation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('yitongcodes/weibo_trends_analyzer_web/weibo-trends-analyzer', 'community', 'yitongcodes', 'weibo_trends_analyzer_web', 'yitongcodes/weibo_trends_analyzer_web', 'weibo-trends-analyzer', 0, 0, 45, '2026-03-08T01:57:15.364Z', '2026-03-08T02:04:18.420Z', '4f09e8e4fba13a21b859d1d9ac559a7db1112e7c9c44bbf62ca32760a840d40f', '{"id":"yitongcodes/weibo_trends_analyzer_web/weibo-trends-analyzer","name":"weibo-trends-analyzer","description":{"en":"The weibo-trends-analyzer skill helps developers identify creative product opportunities from Weibo trending topics, providing real-time hot search data and comprehensive background information.","zh":"Weibo Trends Analyzer 是一个能够分析微博热搜数据并提供创意产品机会的工具，帮助您洞察中国市场的趋势","ja":"Weibo Trends Analyzer は微博のトレンドデータを分析し、創造的な製品アイデアを提供する AI エージェントです","ko":"Weibo Trends Analyzer는 중국 시장의 트렌드를 분석하여 창의적인 제품 아이디어를 제공하는 AI 도구입니다","es":"Weibo Trends Analyzer es una herramienta que analiza temas de tendencia en Weibo y proporciona ideas de productos relacionados","fr":"Weibo Trends Analyzer est un outil qui analyse les sujets tendance sur Weibo et fournit des idées de produits liés","de":"Weibo Trends Analyzer ist ein Tool, das Trends auf Weibo analysiert und relevante Produktideen liefert","pt":"O Weibo Trends Analyzer é uma ferramenta que ajuda a identificar oportunidades de produtos criativos a partir de tópicos em tendência no Weibo, utilizando tecnologias de fetch de dados em tempo real e análise de mercado","ru":"Weibo Trends Analyzer - это инструмент, который помогает выявить творческие возможности продукта из трендов в социальной сети Weibo, используя технологии сбора данных в реальном времени и анализ рынка с помощью ИИ Агенты","ar":"Weibo Trends Analyzer هو أداة تساعد في تحديد فرص المنتجات الإبداعية من المواضيع الشائعة في Weibo، باستخدام تقنيات ال fetch البيانات في الوقت الفعلي وتحليل السوق مع أدوات الإعلام الاجتماعي الإلكتروني"},"seo":{"title":{"en":"weibo-trends-analyzer: Hot Topic Analysis for AI Agents |...","zh":"Weibo Trends Analyzer 设置指南 - 微博热搜创意产品分析","ja":"Weibo Trends Analyzer のベストプラクティス - AIエージェントによる微博トレンド分析","ko":"Weibo Trends Analyzer 설정 가이드 - 중국 시장 트렌드 분석을 위한 AI 도구","es":"Guía de configuración de Weibo Trends Analyzer para desar...","fr":"Guide d''installation de Weibo Trends Analyzer pour les dé...","de":"Einrichtungsleitfaden für Weibo Trends Analyzer-Entwickler","pt":"Guia de Configuração do Weibo Trends Analyzer - Ferrament...","ru":"Настройка Weibo Trends Analyzer - Инструмент для Анализа ...","ar":"دليل إعداد Weibo Trends Analyzer - أداة تحليل الاتجاهات ف..."},"description":{"en":"Unlock Weibo''s trending topics and discover creative product ideas with weibo-trends-analyzer. Get started now and uncover new market opportunities!","zh":"了解 Weibo Trends Analyzer 的功能和特点，掌握微博热搜创意产品分析的技巧，提升您的市场洞察力","ja":"Weibo Trends Analyzer を使用して微博のトレンドを分析し、中国市場の機会を発見しよう","ko":"Weibo Trends Analyzer를 사용하여 중국 시장의 트렌드를 분석하고 창의적인 제품 아이디어를 발굴하세요","es":"Descubre cómo utilizar Weibo Trends Analyzer para identificar oportunidades de productos creativos en el mercado chino","fr":"Découvrez comment utiliser Weibo Trends Analyzer pour identifier des opportunités de produits créatifs sur le marché chinois","de":"Erfahren Sie, wie Sie Weibo Trends Analyzer verwenden, um kreative Produktmöglichkeiten auf dem chinesischen Markt zu finden","pt":"Aprenda a configurar o Weibo Trends Analyzer para identificar oportunidades de produtos criativos a partir de tópicos em tendência no Weibo","ru":"Узнайте, как настроить Weibo Trends Analyzer для выявления творческих возможностей продукта из трендов в социальной сети Weibo с помощью ИИ Агенты","ar":"تعلم كيفية إعداد Weibo Trends Analyzer لتحديد فرص المنتجات الإبداعية من المواضيع الشائعة في Weibo باستخدام أدوات الإعلام الاجتماعي الإلكتروني"},"definition":{"en":"weibo-trends-analyzer is a skill that analyzes Weibo hot topics and provides related product ideas based on trending discussions.","zh":"Weibo Trends Analyzer 是一个微博热搜创意产品分析工具，用于分析微博的热搜数据","ja":"Weibo Trends Analyzer は微博のトレンドデータを分析する AI エージェントです","ko":"Weibo Trends Analyzer는 중국 시장의 트렌드를 분석하는 AI 도구로 微博의 热搜 데이터를 분석합니다","es":"Weibo Trends Analyzer es una herramienta de análisis de tendencias que identifica oportunidades de productos creativos en Weibo","fr":"Weibo Trends Analyzer est un outil d''analyse de tendances qui identifie des opportunités de produits créatifs sur Weibo","de":"Weibo Trends Analyzer ist ein Trendanalyse-Tool, das kreative Produktmöglichkeiten auf Weibo identifiziert","pt":"O Weibo Trends Analyzer é uma ferramenta de análise de tendências que identifica oportunidades de produtos criativos a partir de tópicos em tendência no Weibo","ru":"Weibo Trends Analyzer - это инструмент анализа трендов, который выявляет творческие возможности продукта из трендов в социальной сети Weibo","ar":"Weibo Trends Analyzer هو أداة تحليل الاتجاهات التي تحدد فرص المنتجات الإبداعية من المواضيع الشائعة في Weibo"},"features":{"en":["Fetches real-time hot search data from Weibo","Researches comprehensive background information on trending topics","Evaluates product development potential based on market analysis","Presents findings in an interactive dashboard","Identifies creative product opportunities from social media trends","Provides insights into the Chinese market and consumer discussions"],"zh":["实时抓取微博热搜数据","综合背景信息研究","产品开发潜力评估","交互式仪表盘展示","支持微博热搜创意产品分析"],"ja":["微博のトレンドデータをリアルタイムに取得","包括的な背景情報の調査","製品開発の潜在性を評価","インタラクティブなダッシュボードを表示","微博のトレンド分析をサポート"],"ko":["실시간으로 微博의 热搜 데이터를 수집"," 综合적인 背景 정보를 조사","제품 개발 잠재력을 평가","인터랙티브 대시보드를 표시","微博의 热搜 분석을 지원"],"es":["Análisis de temas de tendencia en Weibo en tiempo real","Investigación de información de fondo comprehensiva","Evaluación del potencial de desarrollo de productos","Presentación de resultados en un panel interactivo","Integración con tecnologías de desarrollo como React y Python"],"fr":["Analyse des sujets tendance sur Weibo en temps réel","Recherche d''informations de fond complètes","Évaluation du potentiel de développement de produits","Présentation des résultats dans un tableau de bord interactif","Intégration avec des technologies de développement comme React et Python"],"de":["Echtzeit-Analyse von Trends auf Weibo","Umfassende Recherche von Hintergrundinformationen","Bewertung des Produktentwicklungs-Potenzials","Präsentation der Ergebnisse in einem interaktiven Dashboard","Integration mit Entwicklungstechnologien wie React und Python"],"pt":["Fetch de dados em tempo real do Weibo","Análise de mercado e tendências","Identificação de oportunidades de produtos criativos","Apresentação de resultados em um painel interativo","Utilização de tecnologias de análise de dados avançadas"],"ru":["Сбор данных в реальном времени из Weibo","Анализ рынка и трендов","Выявление творческих возможностей продукта","Представление результатов в интерактивном панеле","Использование передовых технологий анализа данных с помощью ИИ Агенты"],"ar":["استرجاع البيانات في الوقت الفعلي من Weibo","تحليل السوق والاتجاهات","تحديد فرص المنتجات الإبداعية","عرض النتائج في لوحة تفاعلية","استخدام تقنيات متقدمة لتحليل البيانات مع أدوات الإعلام الاجتماعي الإلكتروني"]},"keywords":{"en":["how to use weibo-trends-analyzer","weibo-trends-analyzer setup guide","weibo trends analysis","weibo hot topic tracker","weibo-trends-analyzer alternative","weibo-trends-analyzer vs social media analytics tools","weibo market research","weibo product ideas","weibo trends api","weibo-trends-analyzer install"],"zh":["微博热搜创意产品分析","Weibo Trends Analyzer","中国市场趋势分析","社交媒体趋势分析","创意产品开发","微博热搜数据分析","AI工具","微博营销"],"ja":["微博のトレンド分析","Weibo Trends Analyzer","中国市場のトレンド分析","ソーシャルメディアのトレンド分析","創造的な製品開発","微博のトレンドデータ分析","AIエージェント","微博マーケティング"],"ko":["微博의 热搜 분석","Weibo Trends Analyzer","중국 시장의 트렌드 분석","소셜미디어의 트렌드 분석","창의적인 제품 개발","微博의 热搜 데이터 분석","AI 도구","微博 마케팅"],"es":["Weibo Trends Analyzer","análisis de tendencias","productos creativos","mercado chino","desarrollo de productos","React","Python","herramientas de desarrollo","análisis de datos","tendencias en redes sociales"],"fr":["Weibo Trends Analyzer","analyse de tendances","produits créatifs","marché chinois","développement de produits","React","Python","outils de développement","analyse de données","tendances sur les réseaux sociaux"],"de":["Weibo Trends Analyzer","Trendanalyse","kreative Produkte","chinesischer Markt","Produktentwicklung","React","Python","Entwicklungstools","Datenanalyse","soziale Medien-Trends"],"pt":["Weibo Trends Analyzer","análise de tendências","oportunidades de produtos criativos","fetch de dados em tempo real","análise de mercado","tecnologias de análise de dados avançadas","desenvolvimento de produtos","mercado chinês"],"ru":["Weibo Trends Analyzer","анализ трендов","творческие возможности продукта","сбор данных в реальном времени","анализ рынка","передовые технологии анализа данных","разработка продукта","китайский рынок","ИИ Агенты"],"ar":["Weibo Trends Analyzer","تحليل الاتجاهات","فرص المنتجات الإبداعية","استرجاع البيانات في الوقت الفعلي","تحليل السوق","تقنيات متقدمة لتحليل البيانات","تطوير المنتجات","السوق الصيني","أدوات الإعلام الاجتماعي الإلكتروني"]}},"owner":"yitongcodes","repo":"weibo_trends_analyzer_web","repoPath":"yitongcodes/weibo_trends_analyzer_web","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.364Z","topics":[],"category":"community","skillMd":{"name":"weibo-trends-analyzer","description":"Analyzes Weibo (微博) trending topics and generates creative product ideas based on hot search keywords. Fetches real-time trending data from Weibo API, researches background information and user insights, evaluates product development potential using a 100-point scoring system, and creates an interactive HTML dashboard. Use when analyzing Chinese social media trends, identifying product opportunities from trending topics, or generating market-driven creative product concepts.","bodyPreview":"# Weibo Trends Analyzer - 微博热搜创意产品分析\n\n## Overview\n\nThis skill helps you identify creative product opportunities from Weibo trending topics. It fetches real-time hot search data, researches comprehensive background information, evaluates product development potential, and presents findings in an interactive dashboard.\n\n**Keywords**: Weibo, 微博, trending topics, hot search, 热搜, product ideas, creative products, market analysis, social media trends, Chinese market\n\n## Workflow\n\n### 1. Fetch Weibo Tr","body":"# Weibo Trends Analyzer - 微博热搜创意产品分析\n\n## Overview\n\nThis skill helps you identify creative product opportunities from Weibo trending topics. It fetches real-time hot search data, researches comprehensive background information, evaluates product development potential, and presents findings in an interactive dashboard.\n\n**Keywords**: Weibo, 微博, trending topics, hot search, 热搜, product ideas, creative products, market analysis, social media trends, Chinese market\n\n## Workflow\n\n### 1. Fetch Weibo Trending Topics\n\n**Default API**: https://apis.tianapi.com/weibohot/index?key=4dfdf794141101d7bb8ece0294dbbc02\n\nWhen the user requests Weibo trending analysis, fetch the current hot search list:\n\n```bash\ncurl -s \"https://apis.tianapi.com/weibohot/index?key=4dfdf794141101d7bb8ece0294dbbc02\"\n```\n\n**API Response Processing**:\n\nThe API returns data in this format:\n```json\n{\n  \"code\": 200,\n  \"msg\": \"success\",\n  \"result\": {\n    \"list\": [\n      {\n        \"hotword\": \"trending keyword\",\n        \"hotwordnum\": \"1234567\",\n        \"hottag\": \"新/热/荐\"\n      }\n    ]\n  }\n}\n```\n\n**Field Mapping**:\n- `hotword` → Trending keyword (热搜关键词)\n- `hotwordnum` → Heat value (热度值), may contain category prefix like \"综艺 587870\"\n- `hottag` → Tag (标签): \"新\"(new), \"热\"(hot), \"荐\"(recommended), or empty\n- Ranking position → Inferred from array index (1-based)\n\n**Parsing Instructions**:\n1. Check if `code == 200` to confirm success\n2. Extract the `result.list` array\n3. For each item in the list:\n   - Rank = array index + 1\n   - Keyword = `hotword`\n   - Heat value = extract numeric value from `hotwordnum` (remove category prefix if present)\n   - Tag = `hottag`\n   - Category = extract from `hotwordnum` prefix if exists (e.g., \"综艺\", \"剧集\", \"盛典\", \"演出\")\n4. Limit analysis to top 10-15 items to manage processing time\n\n**Error Handling**:\n\nIf API fetch fails, follow this fallback strategy:\n\n1. **API Returns Error Code (code ≠ 200)**:\n   - Log the error message from API response\n   - Inform user: \"API returned error: {msg}. Would you like to use mock data instead?\"\n   - Suggest checking API key or quota limits\n   - If user agrees, use `.claude/skills/weibo-trends-analyzer/weibo-mock-data.json`\n\n2. **Network/Connection Failure**:\n   - Inform user: \"Unable to connect to API. Possible network issue.\"\n   - Offer to use mock data: `.claude/skills/weibo-trends-analyzer/weibo-mock-data.json`\n   - Suggest verifying internet connection\n\n3. **Invalid JSON Response**:\n   - Log the response received\n   - Inform user: \"API returned invalid data format\"\n   - Recommend checking if API endpoint has changed\n   - Fall back to mock data if available\n\n4. **Empty or Malformed Data**:\n   - If `result.list` is empty or missing\n   - Inform user: \"No trending topics found in API response\"\n   - Use mock data as fallback\n\n### 2. Deep Research Each Trending Topic\n\nFor EACH trending topic, perform **2 focused web searches** to gather essential background:\n\n**Search Strategy (2 searches per topic)**:\n\n**Search 1: Context & Background**\nCombine social media discussions and news background in one search:\n- Search query examples:\n  - \"{keyword} 微博 新闻背景\"\n  - \"{keyword} 热搜原因 讨论\"\n  - \"{keyword} latest news 用户看法\"\n\nGoal: Understand WHAT the trend is about and WHY it''s trending\n\n**Search 2: User Insights & Market Potential**\nFocus on consumer perspective and product opportunities:\n- Search query examples:\n  - \"{keyword} 用户需求 产品\"\n  - \"{keyword} 消费者痛点\"\n  - \"{keyword} 产品创意 市场\"\n\nGoal: Identify user needs, pain points, and product development opportunities\n\n**Information to Extract**:\nFrom the 2 searches, gather:\n- ✅ Social media sentiment and discussion volume (社交媒体讨论)\n- ✅ News background and event context (新闻背景)\n- ✅ Target demographics and audience size (目标人群)\n- ✅ User pain points and unmet needs (用户痛点)\n- ✅ Existing products or market gaps (市场机会)\n- ✅ Cultural/social significance (文化意义)\n\n**Error Handling for Web Searches**:\n\n1. **Search Returns No Results**:\n   - Log: \"No search results for: {keyword}\"\n   - Mark research as \"Limited data available\"\n   - Proceed with analysis using keyword itself and general market knowledge\n   - Note in dashboard: \"⚠️ 背景研究受限\"\n\n2. **Search Timeout or Failure**:\n   - Retry once with simplified query (just keyword without additional terms)\n   - If retry fails, mark as \"Search unavailable\"\n   - Continue analysis with available data\n   - Note limitation in product analysis\n\n3. **Irrelevant Search Results**:\n   - If results don''t match trending topic context:\n   - Try alternative search query with different keywords\n   - Use general industry knowledge for analysis\n   - Document: \"Based on general market analysis\"\n\n4. **Partial Search Success (1 of 2 succeeds)**:\n   - Proceed with available search data\n   - Note which aspect is missing (context vs. user insights)\n   - Make conservative estimates for missing information\n   - Mark in dashboard with: \"⚠️ 部分数据\"\n\n### 3. AI-Powered Product Ideation & Scoring\n\nFor each trending topic, analyze and generate creative product ideas using this scoring framework:\n\n**Scoring System (Total: 100 Points)**\n\n1. **Product Development Potential (可发展度)**: 40 points\n   - Market size and scalability (15 points)\n   - Technical feasibility (10 points)\n   - Trend longevity vs. fleeting fad (10 points)\n   - Competitive landscape (5 points)\n\n2. **Interest Level (有趣度)**: 20 points\n   - Creative uniqueness (10 points)\n   - Emotional appeal (5 points)\n   - Share-ability/viral potential (5 points)\n\n3. **Practical Life Utility (生活有用度)**: 20 points\n   - Daily life integration (10 points)\n   - Problem-solving capability (5 points)\n   - Target audience size (5 points)\n\n4. **Small-Scale Production Ease (小规模生产容易程度)**: 20 points\n   - Manufacturing complexity (10 points)\n   - Material accessibility (5 points)\n   - Cost efficiency for small batches (5 points)\n\n**Product Concept Requirements**:\n\nFor each trend, generate 1-3 creative product concepts including:\n\n- **Market Category (市场赛道)**: Which product category (e.g., home decor, fashion accessories, stationery, tech gadgets, lifestyle products, toys, etc.)\n- **Product Name (产品名称)**: Catchy, memorable name\n- **Target Audience (销售对象人群)**: Specific demographic (age, interests, income level, lifestyle)\n- **Manufacturing Characteristics (工厂批量生产特点)**:\n  - Production method (e.g., 3D printing, injection molding, screen printing, laser cutting)\n  - Material requirements\n  - Minimum order quantity (MOQ) feasibility\n  - Lead time estimates\n  - Cost structure (per unit at different volumes)\n- **Detailed Description (详细描述)**: How the product relates to the trending topic\n- **Total Score (总分)**: Sum of all four scoring dimensions\n- **Score Breakdown (评分分析)**: Brief justification for each score component\n\n**Scoring Guidelines**:\n- Be objective and realistic\n- Consider Chinese market context\n- Factor in current manufacturing capabilities\n- Account for trend cycle timing\n\n### 4. Generate Interactive HTML Dashboard\n\nCreate a comprehensive, visually appealing HTML dashboard with the following structure:\n\n**Dashboard Components**:\n\n**A. Header Section**\n```html\n- Title: \"微博热搜创意产品分析报告 - Weibo Trends Product Analysis\"\n- Generation timestamp\n- Total trends analyzed count\n- Summary statistics (average score, top categories, etc.)\n```\n\n**B. Highlight Section - Top Performers**\nDisplay products by score tiers:\n\n- **🏆 Outstanding (优秀) - Score ≥ 80**:\n  - Prominent display with gold/premium styling\n  - Enlarged cards with detailed breakdown\n  - Recommended action: \"优先开发推荐\"\n\n- **⭐ Good (良好) - Score 60-79**:\n  - Standard card layout with highlighted borders\n  - Recommended action: \"可考虑开发\"\n\n- **📋 Other Products - Score < 60**:\n  - Compact list view\n  - Recommended action: \"观望或需优化\"\n\n**C. Product Cards**\n\nEach product card should display:\n```html\n<div class=\"product-card score-tier-{excellent/good/other}\">\n  <div class=\"trend-info\">\n    <h3>{Trending Keyword}</h3>\n    <span class=\"rank\">热搜排名: #{rank}</span>\n    <span class=\"heat\">热度: {heat_value}</span>\n  </div>\n\n  <div class=\"product-concept\">\n    <h4>{Product Name}</h4>\n    <div class=\"total-score\">{Total Score}/100</div>\n    <div class=\"score-badge\">{优秀/良好/其他}</div>\n\n    <div class=\"details\">\n      <p><strong>市场赛道:</strong> {market_category}</p>\n      <p><strong>目标人群:</strong> {target_audience}</p>\n      <p><strong>产品描述:</strong> {description}</p>\n      <p><strong>生产特点:</strong> {manufacturing_details}</p>\n    </div>\n\n    <div class=\"score-breakdown\">\n      <h5>评分详情</h5>\n      <div class=\"score-bar\">\n        <span>可发展度</span>\n        <progress value=\"{score}\" max=\"40\"></progress>\n        <span>{score}/40</span>\n      </div>\n      <div class=\"score-bar\">\n        <span>有趣度</span>\n        <progress value=\"{score}\" max=\"20\"></progress>\n        <span>{score}/20</span>\n      </div>\n      <div class=\"score-bar\">\n        <span>生活有用度</span>\n        <progress value=\"{score}\" max=\"20\"></progress>\n        <span>{score}/20</span>\n      </div>\n      <div class=\"score-bar\">\n        <span>生产容易度</span>\n        <progress value=\"{score}\" max=\"20\"></progress>\n        <span>{score}/20</span>\n      </div>\n    </div>\n\n    <div class=\"analysis\">\n      <h5>分数分析</h5>\n      <p>{score_justification}</p>\n    </div>\n  </div>\n\n  <div class=\"research-summary\">\n    <h5>背景研究</h5>\n    <ul>\n      <li><strong>社交媒体:</strong> {social_media_insights}</li>\n      <li><strong>新闻背景:</strong> {news_background}</li>\n      <li><strong>用户洞察:</strong> {user_insights}</li>\n    </ul>\n  </div>\n</div>\n```\n\n**D. Dashboard Styling Requirements**\n\n```css\n/* Color Scheme */\n- Excellent products (≥80): Gold/amber theme (#FFD700, #FFA500)\n- Good products (60-79): Blue/cyan theme (#4A90E2, #50C8E8)\n- Other products (<60): Gray/neutral theme (#95A5A6, #BDC3C7)\n\n/* Design Guidelines */\n- Responsive layout (grid or flexbox)\n- Clean, modern aesthetics\n- Clear visual hierarchy\n- Easy-to-read typography (Chinese + English support)\n- Interactive hover effects\n- Sortable/filterable options\n- Progress bars for score visualization\n- Badge system for quick identification\n```\n\n**E. Interactive Features**\n\nInclude JavaScript for:\n- Sort by score (highest to lowest, lowest to highest)\n- Filter by score tier (优秀/良好/其他)\n- Filter by market category\n- Search functionality for keywords\n- Expandable/collapsible detailed sections\n- Export to PDF option (bonus)\n\n**F. Footer Section**\n```html\n- Disclaimer about trend volatility\n- Recommendation to conduct further market research\n- Generation metadata (API source, analysis timestamp)\n- Skill version information\n```\n\n### 5. File Output\n\nGenerate the following files:\n\n1. **`weibo-trends-analysis-{YYYY-MM-DD}.html`**: Complete interactive dashboard\n2. **`weibo-trends-data-{YYYY-MM-DD}.json`**: Raw structured data for further processing (optional)\n\n**Error Handling for File Generation**:\n\n1. **File Write Permission Denied**:\n   - Try alternative filename with timestamp: `weibo-trends-analysis-{YYYY-MM-DD-HHmmss}.html`\n   - If still fails, inform user: \"Unable to write files. Please check directory permissions.\"\n   - Suggest user-provided output path\n\n2. **HTML Generation Error**:\n   - If template rendering fails, create simplified HTML version with basic table layout\n   - Ensure at minimum: product names, scores, and basic descriptions are included\n   - Log error details for troubleshooting\n\n3. **Data Validation Before Output**:\n   - Verify at least 1 product concept was generated\n   - Check all scores are within valid ranges (0-40, 0-20, etc.)\n   - Ensure required fields are present (product name, score, description)\n   - If validation fails, inform user which topics had issues\n\n4. **Large File Handling**:\n   - If analyzing >20 topics, warn user about large file size\n   - Consider generating paginated HTML or summary + detailed sections\n   - Ensure browser compatibility for large datasets\n\n## Best Practices\n\n**Research Quality**:\n- Perform 2 focused web searches per trending topic (optimized for efficiency)\n- Synthesize information from multiple sources within each search\n- Verify factual accuracy\n- Note information freshness\n- Prioritize quality over quantity in search results\n\n**Product Ideation**:\n- Think beyond obvious connections\n- Consider cultural context and Chinese consumer behavior\n- Evaluate both short-term trend exploitation and long-term product viability\n- Be creative but realistic\n\n**Scoring Objectivity**:\n- Use consistent criteria across all products\n- Justify scores with specific evidence\n- Avoid bias toward certain product categories\n- Consider manufacturing realities in China\n\n**Dashboard Quality**:\n- Ensure all Chinese characters display correctly (UTF-8 encoding)\n- Test responsiveness on different screen sizes\n- Validate HTML/CSS/JS syntax\n- Include fallback fonts for Chinese text\n- Make data visualizations clear and intuitive\n\n## Example Usage Flow\n\n```\nUser: \"分析微博热搜\"\n或\nUser: \"分析今日微博热搜并生成产品创意\"\n\nClaude:\n1. Fetches trending data from default API (https://apis.tianapi.com/weibohot/index?key=...)\n   - If API fails, offers to use mock data\n2. Parses the result.list array and extracts top 10-15 trending topics\n3. For each topic:\n   - Performs 2 focused web searches for background research\n   - Handles search failures gracefully with fallback strategies\n   - Analyzes market potential and user needs\n   - Generates creative product concepts\n   - Calculates detailed scores\n4. Validates all generated data\n5. Compiles all data into structured format\n6. Generates interactive HTML dashboard with error indicators if needed\n7. Saves output files\n\nOutput:\n- weibo-trends-analysis-2026-01-11.html\n- weibo-trends-data-2026-01-11.json (optional)\n```\n\n## Limitations and Considerations\n\n**API Dependencies**:\n- Requires valid Weibo API endpoint provided by user\n- API rate limits may affect number of trends that can be analyzed\n- API response format may vary - adapt parsing as needed\n\n**Web Search Constraints**:\n- Search results quality depends on keyword specificity\n- Chinese language content may require specific search strategies\n- Information recency is critical for trend analysis\n\n**Scoring Subjectivity**:\n- Despite structured framework, some scoring involves judgment\n- Market conditions change rapidly\n- Manufacturing feasibility requires domain expertise validation\n\n**Dashboard Limitations**:\n- Static HTML file (not a live web application)\n- Requires modern browser for best experience\n- Large datasets (>50 products) may impact page performance\n\n## Technical Requirements\n\n**Tools Available**:\n- Bash: For API calls using curl\n- WebSearch: For researching trending topics (REQUIRED)\n- Write: For generating HTML and JSON output files\n\n**Dependencies**:\n- No external libraries required for basic functionality\n- Modern web browser for viewing dashboard\n- Internet connection for API and web searches\n\n## Quality Checklist\n\nBefore finalizing output, verify:\n- [ ] All trending topics have been researched (2 focused searches each)\n- [ ] Search failures handled gracefully with appropriate fallbacks\n- [ ] Every product concept includes all required fields\n- [ ] Scores are calculated correctly and sum to totals\n- [ ] Data limitations marked clearly (⚠️ indicators where applicable)\n- [ ] HTML renders correctly with proper UTF-8 encoding\n- [ ] Chinese characters display properly\n- [ ] Interactive features (sort, filter, search) work\n- [ ] Styling differentiates score tiers clearly\n- [ ] All links and references are functional\n- [ ] Dashboard is responsive on different screen sizes\n- [ ] Data accuracy has been verified\n\n## Advanced Features (Optional)\n\nIf time and context allow, consider adding:\n\n**Trend Tracking**:\n- Compare with previous analyses to identify rising/falling trends\n- Track keyword position changes over time\n- Identify recurring themes or patterns\n\n**Competitive Analysis**:\n- Check for existing similar products on Taobao/Tmall/JD\n- Analyze pricing strategies\n- Identify market gaps\n\n**Visual Enhancements**:\n- Charts and graphs for score distributions\n- Trend heat maps\n- Category breakdowns (pie charts)\n- Timeline visualizations\n\n**Export Options**:\n- CSV export for spreadsheet analysis\n- PDF generation for presentations\n- API-ready JSON for integration with other systems\n\n## Version History\n\n- v1.2 (2026-01-17): Error handling & performance optimization\n  - Comprehensive error handling for API, web searches, and file generation\n  - Optimized web searches from 3-5 to 2 focused searches per topic\n  - Improved reliability with graceful fallbacks\n  - 33-40% faster processing time\n- v1.1 (2026-01-11): API integration with TianAPI\n  - Built-in Weibo trending API\n  - Updated data parsing for real API format\n- v1.0 (2026-01-11): Initial skill creation\n  - Core workflow: API fetch → Research → Scoring → Dashboard\n  - 100-point scoring system\n  - Interactive HTML dashboard with tier-based highlighting\n\n## References and Resources\n\n**Weibo Trending Data**:\n- Official Weibo Hot Search: https://s.weibo.com/top/summary\n- Alternative APIs may provide different data structures\n\n**Product Development Resources**:\n- Alibaba 1688: For manufacturing partner research\n- Taobao/Tmall: For market research and competitive analysis\n- Pinduoduo: For trending product categories\n\n**Design Inspiration**:\n- Product Hunt: For creative product naming and positioning\n- Xiaohongshu (小红书): For lifestyle product trends\n- Douyin (抖音): For viral product concepts\n\n## Support and Troubleshooting\n\n**Common Issues**:\n\n1. **API Returns Empty Data**:\n   - Verify API endpoint is correct and accessible\n   - Check API authentication if required\n   - Try alternative Weibo trending API sources\n\n2. **Web Search Not Finding Relevant Information**:\n   - Refine search queries to be more specific\n   - Try different keyword combinations (Chinese + English)\n   - Use site-specific searches (site:weibo.com, site:baidu.com)\n\n3. **HTML Dashboard Not Displaying Correctly**:\n   - Ensure file uses UTF-8 encoding\n   - Check for JavaScript errors in browser console\n   - Verify all HTML tags are properly closed\n\n4. **Scores Seem Inconsistent**:\n   - Review scoring guidelines in Section 3\n   - Ensure all criteria are evaluated objectively\n   - Document reasoning for borderline scores\n\n**Getting Help**:\n- Review official Claude Code skills documentation\n- Check example skills for similar patterns\n- Validate JSON data structure before generating HTML\n\n---\n\n**License**: MIT License - Free to use and modify\n**Author**: Claude Code Skills Framework\n**Last Updated**: 2026-01-17\n**Version**: 1.2"},"lastSynced":"2026-03-08T02:04:18.420Z","agentAnalysis":{"suitability":{"en":"Perfect for Social Media Analysis Agents needing real-time Chinese market trend insights from Weibo.","zh":"非常适合需要从微博获取实时中文市场趋势洞察的社交媒体分析代理","ja":"Weiboからのリアルタイム中国市場トレンドのインサイトが必要なソーシャルメディア分析エージェントに最適","ko":"웨이보에서 실시간 중국 시장 트렌드 인사이트가 필요한 소셜 미디어 분석 에이전트에게 완벽한 솔루션","es":"Perfecto para agentes de Análisis de Medios Sociales que necesitan información sobre tendencias del mercado chino en tiempo real de Weibo.","fr":"Parfait pour les agents d''analyse des médias sociaux ayant besoin d''informations sur les tendances du marché chinois en temps réel provenant de Weibo.","de":"Perfekt für Social Media Analyse-Agenten, die Echtzeit-Einblicke in den chinesischen Markttrend von Weibo benötigen.","pt":"Perfeito para Agentes de Análise de Mídia Social que necessitam de informações em tempo real sobre tendências do mercado chinês do Weibo.","ru":"Идеально подходит для агентов анализа социальных сетей, которым необходимы данные о тенденциях китайского рынка в режиме реального времени из Weibo.","ar":"مثالي لعميل تحليل وسائل الإعلام الاجتماعية الذين يحتاجون إلى رؤى سوقية صينية في الوقت الفعلي من Weibo."},"recommendation":{"en":"Empowers agents to identify creative product opportunities from Weibo trending topics, providing real-time hot search data and comprehensive background information using natural language processing and data visualization techniques.","zh":"能够让代理识别微博热门话题中的创意产品机会，提供实时热搜数据和使用自然语言处理和数据可视化技术的综合背景信息","ja":"エージェントがWeiboのトレンドトピックから創造的な製品の機会を特定できるようにし、リアルタイムのホット検索データと自然言語処理およびデータ視覚化技術を使用した包括的な背景情報を提供する","ko":"에이전트가 웨이보의 트렌드 토픽에서 창의적인 제품 기회를 식별할 수 있도록 하며, 실시간 핫 검색 데이터와 자연어 처리 및 데이터 시각화 기술을 사용한 종합적인 배경 정보를 제공한다","es":"Habilita a los agentes para identificar oportunidades creativas de productos a partir de temas de tendencia de Weibo, proporcionando datos de búsqueda en tiempo real y información de fondo completa utilizando técnicas de procesamiento de lenguaje natural y visualización de datos.","fr":"Permet aux agents d''identifier des opportunités de produits créatifs à partir des sujets tendance de Weibo, en fournissant des données de recherche en temps réel et des informations de fond complètes en utilisant des techniques de traitement du langage naturel et de visualisation de données.","de":"Ermächtigt Agenten, kreative Produktmöglichkeiten aus Weibo-Trends zu identifizieren und bietet Echtzeit-Suchdaten und umfassende Hintergrundinformationen unter Verwendung von Techniken für natürliche Sprachverarbeitung und Datenvisualisierung.","pt":"Habilita os agentes a identificar oportunidades criativas de produtos a partir de tópicos em tendência do Weibo, fornecendo dados de busca quente em tempo real e informações de fundo abrangentes usando técnicas de processamento de linguagem natural e visualização de dados.","ru":"Наделяет агентов возможностью выявлять творческие возможности продукта из тем, которые сейчас популярны в Weibo, обеспечивая данные о горячей поисковой системе в режиме реального времени и полную информацию о фоне с помощью методов обработки естественного языка и визуализации данных.","ar":"يمنح الوكلاء القدرة على تحديد فرص منتجات إبداعية من المواضيع الشائعة في Weibo ، مع توفير بيانات البحث الساخن في الوقت الفعلي والمعلومات الشاملة للخلفية باستخدام تقنيات معالجة اللغة الطبيعية وتصور البيانات."},"useCases":{"en":["Analyzing Weibo hot search data for market trend insights","Generating interactive dashboards for product development potential evaluation","Researching comprehensive background information on trending topics for product ideas"],"zh":["分析微博热搜数据以获取市场趋势洞察","生成交互式仪表板以评估产品开发潜力","研究热门话题的综合背景信息以获取产品创意"],"ja":["Weiboのホット検索データを分析して市場トレンドの洞察を得る","製品開発の潜在能力を評価するためのインタラクティブなダッシュボードを生成する","トレンドトピックの包括的な背景情報を調査して製品のアイデアを得る"],"ko":["웨이보의 핫 검색 데이터를 분석하여 시장 트렌드 인사이트를 얻는 것","제품 개발 잠재력을 평가하기 위한 인터랙티브 대시보드를 생성하는 것","트렌드 토픽의 종합적인 배경 정보를 조사하여 제품 아이디어를 얻는 것"],"es":["Análisis de datos de búsqueda en tiempo real de Weibo para obtener información sobre tendencias del mercado","Generación de paneles interactivos para la evaluación del potencial de desarrollo de productos","Investigación de información de fondo completa sobre temas de tendencia para obtener ideas de productos"],"fr":["Analyse des données de recherche en temps réel de Weibo pour obtenir des informations sur les tendances du marché","Génération de tableaux de bord interactifs pour l''évaluation du potentiel de développement de produits","Recherche d''informations de fond complètes sur les sujets tendance pour obtenir des idées de produits"],"de":["Analyse von Weibo-Echtzeit-Suchdaten für Markttrend-Einblicke","Erzeugung interaktiver Dashboards für die Bewertung des Produktentwicklungs-Potenzials","Recherche umfassender Hintergrundinformationen zu Trends für Produktideen"],"pt":["Analisar dados de busca quente do Weibo para obter informações sobre tendências do mercado","Gerar painéis interativos para avaliação do potencial de desenvolvimento de produtos","Pesquisar informações de fundo abrangentes sobre tópicos em tendência para ideias de produtos"],"ru":["Анализ данных о горячей поисковой системе Weibo для получения информации о тенденциях рынка","Генерирование интерактивных панелей для оценки потенциала разработки продукта","Изучение полной информации о фоне популярных тем для идей продукта"],"ar":["تحليل بيانات البحث الساخن من Weibo للحصول على رؤى سوقية","توليد لوحات تفاعلية لتقييم إمكانات تطوير المنتجات","البحث عن معلومات شاملة للخلفية حول المواضيع الشائعة لأفكار المنتجات"]},"limitations":{"en":["Requires access to Weibo API or data feeds","Limited to Chinese market trends and Weibo platform","Needs data visualization capabilities for interactive dashboard presentation"],"zh":["需要访问Weibo API或数据源","仅限于中国市场趋势和微博平台","需要数据可视化能力以呈现交互式仪表板"],"ja":["Weibo APIまたはデータフィードへのアクセスが必要","中国市場トレンドとWeiboプラットフォームのみに限定される","インタラクティブなダッシュボードの表示にはデータ視覚化機能が必要"],"ko":["웨이보 API 또는 데이터 피드에 접근할 수 있어야 함","중국 시장 트렌드와 웨이보 플랫폼에만 제한됨","인터랙티브 대시보드를 표시하기 위해 데이터 시각화 기능이 필요함"],"es":["Requiere acceso a la API de Weibo o fuentes de datos","Limitado a las tendencias del mercado chino y la plataforma Weibo","Necesita capacidades de visualización de datos para la presentación del panel interactivo"],"fr":["Nécessite un accès à l''API de Weibo ou à des flux de données","Limité aux tendances du marché chinois et à la plate-forme Weibo","Nécessite des capacités de visualisation de données pour la présentation du tableau de bord interactif"],"de":["Erfordert Zugriff auf die Weibo-API oder Datenfeeds","Begrenzt auf chinesische Markttrends und die Weibo-Plattform","Benötigt Datenvisualisierungsfähigkeiten für die interaktive Dashboard-Präsentation"],"pt":["Requer acesso à API do Weibo ou feeds de dados","Limitado a tendências do mercado chinês e plataforma Weibo","Necessita de capacidades de visualização de dados para apresentação de painéis interativos"],"ru":["Требуется доступ к API Weibo или потокам данных","Ограничен тенденциями китайского рынка и платформой Weibo","Требует возможностей визуализации данных для представления интерактивных панелей"],"ar":["يتطلب الوصول إلى واجهة برمجة تطبيقات Weibo أو تدفقات البيانات","محدود بالاتجاهات السوقية الصينية ومنصة Weibo","يحتاج إلى إمكانات تصور البيانات لعرض اللوحات التفاعلية"]},"version":4},"contentHash":"4f09e8e4fba13a21b859d1d9ac559a7db1112e7c9c44bbf62ca32760a840d40f","qualityScore":45}');
