INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('yitongcodes/weibo_trends_analyzer_web/weibo-trends-analyzer', 'weibo-trends-analyzer', 'yitongcodes', 'weibo_trends_analyzer_web', 'community', 'weibo-trends-analyzer yitongcodes weibo_trends_analyzer_web community The weibo-trends-analyzer skill helps developers identify creative product opportunities from Weibo trending topics, providing real-time hot search data and comprehensive background information. Weibo Trends Analyzer 是一个能够分析微博热搜数据并提供创意产品机会的工具，帮助您洞察中国市场的趋势 Weibo Trends Analyzer は微博のトレンドデータを分析し、創造的な製品アイデアを提供する AI エージェントです Weibo Trends Analyzer는 중국 시장의 트렌드를 분석하여 창의적인 제품 아이디어를 제공하는 AI 도구입니다 Weibo Trends Analyzer es una herramienta que analiza temas de tendencia en Weibo y proporciona ideas de productos relacionados Weibo Trends Analyzer est un outil qui analyse les sujets tendance sur Weibo et fournit des idées de produits liés Weibo Trends Analyzer ist ein Tool, das Trends auf Weibo analysiert und relevante Produktideen liefert O Weibo Trends Analyzer é uma ferramenta que ajuda a identificar oportunidades de produtos criativos a partir de tópicos em tendência no Weibo, utilizando tecnologias de fetch de dados em tempo real e análise de mercado Weibo Trends Analyzer - это инструмент, который помогает выявить творческие возможности продукта из трендов в социальной сети Weibo, используя технологии сбора данных в реальном времени и анализ рынка с помощью ИИ Агенты Weibo Trends Analyzer هو أداة تساعد في تحديد فرص المنتجات الإبداعية من المواضيع الشائعة في Weibo، باستخدام تقنيات ال fetch البيانات في الوقت الفعلي وتحليل السوق مع أدوات الإعلام الاجتماعي الإلكتروني how to use weibo-trends-analyzer weibo-trends-analyzer setup guide weibo trends analysis weibo hot topic tracker weibo-trends-analyzer alternative weibo-trends-analyzer vs social media analytics tools weibo market research weibo product ideas weibo trends api weibo-trends-analyzer install 微博热搜创意产品分析 Weibo Trends Analyzer 中国市场趋势分析 社交媒体趋势分析 创意产品开发 微博热搜数据分析 AI工具 微博营销 Fetches real-time hot search data from Weibo Researches comprehensive background information on trending topics Evaluates product development potential based on market analysis Presents findings in an interactive dashboard Identifies creative product opportunities from social media trends Provides insights into the Chinese market and consumer discussions weibo-trends-analyzer is a skill that analyzes Weibo hot topics and provides related product ideas based on trending discussions.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('DarkMonkDev/WitchCityRope/single-source-validator', 'community', 'DarkMonkDev', 'WitchCityRope', 'DarkMonkDev/WitchCityRope', 'single-source-validator', 0, 0, 45, '2026-03-08T01:57:15.364Z', '2026-03-08T02:04:18.574Z', '2bffed89058f71cec7df66ef9924052be7633d9b3b9907094e2c069aba03c164', '{"id":"DarkMonkDev/WitchCityRope/single-source-validator","name":"single-source-validator","description":{"en":"The single-source-validator skill enforces a single source of truth for Skills, preventing duplication and ensuring Phase 5 validation success. It benefits AI agent developers by providing a critical enforcement mechanism.","zh":"Single Source Validator 是一个确保 AI 代理技能单一来源的工具，防止重复和错误","ja":"Single Source Validator は、AI エージェントのスキルが単一の情報源となることを保証するツールで、重複とエラーを防ぎます","ko":"Single Source Validator 는 AI 에이전트의 스킬이 단일 정보원을 보장하는 도구로 중복과 오류를 방지합니다","es":"El validador de fuente única es una habilidad que garantiza la integridad de tus Agentes de IA, evitando la duplicación de habilidades y asegurando la consistencia de los datos.","fr":"Le validateur de source unique est une compétence qui garantit l''intégrité de vos Outils d''IA, en évitant la duplication des compétences et en assurant la cohérence des données.","de":"Der Single-Source-Validator ist eine Fähigkeit, die die Integrität Ihrer KI-Agents sicherstellt, indem sie die Duplizierung von Fähigkeiten vermeidet und die Konsistenz der Daten gewährleistet.","pt":"O validador de origem única é uma habilidade crítica para garantir a integridade dos dados em projetos de Ferramentas de IA, evitando duplicações e erros","ru":"Валидатор единого источника является критической способностью для обеспечения целостности данных в проектах ИИ Агентов, предотвращая дублирование и ошибки","ar":"مميزة مصدر وحيد هي مهارة حاسمة لضمان سلامة البيانات في مشاريع العمليات الذكية، وتجنب التكرار والأخطاء"},"seo":{"title":{"en":"single-source-validator: Enforcement Mechanism Setup Guid...","zh":"Single Source Validator 设置指南 - AIエージェント工具","ja":"Single Source Validator 導入ガイド - AIエージェント","ko":"Single Source Validator 설정 가이드 - AI 에이전트 도구","es":"Guía de configuración del validador de fuente única para ...","fr":"Guide de configuration du validateur de source unique pou...","de":"Einrichtungsanleitung für den Single-Source-Validator für...","pt":"Guia de Configuração do Validador de Origem Única para Fe...","ru":"Настройка валидатора единого источника для ИИ Агентов","ar":"دليل إعداد مميزة مصدر وحيد للعمليات الذكية"},"description":{"en":"Prevent duplication nightmares with single-source-validator. Learn how to enforce a single source of truth for Skills and ensure Phase 5 validation success. ...","zh":"了解 Single Source Validator 的功能和用途，防止 AI 代理技能的重复和错误","ja":"Single Source Validator の機能と使用方法を理解し、AI エージェントのスキルの重複とエラーを防ぐ","ko":"Single Source Validator 의 기능과 용도를 이해하고 AI 에이전트의 스킬 중복과 오류를 방지하세요","es":"Aprende a configurar el validador de fuente única para evitar la duplicación de habilidades en tus Agentes de IA","fr":"Découvrez comment configurer le validateur de source unique pour éviter la duplication des compétences dans vos Outils d''IA","de":"Erfahren Sie, wie Sie den Single-Source-Validator einrichten, um die Duplizierung von Fähigkeiten in Ihren KI-Agents zu vermeiden","pt":"Aprenda a configurar o validador de origem única para evitar duplicações e garantir a integridade dos dados em seus projetos de Ferramentas de IA","ru":"Узнайте, как настроить валидатор единого источника для предотвращения дублирования и обеспечения целостности данных в ваших проектах ИИ Агентов","ar":"تعرف على كيفية إعداد مميزة مصدر وحيد لتجنب التكرار وضمان سلامة البيانات في مشاريع العمليات الذكية"},"definition":{"en":"single-source-validator is a skill that enforces a single source of truth for Skills, preventing duplication and ensuring data consistency.","zh":"Single Source Validator 是一种 AI 代理技能验证工具，确保技能的单一来源","ja":"Single Source Validator は、AI エージェントのスキルを検証するツールで、スキルの単一の情報源を保証します","ko":"Single Source Validator 는 AI 에이전트의 스킬을 검증하는 도구로 스킬의 단일 정보원을 보장합니다","es":"Un validador de fuente única es una herramienta que garantiza que los datos y habilidades de los Agentes de IA sean consistentes y no duplicados.","fr":"Un validateur de source unique est un outil qui garantit que les données et les compétences des Outils d''IA soient cohérentes et non dupliquées.","de":"Ein Single-Source-Validator ist ein Tool, das sicherstellt, dass die Daten und Fähigkeiten der KI-Agents konsistent und nicht dupliziert sind.","pt":"O que é um validador de origem única? É uma habilidade que garante a existência de uma única fonte de verdade para os dados em projetos de Ferramentas de IA","ru":"Что такое валидатор единого источника? Это способность, которая гарантирует существование единого источника правды для данных в проектах ИИ Агентов","ar":"ما هي مميزة مصدر وحيد؟ هي مهارة تضمن وجود مصدر وحيد للبيانات في مشاريع العمليات الذكية"},"features":{"en":["Enforces single source of truth for Skills using blocking authority","Validates Phase 5 finalization and prevents workflow completion on violations","Triggers monthly periodic audits to ensure data consistency","Fails Phase 5 validation on detected violations","Prevents changes from being merged on violations"],"zh":["防止 AI 代理技能的重复和错误","确保技能的单一来源","支持 Phase 5 验证","具有阻塞权限，防止违规","适用于新技能创建、更新和周期性审计"],"ja":["AI エージェントのスキルの重複とエラーを防ぐ","スキルの単一の情報源を保証する","Phase 5 検証をサポートする","ブロッキング権限を持ち、違反を防ぐ","新しいスキルの作成、更新、定期的な監査に適する"],"ko":["AI 에이전트의 스킬 중복과 오류를 방지","스킬의 단일 정보원을 보장","Phase 5 검증을 지원","블록 권한을 가지며 위반을 방지","新的 스킬 생성, 업데이트 및 정기적인 감사를 위한"],"es":["Evita la duplicación de habilidades en los Agentes de IA","Garantiza la consistencia de los datos y las habilidades","Puede ser utilizado durante la creación de nuevas habilidades","Puede ser utilizado durante la actualización de definiciones de agentes","Puede ser utilizado durante auditorías periódicas"],"fr":["Évite la duplication des compétences dans les Outils d''IA","Assure la cohérence des données et des compétences","Peut être utilisé lors de la création de nouvelles compétences","Peut être utilisé lors de la mise à jour des définitions d''agents","Peut être utilisé lors d''audits périodiques"],"de":["Vermeidet die Duplizierung von Fähigkeiten in KI-Agents","Gewährleistet die Konsistenz der Daten und Fähigkeiten","Kann während der Erstellung neuer Fähigkeiten verwendet werden","Kann während der Aktualisierung von Agentendefinitionen verwendet werden","Kann während regelmäßiger Audits verwendet werden"],"pt":["Prevenção de duplicações de dados","Garantia de integridade dos dados","Validação de origem única para Ferramentas de IA","Integração com workflows para garantir a consistência dos dados","Suporte à auditorias periódicas para garantir a conformidade"],"ru":["Предотвращение дублирования данных","Обеспечение целостности данных","Валидация единого источника для ИИ Агентов","Интеграция с рабочими процессами для обеспечения согласованности данных","Поддержка периодических аудитов для обеспечения соответствия"],"ar":["منع تكرار البيانات","ضمان سلامة البيانات","التحقق من مصدر وحيد للعمليات الذكية","التكامل مع سير العمل لضمان الاتساق في البيانات","دعم التدقيق الدوري لضمان المطابقة"]},"keywords":{"en":["how to use single-source-validator","single-source-validator alternative","single-source-validator setup guide","what is single-source-validator","single-source-validator vs data duplication","single-source-validator install","single-source-validator for AI agents","single-source-validator enforcement mechanism","single-source-validator Phase 5 validation"],"zh":["AI 代理工具","Single Source Validator","技能验证","单一来源","Phase 5 验证","阻塞权限","AI 代理开发"],"ja":["AI エージェント","Single Source Validator","スキル検証","単一の情報源","Phase 5 検証","ブロッキング権限","AI エージェント開発"],"ko":["AI 에이전트 도구","Single Source Validator","스킬 검증","단일 정보원","Phase 5 검증","블록 권한","AI 에이전트 개발"],"es":["validador de fuente única","Agentes de IA","duplicación de habilidades","consistencia de datos","creación de habilidades","actualización de definiciones de agentes","auditorías periódicas","Herramientas de IA"],"fr":["validateur de source unique","Outils d''IA","duplication des compétences","cohérence des données","création de compétences","mise à jour des définitions d''agents","audits périodiques","Compétences d''IA"],"de":["Single-Source-Validator","KI-Agents","Duplizierung von Fähigkeiten","Konsistenz der Daten","Erstellung von Fähigkeiten","Aktualisierung von Agentendefinitionen","regelmäßige Audits","KI-Tools"],"pt":["validador de origem única","Ferramentas de IA","integridade dos dados","prevenção de duplicações","auditorias periódicas","workflows de dados","desenvolvimento de Ferramentas de IA","melhores práticas de dados"],"ru":["валидатор единого источника","ИИ Агенты","целостность данных","предотвращение дублирования","периодические аудиты","работа с данными","разработка ИИ Агентов","лучшие практики данных"],"ar":["مميزة مصدر وحيد","العمليات الذكية","سلامة البيانات","منع التكرار","التدقيق الدوري","سير العمل للبيانات","تطوير العمليات الذكية","أفضل ممارسات البيانات"]}},"owner":"DarkMonkDev","repo":"WitchCityRope","repoPath":"DarkMonkDev/WitchCityRope","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.364Z","topics":[],"category":"community","skillMd":{"name":"single-source-validator","description":"ENFORCEMENT tool that detects when Skills automation is duplicated in agent definitions, lessons learned, or process docs. Prevents single source of truth nightmare by finding bash commands, step-by-step procedures, or process descriptions that replicate Skills. BLOCKING AUTHORITY - workflow cannot complete with violations.","bodyPreview":"# Single Source of Truth Validator Skill\n\n**Purpose**: ENFORCE single source of truth for Skills - prevent duplication nightmare.\n\n**When to Use**:\n- After creating any new Skill\n- Before Phase 5 finalization (MANDATORY)\n- When updating agent definitions\n- When updating lessons learned\n- During periodic audits (monthly)\n\n## 🚨 CRITICAL: ENFORCEMENT MECHANISM\n\n**This skill has BLOCKING AUTHORITY.**\n\n**If violations found:**\n- ❌ Phase 5 validation FAILS\n- ❌ Workflow CANNOT complete\n- ❌ Changes MUS","body":"# Single Source of Truth Validator Skill\n\n**Purpose**: ENFORCE single source of truth for Skills - prevent duplication nightmare.\n\n**When to Use**:\n- After creating any new Skill\n- Before Phase 5 finalization (MANDATORY)\n- When updating agent definitions\n- When updating lessons learned\n- During periodic audits (monthly)\n\n## 🚨 CRITICAL: ENFORCEMENT MECHANISM\n\n**This skill has BLOCKING AUTHORITY.**\n\n**If violations found:**\n- ❌ Phase 5 validation FAILS\n- ❌ Workflow CANNOT complete\n- ❌ Changes MUST NOT be committed\n\n**Why this matters:**\n- Skills = ONLY source of automation\n- All other docs REFERENCE skills, never duplicate\n- Agents ignore guides when procedures are scattered\n- User feedback: \"SUPER CRITICAL\" - duplication causes nightmare\n\n---\n\n## Single Source of Truth Architecture\n\n```\nSKILLS (/.claude/skills/*.md)\n    Automation ONLY\n    Executable bash scripts\n    Zero duplication\n         ↑\n         |\n    Referenced by\n         |\n         ↓\nAGENT DEFINITIONS (/.claude/agents/*.md)\n    Role + Tools + Skill References\n    \"Use skill X for Y\"\n    NEVER duplicate procedures\n\nLESSONS LEARNED (/docs/lessons-learned/*.md)\n    Problem → Solution → Example\n    \"See: /.claude/skills/X.md\"\n    NEVER duplicate procedures\n\nPROCESS DOCS (/docs/standards-processes/*.md)\n    Workflow + References\n    \"Automation: /.claude/skills/X.md\"\n    NEVER duplicate procedures\n```\n\n---\n\n## What This Validates\n\nThis skill checks for **8 types** of single-source violations:\n\n1. **Bash Command Duplication** - Exact bash commands from skills appearing in agent definitions, lessons learned, or process docs\n2. **Step-by-Step Procedures** - Numbered or bulleted procedure steps duplicating skill automation\n3. **Hardcoded Skill Paths** - Direct file path references (/.claude/skills/X.md) instead of skill name references\n4. **Detailed Agent Skill Sections** - Agent definitions with When:/What:/Location: patterns (should be reference-only)\n5. **Procedural Keyword Duplication** - Skill-specific procedures duplicated in other documents\n6. **Missing Proper References** - Documents should say \"Use X skill\" or \"See SKILLS-REGISTRY.md\"\n7. **Bash Scripts in Non-Skill Docs** - Bash code blocks in guides without skill references (NEW)\n8. **Procedure Sections Without Skill References** - \"How to\", \"Steps to\", \"Procedure\" sections not referencing skills (NEW)\n\n**Detection Levels:**\n- ❌ **VIOLATIONS** (CRITICAL) - Exact duplications, blocks Phase 5\n- ⚠️ **WARNINGS** - Potential issues, manual review recommended\n\n---\n\n## How to Use This Skill\n\n### From Command Line\n\n```bash\n# Validate specific skill for duplication\nbash .claude/skills/single-source-validator/execute.sh container-restart\n\n# Validate with CRITICAL severity (default - blocks on warnings)\nbash .claude/skills/single-source-validator/execute.sh staging-deploy CRITICAL\n\n# Validate with WARNING severity (warnings don''t block)\nbash .claude/skills/single-source-validator/execute.sh phase-1-validator WARNING\n\n# Show help and usage information\nbash .claude/skills/single-source-validator/execute.sh --help\n```\n\n### From Claude Code\n\n```\nUse the single-source-validator skill to check if [skill-name] has any duplication violations\n```\n\n### Common Usage Patterns\n\n**After creating new skill:**\n```bash\nbash .claude/skills/single-source-validator/execute.sh my-new-skill\n```\n\n**Before Phase 5 finalization (validate all skills):**\n```bash\nfor skill_dir in .claude/skills/*/; do\n    skill_name=$(basename \"$skill_dir\")\n    if [ -f \"$skill_dir/SKILL.md\" ]; then\n        bash .claude/skills/single-source-validator/execute.sh \"$skill_name\"\n    fi\ndone\n```\n\n**During periodic audit:**\n```bash\nbash .claude/skills/single-source-validator/execute.sh container-restart WARNING\n```\n\n---\n\n## Proper Reference Format\n\n### ❌ WRONG - Duplication\n\n**Agent definition** (test-executor.md):\n```markdown\n## Before E2E Tests\n\nRun these steps:\n1. Stop containers: `docker-compose down`\n2. Start with dev overlay: `docker-compose -f docker-compose.yml -f docker-compose.dev.yml up -d`\n3. Wait 15 seconds\n4. Check health: `curl http://localhost:5173`\n```\n\n**Why wrong**: Duplicates bash commands from restart-dev-containers skill\n\n### ✅ CORRECT - Reference\n\n**Agent definition** (test-executor.md):\n```markdown\n## Before E2E Tests\n\n**MANDATORY**: Use restart-dev-containers skill to ensure environment is healthy.\n\n**See**: `/.claude/skills/container-restart.md`\n\nThe skill automatically:\n- Stops containers correctly\n- Starts with dev overlay\n- Checks compilation errors\n- Verifies health endpoints\n```\n\n**Why correct**: References skill, provides context, no duplication\n\n---\n\n## Lessons Learned Format\n\n### ❌ WRONG - Duplication\n\n**Lesson** (test-executor-lessons-learned.md):\n```markdown\n## Problem: E2E Tests Fail\n\n**Solution**:\n1. Run `docker-compose down`\n2. Run `docker-compose -f docker-compose.yml -f docker-compose.dev.yml up -d`\n3. Check logs for compilation errors\n4. Verify health endpoints\n```\n\n**Why wrong**: Step-by-step procedure duplicates skill\n\n### ✅ CORRECT - Reference\n\n**Lesson** (test-executor-lessons-learned.md):\n```markdown\n## Problem: E2E Tests Fail with \"Element Not Found\"\n\n**Root Cause**: Container shows \"Up\" but code has compilation errors inside.\n\n**Solution**: Use `restart-dev-containers` skill before E2E tests.\n\nThe skill automatically checks for compilation errors and verifies health.\n\n**See**: `/.claude/skills/container-restart.md`\n\n**Example**:\n```bash\n# In test-executor workflow\nbash .claude/skills/container-restart.md\n# Then run E2E tests\nnpm run test:e2e\n```\n```\n\n**Why correct**: Explains problem/solution, references skill, shows usage example\n\n---\n\n## Process Documentation Format\n\n### ❌ WRONG - Duplication\n\n**Process doc** (docker-operations-guide.md):\n```markdown\n## Container Restart Procedure\n\nSteps:\n1. Stop: `docker-compose -f docker-compose.yml -f docker-compose.dev.yml down`\n2. Start: `docker-compose -f docker-compose.yml -f docker-compose.dev.yml up -d`\n3. Verify: Check container logs for errors\n4. Health: Test all endpoints\n```\n\n**Why wrong**: Detailed procedure duplicates skill automation\n\n### ✅ CORRECT - Reference\n\n**Process doc** (docker-operations-guide.md):\n```markdown\n## Container Restart Procedure\n\n**Automation**: `/.claude/skills/container-restart.md`\n\nThe skill provides automated container restart with:\n- Correct docker-compose commands (dev overlay)\n- Compilation error checking (critical for E2E tests)\n- Health endpoint verification\n- Database seed data validation\n\n**When to use**: Before E2E tests, after code changes, when containers unhealthy\n\n**Manual procedure**: See skill file for troubleshooting steps if automation fails\n```\n\n**Why correct**: References skill as automation, provides context, no duplication\n\n---\n\n## Integration with Phase 5 Validator\n\n**Update to phase-5-validator.md**:\n\n```bash\n# Step: Check for single source of truth violations\necho \"Checking single source of truth compliance...\"\n\n# Get list of all skills\nSKILLS=$(ls /.claude/skills/*.md 2>/dev/null | grep -v \"README.md\" || true)\n\nfor SKILL_FILE in $SKILLS; do\n    SKILL_NAME=$(basename \"$SKILL_FILE\" .md)\n\n    echo \"Validating skill: $SKILL_NAME\"\n\n    # Run validator\n    bash /.claude/skills/single-source-validator.md \"$SKILL_NAME\" CRITICAL\n\n    if [ $? -ne 0 ]; then\n        echo \"❌ VIOLATION: Duplication detected for skill: $SKILL_NAME\"\n        echo \"Phase 5 validation BLOCKED\"\n        exit 1\n    fi\ndone\n\necho \"✅ All skills maintain single source of truth\"\n```\n\n---\n\n## Validation Workflow\n\n### For New Skills\n\n```bash\n# 1. Create new skill\nvim /.claude/skills/my-new-skill.md\n\n# 2. Validate immediately\nbash /.claude/skills/single-source-validator.md my-new-skill\n\n# 3. Fix any violations before committing\n```\n\n### For Existing Skills\n\n```bash\n# Run validator on specific skill\nbash /.claude/skills/single-source-validator.md container-restart\n\n# Or validate all skills\nfor skill in /.claude/skills/*.md; do\n    name=$(basename \"$skill\" .md)\n    if [ \"$name\" != \"README\" ]; then\n        bash /.claude/skills/single-source-validator.md \"$name\"\n    fi\ndone\n```\n\n### Before Phase 5 Completion\n\n```bash\n# MANDATORY: Validate all skills\n# Integrated into phase-5-validator.md\n# Blocks workflow if violations found\n```\n\n---\n\n## Common Violations & Fixes\n\n### Violation 1: Agent Definition Has Bash Commands\n\n**Violation**:\n```\n❌ VIOLATION: Agent ''test-executor'' duplicates bash command\n   File: /.claude/agents/test-executor.md\n   Command: docker-compose -f docker-compose.yml -f docker-compose.dev.yml up -d\n```\n\n**Fix**:\n```bash\n# 1. Open agent file\nvim /.claude/agents/test-executor.md\n\n# 2. Remove bash command section\n\n# 3. Replace with reference\n# Before E2E Tests\n# Use restart-dev-containers skill: /.claude/skills/container-restart.md\n\n# 4. Validate\nbash /.claude/skills/single-source-validator.md container-restart\n```\n\n### Violation 2: Lessons Learned Has Procedure Steps\n\n**Violation**:\n```\n❌ VIOLATION: Lesson ''test-executor-lessons-learned'' duplicates bash command\n   File: /docs/lessons-learned/test-executor-lessons-learned.md\n   Command: docker logs witchcity-web --tail 50 | grep -i error\n```\n\n**Fix**:\n```bash\n# 1. Open lesson file\nvim /docs/lessons-learned/test-executor-lessons-learned.md\n\n# 2. Remove step-by-step procedure\n\n# 3. Replace with Problem→Solution→Example format\n## Problem: Containers start but tests fail\n**Root Cause**: Compilation errors inside container\n**Solution**: Use restart-dev-containers skill (checks compilation)\n**See**: /.claude/skills/container-restart.md\n\n# 4. Validate\nbash /.claude/skills/single-source-validator.md container-restart\n```\n\n### Violation 3: Process Doc Duplicates Automation\n\n**Violation**:\n```\n❌ VIOLATION: Process doc ''staging-deployment-guide'' duplicates bash command\n   File: /docs/functional-areas/deployment/staging-deployment-guide.md\n   Command: docker build -f apps/api/Dockerfile -t registry.digitalocean.com/...\n```\n\n**Fix**:\n```bash\n# 1. Open process doc\nvim /docs/functional-areas/deployment/staging-deployment-guide.md\n\n# 2. Remove bash script section\n\n# 3. Replace with reference to automation\n**Automation**: /.claude/skills/staging-deploy.md\nThe skill handles: build, registry push, deployment, health checks\n\n**Manual procedure**: This guide covers context and troubleshooting\n\n# 4. Validate\nbash /.claude/skills/single-source-validator.md staging-deploy\n```\n\n---\n\n## Severity Levels\n\n### CRITICAL (Default)\n- **Exact bash command matches**: Always blocked\n- **Step-by-step procedures**: Always blocked\n- **Warnings treated as failures**: Yes\n- **Use for**: Phase 5 validation, skill creation\n\n### WARNING\n- **Exact bash command matches**: Blocked\n- **Step-by-step procedures**: Blocked\n- **Warnings treated as failures**: No (manual review)\n- **Use for**: Periodic audits, exploratory checks\n\n### INFO\n- **Exact bash command matches**: Reported only\n- **Step-by-step procedures**: Reported only\n- **Warnings treated as failures**: No\n- **Use for**: Documentation reviews, planning\n\n---\n\n## Agent Instructions\n\n### All Agents (Mandatory)\n\n**Before modifying agent definitions, lessons learned, or process docs:**\n\n```bash\n# Check if skill exists for this procedure\nls /.claude/skills/ | grep -i \"relevant-keyword\"\n\n# If skill exists, REFERENCE it, don''t duplicate\necho \"See: /.claude/skills/[skill-name].md\" >> file.md\n\n# If no skill exists and procedure is complex, CREATE SKILL FIRST\nvim /.claude/skills/new-procedure.md\n\n# Then reference from other docs\n```\n\n### Orchestrator (Phase 5)\n\n**MANDATORY validation before finalization:**\n\n```bash\n# Run validator on ALL skills\necho \"Validating single source of truth...\"\n\nfor skill in /.claude/skills/*.md; do\n    name=$(basename \"$skill\" .md)\n    if [ \"$name\" != \"README\" ] && [ \"$name\" != \"single-source-validator\" ]; then\n        bash /.claude/skills/single-source-validator.md \"$name\" CRITICAL\n        if [ $? -ne 0 ]; then\n            echo \"❌ Phase 5 validation BLOCKED due to violations in: $name\"\n            exit 1\n        fi\n    fi\ndone\n\necho \"✅ Single source of truth maintained across all skills\"\n```\n\n### Librarian (File Organization)\n\n**When creating/moving documentation:**\n\n```bash\n# Before creating new procedure doc\n# 1. Check if skill exists\nbash /.claude/skills/single-source-validator.md [relevant-skill] INFO\n\n# 2. If skill exists, reference it\n# 3. If no skill, consider if automation needed\n# 4. If automation needed, create skill FIRST\n```\n\n---\n\n## Metrics & Monitoring\n\n### Success Metrics\n\n- **Zero violations** in Phase 5 validation (target: 100%)\n- **Skills referenced** vs **procedures duplicated** ratio (target: >95%)\n- **Agent compliance** - agents using skills vs. duplicating (target: 100%)\n\n### Monitoring Commands\n\n```bash\n# Count total skills\nSKILL_COUNT=$(ls /.claude/skills/*.md | wc -l)\n\n# Count references to skills\nREF_COUNT=$(grep -r \"\\.claude/skills/\" /.claude/agents /docs/lessons-learned /docs/standards-processes | wc -l)\n\n# Count violations (should be 0)\nVIOLATION_COUNT=0\nfor skill in /.claude/skills/*.md; do\n    name=$(basename \"$skill\" .md)\n    if [ \"$name\" != \"README\" ] && [ \"$name\" != \"single-source-validator\" ]; then\n        bash /.claude/skills/single-source-validator.md \"$name\" CRITICAL > /dev/null 2>&1\n        if [ $? -ne 0 ]; then\n            ((VIOLATION_COUNT++))\n        fi\n    fi\ndone\n\necho \"Skills: $SKILL_COUNT\"\necho \"References: $REF_COUNT\"\necho \"Violations: $VIOLATION_COUNT\"\n```\n\n---\n\n## Troubleshooting\n\n### Issue: Validator reports false positive\n\n**Cause**: Skill and doc have similar bash command for different purpose\n\n**Solution**:\n1. Review context around command in both files\n2. If different purpose, add comment in doc: `# Different from skill: [explanation]`\n3. Run validator with WARNING severity for manual review\n\n### Issue: Too many warnings, hard to review\n\n**Cause**: Keyword-based detection is overly broad\n\n**Solution**:\n1. Focus on VIOLATIONS first (exact bash commands)\n2. Review warnings manually during periodic audits\n3. Refine keyword extraction logic if needed\n\n### Issue: Validator missed duplication\n\n**Cause**: Procedure rewritten in different style (paraphrased)\n\n**Solution**:\n1. Manual code review remains important\n2. Validator catches exact duplicates, not paraphrases\n3. Educate agents on spirit of single source of truth\n\n---\n\n## Version History\n\n- **2025-11-04**: Created as ENFORCEMENT mechanism for single source of truth\n- Addresses user feedback: \"SUPER CRITICAL\" - agents ignore guides when procedures scattered\n- Provides BLOCKING AUTHORITY - workflow cannot complete with violations\n- Integrated with phase-5-validator for mandatory validation\n\n---\n\n**Remember**: This skill has blocking authority. Zero tolerance for duplication. Skills are the ONLY source of automation.\n"},"lastSynced":"2026-03-08T02:04:18.574Z","agentAnalysis":{"suitability":{"en":"Ideal for AI agents like Cursor, Windsurf, and Claude Code requiring strict data consistency and validation, particularly in Phase 5 finalization","zh":"适用于像Cursor、Windsurf和Claude Code这样的AI代理，需要严格的数据一致性和验证，特别是在第5阶段的最终确定","ja":"Cursor、Windsurf、Claude CodeのようなAIエージェントに適しています。これらは、特に第5段階の最終決定において、厳格なデータの整合性と検証を必要とします","ko":"Cursor, Windsurf, Claude Code와 같은 AI 에이전트에 적합합니다. 이러한 에이전트는 특히 5단계 최종 결정에서 엄격한 데이터 일관성 및 유효성 검증을 필요로 합니다","es":"Ideal para agentes de IA como Cursor, Windsurf y Claude Code que requieren una consistencia y validación de datos estrictas, particularmente en la finalización de la Fase 5","fr":"Idéal pour les agents IA comme Cursor, Windsurf et Claude Code nécessitant une cohérence et une validation des données strictes, en particulier lors de la finalisation de la Phase 5","de":"Ideal für KI-Agents wie Cursor, Windsurf und Claude Code, die eine strenge Datenkonsistenz und -validierung erfordern, insbesondere bei der Finalisierung der Phase 5","pt":"Ideal para agentes de IA como Cursor, Windsurf e Claude Code que requerem estrita consistência de dados e validação, particularmente na finalização da Fase 5","ru":"Идеально для агентов ИИ, таких как Cursor, Windsurf и Claude Code, требующих строгой согласованности данных и проверки, особенно в финализации Фазы 5","ar":"مثالي للوكلاء الذكاء الاصطناعي مثل Cursor و Windsurf و Claude Code الذين يتطلبون συνέافة بيانات صارمة وتحقق، خاصة في نهائية المرحلة 5"},"recommendation":{"en":"Enforces a single source of truth for Skills, preventing duplication and ensuring validation success through blocking authority, leveraging mandatory Phase 5 validation and workflow completion checks","zh":"强制执行Skills的单一真实来源，防止重复并确保通过阻塞权限、强制第5阶段验证和工作流完成检查来实现验证成功","ja":"Skillsの単一の真実の源を強制し、重複を防ぎ、ブロッキング権限、第5段階の検証、ワークフロー完了チェックを強制することで検証成功を保証します","ko":"스킬의 단일 진실 원천을 강제하여 중복을 방지하고, 차단 권한, 5단계 검증 및 워크플로 완료 검사를 강제함으로써 검증 성공을 보장합니다","es":"Establece una sola fuente de verdad para las Skills, evitando la duplicación y garantizando el éxito de la validación a través de la autoridad de bloqueo, aprovechando la validación obligatoria de la Fase 5 y las comprobaciones de finalización del flujo de trabajo","fr":"Impose une seule source de vérité pour les Skills, empêchant la duplication et assurant la réussite de la validation grâce à l''autorité de blocage, en exploitant la validation obligatoire de la Phase 5 et les vérifications de finalisation du flux de travail","de":"Legt eine einzige Wahrheitsquelle für Skills fest, verhindert Duplizierungen und gewährleistet den Validierungserfolg durch die Sperrbefugnis, indem es die obligatorische Validierung der Phase 5 und die Workflow-Abschlussprüfungen nutzt","pt":"Impõe uma única fonte de verdade para Habilidades, prevenindo duplicação e garantindo sucesso da validação por meio da autoridade de bloqueio, aproveitando a validação obrigatória da Fase 5 e verificações de conclusão do fluxo de trabalho","ru":"Принуждает к единому источнику истины для Навыков, предотвращая дублирование и гарантируя успех проверки посредством блокирующей власти, используя обязательную проверку Фазы 5 и проверки завершения рабочего процесса","ar":"فرض مصدر وحيد للحقيقة للمهارات، ومنع التكرار وضمان نجاح التحقق من خلال سلطة الحجب، واستخدام التحقق الإلزامي للمرحلة 5 وعمليات التحقق من إكمال سير العمل"},"useCases":{"en":["Validating agent definitions to prevent duplication","Enforcing single source of truth during periodic audits","Blocking workflow completion upon validation failures","Ensuring Phase 5 validation success through strict data consistency"],"zh":["验证代理定义以防止重复","在定期审计期间强制单一真实来源","在验证失败时阻塞工作流完成","通过严格的数据一致性确保第5阶段验证成功"],"ja":["エージェント定義を検証して重複を防ぐ","定期監査中に単一の真実の源を強制する","検証失敗時にワークフロー完了をブロックする","厳格なデータの整合性を通じて第5段階の検証成功を確保する"],"ko":["에이전트 정의를 검증하여 중복을 방지합니다","정기적인 감사 중에 단일 진실 원천을 강제합니다","검증 실패 시 워크플로 완료를 차단합니다","엄격한 데이터 일관성을 통해 5단계 검증 성공을 보장합니다"],"es":["Validar las definiciones de agentes para evitar la duplicación","Establecer una sola fuente de verdad durante las auditorías periódicas","Bloquear la finalización del flujo de trabajo en caso de errores de validación","Garantizar el éxito de la validación de la Fase 5 a través de la consistencia de datos estricta"],"fr":["Valider les définitions d''agents pour éviter