INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('DarkMonkDev/WitchCityRope/single-source-validator', 'single-source-validator', 'DarkMonkDev', 'WitchCityRope', 'community', 'single-source-validator DarkMonkDev WitchCityRope community The single-source-validator skill enforces a single source of truth for Skills, preventing duplication and ensuring Phase 5 validation success. It benefits AI agent developers by providing a critical enforcement mechanism. Single Source Validator 是一个确保 AI 代理技能单一来源的工具，防止重复和错误 Single Source Validator は、AI エージェントのスキルが単一の情報源となることを保証するツールで、重複とエラーを防ぎます Single Source Validator 는 AI 에이전트의 스킬이 단일 정보원을 보장하는 도구로 중복과 오류를 방지합니다 El validador de fuente única es una habilidad que garantiza la integridad de tus Agentes de IA, evitando la duplicación de habilidades y asegurando la consistencia de los datos. Le validateur de source unique est une compétence qui garantit l''intégrité de vos Outils d''IA, en évitant la duplication des compétences et en assurant la cohérence des données. Der Single-Source-Validator ist eine Fähigkeit, die die Integrität Ihrer KI-Agents sicherstellt, indem sie die Duplizierung von Fähigkeiten vermeidet und die Konsistenz der Daten gewährleistet. O validador de origem única é uma habilidade crítica para garantir a integridade dos dados em projetos de Ferramentas de IA, evitando duplicações e erros Валидатор единого источника является критической способностью для обеспечения целостности данных в проектах ИИ Агентов, предотвращая дублирование и ошибки مميزة مصدر وحيد هي مهارة حاسمة لضمان سلامة البيانات في مشاريع العمليات الذكية، وتجنب التكرار والأخطاء how to use single-source-validator single-source-validator alternative single-source-validator setup guide what is single-source-validator single-source-validator vs data duplication single-source-validator install single-source-validator for AI agents single-source-validator enforcement mechanism single-source-validator Phase 5 validation AI 代理工具 Single Source Validator 技能验证 单一来源 Phase 5 验证 阻塞权限 AI 代理开发 Enforces single source of truth for Skills using blocking authority Validates Phase 5 finalization and prevents workflow completion on violations Triggers monthly periodic audits to ensure data consistency Fails Phase 5 validation on detected violations Prevents changes from being merged on violations single-source-validator is a skill that enforces a single source of truth for Skills, preventing duplication and ensuring data consistency.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('danielnewman09/MSD-CPP/create-issue', 'community', 'danielnewman09', 'MSD-CPP', 'danielnewman09/MSD-CPP', 'create-issue', 0, 0, 45, '2026-03-08T01:57:15.364Z', '2026-03-08T02:04:20.665Z', 'fd83343eca44ce84c6d54476b5671f45392d50594a97162a3aba2036d4972a8a', '{"id":"danielnewman09/MSD-CPP/create-issue","name":"create-issue","description":{"en":"The create-issue skill converts local markdown tickets into GitHub Issues, preserving content and managing labels. It benefits developers by automating issue creation.","zh":"Create Issue AI Agent可以将本地Markdown票转换为GitHub问题，保留内容、管理标签和工作流阶段子问题","ja":"Create Issue AIエージェントは、ローカルのMarkdownチケットをGitHub Issueに変換し、コンテンツ、ラベル、ワークフローフェーズのサブイシューを保存します","ko":"Create Issue AI 에이전트는 로컬 Markdown 티켓을 GitHub 이슈로 변환하고 내용, 레이블, 워크플로우 단계의 하위 이슈를 보존합니다","es":"Create-issue es una habilidad que convierte tickets de markdown en problemas de GitHub con contenido completo, conservación de etiquetas y resolución de referencias cruzadas","fr":"Create-issue est une compétence qui convertit les tickets markdown en problèmes GitHub avec contenu complet, conservation d''étiquettes et résolution de références croisées","de":"Create-issue ist eine Fähigkeit, die Markdown-Tickets in GitHub-Probleme mit vollständigem Inhalt, Labelverwaltung und Auflösung von Querverweisen umwandelt","pt":"O agente de criação de issues converte tickets em markdown em issues do GitHub com preservação de conteúdo e gerenciamento de labels","ru":"ИИ Агент для создания Issue преобразует локальные tickets в markdown в issues GitHub с сохранением контента и управлением метками","ar":"أداة إنشاء المشكلات تحول التذاكر في تنسيق Markdown إلى مشكلات على GitHub مع الحفاظ على المحتوى وإدارة العلامات"},"seo":{"title":{"en":"create-issue: GitHub Issue Creation Setup Guide | AI Agen...","zh":"创建GitHub问题的设置指南 - Create Issue AI Agent","ja":"GitHub Issueを作成するためのベストプラクティス - Create Issue AIエージェント","ko":"GitHub 이슈 생성을 위한 설정 가이드 - Create Issue AI 에이전트","es":"Guía de configuración para crear problemas de GitHub con ...","fr":"Guide de mise en place pour créer des problèmes GitHub av...","de":"Einrichtungsleitfaden für die Erstellung von GitHub-Probl...","pt":"Guia de Configuração do Agente de Criação de Issues","ru":"Настройка ИИ Агента для Создания Issue","ar":"دليل إعداد أداة إنشاء المشكلات"},"description":{"en":"Automate GitHub issue creation from markdown tickets with label management and cross-reference resolution. Learn how to invoke create-issue with a simple com...","zh":"使用Create Issue AI Agent轻松将本地Markdown票转换为GitHub问题，保留内容、管理标签和工作流阶段子问题","ja":"Create Issue AIエージェントを使用して、ローカルのMarkdownチケットをGitHub Issueに変換します。コンテンツ、ラベル、ワークフローフェーズのサブイシューを保存します","ko":"Create Issue AI 에이전트를 사용하여 로컬 Markdown 티켓을 GitHub 이슈로 변환하고 내용, 레이블, 워크플로우 단계의 하위 이슈를 보존합니다","es":"Aprende a crear problemas de GitHub con create-issue, incluyendo conservación de contenido, administración de etiquetas y resolución de referencias cruzadas","fr":"Découvrez comment créer des problèmes GitHub avec create-issue, y compris la conservation de contenu, la gestion d''étiquettes et la résolution de références ...","de":"Erfahren Sie, wie Sie GitHub-Probleme mit create-issue erstellen, einschließlich Inhaltsverwaltung, Labelverwaltung und Auflösung von Querverweisen","pt":"Aprenda a configurar o agente de criação de issues para preservar conteúdo em markdown e gerenciar labels e referências cruzadas","ru":"Узнайте, как настроить ИИ Агента для создания Issue с сохранением контента в markdown и управлением метками и кросс-референсами","ar":"تعرف على إعداد أداة إنشاء المشكلات للحفاظ على المحتوى في تنسيق Markdown وإدارة العلامات والمراجع المتقاطعة"},"definition":{"en":"create-issue is a skill that automates the creation of GitHub Issues from local markdown tickets, preserving content and managing labels","zh":"Create Issue AI Agent是一种可以将本地Markdown票转换为GitHub问题的工具","ja":"Create Issue AIエージェントは、ローカルのMarkdownチケットをGitHub Issueに変換するツールです","ko":"Create Issue AI 에이전트는 로컬 Markdown 티켓을 GitHub 이슈로 변환하는 도구입니다","es":"Create-issue es una herramienta de AI que crea problemas de GitHub a partir de tickets de markdown","fr":"Create-issue est un outil d''IA qui crée des problèmes GitHub à partir de tickets markdown","de":"Create-issue ist ein AI-Tool, das GitHub-Probleme aus Markdown-Tickets erstellt","pt":"O que é um agente de criação de issues? Um agente que converte tickets em markdown em issues do GitHub","ru":"Что такое ИИ Агент для создания Issue? Агент, который преобразует локальные tickets в markdown в issues GitHub","ar":"ما هي أداة إنشاء المشكلات؟ أداة تحول التذاكر في تنسيق Markdown إلى مشكلات على GitHub"},"features":{"en":["Converts local markdown tickets to GitHub Issues with full content preservation","Manages labels and resolves cross-references","Supports workflow phase sub-issues","Invoked using a simple command with ticket identifier","Works with bare numbers, full filename stems, or filenames with .md extension"],"zh":["将本地Markdown票转换为GitHub问题","保留内容和格式","管理标签和工作流阶段子问题","支持CLI命令行调用","自动解析和创建GitHub问题"],"ja":["ローカルのMarkdownチケットをGitHub Issueに変換","コンテンツとフォーマットを保存","ラベルとワークフローフェーズのサブイシューを管理","CLIコマンドライン呼び出しをサポート","自動解析とGitHub Issueの作成"],"ko":["로컬 Markdown 티켓을 GitHub 이슈로 변환","내용과 형식을 보존","레이블과 워크플로우 단계의 하위 이슈를 관리","CLI 명령줄 호출을 지원","자동 분석과 GitHub 이슈 생성"],"es":["Conservación de contenido completo","Administración de etiquetas","Resolución de referencias cruzadas","Creación de subproblemas de fase de flujo de trabajo","Compatibilidad con identificadores de ticket bare, nombre de archivo completo y extensión .md"],"fr":["Conservation de contenu complet","Gestion d''étiquettes","Résolution de références croisées","Création de sous-problèmes de phase de workflow","Compatibilité avec des identificateurs de ticket bare, nom de fichier complet et extension .md"],"de":["Vollständige Inhaltsverwaltung","Labelverwaltung","Auflösung von Querverweisen","Erstellung von Unterproblemen in Workflow-Phasen","Kompatibilität mit Ticket-Identifikatoren, vollständigen Dateinamen und .md-Erweiterung"],"pt":["Preservação de conteúdo em markdown","Gerenciamento de labels e referências cruzadas","Criação de sub-issues para fases de workflow","Suporte a identificadores de ticket em formato numérico ou com extensão .md","Integração com o GitHub para criar issues"],"ru":["Сохранение контента в markdown","Управление метками и кросс-референсами","Создание суб-issues для фаз workflow","Поддержка идентификаторов ticket в числовом формате или с расширением .md","Интеграция с GitHub для создания issues"],"ar":["الحفاظ على المحتوى في تنسيق Markdown","إدارة العلامات والمراجع المتقاطعة","إنشاء مشكلات فرعية لأطوار سير العمل","دعم معرّفات التذاكر بالتنسيق العددي أو بالامتداد .md","التكامل مع GitHub لإنشاء المشكلات"]},"keywords":{"en":["how to use create-issue","create-issue setup guide","GitHub Issue creation automation","create-issue alternative","create-issue vs GitHub API","create-issue install","what is create-issue","create-issue workflow integration","markdown ticket conversion"],"zh":["Create Issue AI Agent","GitHub问题创建","Markdown票转换","CLI命令行工具","自动化GitHub问题管理","AI工具","GitHub集成"],"ja":["Create Issue AIエージェント","GitHub Issueを作成","Markdownチケットを変換","CLIコマンドラインツール","自動化GitHub Issue管理","AIエージェント","GitHub統合"],"ko":["Create Issue AI 에이전트","GitHub 이슈 생성","Markdown 티켓 변환","CLI 명령줄 도구","자동화 GitHub 이슈 관리","AI 에이전트","GitHub 통합"],"es":["create-issue","github problemas","tickets markdown","herramientas de AI","conservación de contenido","administración de etiquetas","resolución de referencias cruzadas","creación de subproblemas"],"fr":["create-issue","problèmes github","tickets markdown","outils d''IA","conservation de contenu","gestion d''étiquettes","résolution de références croisées","création de sous-problèmes"],"de":["create-issue","github-probleme","markdown-tickets","ai-tools","inhaltsverwaltung","labelverwaltung","auflösung von querverweisen","erstellung von unterproblemen"],"pt":["agente de criação de issues","criação de issues github","preservação de conteúdo markdown","gerenciamento de labels","referências cruzadas","sub-issues","workflow","github issues","ticket em markdown"],"ru":["ИИ Агент для создания Issue","создание Issue на GitHub","сохранение контента в markdown","управление метками","кросс-референсы","суб-issues","workflow","issues GitHub","ticket в markdown"],"ar":["أداة إنشاء المشكلات","إنشاء مشكلات على GitHub","الحفاظ على المحتوى في تنسيق Markdown","إدارة العلامات","المراجع المتقاطعة","مشكلات فرعية","سير العمل","مشكلات GitHub","تذكرة في تنسيق Markdown"]}},"owner":"danielnewman09","repo":"MSD-CPP","repoPath":"danielnewman09/MSD-CPP","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.364Z","topics":[],"category":"community","skillMd":{"name":"create-issue","description":"Convert a ticket markdown file from tickets/ into a GitHub Issue, preserving all content and metadata. Accepts bare number (0039a), full name (0039a_energy_tracking_diagnostic_infrastructure), or with .md extension. Creates labels, resolves cross-references, updates parent issues, and closes completed tickets. For work tickets, creates workflow phase sub-issues (Design, Math, Prototype, Implementation). For investigation/debug tickets, creates debug phase sub-issues (Investigate, Diagnose, Fix, Verify).","bodyPreview":"# Create GitHub Issue from Ticket\n\nConvert a local markdown ticket into a GitHub Issue with full content preservation, label management, cross-reference resolution, and workflow phase sub-issues.\n\n## Invocation\n\nThe user provides:\n- **Ticket identifier**: bare number (`0039a`), full filename stem (`0039a_energy_tracking_diagnostic_infrastructure`), or with `.md` extension\n\nExample: `/create-issue 0040b`\n\n## Workflow Overview\n\n```\n1.  RESOLVE     -> Find the ticket file in tickets/\n2.  PARSE","body":"# Create GitHub Issue from Ticket\n\nConvert a local markdown ticket into a GitHub Issue with full content preservation, label management, cross-reference resolution, and workflow phase sub-issues.\n\n## Invocation\n\nThe user provides:\n- **Ticket identifier**: bare number (`0039a`), full filename stem (`0039a_energy_tracking_diagnostic_infrastructure`), or with `.md` extension\n\nExample: `/create-issue 0040b`\n\n## Workflow Overview\n\n```\n1.  RESOLVE     -> Find the ticket file in tickets/\n2.  PARSE       -> Extract title, metadata, and body sections\n3.  CLASSIFY    -> Determine ticket kind: Feature (epic) vs Work (leaf)\n4.  CHECK       -> Search for existing issue by ticket label (idempotency)\n5.  LABELS      -> Create type, ticket, phase labels if missing\n6.  BUILD       -> Format issue body from template\n7.  CROSSREF    -> Resolve internal ticket links to issue numbers\n8.  CREATE      -> Create or update the GitHub Issue\n9.  PHASES      -> (Work tickets only) Create phase sub-issues and link them\n10. PARENT      -> Update parent issue''s subticket task list\n11. REPORT      -> Show URL, labels, phases, and summary\n```\n\n## Step 1: Resolve Ticket File\n\nFind the ticket file in `tickets/`:\n\n1. If the argument contains `.md`, look for `tickets/{argument}` directly\n2. Otherwise, glob for `tickets/{argument}*.md`\n3. If multiple matches, prefer exact prefix match (e.g., `0040` matches `0040_` not `0040a_`)\n4. If still ambiguous, list matches and ask the user to clarify\n\nRead the matched file.\n\n## Step 2: Parse Ticket\n\nThe project has two ticket header formats. Detect and parse both:\n\n### New Format (Ticket NNNN)\n\nHeader line: `# Ticket NNNN: Title Text`\n\nMetadata appears as bold key-value pairs below the Status section:\n```\n**Current Phase**: value\n**Created**: value\n**Type**: value\n**Prototype**: Yes | No\n**Parent Ticket**: [NNNN_name](filename.md)\n**Dependencies**: [NNNN](filename.md)\n**Blocks**: [NNNN](filename.md)\n```\n\n### Old Format (Feature Ticket)\n\nHeader line: `# Feature Ticket: Title Text`\n\nMetadata appears in a `## Metadata` section:\n```\n## Metadata\n- **Created**: value\n- **Priority**: value\n- **Estimated Complexity**: value\n- **Target Component(s)**: value\n```\n\n### Fields to Extract\n\n| Field | Source (New) | Source (Old) | Required |\n|-------|-------------|-------------|----------|\n| `ticket_id` | From header `NNNN` | From filename prefix | Yes |\n| `title` | After `: ` in `# Ticket NNNN:` | After `: ` in `# Feature Ticket:` | Yes |\n| `current_phase` | `**Current Phase**:` | Derive from Status checkboxes | Yes |\n| `created` | `**Created**:` | `**Created**:` in Metadata | No |\n| `type` | `**Type**:` | None (use `enhancement`) | No |\n| `prototype` | `**Prototype**:` (`Yes`/`No`) | None (default `Yes`) | No |\n| `parent` | `**Parent Ticket**:` link | None | No |\n| `dependencies` | `**Dependencies**:` / `**Depends On**:` links | `## Related Tickets` | No |\n| `blocks` | `**Blocks**:` links | None | No |\n\n### Section Extraction\n\nExtract content from these sections (if present):\n- `## Overview` or `## Summary` or `## Motivation`\n- `## Requirements`\n- `## Implementation Approach`\n- `## Test Plan`\n- `## Acceptance Criteria`\n- `## Subtickets`\n- `## Files to Create/Modify` or `## Files`\n- `## Workflow Log`\n\n### Status Derivation\n\nIf `**Current Phase**:` is not present, derive from the Status checkbox list — the last checked item indicates the current phase.\n\n## Step 3: Classify Ticket\n\nDetermine the ticket kind: **Feature** (epic/parent), **Work** (leaf), or **Investigation** (debug).\n\n### Feature Ticket (Epic)\n\nA ticket is a Feature if ANY of these are true:\n- `Type` field contains `(Parent)` — e.g., `Implementation (Parent)`, `Debug Investigation (Parent)`\n- The ticket has a `## Subtickets` section with a table of child tickets\n- The ticket body is primarily a tracking document for child work items\n\nFeature tickets:\n- Get child work tickets as sub-issues (from the Subtickets table)\n- Do NOT get workflow phase sub-issues\n- Get the `feature` label\n\n### Investigation Ticket (Debug)\n\nA ticket is an Investigation if ANY of these are true:\n- `Type` field contains `Investigation` (but NOT `(Parent)`) — e.g., `Investigation`, `Debug Investigation`\n- The ticket has a `## Hypothesis Space` or `## Problem Statement` section\n- The ticket has a `## Suspect Code` or `## Files to Investigate` section\n\nInvestigation tickets:\n- Get debug workflow phase sub-issues (Investigate, Diagnose, Fix, Verify)\n- May be a sub-issue of a parent Feature ticket\n- Get the `type:investigation` label\n\n### Work Ticket (Leaf)\n\nAll other tickets are Work tickets. These represent actual units of work that go through the design-to-implementation workflow.\n\nWork tickets:\n- Get workflow phase sub-issues (Design, Math, Prototype, Implementation)\n- May be a sub-issue of a parent Feature ticket\n\n## Step 4: Check for Existing Issue\n\nSearch for an existing issue with the ticket label:\n\n```bash\ngh issue list --label \"ticket:{ticket_id}\" --state all --json number,title,state --limit 1\n```\n\n- If found and `--state open`: offer to **update** the existing issue\n- If found and `--state closed`: report that the issue already exists and is closed; ask if user wants to reopen and update\n- If not found: proceed to create\n\nAlso check for existing phase sub-issues (for Work and Investigation tickets):\n```bash\n# Work ticket phases\ngh issue list --label \"ticket:{ticket_id}\" --label \"phase:design\" --state all --json number --limit 1\ngh issue list --label \"ticket:{ticket_id}\" --label \"phase:math\" --state all --json number --limit 1\ngh issue list --label \"ticket:{ticket_id}\" --label \"phase:prototype\" --state all --json number --limit 1\ngh issue list --label \"ticket:{ticket_id}\" --label \"phase:implementation\" --state all --json number --limit 1\n\n# Investigation ticket phases\ngh issue list --label \"ticket:{ticket_id}\" --label \"phase:investigate\" --state all --json number --limit 1\ngh issue list --label \"ticket:{ticket_id}\" --label \"phase:diagnose\" --state all --json number --limit 1\ngh issue list --label \"ticket:{ticket_id}\" --label \"phase:fix\" --state all --json number --limit 1\ngh issue list --label \"ticket:{ticket_id}\" --label \"phase:verify\" --state all --json number --limit 1\n```\n\nOnly check the phases relevant to the ticket kind. Skip creating any phase sub-issue that already exists.\n\n## Step 5: Create Labels\n\nCheck and create labels as needed using `gh label create`. See `references/label-mapping.md` for the full mapping.\n\nRequired labels for every issue:\n1. **Ticket label**: `ticket:{ticket_id}` (color `#0E8A16`) — idempotency key\n2. **Type label**: derived from the `Type` metadata field\n\nFor Feature tickets:\n3. **Feature label**: `feature` (color `#FBCA04`)\n\nFor Work tickets, create phase labels:\n3. `phase:design` (color `#C2E0C6`)\n4. `phase:math` (color `#F9D0C4`) — only if math phase applies\n5. `phase:prototype` (color `#FEF2C0`) — only if prototype phase applies\n6. `phase:implementation` (color `#BFD4F2`)\n\nFor Investigation tickets, create debug phase labels:\n3. `phase:investigate` (color `#D4C5F9`)\n4. `phase:diagnose` (color `#F9D0C4`)\n5. `phase:fix` (color `#C2E0C6`)\n6. `phase:verify` (color `#BFD4F2`)\n\nCreate each label only if it doesn''t already exist:\n```bash\ngh label create \"ticket:{ticket_id}\" --color \"0E8A16\" --description \"Ticket {ticket_id}\" --force\ngh label create \"type:{type}\" --color \"{color}\" --force\ngh label create \"phase:design\" --color \"C2E0C6\" --description \"Design phase\" --force\n```\n\nUse `--force` to avoid errors if the label already exists.\n\n## Step 6: Build Issue Body\n\nUse the template from `references/body-template.md`.\n\nRules:\n- **Omit empty sections entirely** — do not include section headers with no content\n- **Acceptance Criteria**: Convert `- [ ] **AC1**: text` or `- [x] text` to GitHub task list format `- [ ] text` / `- [x] text`\n- **Subtickets** (Feature tickets only): Build a task list of children\n- **Workflow Phases** (Work and Investigation tickets): Include a task list of phase sub-issues (populated after Step 9)\n- **Workflow Log**: Wrap in `<details>` collapsible\n- **Max body length**: GitHub limits issue body to ~65535 chars. If body exceeds 60000 chars, truncate the Workflow Log section and add a note\n\n### Subticket Task List (Feature Tickets)\n\nFor Feature tickets with a `## Subtickets` section:\n\n1. Parse the subticket table for ticket IDs and titles\n2. For each subticket, check if a GitHub issue exists: `gh issue list --label \"ticket:{child_id}\" --state all --json number,title --limit 1`\n3. Format:\n   - Has issue: `- [ ] #{issue_number} - {title}`\n   - No issue yet: `- [ ] {title} _(ticket: {child_id}, no issue yet)_`\n   - If the child ticket''s phase indicates completion, use `- [x]` instead\n\n### Workflow Phases Section (Work and Investigation Tickets)\n\nFor Work and Investigation tickets, include a `## Workflow Phases` section with placeholders. This section is updated after phase sub-issues are created in Step 9.\n\n**Work tickets:**\n```markdown\n## Workflow Phases\n\n- [ ] #{design_issue} Design\n- [ ] #{math_issue} Math Formulation\n- [ ] #{prototype_issue} Prototype\n- [ ] #{impl_issue} Implementation\n```\n\nOmit the Math line if math phase doesn''t apply. Omit the Prototype line if prototype phase doesn''t apply.\n\n**Investigation tickets:**\n```markdown\n## Workflow Phases\n\n- [ ] #{investigate_issue} Investigate\n- [ ] #{diagnose_issue} Diagnose\n- [ ] #{fix_issue} Fix\n- [ ] #{verify_issue} Verify\n```\n\n## Step 7: Resolve Cross-References\n\nScan the issue body for internal ticket links in these patterns:\n- `[NNNN](NNNN_name.md)` — markdown link to another ticket\n- `[NNNN_name](NNNN_name.md)` — full name link\n- `ticket NNNN` or `Ticket NNNN` — plain text reference\n\nFor each referenced ticket:\n1. Check if a GitHub issue exists: `gh issue list --label \"ticket:{ref_id}\" --state all --json number --limit 1`\n2. If found: replace the link with `#N` (the GitHub issue number)\n3. If not found: keep the original text but append ` _(no issue yet)_`\n\nTrack and report all link resolutions in Step 11.\n\n## Step 8: Create or Update Main Issue\n\n### Create New Issue\n\n```bash\ngh issue create \\\n  --title \"{title}\" \\\n  --body \"{body}\" \\\n  --label \"ticket:{ticket_id}\" \\\n  --label \"type:{type}\" \\\n  [--label \"feature\"]\n```\n\nCapture the issue number from the output URL.\n\n### Update Existing Issue\n\n```bash\ngh issue edit {issue_number} \\\n  --title \"{title}\" \\\n  --body \"{body}\"\n```\n\nAlso ensure all labels are applied:\n```bash\ngh issue edit {issue_number} --add-label \"ticket:{ticket_id},type:{type}\"\n```\n\n### Close Completed Issues\n\nIf the ticket''s status indicates completion (phase contains \"Complete\" or \"Merged\"), close the issue after creation:\n\n```bash\ngh issue close {issue_number} --reason \"completed\"\n```\n\n## Step 9: Create Phase Sub-Issues (Work and Investigation Tickets)\n\nSkip this step entirely for Feature tickets.\n\n### 9a: Determine Applicable Phases\n\n**Work tickets** get these phases:\n1. **Design** — always\n2. **Math Formulation** — only if math is detected (see detection rules below)\n3. **Prototype** — only if prototype is needed (see detection rules below)\n4. **Implementation** — always\n\n**Investigation tickets** get these phases:\n1. **Investigate** — always (instrument, reproduce, gather evidence)\n2. **Diagnose** — always (hypothesis elimination, root cause identification)\n3. **Fix** — always (implement the fix)\n4. **Verify** — always (regression testing, sanitizer validation)\n\n### 9b: Math Phase Detection (Work Tickets Only)\n\nInclude the Math Formulation phase if ANY of these are true:\n- The ticket body contains keywords: `physics`, `collision`, `inertia`, `quaternion`, `tensor`, `eigenvalue`, `impulse`, `friction`, `torque`, `angular`, `kinetic energy`, `potential energy`, `Lagrangian`, `Jacobian`, `numerical stability`, `convergence`\n- A file exists at `docs/designs/{ticket_name}/math-formulation.md`\n- The ticket''s `## Requirements` section contains LaTeX-style math (backtick blocks with equations, `½`, `ω`, `∑`, etc.)\n\nWhere `{ticket_name}` is the full filename stem without `.md` (e.g., `0040b_split_impulse_position_correction`).\n\n### 9b2: Prototype Phase Detection (Work Tickets Only)\n\nInclude the Prototype phase unless the ticket explicitly opts out. Check in this order:\n\n1. If the ticket has a `**Prototype**:` metadata field set to `No` (case-insensitive), **skip** the Prototype phase\n2. If the `**Prototype**:` field is `Yes` or absent, **include** the Prototype phase (default behavior)\n\nThis allows ticket authors to opt out of prototyping for straightforward work like API refactors, renames, or simple bug fixes where there are no design assumptions to validate.\n\n### 9c: Create Each Phase Sub-Issue\n\nFor each applicable phase, create a sub-issue:\n\n```bash\ngh issue create \\\n  --title \"[Phase] {title}\" \\\n  --body \"{phase_body}\" \\\n  --label \"ticket:{ticket_id}\" \\\n  --label \"phase:{phase}\"\n```\n\n**Work ticket** phase titles:\n- `[Design] Split Impulse Position Correction`\n- `[Math] Split Impulse Position Correction`\n- `[Prototype] Split Impulse Position Correction`\n- `[Implementation] Split Impulse Position Correction`\n\n**Investigation ticket** phase titles:\n- `[Investigate] Collision Energy Stabilization Debug`\n- `[Diagnose] Collision Energy Stabilization Debug`\n- `[Fix] Collision Energy Stabilization Debug`\n- `[Verify] Collision Energy Stabilization Debug`\n\n### Phase Sub-Issue Body Content\n\nSee `references/phase-templates.md` for the body content of each phase sub-issue. Work and Investigation tickets use different templates.\n\n### 9d: Link Phase Sub-Issues to Parent\n\nAfter creating each phase sub-issue, link it as a sub-issue of the main ticket issue using the GitHub GraphQL API:\n\n```bash\n# Get the node ID of the main issue\nPARENT_ID=$(gh issue view {main_issue_number} --json id -q ''.id'')\n\n# Get the node ID of the phase sub-issue\nCHILD_ID=$(gh issue view {phase_issue_number} --json id -q ''.id'')\n\n# Link as sub-issue (use -F for GraphQL variables, -f for query)\ngh api graphql -F parentId=\"$PARENT_ID\" -F childId=\"$CHILD_ID\" -f query=''\nmutation AddSubIssue($parentId: ID!, $childId: ID!) {\n  addSubIssue(input: {\n    issueId: $parentId\n    subIssueId: $childId\n  }) {\n    issue { id }\n    subIssue { id }\n  }\n}''\n```\n\nIf the GraphQL API fails (e.g., sub-issues not enabled for the repo), fall back to including the phase issues as a task list in the main issue body.\n\n### 9e: Update Main Issue Body with Phase Links\n\nAfter creating all phase sub-issues, update the main issue''s `## Workflow Phases` section to include the actual issue numbers:\n\n**Work tickets:**\n```markdown\n## Workflow Phases\n\n- [ ] #42 Design\n- [ ] #43 Math Formulation\n- [ ] #44 Prototype\n- [ ] #45 Implementation\n```\n\nOmit Math and/or Prototype lines if those phases don''t apply.\n\n**Investigation tickets:**\n```markdown\n## Workflow Phases\n\n- [ ] #42 Investigate\n- [ ] #43 Diagnose\n- [ ] #44 Fix\n- [ ] #45 Verify\n```\n\n```bash\ngh issue edit {main_issue_number} --body \"{updated_body}\"\n```\n\n## Step 10: Update Parent Issue\n\nIf the ticket has a `**Parent Ticket**:` field:\n\n1. Find the parent''s GitHub issue: `gh issue list --label \"ticket:{parent_id}\" --state all --json number,body --limit 1`\n2. If the parent issue exists and is a Feature ticket:\n   - Find the `## Subtickets` section in the parent body\n   - Replace the line for this child ticket with the linked version: `- [ ] #{new_issue} - {title}`\n   - Use `gh issue edit {parent_number} --body \"{updated_body}\"`\n3. Link this issue as a sub-issue of the parent (same GraphQL as Step 9d)\n\nIf the parent issue doesn''t exist yet, skip this step and note it in the report.\n\n## Step 11: Report\n\nPrint a summary:\n\n```\nIssue created: #{number} — {title}\nURL: {url}\nKind: Feature | Work | Investigation\nLabels: ticket:{id}, type:{type}, [feature]\n\nWorkflow phases created:          (Work and Investigation tickets)\n  Work:\n    - #42 [Design] {title}\n    - #43 [Math] {title}\n    - #44 [Prototype] {title}\n    - #45 [Implementation] {title}\n  Investigation:\n    - #42 [Investigate] {title}\n    - #43 [Diagnose] {title}\n    - #44 [Fix] {title}\n    - #45 [Verify] {title}\n  Sub-issue linking: success | fallback to task list\n\nCross-references resolved:\n  - ticket 0038 -> #12\n  - ticket 0040a -> #15\n  - ticket 0040d (no issue yet)\n\nParent update:\n  - Updated #{parent} subticket list with #{number}\n  - Linked as sub-issue of #{parent}: success | skipped\n```\n\n## Error Handling\n\n### Ticket file not found\n- List all files in `tickets/` that start with the given prefix\n- If none match, report \"No ticket found matching ''{input}''\"\n\n### `gh` not authenticated\n- If any `gh` command fails with auth error, tell the user to run `gh auth login`\n\n### Label creation fails\n- Use `--force` flag which updates existing labels rather than failing\n- If `gh label create` still fails, report the error and continue without the label\n\n### Sub-issue API not available\n- If the GraphQL `addSubIssue` mutation fails, fall back to task list references in the issue body\n- Report that sub-issue linking was skipped and why\n\n### Parent issue body too large to parse\n- If the parent body can''t be reliably modified, skip the parent update and report it\n\n### Phase sub-issue already exists\n- If a phase sub-issue with the matching `ticket:{id}` + `phase:{phase}` labels already exists, skip creating it\n- Use the existing issue number in the Workflow Phases section\n\n## References\n\n- See `references/label-mapping.md` for label naming conventions and color codes\n- See `references/body-template.md` for the issue body template\n- See `references/phase-templates.md` for phase sub-issue body templates\n"},"lastSynced":"2026-03-08T02:04:20.665Z","agentAnalysis":{"suitability":{"en":"Ideal for GitHub Integration Agents seeking to automate issue creation from local markdown tickets.","zh":"适合于 GitHub Integration Agents 寻求自动化从本地 markdown 票据创建问题。","ja":"GitHub Integration Agents がローカルの Markdown チケットから問題を作成する自動化を目指している場合に最適です。","ko":"GitHub Integration Agents 가 로컬 마크다운 티켓에서 문제を作成하는 자동화를 목표로 하는 경우에 이상적입니다.","es":"Ideal para agentes de integración de GitHub que buscan automatizar la creación de problemas a partir de tickets de markdown locales.","fr":"Idéal pour les agents d''intégration GitHub cherchant à automatiser la création de problèmes à partir de tickets markdown locaux.","de":"Ideal für GitHub-Integration Agents, die die Erstellung von Problemen aus lokalen Markdown-Tickets automatisieren möchten.","pt":"Ideal para Agentes de Integração do GitHub que buscam automatizar a criação de problemas a partir de tickets markdown locais.","ru":"Идеально подходит для агентов интеграции GitHub, которые хотят автоматизировать создание проблем из локальных билетов markdown.","ar":"مثالي لعميل تطبيق إدماج GitHub الراغب في تسهيل إنشاء المشكلات من تذاكر ماركداون المحلية."},"recommendation":{"en":"Empowers agents to convert local markdown tickets into GitHub Issues with preserved content, managed labels, and resolved cross-references using markdown file formats and GitHub API protocols.","zh":"赋予代理将本地 markdown 票据转换为 GitHub Issues 的能力，保留内容、管理标签，并使用 markdown 文件格式和 GitHub API 协议解析跨引用。","ja":"エージェントがローカルの Markdown チケットを GitHub Issues に変換する能力を提供し、コンテンツを保存し、ラベルを管理し、Markdown ファイル形式と GitHub API プロトコルを使用してクロスリファレンスを解決します。","ko":"에이전트가 로컬 마크다운 티켓을 GitHub Issues로 변환할 수 있는 기능을 제공하여 콘텐츠를 보존하고 레이블을 관리하며 마크다운 파일 형식과 GitHub API 프로토콜을 사용하여 크로스 참조를 해결합니다.","es":"Habilita a los agentes a convertir tickets markdown locales en problemas de GitHub con contenido preservado, etiquetas administradas y referencias cruzadas resueltas utilizando formatos de archivo markdown y protocolos de API de GitHub.","fr":"Permet aux agents de convertir des tickets markdown locaux en problèmes GitHub avec contenu préservé, étiquettes gérées et références croisées résolues en utilisant des formats de fichiers markdown et des protocoles d''API GitHub.","de":"Ermächtigt die Agenten, lokale Markdown-Tickets in GitHub-Probleme mit erhaltenem Inhalt, verwalteten Labels und aufgelösten Querverweisen umzuwandeln, indem sie Markdown-Dateiformate und GitHub-API-Protokolle verwenden.","pt":"Habilita os agentes a converter bilhetes markdown locais em Problemas do GitHub com conteúdo preservado, rótulos gerenciados e referências cruzadas resolvidas usando formatos de arquivo markdown e protocolos da API do GitHub.","ru":"Наделяет агентов возможностью преобразовывать локальные билеты markdown в проблемы GitHub с сохраненным контентом, управляемыми метками и решенными кросс-референсами, используя форматы файлов markdown и протоколы API GitHub.","ar":"يمنح العميل القدرة على تحويل التذاكر ماركداون المحلية إلى مشكلات GitHub مع المحتوى المحفوظ والأوسمة المدارة والمراجع المتقاطعة المحلولة باستخدام صيغ الملفات ماركداون وبروتوكولات واجهة برمجة التطبيقات GitHub."},"useCases":{"en":["Automating issue creation from local markdown files","Preserving content and managing labels for GitHub Issues","Resolving cross-references in markdown tickets"],"zh":["从本地 markdown 文件自动创建问题","为 GitHub Issues 保留内容和管理标签","在 markdown 票据中解析跨引用"],"ja":["ローカルの Markdown ファイルから問題を作成する自動化","GitHub Issues のコンテンツを保存しラベルを管理する","Markdown チケットのクロスリファレンスを解決する"],"ko":["로컬 마크다운 파일에서 문제를 자동 생성하는 것","GitHub Issues의 콘텐츠를 보존하고 레이블을 관리하는 것","마크다운 티켓의 크로스 참조를 해결하는 것"],"es":["Automatizar la creación de problemas a partir de archivos markdown locales","Preservar el contenido y administrar etiquetas para problemas de GitHub","Resolver referencias cruzadas en tickets markdown"],"fr":["Automatiser la création de problèmes à partir de fichiers markdown locaux","Préserver le contenu et gérer des étiquettes pour les problèmes GitHub","Résoudre des références croisées dans des tickets markdown"],"de":["Automatisieren der Problemerstellung aus lokalen Markdown-Dateien","Erhalten von Inhalt und Verwalten von Labels für GitHub-Probleme","Auflösen von Querverweisen in Markdown-Tickets"],"pt":["Automatizar a criação de problemas a partir de arquivos markdown locais","Preservar o conteúdo e gerenciar rótulos para Problemas do GitHub","Resolver referências cruzadas em bilhetes markdown"],"ru":["Автоматизировать создание проблем из локальных файлов markdown","Сохранять контент и управлять метками для проблем GitHub","Решать кросс-референсы в билетах markdown"],"ar":["تسهيل إنشاء المشكلات من الملفات ماركداون المحلية","الحفاظ على المحتوى وإدارة الأوسمة لمشكلات GitHub","حل المراجع المتقاطعة في تذاكر ماركداون"]},"limitations":{"en":["Requires GitHub API access","Limited to markdown file format","Needs filesystem access to tickets directory"],"zh":["需要 GitHub API 访问","仅限于 markdown 文件格式","需要文件系统访问 tickets 目录"],"ja":["GitHub API アクセスが必要","Markdown ファイル形式のみに制限される","チケットディレクトリへのファイルシステムアクセスが必要"],"ko":["GitHub API 액세스가 필요함","마크다운 파일 형식만으로 제한됨","티켓 디렉토리에 대한 파일 시스템 액세스가 필요함"],"es":["Requiere acceso a la API de GitHub","Limitado al formato de archivo markdown","Necesita acceso al sistema de archivos al directorio de tickets"],"fr":["Nécessite un accès à l''API GitHub","Limité au format de fichier markdown","Nécessite un accès au système de fichiers du répertoire de tickets"],"de":["Benötigt Zugriff auf die GitHub-API","Begrenzt auf das Markdown-Dateiformat","Benötigt Dateisystemzugriff auf das Ticket-Verzeichnis"],"pt":["Exige acesso à API do GitHub","Limitado ao formato de arquivo markdown","Necessita acesso ao sistema de arquivos para o diretório de tickets"],"ru":["Требует доступа к API GitHub","Ограничен форматом файла markdown","Требует доступа к файловой системе для каталога билетов"],"ar":["يتطلب الوصول إلى واجهة برمجة التطبيقات GitHub","محدود بصيغة ملف ماركداون","يحتاج إلى الوصول إلى نظام الملفات للمجلد التذاكر"]},"version":4},"contentHash":"fd83343eca44ce84c6d54476b5671f45392d50594a97162a3aba2036d4972a8a","qualityScore":45}');
