INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('danielnewman09/MSD-CPP/create-issue', 'create-issue', 'danielnewman09', 'MSD-CPP', 'community', 'create-issue danielnewman09 MSD-CPP community The create-issue skill converts local markdown tickets into GitHub Issues, preserving content and managing labels. It benefits developers by automating issue creation. Create Issue AI Agent可以将本地Markdown票转换为GitHub问题，保留内容、管理标签和工作流阶段子问题 Create Issue AIエージェントは、ローカルのMarkdownチケットをGitHub Issueに変換し、コンテンツ、ラベル、ワークフローフェーズのサブイシューを保存します Create Issue AI 에이전트는 로컬 Markdown 티켓을 GitHub 이슈로 변환하고 내용, 레이블, 워크플로우 단계의 하위 이슈를 보존합니다 Create-issue es una habilidad que convierte tickets de markdown en problemas de GitHub con contenido completo, conservación de etiquetas y resolución de referencias cruzadas Create-issue est une compétence qui convertit les tickets markdown en problèmes GitHub avec contenu complet, conservation d''étiquettes et résolution de références croisées Create-issue ist eine Fähigkeit, die Markdown-Tickets in GitHub-Probleme mit vollständigem Inhalt, Labelverwaltung und Auflösung von Querverweisen umwandelt O agente de criação de issues converte tickets em markdown em issues do GitHub com preservação de conteúdo e gerenciamento de labels ИИ Агент для создания Issue преобразует локальные tickets в markdown в issues GitHub с сохранением контента и управлением метками أداة إنشاء المشكلات تحول التذاكر في تنسيق Markdown إلى مشكلات على GitHub مع الحفاظ على المحتوى وإدارة العلامات how to use create-issue create-issue setup guide GitHub Issue creation automation create-issue alternative create-issue vs GitHub API create-issue install what is create-issue create-issue workflow integration markdown ticket conversion Create Issue AI Agent GitHub问题创建 Markdown票转换 CLI命令行工具 自动化GitHub问题管理 AI工具 GitHub集成 Converts local markdown tickets to GitHub Issues with full content preservation Manages labels and resolves cross-references Supports workflow phase sub-issues Invoked using a simple command with ticket identifier Works with bare numbers, full filename stems, or filenames with .md extension create-issue is a skill that automates the creation of GitHub Issues from local markdown tickets, preserving content and managing labels');
